window.HAFTAROT_DATA["haftarot-levitic"] = {"chapters":[{"num":1,"title":"Vaikra - Și a chemat","ref":"Isaia 43:21-44:23","intro":"Haftarat Vaikra deschide ciclul haftarot al cărții Levitic acolo unde pericopa își începe propriul discurs — cu jertfele aduse în Sanctuar. Isaia răstoarnă însă perspectiva: DOMNUL nu a fost împovărat de cerințe de jertfă, ci dimpotrivă, poporul L-a împovărat cu păcatele lui, aducând prea puțin, nu prea mult. Din acest rechizitoriu, capitolul 43 se încheie, iar capitolul 44 se deschide cu una din cele mai limpezi afirmații monoteiste din toată Scriptura — polemica împotriva idolilor, cu descrierea detaliată, aproape satirică, a meșterului care taie un copac, arde jumătate ca lemn de foc și se închină celeilalte jumătăți ca unui dumnezeu — încheiată cu asigurarea răscumpărării și un imn cosmic de bucurie.","verses":[{"v":"43:21","t":"Acest popor l-am făurit pentru Mine, ca să-Mi declare slava.","tokens":[{"t":"Acest popor l-am "},{"t":"făurit","w":"făurit","heb":"יָצַרְתִּי","translit":"iațarti","strong":"H3335","pos":"verb, qal perfect","def_ro":"am format, am modelat.","greek":"περιποιέω (peripoieo)","greek_def_ro":"περιποιέω (peripoieo) — a dobândi, a-și însuși (pentru sine).","diff_ro":"Septuaginta are nuanța de „a-mi însuși/dobândi\", nu strict „a făuri/modela\" (iatsar) ca în ebraică.","dict_ro":"Iatzar — același verb folosit la Geneza 2:7 pentru formarea omului din țărână, ca un olar care modelează lutul. Folosindu-l aici pentru poporul Israel, Isaia leagă alegerea lui Israel de actul Creației înseși — Israel nu e doar ales, ci „modelat” cu aceeași grijă intenționată cu care a fost modelat Adam."},{"t":" pentru Mine, ca să-Mi declare slava."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"„Poporul acesta l-am întocmit pentru Mine” — ca să vestească lauda Mea."},{"author":"Metzudat David","text":"„I-am format ca popor pentru Mine, ca ei să istorisească slava Mea” — scopul creării lui Israel ca popor distinct este proclamarea publică a lui Dumnezeu, nu doar existența lui privată."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"עַם־זוּ יָצַרְתִּי לִי תְּהִלָּתִי יְסַפֵּרוּ׃","translation":"„Acest popor l-am făurit pentru Mine...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"λαόν μου, ὃν περιεποιησάμην τὰς ἀρετάς μου διηγεῖσθαι.","greek":true,"translation":"„Poporul Meu, pe care l-am dobândit ca să istorisească virtuțile Mele.”","note":"Corespondență strânsă cu Textul Masoretic; LXX redă „tehilati” (slava/lauda Mea) prin „τὰς ἀρετάς μου” (virtuțile Mele) — o nuanță reală, mutând accentul de la laudă/imn spre calitate morală demonstrată."}],"refs":["Isaia 60:21","Psalmii 102:18","Proverbe 16:4","1 Petru 2:9","Evrei 13:15","Tit 2:14"]},{"v":"43:22","t":"Dar n-ai strigat către Mine, Iacove, căci te-ai obosit de Mine, Israele.","tokens":[{"t":"Dar n-ai strigat către Mine, Iacove, căci te-ai "},{"t":"obosit","w":"obosit","heb":"יָגַעְתָּ","translit":"iagata","strong":"H3021","pos":"verb, qal perfect","def_ro":"te-ai ostenit, te-ai plictisit.","greek":"κοπιάω (kopiao)","greek_def_ro":"κοπιάω (kopiao) — a se obosi, a trudi.","dict_ro":"Iaga — verbul denotă oboseală fizică din muncă istovitoare, aplicat aici metaforic la relația cu DOMNUL: nu e vorba de o povară obiectivă (v.23 arată că cerințele rituale erau minime), ci de o oboseală subiectivă, o lehamite spirituală a poporului față de închinare."},{"t":" de Mine, Israele."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"„Dar n-ai strigat către Mine” — și tu n-ai strigat către Mine când te-ai întors după idolatrie. „Căci te-ai obosit de Mine” — v-ați săturat repede de slujirea Mea (Pesikta Rabbati 29)."},{"author":"Metzudat David","text":"Metzudat David precizează contrastul: „tu, Iacov, nu M-ai chemat, căci te-ai întors spre idoli — ai devenit ostenit și obosit în slujirea Mea și ai părăsit-o”."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְלֹא־אֹתִי קָרָאתָ יַעֲקֹב כִּי־יָגַעְתָּ בִּי יִשְׂרָאֵל׃","translation":"„Dar n-ai strigat către Mine, Iacove...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"οὐ νῦν ἐκάλεσά σε, Ἰακώβ, οὐδὲ κοπιάσαι σε ἐποίησα, Ἰσραήλ.","greek":true,"translation":"„Nu acum te-am chemat, Iacove, nici nu te-am făcut să te ostenești, Israele.”","note":"Divergență reală: Textul Masoretic pune poporul ca subiect activ care nu L-a chemat pe DOMNUL și s-a obosit el însuși de El; Septuaginta inversează structura — DOMNUL e Cel care „nu te-a chemat” și „nu te-a făcut să te ostenești”, mutând accentul dinspre vina poporului spre absența unei poveri impuse de Dumnezeu."}],"refs":["Mica 6:3","Maleahi 1:13","Isaia 64:7","Iov 21:14,15","Psalmii 14:4","Iov 27:9,10"]},{"v":"43:23","t":"Nu Mi-ai adus mielul arderilor-de-tot ale tale și nici nu M-ai cinstit cu jertfele tale de pace. Eu nu te-am împovărat cu prinosuri și nu te-am obosit cu tămâie.","tokens":[{"t":"Nu Mi-ai adus mielul "},{"t":"arderilor-de-tot","w":"arderilor-de-tot","heb":"עֹלֹתֶיךָ","translit":"oloteha","strong":"H5930","pos":"substantiv, feminin plural construct + sufix","def_ro":"arderile tale de tot.","greek":"ὁλοκάρπωσις (holokarposis)","greek_def_ro":"ὁλοκάρπωσις (holokarposis) — ardere-de-tot.","dict_ro":"Ola — jertfa mistuită integral pe altar, fără nicio parte lăsată închinătorului, simbol al dăruirii totale. Faptul că DOMNUL notează absența ei nu ca acuzație de neglijență rituală, ci ca argument („nu te-am împovărat”), inversează logica obișnuită a rechizitoriilor profetice: aici lipsa jertfei arată tocmai cât de puțin a cerut DOMNUL, nu cât de mult a lipsit poporul."},{"t":" ale tale și nici nu M-ai cinstit cu jertfele tale de pace. Eu nu te-am împovărat cu prinosuri și nu te-am obosit cu tămâie."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"„Nu Mi-ai adus mieii arderilor tale de tot” — ci idolatriei. „Nu te-am împovărat” — cu multă muncă la darul de mâncare: doar o mână plină urca spre Cel Preaînalt, și nici pe aceea nu ți-am spus s-o aduci ca datorie, ci ca dar de bunăvoie."},{"author":"Metzudat David","text":"„Nu te-am împovărat cu prinosuri” — nu ți-am impus o muncă grea sau o cheltuială mare la aducerea prinosului, căci am poruncit doar un pumn mic să fie ars pe altar, iar tămâia nu Mi-am cerut-o din abundență."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"לֹא־הֵבֵיאתָ לִּי שֵׂה עֹלֹתֶיךָ...","translation":"„Nu Mi-ai adus mielul arderilor-de-tot ale tale...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"οὐκ ἐμοὶ ἤνεγκας πρόβατα τῆς ὁλοκαρπώσεώς σου, οὐδὲ ἐν ταῖς θυσίαις σου ἐδόξασάς με· οὐκ ἐδούλωσά σε ἐν θυσίαις, οὐδὲ ἔγκοπον ἐποίησά σε ἐν λιβάνῳ.","greek":true,"translation":"„Nu Mi-ai adus oile arderii tale de tot, nici nu M-ai slăvit cu jertfele tale; nu te-am înrobit cu jertfe, nici nu te-am făcut ostenit cu tămâie.”","note":"Corespondență apropiată cu Textul Masoretic pe tot versetul."}],"refs":["Isaia 1:11-15","Amos 5:21,22","Zaharia 7:5,6","Matei 11:30","Amos 5:25"]},{"v":"43:24","t":"Nu Mi-ai cumpărat scorțișoară cu bani și nici nu M-ai săturat cu grăsimea jertfelor tale, ci M-ai împovărat cu păcatele tale și M-ai obosit cu nelegiuirile tale.","tokens":[{"t":"Nu Mi-ai cumpărat scorțișoară cu bani și nici nu M-ai săturat cu grăsimea jertfelor tale, ci M-ai "},{"t":"împovărat","w":"împovărat","heb":"הֶעֱבַדְתַּנִי","translit":"heevadtani","strong":"H5647","pos":"verb, hifil perfect + sufix","def_ro":"m-ai pus să slujesc, m-ai făcut rob.","diff_ro":"Septuaginta are aici „προέστην σου\" („am stat în fața ta, te-am condus\"), nu „M-ai împovărat/M-ai făcut să slujesc\" (heevadtani) ca în ebraică — o imagine destul de diferită, mai degrabă de autoritate decât de servitute impusă.","dict_ro":"Avad la forma hifil — „m-ai făcut să slujesc/muncesc”, aceeași rădăcină din care vine „eved” (rob) și „avoda” (slujire, inclusiv slujirea rituală din Templu). Ironia versetului stă în inversarea rolurilor: poporul n-a fost pus să „slujească” prin jertfe grele, dar L-a pus pe DOMNUL Însuși să „slujească”, purtând povara păcatelor lor — o imagine șocantă, pe care Rashi o leagă explicit de exil."},{"t":" cu păcatele tale și M-ai obosit cu nelegiuirile tale."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"„N-ai cumpărat pentru Mine cu argint trestie mirositoare” — pentru tămâie n-ai avut nevoie s-o cumperi cu argint, căci era din belșug în țara voastră; Rabi Aba a spus: scorțișoara creștea în țara lui Israel, și o mâncau caprele și căprioarele (Eiha Raba, Petihta 10). „M-ai împovărat cu păcatele tale” — voi M-ați făcut să fiu slujitor al închinătorilor la idoli, cum a văzut Ezechiel: „și iată, a venit un vânt năprasnic de la miazănoapte” (Ezechiel 1:4), căci carul Prezenței lui Dumnezeu se întorcea din Babilon, unde se dusese să supună toată lumea sub mâna lui Nabucodonosor, ca să nu se spună că Și-a dat copiii în mâna unui neam de nimic, cum se află în Haghiga (13b)."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"לֹא־קָנִיתָ לִּי בַכֶּסֶף קָנֶה...","translation":"„Nu Mi-ai cumpărat scorțișoară cu bani...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"οὐδὲ ἐκτήσω μοι ἀργυρίου θυμίαμα, οὐδὲ τὸ στέαρ τῶν θυσιῶν σου ἐπεθύμησα, ἀλλὰ ἐν ταῖς ἁμαρτίαις σου καὶ ἐν ταῖς ἀδικίαις σου προέστην σου.","greek":true,"translation":"„Nici nu Mi-ai dobândit cu argint tămâie, nici n-am poftit grăsimea jertfelor tale, ci cu păcatele tale și cu nedreptățile tale ai stat înaintea Mea/M-ai împovărat.”","note":"Divergență lexicală reală: Textul Masoretic vorbește despre „kane” (trestie mirositoare/calamus, o mirodenie specifică), pe când Septuaginta traduce generic prin „θυμίαμα” (tămâie) — probabil pentru că traducătorii alexandrini nu au găsit un echivalent grecesc exact pentru planta ebraică."}],"refs":["Ieremia 6:20","Psalmii 50:9-13","Ezechiel 6:9","Amos 2:13","Exod 30:7,23,24,34"]},{"v":"43:25","t":"Eu, doar Eu, sunt cel care șterg nelegiuirile tale de dragul Meu, iar păcatele tale nu le mai amintesc.","tokens":[{"t":"Eu, doar Eu, sunt cel care "},{"t":"șterg","w":"șterg","heb":"מֹחֶה","translit":"mohe","strong":"H4229","pos":"verb, qal participiu","def_ro":"cel care șterge, cel care curăță.","greek":"ἐξαλείφω (exaleipho)","greek_def_ro":"ἐξαλείφω (exaleipho) — a șterge, a nimici cu totul.","dict_ro":"Mahah — imaginea e a ștergerii unui text scris (aceeași rădăcină e folosită pentru ștergerea numelui divin în ritualul soției bănuite de infidelitate, Numeri 5:23) — păcatul e conceput ca o înscriere care poate fi complet îndepărtată, nu doar acoperită. Dubla repetiție „Anochi anochi” (Eu, Eu) subliniază că numai DOMNUL, nimeni altcineva, are autoritatea de a ierta astfel."},{"t":" nelegiuirile tale de dragul Meu, iar păcatele tale nu le mai amintesc."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Eu, Eu” — Eu sunt Cel care le-am șters de atunci, și Eu le șterg și acum; „de dragul Meu” — nu datorită vreunui merit al tău, nici al dreptății părinților tăi."},{"author":"Metzudat David","text":"„De dragul Meu, ca să nu-Mi fie profanat Numele când voi face cu voi ceea ce meritați pentru păcatele voastre — de aceea le șterg cu desăvârșire, să nu rămână nicio urmă, nici să nu mai fie amintite.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"אָנֹכִי אָנֹכִי הוּא מֹחֶה פְשָׁעֶיךָ...","translation":"„Eu, doar Eu, sunt cel care șterg nelegiuirile tale...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ἐγώ εἰμι, ὁ ἐξαλείφων τὰς ἀνομίας σου ἕνεκεν ἐμοῦ καὶ τὰς ἁμαρτίας σου καὶ οὐ μὴ μνησθήσομαι.","greek":true,"translation":"„Eu sunt Cel ce șterge nelegiuirile tale de dragul Meu și păcatele tale, și nu Mi le voi aminti.”","note":"Septuaginta redă repetiția emfatică ebraică „Anochi anochi” (Eu, Eu) printr-un simplu „ἐγώ εἰμι” (Eu sunt), pierzând nuanța de accentuare dublă a Textului Masoretic."}],"refs":["Isaia 44:22","Mica 7:18,19","Ieremia 31:34","Evrei 8:12","Isaia 43:11","Isaia 37:35"]},{"v":"43:26","t":"Adu-Mi aminte, hai să ne judecăm unul cu altul! Apără-ți cauza, ca să fii socotit drept.","tokens":[{"t":"Adu-Mi aminte, hai să ne "},{"t":"judecăm","w":"judecăm","heb":"נִשָּׁפְטָה","translit":"nișafta","strong":"H8199","pos":"verb, nifal cohortativ","def_ro":"să ne judecăm, să intrăm la judecată.","greek":"κρίνομαι (krinomai)","greek_def_ro":"κρίνομαι (krinomai) — a ne judeca.","dict_ro":"Șafat la forma nifal cohortativă evocă limbajul juridic al unui proces (rîv) — DOMNUL invită poporul la o dezbatere de tribunal, în care fiecare parte își prezintă argumentele. E o formulă retorică frecventă la profeți (cf. Isaia 1:18, Mica 6:1-2), care nu presupune o judecată reală egală, ci ironizează pretenția omului de a avea vreo apărare valabilă în fața lui Dumnezeu."},{"t":" unul cu altul! Apără-ți cauza, ca să fii socotit drept."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Adu-Mi aminte” — orice răsplată pe care crezi că o ai de la Mine, tu și părinții tăi; „să ne judecăm unul cu altul” — să venim la judecată."},{"author":"Metzudat David","text":"Metzudat David explică imaginea printr-o parabolă între oameni: „adu-mi aminte ce merit ai față de mine, să ne judecăm împreună” — chiar dacă tu vei vorbi primul, nu vei fi găsit drept înaintea Mea."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"הַזְכִּירֵנִי נִשָּׁפְטָה יָחַד...","translation":"„Adu-Mi aminte, hai să ne judecăm unul cu altul...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"σὺ δὲ μνήσθητι καὶ κριθῶμεν· λέγε σὺ τὰς ἀνομίας σου πρῶτος, ἵνα δικαιωθῇς.","greek":true,"translation":"„Iar tu adu-ți aminte și să ne judecăm; spune tu nelegiuirile tale mai întâi, ca să fii îndreptățit.”","note":"Divergență reală, notabilă: Textul Masoretic are imperativul „Adu-Mi aminte” (hazkireni, cu sufixul de persoana I — „fă-Mă să-Mi amintesc”), pe când Septuaginta redă „σὺ...μνήσθητι” — „TU adu-ți aminte”, mutând accentul dinspre o provocare adresată lui Dumnezeu spre un îndemn la autoexaminare adresat poporului. LXX adaugă și explicit „spune nelegiuirile tale” (τὰς ἀνομίας σου), acolo unde Textul Masoretic are doar „saper ata” („tu, recunoaște/expune-ți cauza”), fără să precizeze dacă obiectul e nelegiuirea sau argumentele de apărare."}],"refs":["Isaia 1:18","Iov 23:3-6","Luca 18:9-14","Romani 8:33","Isaia 43:9"]},{"v":"43:27","t":"Primul tău strămoș a greșit, iar avocații tăi M-au trădat.","tokens":[{"t":"Primul tău strămoș a greșit, iar "},{"t":"avocații","w":"avocații","heb":"וּמְלִיצֶיךָ","translit":"umlițeha","strong":"H3887","pos":"verb, hifil participiu + sufix","def_ro":"interpreții tăi, mijlocitorii tăi.","diff_ro":"Septuaginta are „οἱ ἄρχοντες ὑμῶν\" („conducătorii voștri\"), nu „avocații/mijlocitorii tăi\" (melitzeha) ca în ebraică — un termen diferit pentru acest grup acuzat de trădare.","dict_ro":"Melitz — de la rădăcina „lutz”, cel care mijlocește sau interpretează, aici cu sensul de purtător de cuvânt sau apărător — un termen aplicat de tradiție preoților și profeților care ar fi trebuit să pledeze cauza poporului, dar care, în schimb, s-au făcut ei înșiși vinovați de răzvrătire."},{"t":" tăi M-au trădat."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"„Primul tău părinte a păcătuit” — când a zis: „Prin ce voi cunoaște...?” (Geneza 15:8). „Și mijlocitorii tăi s-au răzvrătit împotriva Mea” — n-ai niciunul dintre mijlocitorii pe al căror merit te sprijini în care să nu fi găsit o răzvrătire: Isaac l-a iubit pe vrăjmașul Meu."},{"author":"Metzudat David","text":"Metzudat David citește versetul diferit, identificând „primul tău strămoș” cu Adam, care a păcătuit mâncând din pomul cunoștinței — deși era el însuși lucrarea directă a mâinilor lui Dumnezeu; cu atât mai mult voi, care v-ați născut din bărbat și femeie, plini de nelegiuire."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"אָבִיךָ הָרִאשׁוֹן חָטָא...","translation":"„Primul tău strămoș a greșit...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"οἱ πατέρες ὑμῶν πρῶτοι καὶ οἱ ἄρχοντες ὑμῶν ἠνόμησαν εἰς ἐμέ.","greek":true,"translation":"„Părinții voștri, cei dintâi, și conducătorii voștri au nelegiuit împotriva Mea.”","note":"Divergență reală: Textul Masoretic vorbește la singular despre „primul tău strămoș” (avicha harișon) și despre „mijlocitorii/interpreții tăi” (melitzeha); Septuaginta pluralizează în „părinții voștri” și înlocuiește „mijlocitorii” cu „conducătorii” (ἄρχοντες) — o schimbare de sens reală, de la rolul de apărători/interpreți la cel de autorități politice."}],"refs":["Romani 5:12","Ezechiel 16:3","Ieremia 23:11-15","Mica 3:11","Ezechiel 22:25-28"]},{"v":"43:28","t":"De aceea, i-am pângărit pe conducătorii Sanctuarului, l-am dat spre distrugere pe Iacov, iar pe Israel [l-am dat] dojenilor.","tokens":[{"t":"De aceea, i-am "},{"t":"pângărit","w":"pângărit","heb":"וַאֲחַלֵּל","translit":"vaahalēl","strong":"H2490","pos":"verb, piel imperfect","def_ro":"și am profanat, am spurcat.","greek":"μιαίνω (miaino)","greek_def_ro":"μιαίνω (miaino) — a pângări, a spurca.","dict_ro":"Halal la forma piel — „a profana”, opusul lui „kadeș” (a sfinți); folosit aici pentru „sarei kodeș” (conducătorii sfințeniei/Sanctuarului), sugerează degradarea publică a rangului preoțesc/conducător ca pedeapsă directă pentru păcatele descrise anterior — cei puși să păzească sfințenia devin ei înșiși dezonorați."},{"t":" pe conducătorii Sanctuarului, l-am dat spre distrugere pe Iacov, iar pe Israel [l-am dat] dojenilor."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „i-am pângărit” — din cauza nelegiuirilor voastre."},{"author":"Metzudat David","text":"„Din cauza păcatelor voastre am pângărit chiar și pe conducătorii voștri sfinți, i-am dat spre nimicire și ocară în gura vrăjmașului.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַאֲחַלֵּל שָׂרֵי קֹדֶשׁ...","translation":"„De aceea, i-am pângărit pe conducătorii Sanctuarului...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐμίαναν οἱ ἄρχοντες τὰ ἅγιά μου, καὶ ἔδωκα ἀπολέσαι Ἰακὼβ καὶ Ἰσραὴλ εἰς ὀνειδισμόν.","greek":true,"translation":"„Și conducătorii au pângărit cele sfinte ale Mele, și am dat spre pieire pe Iacov, și pe Israel spre ocară.”","note":"Divergență reală și semnificativă: în Textul Masoretic DOMNUL Însuși este subiectul care „pângărește” conducătorii Sanctuarului, ca act de pedeapsă; în Septuaginta, rolurile se inversează — conducătorii (ἄρχοντες) sunt cei care pângăresc „cele sfinte ale Mele” ale lui Dumnezeu, ca act de vină, iar pedeapsa (distrugerea lui Iacov) urmează separat ca o consecință. LXX schimbă astfel agentul acțiunii de profanare de la Dumnezeu la conducătorii înșiși."}],"refs":["Psalmii 89:39","Deuteronom 28:15-20","Isaia 42:24,25","Ieremia 24:9","Isaia 47:6"]},{"v":"44:1","t":"Dar acum ascultă, Iacove, slujitorul Meu, și Israele, pe care l-am ales!","tokens":[{"t":"Dar acum ascultă, Iacove, "},{"t":"slujitorul","w":"slujitorul","heb":"עַבְדִּי","translit":"avdi","strong":"H5650","pos":"substantiv, masculin singular construct + sufix","def_ro":"slujitorul Meu, robul Meu.","greek":"παῖς (pais)","greek_def_ro":"παῖς (pais) — slujitor, servitor.","dict_ro":"Eved — titlul „robul/slujitorul DOMNULUI” aplicat lui Israel revine ca un laitmotiv structural în Isaia 40-53 (cf. 41:8, 44:21, 49:3), desemnând nu înjosire, ci o relație de apartenență privilegiată și de misiune — la fel cum Moise e numit „robul DOMNULUI” (Deuteronomul 34:5) ca titlu de onoare, nu de subordonare degradantă."},{"t":" Meu, și Israele, pe care l-am ales!"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Dar acum ascultă” — întoarce-te la Tora Mea, Iacove, robul Meu."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְעַתָּה שְׁמַע יַעֲקֹב עַבְדִּי...","translation":"„Dar acum ascultă, Iacove, slujitorul Meu...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"Νῦν δὲ ἄκουσον, Ἰακὼβ ὁ παῖς μου καὶ Ἰσραήλ, ὃν ἐξελεξάμην.","greek":true,"translation":"„Iar acum ascultă, Iacove, slujitorul Meu, și Israele, pe care l-am ales.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Isaia 41:8","Deuteronom 7:6-8","Ieremia 30:10","Isaia 43:1","Isaia 42:23"]},{"v":"44:2","t":"Așa spune DOMNUL, cel care te-a făcut și te-a făurit din pântec – El te va ajuta. Nu te teme, slujitorul Meu Iacov, și Ieșurun pe care l-am ales.","tokens":[{"t":"Așa spune DOMNUL, cel care te-a făcut și te-a făurit din pântec – El te va ajuta. Nu te teme, slujitorul Meu Iacov, și "},{"t":"Ieșurun","w":"Ieșurun","heb":"וִישֻׁרוּן","translit":"vișurun","strong":"H3484","pos":"nume propriu","def_ro":"cel drept, poreclă poetică pentru Israel.","diff_ro":"Septuaginta nu transliterează acest nume simbolic, ci îl redă „ἠγαπημένος Ἰσραήλ\" („Israel cel iubit\") — o traducere interpretativă a sensului numelui „Ieșurun\" (legat de rădăcina „drept/cinstit\"), nu o transliterare.","dict_ro":"Ieșurun — de la rădăcina „iașar” (drept), un nume de alint/idealizat pentru Israel, folosit doar de patru ori în toată Scriptura (aici, Deuteronomul 32:15, 33:5, 33:26) — desemnând poporul nu așa cum e de fapt, mereu răzvrătit, ci așa cum ar trebui să fie sau va ajunge să fie, drept și integru, într-un contrast voit cu numele „Iacov”, care evocă înșelăciunea de la naștere (Geneza 25:26)."},{"t":" pe care l-am ales."}],"commentaries":[{"author":"Metzudat David","text":"„Cel care te-a făcut și te-a format” — din clipa în care ai ieșit din pântece, te va ajuta; iar „Ieșurun” este numele sub care e chemat Israel, poporul cel drept."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"כֹּה־אָמַר יְהוָה עֹשֶׂךָ וְיֹצֶרְךָ מִבֶּטֶן...","translation":"„Așa spune DOMNUL, cel care te-a făcut și te-a făurit din pântec...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"οὕτω λέγει Κύριος ὁ Θεὸς ὁ ποιήσας σε καὶ ὁ πλάσας σε ἐκ κοιλίας· ἔτι βοηθηθήσῃ, μὴ φοβοῦ, παῖς μου Ἰακὼβ καὶ ἠγαπημένος Ἰσραήλ, ὃν ἐξελεξάμην.","greek":true,"translation":"„Așa zice Domnul Dumnezeu, Cel ce te-a făcut și te-a plăsmuit din pântece; iarăși vei fi ajutat, nu te teme, slujitorul Meu Iacov, și iubitul Israel, pe care l-am ales.”","note":"Divergență lexicală reală: acolo unde Textul Masoretic are numele distinctiv „Ieșurun”, Septuaginta redă printr-un epitet generic — „ἠγαπημένος” („cel iubit”) — probabil pentru că traducătorii alexandrini n-au avut un echivalent pentru acest nume rar, preferând să-i traducă sensul afectiv."}],"refs":["Isaia 43:1","Ieremia 1:5","Deuteronom 32:15","Deuteronom 33:5","Efeseni 1:4","Isaia 44:21"]},{"v":"44:3","t":"La fel cum torn apă peste pământul însetat și râuri peste pământul uscat, așa voi turna duhul Meu peste seminția ta și binecuvântarea Mea peste urmașii tăi.","tokens":[{"t":"La fel cum torn apă peste pământul însetat și râuri peste pământul uscat, așa voi turna "},{"t":"duhul","w":"duhul","heb":"רוּחִי","translit":"ruhi","strong":"H7307","pos":"substantiv, masculin și feminin singular construct + sufix","def_ro":"duhul Meu, suflarea Mea.","greek":"πνεῦμα (pneuma)","greek_def_ro":"πνεῦμα (pneuma) — duh, suflare.","dict_ro":"Ruah — același cuvânt pentru „duh/suflare/vânt”, folosit aici într-o revărsare care depășește darul obișnuit al profeției individuale, promițând o efuziune generalizată peste toată „sămânța” poporului — tradiția rabinică (și, separat, cea creștină prin Faptele apostolilor 2, care citează exact acest tip de pasaj din Ioel 3:1) citește acest verset ca profeție a unei transformări spirituale colective, nu doar a câtorva aleși."},{"t":" Meu peste seminția ta și binecuvântarea Mea peste urmașii tăi."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „la fel cum torn apă peste pământul însetat”, tot așa „voi turna duhul Meu peste sămânța ta”."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"כִּי אֶצָּק־מַיִם עַל־צָמֵא...","translation":"„La fel cum torn apă peste pământul însetat...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ὅτι ἐγὼ δώσω ὕδωρ ἐν δίψει τοῖς πορευομένοις ἐν ἀνύδρῳ, ἐπιθήσω τὸ πνεῦμά μου ἐπὶ τὸ σπέρμα σου καὶ τὰς εὐλογίας μου ἐπὶ τὰ τέκνα σου.","greek":true,"translation":"„Căci Eu voi da apă celor însetați, celor ce merg prin pustiu fără apă; voi pune Duhul Meu peste sămânța ta și binecuvântările Mele peste copiii tăi.”","note":"Divergență de nuanță: Textul Masoretic vorbește generic despre „pământul însetat/uscat”, pe când Septuaginta concretizează imaginea prin „celor ce merg prin pustiu fără apă” — o adaptare narativă a metaforei agricole într-o imagine de călătorie."}],"refs":["Ioel 3:1","Faptele apostolilor 2:17","Ezechiel 39:29","Isaia 35:6,7","Ioan 7:37-39","Isaia 41:17"]},{"v":"44:4","t":"Ei vor înmuguri în iarbă, precum sălciile lângă pâraiele de apă.","tokens":[{"t":"Ei vor înmuguri în iarbă, precum "},{"t":"sălciile","w":"sălciile","heb":"כַּעֲרָבִים","translit":"kaaravim","strong":"H6155","pos":"substantiv, feminin plural","def_ro":"ca sălciile, ca plopii de baltă.","greek":"ἰτέα (itea)","greek_def_ro":"ἰτέα (itea) — salcie.","dict_ro":"Aravim — sălciile de apă, aceeași plantă din care se face una dintre cele patru specii ale Sucotului (lulav). Metzudat David citește „iarba” (hatzir) din prima parte a versetului ca aluzie la Amalec, cel mai slab și disprețuit dușman al lui Israel (cf. Isaia 34:13, unde „hatzir” denotă pustiirea locurilor lui Amalec), sugerând că mulțimea urmașilor lui Israel va crește chiar din mijlocul celor mai neașteptate origini — prin convertiți."},{"t":" lângă pâraiele de apă."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"„Și vor crește ca iarba” (bebein hațir) — în mijlocul lui Amalec, prin prozeliții care li se vor adăuga; „între iarbă” e Amalec, căci s-a spus despre el: „vor fi locuința șacalilor și loc de odihnă (hațir) pentru struți” (Isaia 34:13)."},{"author":"Metzudat David","text":"„Vor crește și se vor înmulți ca și cum ar fi puși în mijlocul ierbii, asemenea sălciilor de pârâu sădite lângă albiile de apă, care cresc și înfloresc repede.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְצָמְחוּ בְּבֵין חָצִיר...","translation":"„Ei vor înmuguri în iarbă...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἀνατελοῦσιν ὡς ἀναμέσον ὕδατος χόρτος καὶ ὡς ἰτέα ἐπὶ παραρρέον ὕδωρ.","greek":true,"translation":"„Și vor răsări ca iarba în mijlocul apei și ca salcia lângă apa curgătoare.”","note":"Corespondență apropiată cu Textul Masoretic."}],"refs":["Isaia 58:11","Psalmii 92:13-15","Ezechiel 17:5","Psalmii 137:1,2","Isaia 61:11"]},{"v":"44:5","t":"Unul va spune: „Eu sunt al DOMNULUI”, iar altul va invoca numele lui Iacov; unul va iscăli cu mâna [lui] că aparține DOMNULUI, iar altul va adopta numele de Israel.","tokens":[{"t":"Unul va spune: „Eu sunt al DOMNULUI”, iar altul va invoca numele lui Iacov; unul va "},{"t":"iscăli","w":"iscăli","heb":"יִכְתֹּב","translit":"ihtov","strong":"H3789","pos":"verb, qal imperfect","def_ro":"va scrie cu mâna lui, își va semna angajamentul.","greek":"ἐπιγράφω (epigrapho)","greek_def_ro":"ἐπιγράφω (epigrapho) — a scrie, a semna.","dict_ro":"Katav yado — literal „își va scrie mâna”, o expresie idiomatică pentru un angajament formal, în scris, asumat personal — imaginea unui legământ pus pe hârtie și semnat, precum legământul scris și pecetluit al lui Neemia (Neemia 9:38, 10:1). Midrașul citat de Rashi (Avot deRabi Natan 36) identifică patru categorii de oameni în acest verset: drepți desăvârșiți, copii ai celor răi care se îndreaptă, penitenți și prozeliți."},{"t":" cu mâna [lui] că aparține DOMNULUI, iar altul va adopta numele de Israel."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi, citând Avot deRabi Natan (36): „acesta va spune: al DOMNULUI sunt eu” — aceștia sunt drepții desăvârșiți; „iar acesta va invoca numele lui Iacov” — aceștia sunt copiii mici ai celor răi; „acesta va iscăli cu mâna lui că aparține DOMNULUI” — aceștia sunt cei ce se pocăiesc; „iar acesta va adopta numele de Israel” — aceștia sunt convertiții dintre popoarele idolatre."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"זֶה יֹאמַר לַיהוָה אָנִי...","translation":"„Unul va spune: «Eu sunt al DOMNULUI»...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"οὗτος ἐρεῖ· τοῦ Θεοῦ εἰμι, καὶ οὗτος βοήσεται ἐπὶ τῷ ὀνόματι Ἰακώβ, καὶ ἕτερος ἐπιγράψει χειρὶ αὐτοῦ· τοῦ Θεοῦ εἰμι, καὶ ἐπὶ τῷ ὀνόματι Ἰσραὴλ βοήσεται.","greek":true,"translation":"„Acesta va zice: al lui Dumnezeu sunt; și acesta va striga în numele lui Iacov; și altul va scrie cu mâna lui: al lui Dumnezeu sunt; și în numele lui Israel va striga.”","note":"Corespondență generală cu Textul Masoretic, cu variație de topică între cele patru declarații paralele."}],"refs":["Neemia 9:38","Zaharia 8:20-23","Ieremia 50:5","2 Corinteni 8:5"]},{"v":"44:6","t":"Așa a spus DOMNUL, Regele lui Israel și Mântuitorul lui, DOMNUL Oștirilor: „Eu sunt cel dintâi și Eu sunt cel din urmă, și în afară de Mine nu este alt dumnezeu.","tokens":[{"t":"Așa a spus DOMNUL, Regele lui Israel și "},{"t":"Mântuitorul","w":"Mântuitorul","heb":"וְגֹאֲלוֹ","translit":"vegoalo","strong":"H1350","pos":"verb, qal participiu + sufix","def_ro":"răscumpărătorul lui, cel care îl eliberează.","greek":"ῥύομαι (rhyomai)","greek_def_ro":"ῥύομαι (rhyomai) — a elibera, a izbăvi.","dict_ro":"Goel — termen din dreptul familial israelit, desemnând ruda cea mai apropiată cu obligația de a răscumpăra o proprietate pierdută, a elibera o rudă din robie sau a răzbuna sângele vărsat (cf. cartea lui Rut). Aplicat lui Dumnezeu, titlul „Goel” transformă relația legământului într-una de rudenie apropiată și obligație personală, nu doar de suveranitate distantă."},{"t":" lui, DOMNUL Oștirilor: „Eu sunt cel dintâi și Eu sunt cel din urmă, și în afară de Mine nu este alt dumnezeu."}],"commentaries":[{"author":"Metzudat David","text":"„Eu sunt cel dintâi” — mai dinainte de crearea lumii; „și Eu sunt cel din urmă” — după ce lumea va înceta să existe."},{"author":"Talmud Bavli, Sanhedrin 38b","text":"Talmudul folosește chiar acest verset ca respingere directă a ereziei „celor două puteri” din cer: „Eu sunt cel dintâi” — n-am tată; „și Eu sunt cel din urmă” — n-am fiu/frate; „și în afară de Mine nu este alt dumnezeu” — n-am asociat."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"כֹּה־אָמַר יְהוָה מֶלֶךְ־יִשְׂרָאֵל...","translation":"„Așa a spus DOMNUL, Regele lui Israel...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"Οὕτως λέγει ὁ Θεὸς ὁ βασιλεὺς τοῦ Ἰσραὴλ ὁ ῥυσάμενος αὐτὸν Θεὸς σαβαώθ· ἐγὼ πρῶτος καὶ ἐγὼ μετὰ ταῦτα· πλὴν ἐμοῦ οὐκ ἔστι Θεός.","greek":true,"translation":"„Așa zice Dumnezeu, Împăratul lui Israel, Cel ce l-a izbăvit, Dumnezeu Savaot: Eu sunt Cel dintâi și Eu sunt după acestea; în afară de Mine nu este Dumnezeu.”","note":"Corespondență apropiată de sens, cu variație minoră: LXX redă „Eu sunt cel din urmă” (aharon) prin expresia „Eu sunt după acestea” — o formulare mai puțin simetrică decât perechea ebraică „rișon/aharon” (cel dintâi/cel din urmă)."}],"refs":["Isaia 41:4","Isaia 48:12","Apocalipsa 22:13","Deuteronom 32:39","Deuteronom 6:4","Isaia 33:22"]},{"v":"44:7","t":"Cine este capabil să spună că el, ca și Mine, poate proclama ordinea lucrurilor de când Mi-am întemeiat poporul? Să spună ce miracole se vor mai întâmpla!","tokens":[{"t":"Cine este capabil să spună că el, ca și Mine, poate proclama ordinea lucrurilor de când Mi-am întemeiat poporul? Să spună "},{"t":"ce miracole","w":"ce miracole","heb":"וְאֹתִיּוֹת","translit":"veotiot","strong":"H226","pos":"verb, qal participiu","def_ro":"și semnele, și minunile.","greek":"τὰ ἐπερχόμενα (ta eperchomena)","greek_def_ro":"τὰ ἐπερχόμενα (ta eperchomena) — cele ce vor veni, semnele viitoare.","dict_ro":"Ot (plural otiyot) — „semn”, cuvântul folosit și pentru minunile din Egipt (Exodul 4:8-9) sau pentru semnele cerești (Geneza 1:14); Rashi îl citește aici ca „cuvinte de minune”, adică profeții care se vor confirma prin împlinire — capacitatea unică a lui Dumnezeu de a vesti dinainte evenimente ca eliberarea prin Cirus, la o vreme când nici Templul nu era distrus, nici exilul nu începuse, nici Cirus nu se născuse."},{"t":" se vor mai întâmpla!"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „și cine va vesti și va rândui înaintea Mea” tot ce s-a întâmplat „de când am întemeiat poporul veșnic” și până acum? „Otiyot” — cuvinte de minune; „și cele ce vor veni” — și lucrurile viitoare le va vesti, așa cum fac Eu acum, când Templul încă nu era dărâmat, voi nu erați exilați, Cirus nu se născuse, iar Eu vă vestesc despre el."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וּמִי־כָמוֹנִי יִקְרָא...","translation":"„Cine este capabil să spună că el, ca și Mine...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"τίς ὥσπερ ἐγώ; στήτω καὶ καλεσάτω καὶ ἀναγγειλάτω καὶ ἑτοιμασάτω μοι ἀφ᾽ οὗ ἐποίησα ἄνθρωπον εἰς τὸν αἰῶνα, καὶ τὰ ἐπερχόμενα πρὸ τοῦ ἐλθεῖν ἀναγγειλάτωσαν ὑμῖν.","greek":true,"translation":"„Cine este ca Mine? Să stea și să cheme și să vestească și să-Mi pregătească [dovada], de când am făcut omul pentru veșnicie, și cele ce vin, înainte să vină, să vi le vestească.”","note":"Divergență notabilă: Textul Masoretic vorbește despre întemeierea „poporului” (am-olam, „popor veșnic” — Israel), pe când Septuaginta extinde referința la crearea „omului” în general (ἄνθρωπον) — o universalizare reală a domeniului provocării divine, de la istoria lui Israel la istoria omenirii."}],"refs":["Isaia 46:9,10","Isaia 45:21","Isaia 48:3-8","Deuteronom 32:8","Faptele apostolilor 17:26","Isaia 41:22,26"]},{"v":"44:8","t":"Nu vă temeți, nu vă înspăimântați! Oare nu v-am anunțat și nu v-am vestit aceste lucruri de demult? Voi Îmi sunteți martori că nu există alt dumnezeu în afară de Mine și că nu există nicio stâncă pe care să nu o cunosc!","tokens":[{"t":"Nu vă temeți, nu vă înspăimântați! Oare nu v-am anunțat și nu v-am vestit aceste lucruri de demult? Voi Îmi sunteți "},{"t":"martori","w":"martori","heb":"עֵדָי","translit":"ēdai","strong":"H5707","pos":"substantiv, masculin plural construct + sufix","def_ro":"martorii Mei.","greek":"μάρτυς (martys)","greek_def_ro":"μάρτυς (martys) — martor.","dict_ro":"Ed (plural edim/edai) — termen juridic pentru martorul dintr-un proces; Israel e chemat aici, la fel ca la Isaia 43:10,12, să depună mărturie despre unicitatea lui Dumnezeu, nu pe baza unei speculații filosofice, ci a experienței istorice directe — Rashi leagă acest rol de revelația de la Sinai, unde șapte ceruri s-au deschis ca dovadă vizibilă."},{"t":" că nu există alt dumnezeu în afară de Mine și că nu există nicio stâncă pe care să nu o cunosc!"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „de la Sinai v-am vestit și v-am spus acolo că nu este alt dumnezeu în afară de Mine”; „și voi sunteți martorii Mei” — căci v-am deschis șapte ceruri și v-am arătat că nu este altul, iar voi sunteți martorii Mei în acest lucru. Iar „bal iadati” (targumul lui Ionatan): „și nu este tare afară de Cel de la care i se dă tărie oricărui tare”."},{"author":"Metzudat David","text":"„Nu vă temeți de alți dumnezei; la muntele Sinai v-am vestit și am arătat că nu este alt dumnezeu afară de Mine, iar voi sunteți martorii Mei în această privință, căci am deschis atunci șapte ceruri.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"אַל־תִּפְחֲדוּ וְאַל־תִּרְהוּ...","translation":"„Nu vă temeți, nu vă înspăimântați!...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"μὴ παρακαλύπτεσθε μηδὲ πλανᾶσθε· οὐκ ἀπ᾿ ἀρχῆς ἠνωτίσασθε καὶ ἀπήγγειλα ὑμῖν; μάρτυρες ὑμεῖς ἐστε, εἰ ἔτσι Θεὸς πλὴν ἐμοῦ.","greek":true,"translation":"„Nu vă ascundeți, nici nu vă rătăciți; oare nu de la început ați auzit și v-am vestit? Voi sunteți martori, dacă este Dumnezeu în afară de Mine.”","note":"Divergență lexicală reală: Textul Masoretic are „nu vă temeți, nu vă înspăimântați” (verbe de frică), pe când Septuaginta traduce „nu vă ascundeți, nu vă rătăciți” — o citire diferită a rădăcinii ebraice rare „רהה”, tradusă de traducătorii alexandrini nu ca teamă, ci ca rătăcire/eroare."}],"refs":["Isaia 43:10,12","1 Samuel 2:2","2 Samuel 22:32","Faptele apostolilor 1:8","Isaia 44:2"]},{"v":"44:9","t":"Făuritorii de idoli sunt cu toții pustii, iar lucrurile dragi lor nu sunt de niciun folos; ei mărturisesc despre ei înșiși, nu văd și nu cunosc, iar cei care îi venerează vor fi rușinați.","tokens":[{"t":"Făuritorii de "},{"t":"idoli","w":"idoli","heb":"פֶסֶל","translit":"fesel","strong":"H6459","pos":"substantiv, masculin singular","def_ro":"chip cioplit, idol.","diff_ro":"Septuaginta descrie aici făuritorii generic („cei care modelează și sculptează\"), fără un substantiv separat corespunzător exact lui „idoli\" (pesel) — accentul cade pe acțiune, nu pe obiect.","dict_ro":"Pesel — de la rădăcina „pasal” (a ciopli), desemnând orice imagine sculptată folosită ca obiect de cult, interzisă explicit în a doua poruncă (Exodul 20:4). Faptul că „mărturisesc despre ei înșiși” (edeihem hema) joacă ironic pe tema martorului din v.8 — idolii, martori muți și orbi ai propriei lor neputințe, contrastează direct cu Israel, martor viu al unui Dumnezeu care vede și cunoaște."},{"t":" sunt cu toții pustii, iar lucrurile dragi lor nu sunt de niciun folos; ei mărturisesc despre ei înșiși, nu văd și nu cunosc, iar cei care îi venerează vor fi rușinați."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „și martorii lor sunt aceștia” — chipurile cioplite sunt martorii rușinii închinătorilor lor, căci noi vedem că ele nu văd și nu cunosc, și totuși oamenii li se închinau; „ca ei să se rușineze” — cei care li se închină."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"יֹצְרֵי־פֶסֶל כֻּלָּם תֹּהוּ...","translation":"„Făuritorii de idoli sunt cu toții pustii...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ οὐκ ἦσαν τότε οἱ πλάσσοντες καὶ γλύφοντες πάντες μάταιοι οἱ ποιοῦντες τὰ καταθύμια αὐτῶν, ἃ οὐκ ὠφελήσει αὐτούς· ἀλλὰ αἰσχυνθήσονται.","greek":true,"translation":"„Și nu erau atunci cei ce plăsmuiesc și cioplesc, toți deșerți, cei ce fac după plăcerea inimii lor, lucruri care nu le vor folosi; ci se vor rușina.”","note":"Divergență structurală: Septuaginta leagă gramatical acest verset de contextul precedent («și nu erau atunci...»), o construcție sintactică diferită de afirmația directă și autonomă a Textului Masoretic («Făuritorii de idoli sunt cu toții pustii»)."}],"refs":["Ieremia 10:3-8,14,15","Psalmii 115:8","1 Corinteni 8:4","Isaia 41:24,29","Isaia 2:20,21"]},{"v":"44:10","t":"Cine ar modela un dumnezeu sau un idol turnat ce nu are vreun rost?","tokens":[{"t":"Cine ar modela un dumnezeu sau un idol "},{"t":"turnat","w":"turnat","heb":"נָסָךְ","translit":"nasah","strong":"H5257","pos":"verb, qal perfect","def_ro":"turnat, vărsat în tipar.","greek":"γλύφω (glypho)","greek_def_ro":"γλύφω (glypho) — a sculpta, a ciopli.","diff_ro":"Septuaginta folosește aici verbul general „a sculpta\" (γλύφοντες), nu un termen specific pentru „a turna\" (nasah) ca în ebraică.","dict_ro":"Nasach — de la rădăcina care înseamnă și „a turna” (metal topit) și „a vărsa” (o libație de vin), cu litera nun a rădăcinii care de fapt dispare la anumite forme flexionare (aceeași categorie ca „nașach” — a mușca sau „nagaf” — a lovi), o observație gramaticală pe care Rashi o notează explicit — idolul turnat era realizat prin vărsarea metalului topit într-un tipar."},{"t":" ce nu are vreun rost?"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"„Turnat” (nasah) — cuvânt de turnare și de idol turnat; nun-ul din cuvânt e o literă a rădăcinii care uneori cade, ca nun-ul din „a mușca” și din „a lovi”."},{"author":"Metzudat David","text":"„Cine ar face o asemenea prostie, să facă un dumnezeu și să toarne un idol fără niciun folos?”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"מִי־יָצַר אֵל וּפֶסֶל נָסָךְ...","translation":"„Cine ar modela un dumnezeu sau un idol turnat...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"πάντες οἱ πλάσσοντες Θεὸν καὶ γλύφοντες ἀνωφελῆ.","greek":true,"translation":"„Toți cei ce plăsmuiesc un dumnezeu și cioplesc [ceva] nefolositor.”","note":"Divergență de formă: Textul Masoretic pune întrebarea retorică („cine ar modela...?”), pe când Septuaginta o transformă într-o afirmație descriptivă generală despre „toți cei ce plăsmuiesc” — pierzând nuanța retorică a originalului."}],"refs":["1 Împărați 12:28","Ieremia 10:5","Daniel 3:1,14","Habacuc 2:18","Faptele apostolilor 19:26","1 Corinteni 8:4"]},{"v":"44:11","t":"Iată, toți cei care i se alătură vor fi rușinați, iar făuritorii [lui] sunt doar oameni! Să se adune și să stea în picioare și să se teamă și să se rușineze laolaltă!","tokens":[{"t":"Iată, toți cei care i se alătură vor fi rușinați, iar "},{"t":"făuritorii","w":"făuritorii","heb":"וְחָרָשִׁים","translit":"veharașim","strong":"H2796","pos":"substantiv, masculin plural","def_ro":"meșterii, artizanii.","diff_ro":"Septuaginta are aici „κωφοὶ\" („surzi/muți\"), nu „făuritorii\" (harașim, meșteșugari) ca în ebraică — probabil o confuzie veche între rădăcinile omografe „harash\" (meșteșugar) și „cheresh\" (surd), identice fără vocalizare în ebraica scrisă.","dict_ro":"Harash — termen general pentru orice meșteșugar (fierar, tâmplar, sculptor), aici cu accent polemic: cei care fac idolii „sunt doar oameni” (meadam), muritori limitați, deci incapabili prin definiție să confere putere divină obiectului pe care îl modelează — argumentul central al întregii polemici din capitol."},{"t":" [lui] sunt doar oameni! Să se adune și să stea în picioare și să se teamă și să se rușineze laolaltă!"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „toți tovarășii lui” — ai acelui meșter care modelează și toarnă idoli, cei care se alătură lui ca să se închine lucrării și turnăturii lui, vor fi rușinați; „iar meșterii aceștia sunt [doar] oameni” — cu atât mai mult lucrarea lor, care e deșertăciune."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"הֵן כָּל־חֲבֵרָיו יֵבֹשׁוּ...","translation":"„Iată, toți cei care i se alătură vor fi rușinați...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ πάντες ὅθεν ἐγένοντο ἐξηράνθησαν, καὶ κωφοὶ ἀπὸ ἀνθρώπων συναχθήτωσαν πάντες καὶ στησάτωσαν ἅμα, ἐντραπήτωσαν καὶ αἰσχυνθήτωσαν ἅμα.","greek":true,"translation":"„Și toți din care s-au născut s-au uscat, și surzii dintre oameni să se adune toți și să stea împreună, să se rușineze și să fie făcuți de ocară împreună.”","note":"Divergență lexicală notabilă: Textul Masoretic vorbește despre „tovarășii/asociații” idolului care se rușinează; Septuaginta introduce imaginea „surzilor” (κωφοί) — o traducere diferită a termenului ebraic dificil, posibil legată de o interpretare a rădăcinii ca referindu-se la incapacitatea de a auzi/răspunde."}],"refs":["Isaia 45:16","Ieremia 10:14","Psalmii 97:7","Isaia 1:29"]},{"v":"44:12","t":"Un fierar își face unealta și lucrează cu cărbune și făurește cu lovituri de ciocan, îl modelează cu toată puterea brațului său; chiar dacă flămânzește sau nu are putere, nu bea apă și vlăguiește.","tokens":[{"t":"Un "},{"t":"fierar","w":"fierar","heb":"חָרַשׁ","translit":"haraș","strong":"H2796","pos":"substantiv, masculin singular construct","def_ro":"meșter în fier, fierar.","greek":"τέκτων (tekton)","greek_def_ro":"τέκτων (tekton) — meșteșugar, lucrător (în general).","diff_ro":"Septuaginta folosește un termen general pentru „meșteșugar\" (τέκτων), nu unul specific pentru lucrătorul în fier ca în ebraică.","dict_ro":"Harash barzel — „meșterul fierului”, literalmente. Metzudat David subliniază ironia detaliului final: meșterul care modelează „dumnezeul” devine el însuși, în timpul lucrului, slab, înfometat și vlăguit — cel care are nevoie de hrană și apă ca să supraviețuiască pretinde să dea naștere unei ființe pretins atotputernice."},{"t":" își face unealta și lucrează cu cărbune și făurește cu lovituri de ciocan, îl modelează cu toată puterea brațului său; chiar dacă flămânzește sau nu are putere, nu bea apă și vlăguiește."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"„Fierarul” — făuritorul de fier. „Unealta” — una din uneltele fierarilor. „Și lucrează” — chipul cioplit. „Pe cărbuni” — cărbune. „Și cu ciocanele” — ciocan. „Îl întocmește” — cuvânt de închipuire. „Și îl lucrează cu brațul lui puternic; dar îi e foame...” — chiar el, făuritorul, e lipsit de putere și slab: dacă îi e foame, n-are putere, sau dacă n-a băut apă, obosește îndată; cu atât mai mult lucrarea lui nu poate fi de niciun folos."},{"author":"Metzudat David","text":"Meșterul de fier face un topor și lucrează cu cărbuni, îl modelează cu ciocanele, punând toată puterea brațului în lucrare — chiar dacă flămânzește, nu-și lasă lucrul, iar dacă însetează și n-a băut apă, ajunge vlăguit dintr-o dată — cu atât mai mult lucrarea lui n-are nicio putere să ajute pe altcineva."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"חָרַשׁ בַּרְזֶל מַעֲצָד...","translation":"„Un fierar își face unealta...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ὅτι ὤξυνε τέκτων σίδηρον, σκεπάρνῳ εἰργάσατο αὐτὸ καὶ ἐν τερέτρῳ ἔστησεν αὐτό, εἰργάσατο αὐτὸ ἐν τῷ βραχίονι τῆς ἰσχύος αὐτοῦ· καὶ πεινάσει καὶ ἀσθενήσει καὶ οὐ μὴ πίῃ ὕδωρ.","greek":true,"translation":"„Căci meșterul a ascuțit fierul, l-a lucrat cu securea și l-a fixat cu sfredelul, l-a lucrat cu brațul puterii sale; și va flămânzi și va slăbi și nu va bea apă.”","note":"Corespondență generală cu Textul Masoretic, cu unelte specifice redate diferit (securea/sfredelul grecesc versus ciocanul ebraic)."}],"refs":["Isaia 40:19","Isaia 41:6,7","Exod 32:4,8","Ieremia 10:3-11","Habacuc 2:13"]},{"v":"44:13","t":"Un tâmplar măsoară cu linia, își însemnează forma cu cretă, rindeluiește și o marchează cu compasul; o face în formă de bărbat, de om în splendoarea sa, de așezat în casă.","tokens":[{"t":"Un tâmplar măsoară cu linia, își însemnează forma cu cretă, rindeluiește și o marchează cu compasul; o face în formă de bărbat, de om în "},{"t":"splendoarea","w":"splendoarea","heb":"כְּתִפְאֶרֶת","translit":"ketiferet","strong":"H8597","pos":"substantiv, feminin singular construct","def_ro":"podoaba, frumusețea, splendoarea.","greek":"ὡραιότης (horaiotes)","greek_def_ro":"ὡραιότης (horaiotes) — frumusețe, splendoare.","dict_ro":"Tiferet — Metzudat David citește aici „tiferet adam” (splendoarea omului) ca referire la femeie — „ea este podoaba bărbatului ei” — meșterul dând idolului forma cea mai frumoasă cunoscută lui, aceea a chipului omenesc idealizat, ca să fie potrivit de stat în casă."},{"t":" sa, de așezat în casă."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi detaliază uneltele tâmplarului: „netiat kav” — după obiceiul tâmplarilor, cu firul întins; „yetaarehu vasered” — îl netezește cu fierăstrăul; „bamaketzot” — îl șlefuiește cu rindeaua și dalta, tradus de Targum Ionatan „izmelaya”; „uvamehuga” — dacă vrea să facă forme rotunde, îl învârte cu compasul."},{"author":"Metzudat David","text":"„Ktiferet adam” — aceasta este femeia, care e podoaba soțului ei; iar întreaga muncă arată că omul n-a făcut niciodată idolul ca să stea în casă din alt motiv decât ca să-l vadă frumos, ca pe un chip de om."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"חָרַשׁ עֵצִים נָטָה קָו...","translation":"„Un tâmplar măsoară cu linia...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ἐκλεξάμενος τέκτων ξύλον ἔστησεν αὐτὸ ἐν μέτρῳ καὶ ἐν κόλλῃ ἐρρύθμισεν αὐτὸ καὶ ἐποίησεν αὐτὸ ὡς μορφὴν ἀνδρὸς καὶ ὡς ὡραιότητα ἀνθρώπου στῆσαι αὐτὸ ἐν οἴκῳ.","greek":true,"translation":"„Alegând lemnul, tâmplarul l-a măsurat și l-a potrivit cu clei și l-a făcut în chip de bărbat și ca frumusețea omului, ca să-l așeze în casă.”","note":"Divergență reală: Textul Masoretic menționează măsurarea cu „compasul” (mehuga) pentru forme rotunjite, pe când Septuaginta vorbește despre fixarea cu „clei” (κόλλῃ) — instrumente și tehnici de lucru redate diferit între cele două tradiții textuale."}],"refs":["Exod 20:4,5","Romani 1:23","Judecători 17:4,5","Ezechiel 8:12","Geneza 31:19,30,32","Deuteronom 4:16-18,28"]},{"v":"44:14","t":"Taie el însuși cedri, ia gorun și stejar și-i întărește cu copaci din pădure; plantează un pin, iar ploaia îl face să crească.","tokens":[{"t":"Taie el însuși cedri, ia gorun și stejar și-i întărește cu copaci din pădure; "},{"t":"plantează","w":"plantează","heb":"נָטַע","translit":"nata","strong":"H5193","pos":"verb, qal perfect","def_ro":"a sădit, a plantat.","diff_ro":"Septuaginta comprimă mult acest verset și, surprinzător, atribuie plantarea Domnului („ὃ ἐφύτευσε Κύριος\"), nu idolatrului care își taie lemnul, ca în ebraică — probabil o lectură diferită a subiectului gramatical.","dict_ro":"Nata — Metzudat David observă aici o ironie suplimentară, dincolo de tăierea copacilor deja crescuți: unii meșteri merg mai departe și plantează chiar ei un pui de pin anume pentru acest scop, așteptând ani de zile să crească — o investiție de efort și timp cu atât mai absurdă, dată fiind ținta finală."},{"t":" un pin, iar ploaia îl face să crească."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „tirza” și „alon” — specii de copaci sălbatici, fără rod; „îi întărește cu copaci din pădure” — le adaugă tărie, fie pentru soliditate, fie pentru frumusețe, cu specii de lemn diferite unele de altele la înfățișare."},{"author":"Metzudat David","text":"Mai sus s-a vorbit despre lucrarea idolului dintr-un copac deja tăiat; acum se arată că unii merg și mai departe: taie cedri, iau gorun și stejar, îi întăresc cu alți copaci — și unul chiar sădește dinadins un pin, așteptând ca ploaia să-l facă să crească, tocmai pentru acest scop."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"לִכְרָת־לוֹ אֲרָזִים...","translation":"„Taie el însuși cedri...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ἔκοψε ξύλον ἐκ τοῦ δρυμοῦ, ὃ ἐφύτευσε Κύριος καὶ ὑετὸς ἐμήκυνεν.","greek":true,"translation":"„A tăiat lemn din pădure, pe care l-a sădit Domnul și ploaia l-a făcut să crească.”","note":"Divergență teologică reală și semnificativă: Textul Masoretic atribuie plantarea copacului meșterului însuși („nata” — el a plantat), pe când Septuaginta face din DOMNUL subiectul plantării („ὃ ἐφύτευσε Κύριος” — pe care l-a sădit Domnul) — o schimbare care adaugă o ironie suplimentară textului grecesc: chiar copacul din care omul își face idolul a fost sădit de adevăratul Dumnezeu."}],"refs":["Isaia 40:20","Ieremia 10:3-8","Osea 4:12","Habacuc 2:19"]},{"v":"44:15","t":"El va fi [lemn de foc] omului, va lua din ei și se va încălzi, chiar va aprinde foc și va coace pâine – și apoi va face un dumnezeu căruia i se va prosterna, va face din el chip cioplit și îl va venera.","tokens":[{"t":"El va fi [lemn de foc] omului, va lua din ei și se va încălzi, chiar va aprinde foc și va coace pâine – și apoi va face un "},{"t":"dumnezeu","w":"dumnezeu","heb":"אֵל","translit":"ēl","strong":"H410","pos":"substantiv, masculin singular","def_ro":"dumnezeu, ființă divină.","greek":"θεός (theos)","greek_def_ro":"θεός (theos) — dumnezeu (zeu).","dict_ro":"El — cel mai general termen semitic pentru „dumnezeu/zeitate”, aici folosit ironic pentru un obiect din același lemn cu care omul tocmai și-a copt pâinea — Isaia insistă asupra identității materiale totale între combustibilul banal și obiectul de cult, distrugând orice pretenție de sacralitate intrinsecă a materiei."},{"t":" căruia i se va prosterna, va face din el chip cioplit și îl va venera."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: acel lemn „va fi pentru om spre a-l arde” — din el va lua omul și se va încălzi la foc, chiar va aprinde din el cuptorul și va coace pâine; „af-yifal-el” — și din ce a rămas [dincolo de ce a folosit ca lemn de foc]."},{"author":"Metzudat David","text":"Din același copac, o parte va fi folosită de om ca lemn de foc — va lua din el, se va încălzi, va aprinde cuptorul și va coace pâine cu el — iar din rest va face un dumnezeu, i se va prosterna, îl va face chip cioplit și i se va închina."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְהָיָה לְאָדָם לְבָעֵר...","translation":"„El va fi [lemn de foc] omului...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ἵνα ᾖ ἀνθρώποις εἰς καῦσιν· καὶ λαβὼν ἀπ᾿ αὐτοῦ ἐθερμάνθη, καὶ καύσαντες ἔπεψαν ἄρτους ἐπ᾿ αὐτῶν, τὸ δὲ λοιπὸν εἰργάσαντο θεούς, καὶ προσκυνοῦσιν αὐτοῖς.","greek":true,"translation":"„Ca să fie oamenilor spre ardere; și luând din el s-a încălzit, și arzând au copt pâini pe ele, iar restul l-au lucrat în dumnezei, și li se închină lor.”","note":"Divergență de număr: Textul Masoretic vorbește la singular despre „un dumnezeu” (el) făcut de un singur om, pe când Septuaginta pluralizează în „dumnezei” (θεούς) cărora „li se închină” la plural — o generalizare a practicii idolatre de la un caz individual la o practică colectivă."}],"refs":["Isaia 44:10","Isaia 45:20","2 Cronici 25:14","Apocalipsa 9:20"]},{"v":"44:16","t":"Jumătate din el îl arde în foc, cu jumătate gătește carne să mănânce, frigând-o și săturându-se; se și încălzește și spune: „Ah, m-am încălzit, mă bucur de foc!”","tokens":[{"t":"Jumătate din el îl arde în foc, cu jumătate gătește carne să mănânce, frigând-o și săturându-se; se și încălzește și spune: „Ah, "},{"t":"m-am încălzit","w":"m-am încălzit","heb":"חַמּוֹתִי","translit":"hamoti","strong":"H2552","pos":"verb, qal perfect","def_ro":"m-am încălzit.","greek":"θερμαίνομαι (thermainomai)","greek_def_ro":"θερμαίνομαι (thermainomai) — a se încălzi.","dict_ro":"Ham — verb comun, banal, descriind pur și simplu senzația fizică de căldură lângă foc; forța retorică a versetului stă tocmai în banalitatea absolută a exclamației — omul rostește aceleași cuvinte simple, satisfăcute, indiferent dacă lemnul care arde e destinat gătitului sau, în versetul următor, dacă restul aceluiași lemn devine „dumnezeul” lui."},{"t":", mă bucur de foc!”"}],"commentaries":[{"author":"Metzudat David","text":"Cu o parte din lemn arde direct focul, cu altă parte frige carne pe care o mănâncă și se satură; iar el, încălzindu-se, se bucură și spune: «Ah, m-am încălzit, mă bucur privind focul!»"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"חֶצְיוֹ שָׂרַף בְּמוֹ־אֵשׁ...","translation":"„Jumătate din el îl arde în foc...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"οὗ τὸ ἥμισυ αὐτοῦ κατέκαυσεν ἐν πυρὶ καὶ καύσαντες ἔπεψαν ἄρτους ἐπ᾿ αὐτῶν· καὶ ἐπ᾿ αὐτοῦ κρέας ὀπτήσας ἔφαγε καὶ ἐνεπλήσθη, καὶ θερμανθεὶς εἶπεν· ἡδύ μοι ὅτι ἐθερμάνθην καὶ εἶδον πῦρ.","greek":true,"translation":"„Din care jumătate a ars-o în foc și, arzând, au copt pâini pe ea; și pe ea a fript carne și a mâncat și s-a săturat, și încălzindu-se a zis: plăcut îmi este că m-am încălzit și am văzut focul.”","note":"Septuaginta adaugă explicit coacerea pâinii la acest verset (element absent aici în Textul Masoretic, unde apăruse deja la v.15/19), o dublare armonizantă între versete, probabil din tendința traducătorilor de a completa lista completă a folosințelor lemnului la fiecare menționare."}],"refs":[]},{"v":"44:17","t":"Iar cu restul își face un dumnezeu ca și chip cioplit, se înclină în fața lui, se prosternează și se roagă la el și spune: „Salvează-mă, căci tu ești dumnezeul meu!”","tokens":[{"t":"Iar cu "},{"t":"restul","w":"restul","heb":"וּשְׁאֵרִיתוֹ","translit":"ușērito","strong":"H7611","pos":"substantiv, feminin singular construct + sufix","def_ro":"rămășița lui, ce a mai rămas din el.","greek":"λοιπός (loipos)","greek_def_ro":"λοιπός (loipos) — rest, rămășiță.","dict_ro":"Șeerit — „rămășița”, un cuvânt care în alte contexte profetice (Isaia 10:20-22) desemnează cu speranță „rămășița lui Israel” care va supraviețui judecății; aici, folosit despre bucata de lemn rămasă neconsumată de foc, cuvântul devine o ironie amară — „rămășița” care ar trebui să poarte speranța de mântuire devine, în chip absurd, obiectul din care e sculptat „mântuitorul” fals, căruia i se cere „salvează-mă”."},{"t":" își face un dumnezeu ca și chip cioplit, se înclină în fața lui, se prosternează și se roagă la el și spune: „Salvează-mă, căci tu ești dumnezeul meu!”"}],"commentaries":[{"author":"Metzudat David","text":"„Din ce a mai rămas din lemn, face un dumnezeu — își face din el un chip cioplit — se prosternează în fața lui, se roagă la el și spune: «Salvează-mă, căci tu ești dumnezeul meu.»”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וּשְׁאֵרִיתוֹ לְאֵל עָשָׂה...","translation":"„Iar cu restul își face un dumnezeu...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"τὸ δὲ λοιπὸν ἐποίησεν εἰς θεὸν γλυπτὸν καὶ προσκυνεῖ αὐτῷ καὶ προσεύχεται λέγων· ἐξελοῦ με, ὅτι θεός μου εἶ σύ.","greek":true,"translation":"„Iar din rest a făcut dumnezeu cioplit și i se închină și se roagă lui, zicând: izbăvește-mă, căci dumnezeul meu ești tu.”","note":"Corespondență apropiată cu Textul Masoretic."}],"refs":["Isaia 36:19,20","Isaia 37:38","Daniel 3:17,29","Daniel 6:16,20-22,27"]},{"v":"44:18","t":"Ei nu știu și nu înțeleg; un văl le acoperă ochii ca să nu vadă și inimile ca să nu priceapă.","tokens":[{"t":"Ei nu știu și nu înțeleg; un "},{"t":"văl","w":"văl","heb":"טַח","translit":"tah","strong":"H2902","pos":"verb, qal perfect","def_ro":"e tencuit, e lipit, e astupat.","greek":"ἀπαμαυρόομαι (apamauroomai)","greek_def_ro":"ἀπαμαυρόομαι (apamauroomai) — a fi întunecat, a fi făcut să nu vadă.","diff_ro":"Septuaginta are un verb („au fost întunecați/orbiți\"), nu imaginea nominală a unui „văl/tencuială\" (tach) peste ochi, ca în ebraică — aceeași idee de orbire, exprimată diferit gramatical.","dict_ro":"Tah — de la rădăcina „a tencui/a lipi” (aceeași folosită pentru tencuirea unui zid), o imagine puternică: nu e vorba de o simplă lipsă de vedere, ci de o acoperire activă, ca un strat de tencuială lipit peste ochi, care blochează complet percepția. Metzudat David atribuie această orbire înclinației spre rău (yetzer hara) din inima omului, care „tencuiește” singură ochii de la a vedea adevărul."},{"t":" le acoperă ochii ca să nu vadă și inimile ca să nu priceapă."}],"commentaries":[{"author":"Metzudat David","text":"„Nu au nici cunoștință, nici înțelegere — înclinația rea [yetzer hara] care îi ademenește le-a tencuit ochii ca să nu vadă și inimile ca să nu priceapă.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"לֹא יָדְעוּ וְלֹא יָבִינוּ...","translation":"„Ei nu știu și nu înțeleg...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"οὐκ ἔγνωσαν φρονῆσαι, ὅτι ἀπημαυρώθησαν τοῦ βλέπειν τοῖς ὀφθαλμοῖς αὐτῶν καὶ τοῦ νοῆσαι τῇ καρδίᾳ αὐτῶν.","greek":true,"translation":"„N-au cunoscut ca să priceapă, căci li s-au întunecat ochii ca să nu vadă și inima ca să nu înțeleagă.”","note":"Corespondență de sens cu Textul Masoretic, cu o nuanță diferită de imagine: LXX vorbește despre „întunecare” (ἀπημαυρώθησαν), Textul Masoretic despre o acoperire/tencuire fizică a ochilor (tah)."}],"refs":["Isaia 6:10","Matei 13:14,15","Ioan 12:39,40","Isaia 29:10","Isaia 44:9,20","Isaia 56:11"]},{"v":"44:19","t":"Niciunul nu-i dă replică propriei inimi, nu au înțelepciune sau discernământ să-și spună: „Am ars în foc jumătate din el și am copt pâine pe cărbunii lui, am fript carne și am mâncat-o – pot oare să fac o oroare din restul [lemnului], pot oare să mă prosternez la ramura unui copac?”","tokens":[{"t":"Niciunul nu-i dă replică propriei inimi, nu au înțelepciune sau discernământ să-și spună: „Am ars în foc jumătate din el și am copt pâine pe cărbunii lui, am fript carne și am mâncat-o – pot oare să fac o "},{"t":"oroare","w":"oroare","heb":"לְתוֹעֵבָה","translit":"letoēva","strong":"H8441","pos":"substantiv, feminin singular","def_ro":"urâciune, lucru dezgustător ritual.","greek":"βδέλυγμα (bdelygma)","greek_def_ro":"βδέλυγμα (bdelygma) — urâciune, lucru detestabil.","dict_ro":"Toeva — termenul tehnic pentru „urâciune” folosit constant în Tora pentru practicile idolatre și ritualurile interzise (cf. Deuteronomul 7:25-26). Ironia versetului e maximă aici: bucata de lemn deja identificată, fără ambiguitate, ca fiind aceeași cu cea folosită pentru gătit — recunoscută de omul însuși ca material banal — devine totuși, prin propria lui alegere absurdă, obiectul unei „urâciuni” pe care el singur o creează și i se închină."},{"t":" din restul [lemnului], pot oare să mă prosternez la ramura unui copac?”"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „nu-i dă replică inimii lui” [să spună]: «jumătate din el l-am ars în foc»; „nu are nici cunoștință, nici discernământ” să spună acest lucru; „levul etz” — spre putrezirea lemnului mă prosternez."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְלֹא־יָשִׁיב אֶל־לִבּוֹ...","translation":"„Niciunul nu-i dă replică propriei inimi...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ οὐκ ἐλογίσατο τῇ καρδίᾳ αὐτοῦ οὐδὲ ἀνελογίσατο ἐν τῇ ψυχῇ αὐτοῦ οὐδὲ ἔγνω τῇ φρονήσει, ὅτι τὸ ἥμισυ αὐτοῦ κατέκαυσεν ἐν πυρὶ καὶ ἔπεψεν ἐπὶ τῶν ἀνθράκων αὐτοῦ ἄρτους καὶ ὀπτήσας κρέα ἔφαγε καὶ τὸ λοιπὸν αὐτοῦ εἰς βδέλυγμα ἐποίησε καὶ προσκυνοῦσιν αὐτῷ.","greek":true,"translation":"„Și nu a cugetat în inima lui, nici n-a socotit în sufletul lui, nici n-a cunoscut cu mintea, că jumătate din el l-a ars în foc și a copt pâini pe cărbunii lui și a fript și a mâncat carne, iar din rest a făcut urâciune și i se închină.”","note":"Corespondență apropiată de sens; Septuaginta redă tot la persoana a III-a narativă, unde Textul Masoretic trece la vorbire directă («am ars», «am copt») în interiorul citatului ipotetic al gândului nerostit."}],"refs":["Isaia 46:8","Deuteronom 27:15","1 Împărați 11:5,7","2 Împărați 23:13","Hagai 1:5","Osea 7:2"]},{"v":"44:20","t":"Păstorul lor este doar cenușă, inima lui înșelătoare l-a condus greșit; nici măcar nu se poate salva, dar totuși nu spune: „Ce țin în mâna mea dreaptă este o minciună!”","tokens":[{"t":"Păstorul lor este doar "},{"t":"cenușă","w":"cenușă","heb":"אֵפֶר","translit":"ēfer","strong":"H665","pos":"substantiv, masculin singular","def_ro":"cenușă.","greek":"σποδός (spodos)","greek_def_ro":"σποδός (spodos) — cenușă.","dict_ro":"Efer — cenușa, ceea ce rămâne după arderea completă a jumătății de lemn (v.16,19). Rashi oferă o a doua lectură pentru „roe efer” („păstor de cenușă”): nu doar „păstorul lui e cenușă”, ci o joacă de cuvinte pe rădăcina „reut” (tovărășie/asociere) — omul „se asociază cu” lucrarea altora, adunând la sine o slujire care nu e decât cenușă."},{"t":", inima lui înșelătoare l-a condus greșit; nici măcar nu se poate salva, dar totuși nu spune: „Ce țin în mâna mea dreaptă este o minciună!”"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „inima lui înșelătoare” — nebunul acesta credea că are un păstor și un purtător de grijă [în idol]; altă interpretare: „roe efer” din rădăcina „reut” (tovărășie) — slujește lucrarea altora și adună la sine slujirea altora, care e doar cenușă."},{"author":"Metzudat David","text":"„Nici măcar sufletul propriu nu și-l poate salva, rătăcitul, ca să spună: «oare nu-i minciună ce țin în dreapta mea?» — și să se despartă de idol.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"רֹעֶה אֵפֶר לֵב הוּתַל הִטָּהוּ...","translation":"„Păstorul lor este doar cenușă...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"γνῶθι ὅτι σποδὸς ἡ καρδία αὐτῶν, καὶ πλανῶνται, καὶ οὐδεὶς δύναται ἐξελέσθαι τὴν ψυχὴν αὐτοῦ· ἴδετε, οὐκ ἐρεῖτε ὅτι ψεῦδος ἐν τῇ δεξιᾷ μου;","greek":true,"translation":"„Cunoaște că inima lor este cenușă, și se rătăcesc, și nimeni nu-și poate izbăvi sufletul; vedeți, nu veți zice: oare nu e minciună în dreapta mea?”","note":"Divergență reală de subiect: Textul Masoretic vorbește despre „păstorul” (roe) ca fiind cenușă, o imagine despre idolul-păstor fals; Septuaginta mută accentul direct pe „inima lor” (ἡ καρδία αὐτῶν) ca fiind cenușă — deplasând imaginea de la obiectul închinat la starea internă a închinătorului."}],"refs":["Osea 12:1","Iov 15:31","2 Tesaloniceni 2:11","Isaia 28:15-17","Ieremia 16:19","Iov 15:2"]},{"v":"44:21","t":"Amintește-ți de aceasta, Iacov și Israel, căci tu ești slujitorul Meu – te-am făurit să fii slujitorul Meu – Israele, nu mă uita!","tokens":[{"t":"Amintește-ți de aceasta, Iacov și Israel, căci tu ești slujitorul Meu – te-am făurit să fii slujitorul Meu – Israele, nu mă "},{"t":"uita","w":"uita","heb":"תִנָּשֵׁנִי","translit":"tinașēni","strong":"H5382","pos":"verb, nifal imperfect + sufix","def_ro":"nu Mă vei uita, nu vei fi uitat de Mine.","greek":"ἐπιλανθάνομαι (epilanthanomai)","greek_def_ro":"ἐπιλανθάνομαι (epilanthanomai) — a uita.","dict_ro":"Nașa — verbul „a uita”, aici la o formă nifal ambiguă gramatical, pe care Rashi o citește ca „nu vei fi uitat de frica Mea” — nu doar un îndemn pasiv de a nu uita, ci o asigurare că legătura poporului cu DOMNUL nu se va stinge din memorie, oricât ar fi ea amenințată de idolatria descrisă anterior."},{"t":"!"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „nu vei fi uitat” de frica Mea."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"זְכָר־אֵלֶּה יַעֲקֹב וְיִשְׂרָאֵל...","translation":"„Amintește-ți de aceasta, Iacov și Israel...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"Μνήσθητι ταῦτα Ἰακὼβ καὶ Ἰσραήλ, ὅτι παῖς μου εἶ σύ· ἔπλασά σε παῖδά μου, καὶ σὺ Ἰσραὴλ μὴ ἐπιλανθάνου μου.","greek":true,"translation":"„Adu-ți aminte de acestea, Iacove și Israele, căci slujitorul Meu ești tu; te-am plăsmuit slujitorul Meu, și tu, Israele, nu Mă uita.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Isaia 44:1,2","Deuteronom 32:18","Isaia 49:15,16","Isaia 41:8,9"]},{"v":"44:22","t":"Am șters păcatele tale ca o negură și greșelile tale ca un nor. Întoarce-te la Mine, căci te-am răscumpărat.","tokens":[{"t":"Am șters păcatele tale ca o negură și greșelile tale ca un nor. "},{"t":"Întoarce-te","w":"Întoarce-te","heb":"שׁוּבָה","translit":"șuva","strong":"H7725","pos":"verb, qal imperativ + sufix","def_ro":"întoarce-te, revino.","greek":"ἐπιστρέφομαι (epistrephomai)","greek_def_ro":"ἐπιστρέφομαι (epistrephomai) — a se întoarce.","dict_ro":"Șuv — rădăcina din care vine și „teșuva” (pocăința/întoarcerea), termenul central al teologiei biblice a pocăinței. Ordinea logică a versetului e semnificativă: iertarea („am șters”) precede chemarea la întoarcere, nu invers — DOMNUL nu așteaptă pocăința ca precondiție a iertării, ci anunță întâi iertarea deja înfăptuită, ca temei și motivație pentru întoarcere."},{"t":" la Mine, căci te-am răscumpărat."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"„Ți-am șters fărădelegile ca un nor” — în Egipt și în pustie; și acum, întoarce-te la Mine."},{"author":"Metzudat David","text":"„Dintotdeauna am șters păcatele tale ca acest nor care se șterge cu apa — de aceea, întoarce-te la Mine, căci Eu sunt Cel care te răscumpără.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"מָחִיתִי כֶעָב פְּשָׁעֶיךָ...","translation":"„Am șters păcatele tale ca o negură...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ἰδοὺ γὰρ ἀπήλειψα ὡς νεφέλην τὰς ἀνομίας σου καὶ ὡς γνόφον τὰς ἁμαρτίας σου· ἐπιστράφηθι πρός με, καὶ λυτρώσομαί σε.","greek":true,"translation":"„Căci iată, am șters ca un nor nelegiuirile tale și ca o negură păcatele tale; întoarce-te la Mine, și te voi răscumpăra.”","note":"Divergență de timp verbal reală: Textul Masoretic are „te-am răscumpărat” (gealticha, perfect — răscumpărarea deja înfăptuită), pe când Septuaginta are „λυτρώσομαί σε” (viitor — «te voi răscumpăra») — o schimbare temporală care mută promisiunea răscumpărării din trecutul deja asigurat spre un viitor condiționat de întoarcere."}],"refs":["Isaia 43:25","Psalmii 103:12","Osea 14:1-4","Faptele apostolilor 3:19","Isaia 1:18","Iov 37:11"]},{"v":"44:23","t":"Cântați cântare veselă, cerurilor, pentru ce a făcut DOMNUL! Strigă, miez al pământului! Izbucniți, munților, în cântec vesel, pădure și fiecare copac din ea! Căci DOMNUL l-a răscumpărat pe Iacov, și în Israel va fi slăvit.","tokens":[{"t":"Cântați cântare veselă, cerurilor, pentru ce a făcut DOMNUL! Strigă, miez al pământului! "},{"t":"Izbucniți","w":"Izbucniți","heb":"פִּצְחוּ","translit":"pițhu","strong":"H6476","pos":"verb, qal imperativ","def_ro":"izbucniți, spargeți tăcerea.","greek":"βοάω (boao)","greek_def_ro":"βοάω (boao) — a striga, a izbucni în strigăt.","dict_ro":"Patzah — verbul descrie o izbucnire bruscă, ca o deschidere forțată (aceeași rădăcină apare pentru „a deschide gura larg” la Judecători 11:35-36) — nu o simplă bucurie liniștită, ci o erupție copleșitoare, care implică deopotrivă cerurile, adâncurile pământului, munții și pădurea într-un cor cosmic al răscumpărării — natura însăși devine martoră și participantă la eliberarea lui Iacov."},{"t":", munților, în cântec vesel, pădure și fiecare copac din ea! Căci DOMNUL l-a răscumpărat pe Iacov, și în Israel va fi slăvit."}],"commentaries":[{"author":"Metzudat David","text":"„Ranu șamayim” — e o figură de stil, arătând bucuria mare care va fi în lume; „tahtiyot aretz” — punctul median al globului pământesc; „yaar” — locul unde stau copacii; „uveIsraël yitpaar” — prin răscumpărarea lui Israel, El va fi slăvit în gura tuturor."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"רָנּוּ שָׁמַיִם כִּי־עָשָׂה יְהוָה...","translation":"„Cântați cântare veselă, cerurilor...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"εὐφράνθητε, οὐρανοί, ὅτι ἠλέησεν ὁ Θεός τὸν Ἰσραήλ· σαλπίσατε, τὰ θεμέλια τῆς γῆς, βοήσατε, ὄρη, εὐφροσύνην, οἱ βουνοὶ καὶ πάντα τὰ ξύλα τὰ ἐν αὐτοῖς, ὅτι ἐλυτρώσατο ὁ Θεὸς τὸν Ἰακώβ, καὶ Ἰσραὴλ δοξασθήσεται.","greek":true,"translation":"„Veseliți-vă, ceruri, căci Dumnezeu a avut milă de Israel; trâmbițați, temelii ale pământului, strigați, munților, de veselie, dealurilor și tuturor copacilor de pe ele, căci Dumnezeu l-a răscumpărat pe Iacov, și Israel va fi slăvit.”","note":"Divergență reală: acolo unde Textul Masoretic are „ki-asa ADONAI” („căci DOMNUL a lucrat/a făcut [aceasta]”, fără obiect explicit), Septuaginta precizează „ὅτι ἠλέησεν ὁ Θεός τὸν Ἰσραήλ” („căci Dumnezeu a avut milă de Israel”) — o completare interpretativă explicită a obiectului acțiunii divine, absentă din formularea ebraică mai laconică."}],"refs":["Psalmii 96:11,12","Psalmii 98:7,8","Isaia 49:13","Isaia 55:12,13","Isaia 42:10-12","Isaia 26:15"]}]},{"num":2,"title":"Țav - Poruncește","ref":"Ieremia 7:21-8:3, 9:23-24","intro":"Haftarat Țav oglindește invers pericopa Țav, dedicată în întregime regulilor precise ale jertfelor. Ieremia răstoarnă accentul: DOMNUL n-a cerut niciodată jertfa ca scop în sine, ci ascultarea — „ascultați de glasul Meu, ca să vă fiu Dumnezeu”. Refuzul acestei ascultări, culminând cu urâciunea copiilor arși în Valea lui Ben-Hinom, aduce o judecată descrisă în imagini din ce în ce mai sumbre: Tofetul devenit Valea Măcelului, oasele regilor scoase din morminte, hoiturile lăsate păsărilor. Haftara se încheie însă, ca de obicei, cu o notă care depășește judecata: adevărata laudă a omului nu stă în înțelepciune, putere sau bogăție, ci în cunoașterea DOMNULUI, care înfăptuiește bunăvoință, justiție și dreptate pe pământ.","verses":[{"v":"7:21","t":"Așa a spus DOMNUL Oștirilor, Dumnezeul lui Israel: „Îngrămădiți-vă arderile-de-tot peste jertfele voastre de pace și mâncați[-le] carnea.","tokens":[{"t":"Așa a spus DOMNUL Oștirilor, Dumnezeul lui Israel: „Îngrămădiți-vă "},{"t":"arderile-de-tot","w":"arderile-de-tot","heb":"עֹלוֹתֵיכֶם","translit":"olotēhem","strong":"H5930","pos":"substantiv, feminin plural construct + sufix","def_ro":"arderile voastre de tot.","greek":"ὁλοκαύτωμα (holokautoma)","greek_def_ro":"ὁλοκαύτωμα (holokautoma) — ardere-de-tot.","dict_ro":"Ola — jertfa mistuită integral pe altar, singura din care închinătorul nu mânca nimic (spre deosebire de zevah/jertfa de pace, din care o parte revenea celui ce o aducea). Ironia amară a versetului stă tocmai aici: DOMNUL spune „adăugați arderile de tot la jertfele de pace și mâncați carnea” — un îndemn absurd, pentru că arderea de tot, prin definiție, nu poate fi mâncată de nimeni; e felul lui Dumnezeu de a spune că ritualul lor, oricât de corect executat tehnic, nu mai are nicio valoare reală în ochii Lui."},{"t":" peste jertfele voastre de pace și mâncați[-le] carnea."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „arderile-de-tot” — pe care le aduceți în întregime, e mai bine pentru voi să le adăugați la jertfele voastre de pace, s-o aduceți ca jertfă de pace și să mâncați carnea, de vreme ce oricum nu-Mi sunt primite; de ce să le pierdeți degeaba?"},{"author":"Metzudat David","text":"„Arderile de tot pe care le aduceți, care sunt în întregime mistuite, adăugați-le la jertfele voastre de pace și mâncați carnea — de vreme ce arderile de tot nu-Mi sunt plăcute, de ce să pierdeți carnea?”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"כֹּה אָמַר יְהוָה צְבָאוֹת אֱלֹהֵי יִשְׂרָאֵל...","translation":"„Așa a spus DOMNUL Oștirilor, Dumnezeul lui Israel...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"τάδε λέγει Κύριος· τὰ ὁλοκαυτώματα ὑμῶν συναγάγετε μετὰ τῶν θυσιῶν ὑμῶν καὶ φάγετε κρέα.","greek":true,"translation":"„Așa zice Domnul: adunați-vă arderile de tot împreună cu jertfele voastre și mâncați carne.”","note":"Septuaginta omite epitetele „Oștirilor” și „Dumnezeul lui Israel” din formula de deschidere, păstrând doar „Κύριος” — o simplificare reală a titulaturii divine față de Textul Masoretic."}],"refs":["Ieremia 6:20","Isaia 1:11-15","Osea 8:13","Amos 5:21-23"]},{"v":"7:22","t":"Căci nu am vorbit strămoșilor voștri și nici nu le-am poruncit, în ziua când i-am scos din țara Egiptului, despre arderi-de-tot sau jertfe de pace,","tokens":[{"t":"Căci nu am vorbit strămoșilor voștri și nici nu le-am "},{"t":"poruncit","w":"poruncit","heb":"צִוִּיתִים","translit":"țivitim","strong":"H6680","pos":"verb, piel perfect + sufix","def_ro":"le-am poruncit.","greek":"ἐντέλλομαι (entellomai)","greek_def_ro":"ἐντέλλομαι (entellomai) — a porunci.","dict_ro":"Tzava — Rashi precizează limita exactă a afirmației: nu că porunca despre jertfe n-ar exista deloc (ea vine în Levitic), ci că nu aceasta a fost condiția inițială pusă la Sinai — condiția dintâi, dinaintea oricărei legi rituale, a fost simplu „ascultați de glasul Meu” (v.23), citând explicit Exodul 19:5. Jertfele sunt parte din Lege, dar nu temelia legământului."},{"t":", în ziua când i-am scos din țara Egiptului, despre arderi-de-tot sau jertfe de pace,"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"„În ziua când i-am scos” — începutul condiției n-a fost decât: „dacă veți asculta glasul Meu și dacă veți păzi legământul Meu, veți fi ai Mei dintre toate popoarele” (Exod 19:5)."},{"author":"Metzudat David","text":"„În ziua în care i-am scos din Egipt, nu le-am vorbit atunci despre jertfă și ardere de tot — și dacă scopul scoaterii lor din Egipt ar fi fost aducerea jertfelor, ar fi fost firesc să fie poruncite chiar atunci, în acea zi.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"כִּי לֹא־דִבַּרְתִּי אֶת־אֲבוֹתֵיכֶם...","translation":"„Căci nu am vorbit strămoșilor voștri...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ὅτι οὐκ ἐλάλησα πρὸς τοὺς πατέρας ὑμῶν καὶ οὐκ ἐνετειλάμην αὐτοῖς ἐν ἡμέρᾳ, ᾗ ἀνήγαγον αὐτοὺς ἐκ γῆς Αἰγύπτου, περὶ ὁλοκαυτωμάτων καὶ θυσίας.","greek":true,"translation":"„Căci n-am vorbit către părinții voștri și nu le-am poruncit în ziua în care i-am scos din țara Egiptului despre arderi de tot și jertfă.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["1 Samuel 15:22","Osea 6:6","Matei 9:13","Psalmii 51:16,17","Psalmii 40:6","Marcu 12:33"]},{"v":"7:23","t":"ci le-am poruncit doar legat de aceasta, spunând: „Ascultați de glasul Meu, ca să vă fiu Dumnezeu și voi să-Mi fiți popor și să urmați toată calea pe care v-o poruncesc, ca să vă fie bine.","tokens":[{"t":"ci le-am poruncit doar legat de aceasta, spunând: „"},{"t":"Ascultați","w":"Ascultați","heb":"שִׁמְעוּ","translit":"șimu","strong":"H8085","pos":"verb, qal imperativ","def_ro":"ascultați.","greek":"ἀκούω (akouo)","greek_def_ro":"ἀκούω (akouo) — a asculta.","dict_ro":"Șama — verbul „a asculta” în ebraică poartă implicit și sensul de „a se supune”, nu doar „a auzi” (aceeași rădăcină din Șema Israel). Metzudat David subliniază structura logică a versetului: ascultarea de glasul DOMNULUI e „lucrul acesta” (hadavar haze) — condiția unică și centrală a legământului, iar toate poruncile particulare, inclusiv cele despre jertfe, decurg din ea ca ramuri, nu ca temelie."},{"t":" de glasul Meu, ca să vă fiu Dumnezeu și voi să-Mi fiți popor și să urmați toată calea pe care v-o poruncesc, ca să vă fie bine."}],"commentaries":[{"author":"Metzudat David","text":"„Ascultați de glasul Meu” — doar acest lucru le-am poruncit atunci, ca temelie; iar dacă acesta e temeiul, atunci și aducerea jertfelor e doar una dintre poruncile particulare, în care nu e nicio mulțumire fără ascultarea de glasul DOMNULUI. „Și voi fi vouă Dumnezeu” — Eu Însumi vă voi revărsa binele, fără mijlocitor. „Ca să vă fie bine” — nu Mie Îmi vine vreun folos din aceasta, ci doar ca să vă fie vouă bine."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"כִּי אִם־אֶת־הַדָּבָר הַזֶּה צִוִּיתִי אוֹתָם...","translation":"„ci le-am poruncit doar legat de aceasta...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ἀλλ' ἢ τὸ ῥῆμα τοῦτο ἐνετειλάμην αὐτοῖς, λέγων· ἀκούσατε τῆς φωνῆς μου, καὶ ἔσομαι ὑμῖν εἰς Θεόν, καὶ ὑμεῖς ἔσεσθέ μοι εἰς λαόν· καὶ πορεύεσθε ἐν πάσαις ταῖς ὁδοῖς μου, αἷς ἂν ἐντείλωμαι ὑμῖν, ὅπως ἂν εὖ ᾖ ὑμῖν.","greek":true,"translation":"„Ci numai acest cuvânt le-am poruncit, zicând: ascultați glasul Meu, și voi fi vouă Dumnezeu, și voi Îmi veți fi popor; și umblați în toate căile Mele, câte vă voi porunci, ca să vă fie bine.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Exod 19:5,6","Ieremia 31:33","Levitic 26:3-12","Evrei 5:9","Ieremia 11:4,7","Ieremia 42:6"]},{"v":"7:24","t":"Dar ei nu au ascultat și nu și-au plecat urechea, ci au urmat propriile lor sfaturi, pornirile inimii lor rele, au mers înapoi și nu înainte.","tokens":[{"t":"Dar ei nu au ascultat și nu și-au plecat urechea, ci au urmat propriile lor sfaturi, "},{"t":"pornirile inimii lor rele","w":"pornirile inimii lor rele","heb":"בְּמֹעֵצוֹת בִּשְׁרִרוּת","translit":"bemoēțot bișrirut","strong":"H8307","pos":"substantiv, feminin plural + substantiv, feminin singular construct","def_ro":"în încăpățânarea inimii lor rele.","greek":"ἐνθύμημα τῆς καρδίας κακῆς (enthymema tes kardias kakes)","greek_def_ro":"ἐνθύμημα τῆς καρδίας κακῆς (enthymema tes kardias kakes) — pornirile inimii rele.","dict_ro":"Șerirut — „încăpățânare/îndărătnicie”, un termen aproape exclusiv ieremian (apare de 8 ori numai în această carte), desemnând nu o singură alunecare, ci un tipar de comportament statornic: fiecare generație urmează propriile porniri, în locul poruncii primite, într-un cerc care se repetă de la Exod până în prezentul lui Ieremia."},{"t":", au mers înapoi și nu înainte."}],"commentaries":[{"author":"Metzudat David","text":"„Nu au ascultat” — chiar cei ieșiți din Egipt nu au ascultat. „În sfaturile lor” — după sfatul pe care li-l arăta inima lor rea, adică după ceea ce doreau și poftiau. „Au mers înapoi” — în fiecare zi se depărtau tot mai mult de slujirea DOMNULUI, în loc să se apropie."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְלֹא שָׁמְעוּ וְלֹא־הִטּוּ אֶת־אָזְנָם...","translation":"„Dar ei nu au ascultat și nu și-au plecat urechea...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ οὐκ ἤκουσάν μου, καὶ οὐ προσέσχε τὸ οὖς αὐτῶν, ἀλλ' ἐπορεύθησαν ἐν τοῖς ἐνθυμήμασι τῆς καρδίας αὐτῶν τῆς κακῆς καὶ ἐγενήθησαν εἰς τὰ ὄπισθεν καὶ οὐκ εἰς τὰ ἔμπροσθεν.","greek":true,"translation":"„Și nu M-au ascultat, și urechea lor nu a luat aminte, ci au umblat după cugetele inimii lor celei rele și s-au făcut înapoi, iar nu înainte.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Ieremia 7:26","Exod 32:7,8","Neemia 9:16-20","Ieremia 2:27","Ieremia 23:17"]},{"v":"7:25","t":"Din ziua în care strămoșii tăi au ieșit din țara Egiptului și până astăzi, le-am trimis pe toți slujitorii Mei, profeții, în fiecare zi îi trimit dimineața devreme.","tokens":[{"t":"Din ziua în care strămoșii tăi au ieșit din țara Egiptului și până astăzi, le-am trimis pe toți "},{"t":"slujitorii Mei, profeții","w":"slujitorii Mei, profeții","heb":"עֲבָדַי הַנְּבִיאִים","translit":"avadai hanvim","strong":"H5030","pos":"substantiv, masculin plural construct + sufix + substantiv, masculin plural","def_ro":"robii Mei, profeții.","greek":"δοῦλοι προφῆται (douloi prophetai)","greek_def_ro":"δοῦλοι προφῆται (douloi prophetai) — slujitorii, profeții.","dict_ro":"Navi (plural neviim) — titlul „robii Mei, profeții” revine ca formulă fixă la Ieremia (cf. 7:25, 25:4, 26:5, 29:19, 35:15, 44:4) pentru a descrie întregul șir neîntrerupt de trimiși divini de-a lungul istoriei lui Israel — imaginea „dimineața devreme” (yom hașkem) sugerează, după Rashi, o grabă și o stăruință părintească, nu o formalitate birocratică."},{"t":", în fiecare zi îi trimit dimineața devreme."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „yom hașkem veșaloah” — zi de zi [îi trimit] dis-de-dimineață și stăruitor."},{"author":"Metzudat David","text":"„De atunci și până acum, nu le-am lipsit slujitorii Mei profeții nicio zi, ci în fiecare zi îi trimiteam devreme, stăruind să-i întoarcă spre bine.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"לְמִן־הַיּוֹם אֲשֶׁר יָצְאוּ אֲבוֹתֵיכֶם...","translation":"„Din ziua în care strămoșii tăi au ieșit din țara Egiptului...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ἀφ' ἧς ἡμέρας ἐξήλθοσαν οἱ πατέρες αὐτῶν ἐκ γῆς Αἰγύπτου καὶ ἕως τῆς ἡμέρας ταύτης, καὶ ἐξαπέστειλα πρὸς ὑμᾶς πάντας τοὺς δούλους μου, τοὺς προφήτας, ἡμέρας καὶ ὄρθρου, καὶ ἀπέστειλα.","greek":true,"translation":"„Din ziua în care au ieșit părinții lor din țara Egiptului și până în ziua aceasta, am trimis la voi pe toți robii Mei, profeții, zi de zi și dis-de-dimineață, și am trimis.”","note":"Corespondență apropiată; Septuaginta dublează verbul trimiterii la final („am trimis... și am trimis”), unde Textul Masoretic are expresia idiomatică „yom hașkem veșaloah” tradusă printr-o construcție mai puțin naturală în greacă."}],"refs":["Ieremia 25:4","2 Cronici 36:15","Matei 21:34-36","Ezechiel 2:3","Ieremia 32:30,31","Ieremia 7:13"]},{"v":"7:26","t":"Dar ei nu ascultă de Mine și nu își pleacă urechea; ei și-au învârtoșat grumazul și au devenit mai răi decât strămoșii lor.","tokens":[{"t":"Dar ei nu ascultă de Mine și nu își pleacă urechea; ei și-au "},{"t":"învârtoșat grumazul","w":"învârtoșat grumazul","heb":"וַיַּקְשׁוּ","translit":"vaiakșu","strong":"H7185","pos":"verb, hifil imperfect consecutiv","def_ro":"și-au înțepenit ceafa.","greek":"σκληρύνω τὸν τράχηλον (skleryno ton trachelon)","greek_def_ro":"σκληρύνω τὸν τράχηλον (skleryno ton trachelon) — și-au înțepenit grumazul.","dict_ro":"Kașa oref — expresia idiomatică „a-și înțepeni ceafa” descrie imaginea unui animal de tracțiune care se opune încordat hățurilor, refuzând să fie condus; e aceeași expresie folosită pentru păcatul vițelului de aur (Exodul 32:9) — folosind-o aici, Ieremia leagă în mod explicit generația lui de generația fondatoare a idolatriei din pustie, agravând acuzația prin comparație directă: „mai răi decât strămoșii lor”."},{"t":" și au devenit mai răi decât strămoșii lor."}],"commentaries":[{"author":"Metzudat David","text":"„Nu M-au ascultat” — oamenii acestei generații; „și-au înțepenit grumazul” — o expresie figurată, ca și cum grumazul li s-ar fi înțepenit atât de tare încât nu mai pot întoarce fața spre acel loc [DOMNUL], asemenea unui om care nu vrea să-și întoarcă fața spre semenul lui ca să-i asculte cuvintele; „au făcut rele” — mai multe decât părinții lor."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְלוֹא שָׁמְעוּ אֵלַי...","translation":"„Dar ei nu ascultă de Mine...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ οὐκ εἰσήκουσάν μου, καὶ οὐ προσέσχε τὸ οὖς αὐτῶν, καὶ ἐσκλήρυναν τὸν τράχηλον αὐτῶν ὑπὲρ τοὺς πατέρας αὐτῶν.","greek":true,"translation":"„Și nu M-au ascultat, și urechea lor n-a luat aminte, și și-au înțepenit grumazul mai mult decât părinții lor.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Ieremia 19:15","2 Împărați 17:14","Faptele apostolilor 7:51","Matei 23:32","Proverbe 29:1","Ieremia 7:24"]},{"v":"7:27","t":"Le vei spune toate aceste lucruri, dar ei nu te vor asculta; îi vei striga, dar ei nu îți vor răspunde.","tokens":[{"t":"Le vei spune toate aceste lucruri, dar ei nu te vor asculta; îi vei "},{"t":"striga","w":"striga","heb":"וְקָרָאתָ","translit":"vekarata","strong":"H7121","pos":"verb, qal perfect consecutiv","def_ro":"și vei striga, vei chema.","diff_ro":"Întregul verset nu are corespondent în Septuaginta disponibilă — nu există traducere grecească pentru acest verset.","dict_ro":"Kara — versetul marchează o schimbare de destinatar în text: DOMNUL nu mai vorbește direct poporului (ca la v.21-26), ci i se adresează lui Ieremia însuși, avertizându-l dinainte că misiunea lui va eșua din perspectiva rezultatului imediat — profetul trebuie să vestească oricum, chiar știind că nu va fi ascultat, într-un paralelism structural cu comisionul similar dat lui Isaia (Isaia 6:9-10) și lui Ezechiel (Ezechiel 3:4-11)."},{"t":", dar ei nu îți vor răspunde."}],"commentaries":[{"author":"Metzudat David","text":"„Le vei spune” — chiar dacă știu dinainte că nu te vor asculta, tot trebuie să le spui, ca să nu aibă ce răspunde la judecată, [zicând] că n-au fost înștiințați.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְדִבַּרְתָּ אֲלֵיהֶם אֶת־כָּל־הַדְּבָרִים הָאֵלֶּה...","translation":"„Le vei spune toate aceste lucruri...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"(fără corespondent)","greek":true,"translation":"—","note":"Divergență reală și notabilă: acest verset lipsește complet din Septuaginta — textul grec trece direct de la v.26 la v.28, fără niciun echivalent pentru v.27. E una dintre numeroasele omisiuni reale ale Septuagintei la Ieremia, carte cunoscută pentru o versiune greacă sensibil mai scurtă decât Textul Masoretic (cu aproximativ o optime din text absent, în diverse locuri, potrivit criticii textuale moderne, care leagă acest fenomen de o formă textuală ebraică diferită, atestată parțial la Qumran)."}],"refs":["Ezechiel 2:4-7","Isaia 6:9,10","Zaharia 7:13","Isaia 65:12"]},{"v":"7:28","t":"Le vei spune: „Acesta este neamul care nu va asculta de glasul DOMNULUI, Dumnezeului său, și nu va primi mustrarea; credința sa este pierdută și nimicită din gura lor.”","tokens":[{"t":"Le vei spune: „Acesta este neamul care nu va asculta de glasul DOMNULUI, Dumnezeului său, și nu va primi "},{"t":"mustrarea","w":"mustrarea","heb":"מוּסָר","translit":"musar","strong":"H4148","pos":"substantiv, masculin singular","def_ro":"disciplina, mustrarea, învățătura corectivă.","greek":"παιδεία (paideia)","greek_def_ro":"παιδεία (paideia) — disciplinare, mustrare, educare.","dict_ro":"Musar — termen central în literatura de înțelepciune (cf. Proverbe 1:7, „nebunii disprețuiesc înțelepciunea și musar-ul”), desemnând nu o simplă critică, ci disciplina formativă primită cu smerenie. Refuzul ei aici nu e doar un defect moral izolat, ci simptomul unei pierderi mai adânci: „credința/statornicia” (emuna) însăși a dispărut, până și din vorbire — poporul nu mai poate nici măcar rosti adevărul despre sine."},{"t":"; credința sa este pierdută și nimicită din gura lor.”"}],"commentaries":[{"author":"Metzudat David","text":"„Acesta este neamul” — nu sunt aceștia dintre fiii lui Israel care au auzit cuvântul DOMNULUI la Sinai, ci ca și cum n-ar fi ascultat niciodată glasul DOMNULUI și n-ar fi învățat vreodată disciplina; credința în Dumnezeu a pierit din inimile lor și s-a stins chiar și din gura lor, nu se mai pomenește de ea.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְאָמַרְתָּ אֲלֵיהֶם זֶה הַגּוֹי...","translation":"„Le vei spune: «Acesta este neamul...»” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐρεῖς αὐτοῖς τοῦτον τὸν λόγον· τοῦτο τὸ ἔθνος, ὃ οὐκ ἤκουσε τῆς φωνῆς Κυρίου οὐδὲ ἐδέξατο παιδείαν, ἐξέλιπεν ἡ πίστις ἐκ στόματος αὐτῶν.","greek":true,"translation":"„Și le vei spune acest cuvânt: acesta este neamul care n-a ascultat glasul Domnului, nici n-a primit învățătura; a pierit credința din gura lor.”","note":"Corespondență strânsă cu Textul Masoretic, deși numărul versetului diferă cu o unitate față de Textul Masoretic, ca urmare a omiterii v.27 în Septuaginta."}],"refs":["Isaia 1:4,5","Țefania 3:2","Ieremia 6:29,30","Ieremia 5:1","Mica 7:2-5"]},{"v":"7:29","t":"Smulge-ți părul și aruncă-l, înalță cântare de jale din înălțimi, căci DOMNUL a disprețuit și a părăsit generația mâniei Lui.","tokens":[{"t":"Smulge-ți "},{"t":"părul","w":"părul","heb":"נִזְרֵךְ","translit":"nizrēh","strong":"H5145","pos":"substantiv, masculin singular construct + sufix","def_ro":"coama ta de păr, cununa ta.","greek":"κεφαλή (kephale)","greek_def_ro":"κεφαλή (kephale) — cap.","diff_ro":"Ebraica „nizrēkh\" se referă specific la pletele consacrate (ca ale unui nazireu), nu generic la „cap\" — Septuaginta simplifică la „κεφαλήν\" („capul tău\").","dict_ro":"Nezer — cuvântul poartă și sensul de „cunună/consacrare” (aceeași rădăcină din care vine „nazireu”), o dublă lectură reală pe care Rashi o notează explicit: fie „tunde-ți părul” ca gest ritual de jale (cf. Iov 1:20), fie, printr-o citire alternativă atribuită lui Menahem, „coroana ta de măreție” — Ierusalimul chemat să-și arunce departe însăși gloria pe care o avea."},{"t":" și aruncă-l, înalță cântare de jale din înălțimi, căci DOMNUL a disprețuit și a părăsit generația mâniei Lui."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „gazi nizrech” — smulge-ți părul; ca în „a smuls prepelițele” (Numeri 11:31), „și-a smuls capul” [și-a tuns capul] (Iov 1:20). O altă interpretare: „nizrech” — cununa ta, un termen de măreție; așa a tradus și Targum Ionatan „rabrevich” [măreția ta], iar așa a explicat și Menahem."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"גָּזִּי נִזְרֵךְ וְהַשְׁלִיכִי...","translation":"„Smulge-ți părul și aruncă-l...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"Κεῖραι τὴν κεφαλήν σου καὶ ἀπόρριπτε καὶ ἀνάλαβε ἐπὶ χειλέων θρῆνον, ὅτι ἀπεδοκίμασε Κύριος καὶ ἀπώσατο τὴν γενεὰν τὴν ποιοῦσαν ταῦτα.","greek":true,"translation":"„Tunde-ți capul și aruncă [părul] și ridică pe buze cântare de jale, căci Domnul a lepădat și a izgonit neamul care face acestea.”","note":"Divergență reală: Septuaginta redă generic „τὴν γενεὰν τὴν ποιοῦσαν ταῦτα” („neamul care face acestea”), în timp ce Textul Masoretic are expresia distinctivă „dor evrato” („generația mâniei Lui”) — o formulare mai personală, centrată pe reacția divină, absentă din varianta greacă."}],"refs":["Iov 1:20","Mica 1:16","Ieremia 9:17-21","Deuteronom 32:5","Matei 3:7","Zaharia 11:8,9"]},{"v":"7:30","t":"Căci copiii lui Iuda au făcut ce este rău în ochii Mei – rostirea DOMNULUI – și-au pus scârboșeniile în Casa asupra căreia este proclamat numele Meu, pângărind-o.","tokens":[{"t":"Căci copiii lui Iuda au făcut ce este rău în ochii Mei – rostirea DOMNULUI – și-au pus "},{"t":"scârboșeniile","w":"scârboșeniile","heb":"שִׁקּוּצֵיהֶם","translit":"șikuțēhem","strong":"H8251","pos":"substantiv, masculin plural construct + sufix","def_ro":"urâciunile/idolii lor scârbavnici.","greek":"βδέλυγμα (bdelygma)","greek_def_ro":"βδέλυγμα (bdelygma) — urâciune, lucru detestabil.","dict_ro":"Șikutz — termen tehnic pentru obiecte de cult idolatru, folosit mai ales despre idolii din popoarele vecine (cf. „șikutz Moav” pentru Chemoș, 1 Împărați 11:7); punerea lor chiar în Casa „asupra căreia e proclamat Numele DOMNULUI” (formulă care revine constant în Ieremia pentru Templu) e cea mai gravă formă de profanare posibilă — nu idolatrie undeva departe, ci în chiar centrul autorității legitime a cultului."},{"t":" în Casa asupra căreia este proclamat numele Meu, pângărind-o."}],"commentaries":[{"author":"Metzudat David","text":"„Idolatria scârboasă și-au pus-o în Casă, ca s-o pângărească; iar aceasta arată cât de puțin le pasă de Casa DOMNULUI, de vreme ce n-au ezitat s-o spurce chiar cu idolii lor.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"כִּי־עָשׂוּ בְנֵי־יְהוּדָה הָרַע בְּעֵינַי...","translation":"„Căci copiii lui Iuda au făcut ce este rău în ochii Mei...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ὅτι ἐποίησαν οἱ υἱοὶ Ἰούδα τὸ πονηρὸν ἐναντίον ἐμοῦ, λέγει Κύριος· ἔταξαν τὰ βδελύγματα αὐτῶν ἐν τῷ οἴκῳ, οὗ ἐπικέκληται τὸ ὄνομά μου ἐπ' αὐτόν, τοῦ μιᾶναι αὐτόν.","greek":true,"translation":"„Căci au făcut fiii lui Iuda răul înaintea Mea, zice Domnul; au pus urâciunile lor în casa peste care s-a chemat numele Meu, ca s-o pângărească.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["2 Împărați 21:4,7","Ezechiel 8:5-17","Daniel 9:27","Ezechiel 43:7,8","Ieremia 32:34","Ieremia 23:11"]},{"v":"7:31","t":"Au zidit [altare pe] înălțimile Tofet, care sunt în valea fiului lui Hinom, ca să-i ardă pe fiii și pe fiicele lor în foc – ce nici n-am poruncit și nici nu Mi-a trecut prin minte.","tokens":[{"t":"Au zidit [altare pe] înălțimile "},{"t":"Tofet","w":"Tofet","heb":"הַתֹּפֶת","translit":"hatofet","strong":"H8612","pos":"nume propriu","def_ro":"Tofet, locul de jertfă a copiilor.","greek":"Ταφέθ (Tapheth)","greek_def_ro":"Ταφέθ (Tapheth) — Tofet.","dict_ro":"Tofet — Rashi identifică locul cu cultul lui Moloh: un idol de aramă încins pe dinăuntru, cu brațele întinse, pe care era pus copilul, în timp ce preoții băteau tobe (tupim, de unde ar veni și numele „Tofet”) ca tatăl să nu audă țipătul fiului și să nu i se înmoaie inima — iar „Hinom” ar veni de la gemetele (nehama) copilului. Etimologiile sunt tradiționale, nu documentate arheologic, dar exprimă limpede oroarea morală atribuită locului."},{"t":", care sunt în valea fiului lui Hinom, ca să-i ardă pe fiii și pe fiicele lor în foc – ce nici n-am poruncit și nici nu Mi-a trecut prin minte."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „bamot haTofet” — acesta este [idolul] Moloh (2 Împărați 23:10), care era de aramă, îl încingeau pe dedesubt, cu brațele întinse și încinse, și puneau copilul pe brațele lui, iar el se ardea și gemea; iar preoții băteau în tobe [tupim], ca tatăl să nu audă glasul fiului și să i se înduioșeze inima (cf. Geneza 43:30). „Tofet” — de la numele tobei; „Hinom” — de la gemătul [nehama] fiului (Tanhuma Buber)."},{"author":"Metzudat David","text":"„Aceasta arată cât de rea era fapta lor: nici măcar nu Mi-a trecut prin gând, cu atât mai puțin am poruncit-o vreodată, să ceară o asemenea jertfă.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וּבָנוּ בָּמוֹת הַתֹּפֶת...","translation":"„Au zidit [altare pe] înălțimile Tofet...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ᾠκοδόμησαν τὸν βωμὸν τοῦ Ταφέθ, ὅς ἐστιν ἐν φάραγγι υἱοῦ Ἐννόμ, τοῦ κατακαίειν τοὺς υἱοὺς αὐτῶν καὶ τὰς θυγατέρας αὐτῶν ἐν πυρί, ὃ οὐκ ἐνετειλάμην αὐτοῖς καὶ οὐ διενοήθην ἐν τῇ καρδίᾳ μου.","greek":true,"translation":"„Și au zidit altarul Tafetului, care este în valea fiului lui Enom, ca să-și ardă fiii și fiicele lor în foc, ceea ce nu le-am poruncit și nu Mi-a trecut prin inimă.”","note":"Divergență de număr: Textul Masoretic are plural „bamot” (înălțimile), pe când Septuaginta traduce la singular „τὸν βωμὸν” (altarul) — o normalizare reală a numărului gramatical."}],"refs":["Levitic 18:21","Deuteronom 12:31","Psalmii 106:37,38","2 Cronici 28:3","Ieremia 19:5,6","Ieremia 19:2"]},{"v":"7:32","t":"De aceea, iată, vin zile – rostirea DOMNULUI – când nu se va mai spune Tofet și nici Valea Ben-Hinom, ci Valea Măcelului, și îi vor îngropa [pe cei morți] în Tofet din lipsă de loc.","tokens":[{"t":"De aceea, iată, vin zile – rostirea DOMNULUI – când nu se va mai spune Tofet și nici Valea Ben-Hinom, ci "},{"t":"Valea Măcelului","w":"Valea Măcelului","heb":"גֵּיא הַהֲרֵגָה","translit":"gē haharēga","strong":"H2028","pos":"substantiv, masculin și feminin singular construct + substantiv, feminin singular","def_ro":"valea uciderii, valea măcelului.","greek":"φάραγξ τῶν ἀνῃρημένων (pharanx ton aneremenon)","greek_def_ro":"φάραγξ τῶν ἀνῃρημένων (pharanx ton aneremenon) — valea celor uciși.","dict_ro":"Harega — schimbarea de nume e o formă de judecată poetică: locul unde copiii erau arși ca „jertfă” devine locul unde adulții vor cădea uciși — pedeapsa reflectă exact natura păcatului, în locul exact unde a fost comis. Aceeași vale (Ghe-Hinom) va deveni, în tradiția ulterioară, sursa numelui „Ghehena” pentru locul pedepsei de dincolo de moarte."},{"t":", și îi vor îngropa [pe cei morți] în Tofet din lipsă de loc."}],"commentaries":[{"author":"Metzudat David","text":"„Nu se va mai numi locul acela după numele idolului sau al văii fiului lui Hinom, ci Valea Măcelului, căci acolo vor cădea mulți uciși — și vor fi îngropați acolo, în Tofet, atât de mulți, încât nu se va mai găsi loc pentru alți morți.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"לָכֵן הִנֵּה־יָמִים בָּאִים...","translation":"„De aceea, iată, vin zile...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"διὰ τοῦτο ἰδοὺ ἡμέραι ἔρχονται, λέγει Κύριος, καὶ οὐκ ἐροῦσιν ἔτι· Βωμὸς τοῦ Ταφὲθ καὶ φάραγξ υἱοῦ Ἐννόμ, ἀλλ' ἢ Φάραγξ τῶν ἀνῃρημένων, καὶ θάψουσιν ἐν τῷ Ταφὲθ διὰ τὸ μὴ ὑπάρχειν τόπον.","greek":true,"translation":"„Pentru aceasta, iată, vin zile, zice Domnul, și nu se va mai zice: altarul Tafetului și valea fiului lui Enom, ci Valea celor uciși, și vor îngropa în Tafet din pricină că nu va fi loc.”","note":"Corespondență apropiată cu Textul Masoretic."}],"refs":["Ieremia 19:6","Levitic 26:30","Ezechiel 6:5-7","Ieremia 19:11,13","2 Împărați 23:10"]},{"v":"7:33","t":"Și hoitul acestui popor va fi hrană pentru păsările cerurilor și pentru fiarele pământului și nimeni nu le va speria.","tokens":[{"t":"Și hoitul acestui popor va fi hrană pentru păsările cerurilor și pentru fiarele pământului și nimeni nu le va "},{"t":"speria","w":"speria","heb":"מַחֲרִיד","translit":"maharid","strong":"H2729","pos":"verb, hifil participiu","def_ro":"cel care sperie, cel care alungă.","greek":"ἀποσοβέω (aposobeo)","greek_def_ro":"ἀποσοβέω (aposobeo) — a speria, a îndepărta prin frică.","dict_ro":"Harad — de obicei, prezența unui om viu ar alunga păsările de pe un hoit; absența oricui care să le sperie („ein maharid”) e un mod indirect, dar exact, de a spune că nu va mai rămâne niciun locuitor viu în oraș — o pustiire completă, exprimată prin ceea ce LIPSEȘTE, nu prin ceea ce se întâmplă."},{"t":"."}],"commentaries":[{"author":"Metzudat David","text":"„Nu va mai rămâne niciun om viu care să alunge păsările și fiarele de pe hoituri, căci toți vor fi uciși sau duși în exil.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְהָיְתָה נִבְלַת הָעָם הַזֶּה...","translation":"„Și hoitul acestui popor va fi hrană...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἔσονται οἱ νεκροὶ τοῦ λαοῦ τούτου εἰς βρῶσιν τοῖς πετεινοῖς τοῦ οὐρανοῦ καὶ τοῖς θηρίοις τῆς γῆς, καὶ οὐκ ἔσται ὁ ἀποσοβῶν.","greek":true,"translation":"„Și vor fi morții poporului acestuia hrană păsărilor cerului și fiarelor pământului, și nu va fi cel ce le alungă.”","note":"Corespondență strânsă cu Textul Masoretic; Septuaginta pluralizează „hoitul” în „morții” (οἱ νεκροὶ), o variație minoră de număr."}],"refs":["Ieremia 16:4","Ieremia 34:20","Deuteronom 28:26","Psalmii 79:2,3","Apocalipsa 19:17,18","Ieremia 8:1,2"]},{"v":"7:34","t":"Voi face să înceteze în orașele din Iuda și pe străzile Ierusalimului sunetul bucuriei și sunetul veseliei, glasul mirelui și glasul miresei, căci în ruină va fi țara.","tokens":[{"t":"Voi face să înceteze în orașele din Iuda și pe străzile Ierusalimului sunetul bucuriei și sunetul veseliei, "},{"t":"glasul mirelui și glasul miresei","w":"glasul mirelui și glasul miresei","heb":"חָתָן","translit":"hatan","strong":"H2860","pos":"substantiv, masculin singular","def_ro":"glasul mirelui și glasul miresei.","greek":"φωνή νυμφίου (phone nymphiou)","greek_def_ro":"φωνή νυμφίου (phone nymphiou) — glasul mirelui.","dict_ro":"Hatan/kala — formula pereche „glasul mirelui și glasul miresei” revine ca refren la Ieremia (16:9, 25:10, 33:11) pentru a desemna bucuria socială cea mai firească și mai de neșters dintr-o comunitate — o nuntă. Tocmai de aceea, tăcerea ei devine imaginea supremă a pustiirii complete: nu doar absența bucuriei religioase, ci stingerea vieții obișnuite, de zi cu zi, a orașului."},{"t":", căci în ruină va fi țara."}],"commentaries":[{"author":"Metzudat David","text":"„Voi face să tacă cu totul glasul bucuriei și al veseliei, chiar și glasul de nuntă — până și cea mai firească bucurie a vieții de zi cu zi se va stinge, căci țara va rămâne pustie și fără locuitori.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְהִשְׁבַּתִּי מֵעָרֵי יְהוּדָה...","translation":"„Voi face să înceteze în orașele din Iuda...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ καταλύσω ἐκ πόλεων Ἰούδα καὶ ἐκ διόδων Ἱερουσαλὴμ φωνὴν εὐφραινομένων καὶ φωνὴν χαιρόντων, φωνὴν νυμφίου καὶ φωνὴν νύμφης, ὅτι εἰς ἐρήμωσιν ἔσται πᾶσα ἡ γῆ.","greek":true,"translation":"„Și voi înceta din cetățile lui Iuda și din ulițele Ierusalimului glasul celor ce se veselesc și glasul celor ce se bucură, glasul mirelui și glasul miresei, căci pustiire va fi tot pământul.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Ieremia 25:10","Apocalipsa 18:23","Isaia 24:7,8","Osea 2:11","Isaia 3:26","Levitic 26:33"]},{"v":"8:1","t":"În vremea aceea – rostirea DOMNULUI – vor scoate oasele regilor din Iuda și oasele conducătorilor săi, și oasele preoților, și oasele profeților, și oasele locuitorilor Ierusalimului, din mormintele lor.","tokens":[{"t":"În vremea aceea – rostirea DOMNULUI – vor scoate "},{"t":"oasele","w":"oasele","heb":"עַצְמוֹת","translit":"ațmot","strong":"H6106","pos":"substantiv, feminin plural construct","def_ro":"oasele.","greek":"ὀστέον (osteon)","greek_def_ro":"ὀστέον (osteon) — os.","dict_ro":"Etzem — scoaterea și expunerea oaselor din morminte era considerată printre cele mai grave forme de dezonorare postumă posibile, o negare totală a odihnei cuvenite morților; faptul că lista începe cu „regii”, cei mai onorați în viață, și include chiar preoți și profeți arată că nicio poziție de autoritate religioasă sau politică nu va oferi protecție împotriva acestei rușini colective."},{"t":" regilor din Iuda și oasele conducătorilor săi, și oasele preoților, și oasele profeților, și oasele locuitorilor Ierusalimului, din mormintele lor."}],"commentaries":[{"author":"Metzudat David","text":"„Oasele” — vrăjmașii care vor veni le vor scoate din morminte ca să le dezonoreze; „preoții” — cei ai lui Baal; „profeții” — profeții mincinoși; „locuitorii Ierusalimului” — restul poporului."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"בָּעֵת הַהִיא נְאֻם־יְהוָה...","translation":"„În vremea aceea – rostirea DOMNULUI...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ΕΝ τῷ καιρῷ ἐκείνῳ, λέγει Κύριος, ἐξοίσουσι τὰ ὀστᾶ τῶν βασιλέων Ἰούδα καὶ τὰ ὀστᾶ τῶν ἀρχόντων αὐτοῦ καὶ τὰ ὀστᾶ τῶν ἱερέων καὶ τὰ ὀστᾶ προφητῶν καὶ τὰ ὀστᾶ τῶν κατοικούντων ἐν Ἱερουσαλὴμ ἐκ τῶν τάφων αὐτῶν.","greek":true,"translation":"„În vremea aceea, zice Domnul, vor scoate oasele regilor lui Iuda și oasele conducătorilor lui și oasele preoților și oasele profeților și oasele locuitorilor din Ierusalim, din mormintele lor.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Ieremia 7:32-34","1 Împărați 13:2","2 Cronici 34:4,5","Ezechiel 37:1","Amos 2:1","2 Împărați 23:16,20"]},{"v":"8:2","t":"Și le vor împrăștia la [lumina] soarelui și a lunii și a întregii oștiri a cerurilor, pe care le-au iubit și pe care le-au venerat și pe care le-au urmat, pe care le-au căutat și înaintea cărora s-au prosternat. Nu vor mai fi adunate laolaltă și nici îngropate, ci vor fi ca gunoiul peste fața pământului.","tokens":[{"t":"Și le vor împrăștia la [lumina] soarelui și a lunii și a întregii "},{"t":"oștiri a cerurilor","w":"oștiri a cerurilor","heb":"צְבָא","translit":"țeva","strong":"H6635","pos":"substantiv, masculin și feminin singular construct","def_ro":"oștirea cerurilor.","greek":"στρατιά τοῦ οὐρανοῦ (stratia tou ouranou)","greek_def_ro":"στρατιά τοῦ οὐρανοῦ (stratia tou ouranou) — oștirea cerului.","diff_ro":"Septuaginta adaugă „καὶ πρὸς πάντας τοὺς ἀστέρας\" („și la toate stelele\"), o mențiune absentă din ebraică, alături de soare, lună și oastea cerului.","dict_ro":"Tzeva hașamayim — expresie tehnică pentru cultul astral (închinarea la stele/corpuri cerești), interzis explicit în Tora (Deuteronomul 4:19, 17:3) și asociat mai ales cu regele Manase (2 Împărați 21:3-5); ironia versetului stă în faptul că oasele închinătorilor sunt acum expuse tocmai sub lumina acelorași aștri pe care i-au venerat în viață — obiectul cultului lor devine martorul rușinii lor postume."},{"t":", pe care le-au iubit și pe care le-au venerat și pe care le-au urmat, pe care le-au căutat și înaintea cărora s-au prosternat. Nu vor mai fi adunate laolaltă și nici îngropate, ci vor fi ca gunoiul peste fața pământului."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „ușetahum lașemeș” — și caldeii vor asedia cetatea din mormintele conducătorilor, care erau frumoase ca niște palate (după Talmud Bavli, Sanhedrin 96b). „Ledomen” — ca gunoiul de grajd."},{"author":"Metzudat David","text":"„Ashuvum” — le vor întinde/expune spre soare, ca să le dezonoreze; „așer ahevum” — pe care le-au iubit, primindu-le ca divinități; „lo yeasfu” — nu vor fi strânse în mormânt."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וּשְׁטָחוּם לַשֶּׁמֶשׁ וְלַיָּרֵחַ...","translation":"„Și le vor împrăștia la [lumina] soarelui și a lunii...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ψύξουσιν αὐτὰ πρὸς τὸν ἥλιον καὶ τὴν σελήνην καὶ πρὸς πάντας τοὺς ἀστέρας καὶ πρὸς πᾶσαν τὴν στρατιὰν τοῦ οὐρανοῦ, ἃ ἠγάπησαν, καὶ οἷς ἐδούλευσαν καὶ ὧν ἐπορεύθησαν ὀπίσω αὐτῶν καὶ ὧν ἀντείχοντο καὶ οἷς προσεκύνησαν αὐτοῖς· οὐ κοπήσονται καὶ οὐ ταφήσονται, καὶ ἔσονται εἰς παράδειγμα ἐπὶ προσώπου τῆς γῆς.","greek":true,"translation":"„Și le vor răcori/întinde la soare și la lună și la toate stelele și la toată oștirea cerului, pe care le-au iubit și cărora le-au slujit și după care au umblat și de care s-au ținut și cărora li s-au închinat; nu vor fi jelite și nu vor fi îngropate, și vor fi ca o pildă pe fața pământului.”","note":"Divergență lexicală notabilă: Textul Masoretic are „ledomen” (ca gunoiul/bălegarul), o imagine de degradare fizică maximă; Septuaginta traduce prin „εἰς παράδειγμα” („ca o pildă/exemplu”), o schimbare reală de sens, dinspre imaginea concretă a putrezirii spre o funcție didactică-simbolică."}],"refs":["2 Împărați 21:3,5","2 Împărați 23:5","Deuteronom 4:19","2 Cronici 33:3-5","Țefania 1:5","Faptele apostolilor 7:42"]},{"v":"8:3","t":"Și moartea va fi de preferat vieții pentru toți cei rămași din rămășița acestei familii rele, pentru cei rămași prin toate locurile în care i-am izgonit – rostirea DOMNULUI Oștirilor.","tokens":[{"t":"Și "},{"t":"moartea va fi de preferat","w":"moartea va fi de preferat","heb":"וְנִבְחַר מָוֶת","translit":"venivhar mavet","strong":"H4194","pos":"verb, nifal perfect consecutiv + substantiv, masculin singular","def_ro":"și va fi aleasă moartea.","greek":"αἱρέομαι τὸν θάνατον (haireomai ton thanaton)","greek_def_ro":"αἱρέομαι τὸν θάνατον (haireomai ton thanaton) — au ales moartea.","dict_ro":"Mavet — versetul culminează seria de pedepse cu o inversare deznădăjduită a instinctului elementar de supraviețuire: în mod normal, viața e aleasă întotdeauna în locul morții (cf. Deuteronomul 30:19, „alege viața”); aici, gradul suferinței celor rămași va fi atât de mare, încât moartea celor deja uciși va părea de invidiat față de soarta celor care trebuie să continue să trăiască, exilați, printre popoarele străine."},{"t":" vieții pentru toți cei rămași din rămășița acestei familii rele, pentru cei rămași prin toate locurile în care i-am izgonit – rostirea DOMNULUI Oștirilor."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: chiar dacă văd morții zăcând în batjocură, necazul celor vii va fi și mai mare decât al lor, și vor alege moartea."},{"author":"Metzudat David","text":"„Rămășița care va rămâne va fi într-un necaz atât de mare, încât va alege moartea; iar «în toate locurile rămase» — o inversiune stilistică, la fel ca «cei rămași în toate locurile în care i-am izgonit», adică în exil.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְנִבְחַר מָוֶת מֵחַיִּים...","translation":"„Și moartea va fi de preferat vieții...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ὅτι εἵλοντο τὸν θάνατον ἢ τὴν ζωήν, καὶ πᾶσι τοῖς καταλοίποις τοῖς καταλειφθεῖσιν ἀπὸ τῆς γενεᾶς ἐκείνης ἐν παντὶ τόπῳ, οὗ ἐὰν ἐξώσω αὐτοὺς ἐκεῖ.","greek":true,"translation":"„Căci au ales moartea mai degrabă decât viața, și pentru toți cei rămași care au mai rămas din neamul acela, în orice loc unde îi voi izgoni acolo.”","note":"Divergență gramaticală reală: Textul Masoretic are un verb pasiv impersonal („va fi aleasă moartea”, ca o constatare a sorții lor), pe când Septuaginta redă la persoana a III-a plural activă, „εἵλοντο” („ei au ales”) — o schimbare de la o soartă impusă spre o alegere activă și deja consumată a supraviețuitorilor."}],"refs":["Iov 3:20-22","Iona 4:3","1 Împărați 19:4","Apocalipsa 9:6","Deuteronom 30:1,4","Daniel 9:7"]},{"v":"9:23","t":"Așa a spus DOMNUL: „Cel înțelept să nu se laude cu înțelepciunea sa, și nici cel puternic să nu se laude cu puterea sa, și nici cel bogat să nu se laude cu bogăția sa.","tokens":[{"t":"Așa a spus DOMNUL: „Cel înțelept să nu se "},{"t":"laude","w":"laude","heb":"יִתְהַלֵּל","translit":"ithalēl","strong":"H1984","pos":"verb, hitpael jusiv","def_ro":"să se laude, să se fălească.","greek":"καυχάομαι (kauchaomai)","greek_def_ro":"καυχάομαι (kauchaomai) — a se lăuda, a se mândri.","dict_ro":"Halal la forma hitpael reflexivă — „a se lăuda pe sine”, o formă gramaticală care implică autoreferință și mândrie construită asupra propriei persoane; rădăcina e aceeași din care vine „Aleluia” (Halelu-Ya, „lăudați pe DOMNUL”) — contrastul e voit: lauda îndreptată corect e cea adusă lui Dumnezeu, nu cea adusă sieși pentru înțelepciune, putere sau bogăție."},{"t":" cu înțelepciunea sa, și nici cel puternic să nu se laude cu puterea sa, și nici cel bogat să nu se laude cu bogăția sa."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"„Înțeleptul să nu se laude” — să nu vă lăudați spunând: „suntem înțelepți” (Ieremia 8:8); iată, ați lepădat cuvântul Meu, și ce înțelepciune aveți? (Ieremia 8:9). Dacă aveți pricepere și Mă cunoașteți, atunci lăudați-vă cu înțelepciunea voastră."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"כֹּה אָמַר יְהוָה אַל־יִתְהַלֵּל חָכָם...","translation":"„Așa a spus DOMNUL: «Cel înțelept să nu se laude...»” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"Τάδε λέγει Κύριος· μὴ καυχάσθω ὁ σοφὸς ἐν τῇ σοφίᾳ αὐτοῦ, καὶ μὴ καυχάσθω ὁ ἰσχυρὸς ἐν τῇ ἰσχύϊ αὐτοῦ, καὶ μὴ καυχάσθω ὁ πλούσιος ἐν τῷ πλούτῳ αὐτοῦ.","greek":true,"translation":"„Așa zice Domnul: să nu se laude cel înțelept cu înțelepciunea lui, și să nu se laude cel puternic cu puterea lui, și să nu se laude cel bogat cu bogăția lui.”","note":"Corespondență strânsă de conținut cu Textul Masoretic."}],"refs":["Isaia 10:12,13","Daniel 4:30,31,37","Iov 31:24,25","Psalmii 49:6-9","Iov 5:12-14"]},{"v":"9:24","t":"Doar cu aceasta poate lăudărosul să se laude: că Mă înțelege și că Mă cunoaște, căci Eu sunt DOMNUL, care înfăptuiesc bunăvoință, justiție și dreptate pe pământ; căci acestea sunt cele pe care le doresc – rostirea DOMNULUI!","tokens":[{"t":"Doar cu aceasta poate lăudărosul să se laude: că Mă înțelege și că Mă cunoaște, căci Eu sunt DOMNUL, care înfăptuiesc "},{"t":"bunăvoință, justiție și dreptate","w":"bunăvoință, justiție și dreptate","heb":"חֶסֶד","translit":"hesed","strong":"H2617","pos":"substantiv, masculin singular","def_ro":"îndurare, judecată și dreptate.","greek":"ἔλεος καὶ κρίμα καὶ δικαιοσύνη (eleos kai krima kai dikaiosyne)","greek_def_ro":"ἔλεος καὶ κρίμα καὶ δικαιοσύνη (eleos kai krima kai dikaiosyne) — bunăvoință, judecată și dreptate.","dict_ro":"Hesed/mișpat/tzedaka — triada de atribute divine care încheie haftara nu e întâmplătoare, ci ecoul direct al formulei de autodescriere a lui Dumnezeu de la Sinai, după păcatul vițelului de aur (Exodul 34:6-7) — DOMNUL cel plin de îndurare, dar și de dreptate. Prin această triadă, cartea Ieremia, plină de acuzații și judecată, se încheie (în cadrul haftarei) pe o notă care redefinește adevărata „cunoaștere a lui Dumnezeu”: nu speculație abstractă, ci recunoașterea Lui prin exact aceste calități active în lume."},{"t":" pe pământ; căci acestea sunt cele pe care le doresc – rostirea DOMNULUI!"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"„Că are pricepere” (haskel) — [forma e] ca în „și-a împietrit (hachbed)” (Exod 8:15)."},{"author":"Metzudat David","text":"„Cel ce se laudă, să se laude cu aceasta: că a priceput și M-a cunoscut, că Eu sunt DOMNUL, și nu mai e altul afară de Mine; că Eu sunt Cel care fac bunăvoință celor ce Mă iubesc și păzesc poruncile Mele, Cel care fac judecată ca să pedepsesc pe cei răi și Cel care fac dreptate primindu-i pe cei ce se pocăiesc — nu doar unul care lucrează binele și altul care lucrează răul, ferească Dumnezeu, ci în toate acestea Eu doresc să dau fiecăruia după fapta lui; iar cel care înțelege aceasta e vrednic să se laude cu ea, căci din aceasta va avea mare folos.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"כִּי אִם־בְּזֹאת יִתְהַלֵּל הַמִּתְהַלֵּל...","translation":"„Doar cu aceasta poate lăudărosul să se laude...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ἀλλ' ἢ ἐν τούτῳ καυχάσθω ὁ καυχώμενος, συνίειν καὶ γινώσκειν ὅτι ἐγώ εἰμι Κύριος ὁ ποιῶν ἔλεος καὶ κρίμα καὶ δικαιοσύνην ἐπὶ τῆς γῆς, ὅτι ἐν τούτοις τὸ θέλημά μου, λέγει Κύριος.","greek":true,"translation":"„Ci întru aceasta să se laude cel ce se laudă, să priceapă și să cunoască faptul că Eu sunt Domnul, care fac milă și judecată și dreptate pe pământ, căci în acestea este voia Mea, zice Domnul.”","note":"Corespondență strânsă de conținut cu Textul Masoretic; formula tripartită „ἔλεος καὶ κρίμα καὶ δικαιοσύνην” redă cu acuratețe triada ebraică „hesed, mișpat, tzedaka”."}],"refs":["1 Corinteni 1:31","Ieremia 31:33,34","Ioan 17:3","Mica 6:8","Galateni 6:14","Ieremia 4:2"]}]},{"num":3,"title":"Șemini (sefard) - A opta","ref":"2 Samuel 6:1-19","intro":"Haftarat Șemini oglindește pericopa printr-un ecou tragic: dacă Nadab și Abihu mor pentru o abatere de la ritualul poruncit (Levitic 10), Uza moare pentru o abatere similară — atingerea Chivotului cu propria mână, în loc să-l poarte pe umeri, așa cum era poruncit explicit (Numeri 7:9). Capitolul se mișcă de la entuziasmul inițial al procesiunii, prin tragedia lui Uza și teama lui David, la relansarea reușită a urcării Chivotului, cu jertfe, muzică și dans — și se încheie cu disprețul Mihalei față de dansul regal al lui David, o notă discordantă lăsată deschisă chiar la finalul haftarei (continuarea, cu pedeapsa Mihalei, aparține versetelor următoare, în afara acestei lecturi).","verses":[{"v":"6:1","t":"David i-a adunat din nou pe toți aleșii din Israel, treizeci de mii [la număr].","tokens":[{"t":"David i-a adunat "},{"t":"din nou","w":"din nou","heb":"וַיֹּסֶף","translit":"vaiosef","strong":"H3254","pos":"verb, qal imperfect consecutiv","def_ro":"și a adăugat din nou, a continuat să adune.","greek":"ἔτι (eti)","greek_def_ro":"ἔτι (eti) — din nou, încă.","diff_ro":"Septuaginta are aici o cifră diferită de cea ebraică pentru numărul bărbaților aleși: „ἑβδομήκοντα χιλιάδας\" („șaptezeci de mii\"), nu „treizeci de mii\" — o divergență numerică reală.","dict_ro":"Iasaf od — Rashi explică precis „din nou”: poporul se strânsese deja o dată în jurul lui David când l-au uns rege la Hebron; aceasta este a doua adunare, distinctă de cea dintâi, de aceea textul marchează explicit repetiția cu „din nou”, nu doar „a adunat”."},{"t":" pe toți aleșii din Israel, treizeci de mii [la număr]."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „i-a adunat din nou” — pentru că se adunaseră deja la el când l-au făcut rege la Hebron, iar aceasta a fost o a doua adunare; de aceea se spune „din nou”."},{"author":"Metzudat David","text":"„Fiindcă mulți se adunau la el încă din vremea când a devenit rege, de aceea a spus că a mai adunat din nou la el pe aleșii din Israel, ca să ridice Chivotul.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיֹּסֶף עוֹד דָּוִד אֶת־כָּל־בָּחוּר בְּיִשְׂרָאֵל שְׁלֹשִׁים אָלֶף׃","translation":"„David i-a adunat din nou pe toți aleșii din Israel, treizeci de mii...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ΚΑΙ συνήγαγεν ἔτι Δαυὶδ πάντα νεανίαν ἐξ Ἰσραήλ, ὡς ἑβδομήκοντα χιλιάδας.","greek":true,"translation":"„Și David a adunat din nou pe toți tinerii din Israel, ca la șaptezeci de mii.”","note":"Divergență numerică reală și semnificativă: Textul Masoretic are 30.000 (șeloșim alef), pe când Septuaginta are 70.000 (ἑβδομήκοντα χιλιάδας) — o discrepanță substanțială, necorespunzătoare unei simple confuzii grafice de literă-cifră, documentată ca atare în critica textuală a cărților Samuel."}],"refs":["2 Samuel 5:1","1 Împărați 8:1","1 Cronici 13:1-4","Psalmii 132:1-6"]},{"v":"6:2","t":"Apoi David s-a ridicat și a mers, împreună cu tot poporul care era cu el, de la Baalei-Iuda, ca să ridice de acolo Chivotul lui Dumnezeu asupra căruia este invocat numele – numele DOMNULUI, Stăpânul Oștirilor, întronat pe heruvimi, este asupra lui.","tokens":[{"t":"Apoi David s-a ridicat și a mers, împreună cu tot poporul care era cu el, de la "},{"t":"Baalei-Iuda","w":"Baalei-Iuda","heb":"מִבַּעֲלֵי יְהוּדָה","translit":"mibaalē iehuda","strong":"H1184","pos":"nume propriu + nume propriu","def_ro":"Baale-Iuda, alt nume pentru Chiriat-Iearim.","diff_ro":"Septuaginta nu tratează acest nume ca toponim, ci îl traduce „ἀπὸ τῶν ἀρχόντων Ἰούδα\" („de la conducătorii lui Iuda\") — citind „Baalei\" ca termen generic („stăpâni/conducători\"), nu ca parte dintr-un nume de loc.","dict_ro":"Baale Yehuda — Rashi identifică locul, citând Iosua 15:9 și 1 Cronici 13:6, drept un alt nume pentru Chiriat-Iearim, unde Chivotul fusese adus și păstrat de la înfrângerea filistenilor (1 Samuel 7:1); cuvântul „baal” aici are, după Rashi, sensul de „câmpie/loc neted”, nu de zeitate."},{"t":", ca să ridice de acolo Chivotul lui Dumnezeu asupra căruia este invocat numele – numele DOMNULUI, Stăpânul Oștirilor, întronat pe heruvimi, este asupra lui."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „miBaalei Yehuda” — aceasta este Chiriat-Iearim, după cum se spune la Iosua: „și hotarul se întorcea și urca la Baala, aceasta e Chiriat-Iearim” (Iosua 15:9), și tot așa la Cronici: „și David și tot Israelul s-au suit la Baalata, aceasta e Chiriat-Iearim” (1 Cronici 13:6); „baal” e un termen de câmpie/loc neted."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיָּקָם וַיֵּלֶךְ דָּוִד...","translation":"„Apoi David s-a ridicat și a mers...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἀνέστη καὶ ἐπορεύθη Δαυὶδ καὶ πᾶς ὁ λαὸς ὁ μετ' αὐτοῦ καὶ ἀπὸ τῶν ἀρχόντων Ἰούδα ἐν ἀναβάσει τοῦ ἀναγαγεῖν ἐκεῖθεν τὴν κιβωτὸν τοῦ Θεοῦ, ἐφ' ἣν ἐπεκλήθη τὸ ὄνομα τοῦ Κυρίου τῶν δυνάμεων καθημένου ἐπὶ τῶν Χερουβὶν ἐπ' αὐτῆς.","greek":true,"translation":"„Și s-a ridicat și a mers David și tot poporul care era cu el, și dintre căpeteniile lui Iuda, în suire, ca să aducă de acolo chivotul lui Dumnezeu, peste care s-a chemat numele Domnului puterilor, care șade pe heruvimi, peste el.”","note":"Divergență de nume propriu: acolo unde Textul Masoretic are toponimul „Baale-Iuda”, Septuaginta traduce generic prin „căpeteniile lui Iuda” (τῶν ἀρχόντων Ἰούδα) — o citire diferită a consoanelor ebraice, tratând „baalei” ca „stăpânii/căpeteniile” lui Iuda, nu ca parte a unui nume de loc."}],"refs":["1 Cronici 13:5,6","1 Samuel 7:1","Exod 25:18-22","1 Samuel 4:4","Psalmii 80:1","1 Împărați 8:6,7"]},{"v":"6:3","t":"Și au pus Chivotul lui Dumnezeu într-un car nou și l-au purtat din casa lui Avinadav care era pe deal, iar Uza și Ahio, fiii lui Avinadav, conduceau carul cel nou.","tokens":[{"t":"Și au pus Chivotul lui Dumnezeu într-un "},{"t":"car nou","w":"car nou","heb":"עֲגָלָה","translit":"agala","strong":"H5699","pos":"substantiv, feminin singular","def_ro":"car nou, căruță nouă.","greek":"ἅμαξα καινή (hamaxa kaine)","greek_def_ro":"ἅμαξα καινή (hamaxa kaine) — car nou.","dict_ro":"Agala — greșeala fatală a lui David, spune Rashi, e una pe care „chiar copiii de școală o cunosc”: legea spune explicit că lucrurile sfinte trebuie purtate pe umeri (Numeri 7:9), nu transportate cu carul, oricât de nou. Metoda carului fusese folosită anterior doar de filisteni (1 Samuel 6:7), care nu erau ținuți de Lege — copierea metodei lor păgâne, nu a poruncii mozaice, e sursa reală a tragediei care urmează."},{"t":" și l-au purtat din casa lui Avinadav care era pe deal, iar Uza și Ahio, fiii lui Avinadav, conduceau carul cel nou."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: a greșit într-un lucru pe care chiar copiii de la școală îl cunosc — „căci slujba sfântă e a lor, pe umeri o vor purta” (Numeri 7:9); și fiindcă spusese [David]: „cântări au fost pentru mine hotărârile Tale, în casa pribegiei mele” (Psalmii 119:54), a fost pedepsit să ajungă la aceasta, și Uza a murit prin mâna lui — de aceea, când au adus-o din casa lui Oved, au adus-o pe umeri, precum se spune: „le-a zis: voi sunteți căpeteniile părinților leviților, sfințiți-vă voi și frații voștri și suiți Chivotul... căci întâia dată n-ați fost voi, de aceea DOMNUL Dumnezeul nostru a făcut spărtură în noi, căci nu L-am căutat după rânduială” (1 Cronici 15:12-13)."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיַּרְכִּבוּ אֶת־אֲרוֹן הָאֱלֹהִים...","translation":"„Și au pus Chivotul lui Dumnezeu într-un car nou...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐπεβίβασαν τὴν κιβωτὸν Κυρίου ἐφ' ἅμαξαν καινὴν καὶ ᾖραν αὐτὴν ἐξ οἴκου Ἀμιναδὰβ τοῦ ἐν τῷ βουνῷ· καὶ Ὀζὰ καὶ οἱ ἀδελφοὶ αὐτοῦ υἱοὶ Ἀμιναδὰβ ἦγον τὴν ἅμαξαν σὺν τῇ κιβωτῷ.","greek":true,"translation":"„Și au suit chivotul Domnului pe un car nou și l-au ridicat din casa lui Aminadab cea de pe deal; și Oza și frații lui, fiii lui Aminadab, mânau carul împreună cu chivotul.”","note":"Divergență reală de rudenie: Textul Masoretic numește explicit „Uza și Ahio” (nume propriu), pe când Septuaginta redă „Οζὰ καὶ οἱ ἀδελφοὶ αὐτοῦ” („Oza și frații lui”) — citind „Ahio” nu ca nume propriu, ci ca substantiv comun „ahav” (fratele lui) la plural, o interpretare gramaticală diferită a consoanelor ebraice."}],"refs":["Numeri 4:5-12","Numeri 7:9","1 Samuel 6:7"]},{"v":"6:4","t":"Și l-au purtat din casa lui Avinadav, care era pe deal, împreună cu Chivotul lui Dumnezeu, iar Ahio mergea înaintea carului.","tokens":[{"t":"Și l-au purtat din casa lui Avinadav, care era pe deal, împreună cu Chivotul lui Dumnezeu, iar Ahio mergea "},{"t":"înaintea","w":"înaintea","heb":"לִפְנֵי","translit":"lifnē","strong":"H6440","pos":"substantiv, masculin și feminin plural construct","def_ro":"înaintea, în fața.","greek":"ἔμπροσθεν (emprosthen)","greek_def_ro":"ἔμπροσθεν (emprosthen) — înainte, în fața.","dict_ro":"Lifnei — Metzudat David explică de ce Ahio, nu Uza, e menționat mergând „înaintea Chivotului”: Ahio conducea boii din față, în timp ce Uza mergea alături de Chivot, pe lateral — poziție care explică de ce doar Uza a simțit boii clătinând Chivotul și a întins mâna, în timp ce Ahio, aflat înainte, nu a observat nimic."},{"t":" carului."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"„Cu Chivotul lui Dumnezeu” — acesta e un verset scurtat; [înseamnă:] și ei veneau cu chivotul lui Dumnezeu."},{"author":"Metzudat David","text":"„Ahio mergea înaintea Chivotului” pentru a conduce boii din față, spre deosebire de Uza, care mergea alături de Chivot — de aceea doar el a simțit clătinarea boilor, iar Ahio, fiind în față, nu și-a dat seama.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיִּשָּׂאֻהוּ מִבֵּית אֲבִינָדָב...","translation":"„Și l-au purtat din casa lui Avinadav...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ οἱ ἀδελφοὶ αὐτοῦ ἐπορεύοντο ἔμπροσθεν τῆς κιβωτοῦ.","greek":true,"translation":"„Și frații lui mergeau înaintea chivotului.”","note":"Septuaginta e mult mai scurtă la acest verset, omițând repetarea „l-au purtat din casa lui Avinadav, care era pe deal” (deja spusă la v.3) și păstrând doar partea finală despre mersul înaintea Chivotului — coerent cu redarea de la v.3, unde „Ahio” fusese deja tradus la plural, „frații lui”."}],"refs":["1 Samuel 7:1,2","1 Cronici 13:7"]},{"v":"6:5","t":"Și David și toată casa lui Israel jucau înaintea DOMNULUI cu tot [soiul de] instrumente din lemn de chiparos, și cu harpe, și cu lire, și cu tobe, și cu tamburine, și cu talgere.","tokens":[{"t":"Și David și toată casa lui Israel jucau înaintea DOMNULUI cu tot [soiul de] instrumente din "},{"t":"lemn de chiparos","w":"lemn de chiparos","heb":"בְרוֹשִׁים","translit":"veroșim","strong":"H1265","pos":"substantiv, masculin plural","def_ro":"lemne de chiparos/brad.","diff_ro":"Septuaginta are aici „ἐν ὀργάνοις ἡρμοσμένοις ἐν ἰσχύϊ\" („cu instrumente bine acordate, cu putere\"), fără mențiunea specifică a lemnului de chiparos — o descriere generică a instrumentelor, nu un detaliu despre materialul lor.","dict_ro":"Beroș — Rashi precizează că expresia nu descrie pădurea prin care treceau, ci materialul din care erau confecționate instrumentele muzicale înșirate imediat după — harpe, lire, tobe, tamburine, talgere — toate lucrate din lemn de chiparos, cunoscut pentru rezonanța lui bună."},{"t":", și cu harpe, și cu lire, și cu tobe, și cu tamburine, și cu talgere."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „becol atzei veroșim” — cu instrumente muzicale lucrate din lemn de chiparos."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְדָוִד וְכָל־בֵּית יִשְׂרָאֵל מְשַׂחֲקִים...","translation":"„Și David și toată casa lui Israel jucau înaintea DOMNULUI...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ Δαυὶδ καὶ υἱοὶ Ἰσραὴλ παίζοντες ἐνώπιον Κυρίου ἐν ὀργάνοις ἡρμοσμένοις ἐν ἰσχύϊ, καὶ ἐν ᾠδαῖς καὶ ἐν κινύραις καὶ ἐν νάβλαις καὶ ἐν τυμπάνοις καὶ ἐν κυμβάλοις καὶ ἐν αὐλοῖς.","greek":true,"translation":"„Și David și fiii lui Israel jucau înaintea Domnului cu instrumente acordate cu putere, și cu cântări, și cu lire, și cu harpe, și cu tobe, și cu chimvale, și cu fluiere.”","note":"Divergență reală: acolo unde Textul Masoretic specifică „lemn de chiparos” ca material al instrumentelor, Septuaginta traduce generic „instrumente acordate cu putere” (ὀργάνοις ἡρμοσμένοις ἐν ἰσχύϊ) — pierzând referința la materialul lemnos — și adaugă „fluiere” (αὐλοῖς), instrument absent din lista ebraică."}],"refs":["1 Cronici 13:8","Psalmii 150:3-5","Amos 6:5","1 Samuel 16:16","1 Samuel 10:5","2 Împărați 3:15"]},{"v":"6:6","t":"Au ajuns la aria lui Nahon, și Uza s-a întins către Chivotul lui Dumnezeu și l-a apucat, căci boii îl mișcaseră.","tokens":[{"t":"Au ajuns la aria lui Nahon, și Uza s-a întins către Chivotul lui Dumnezeu și l-a "},{"t":"apucat","w":"apucat","heb":"וַיֹּאחֶז","translit":"vaiohez","strong":"H270","pos":"verb, qal imperfect consecutiv","def_ro":"și l-a prins, l-a apucat.","greek":"κρατέω (krateo)","greek_def_ro":"κρατέω (krateo) — a apuca, a ține strâns.","dict_ro":"Ahaz — Metzudat David explică motivul gestului: Uza a crezut că Chivotul e pe cale să cadă din car, din pricina zdruncinării provocate de boi, și a întins mâna instinctiv ca să-l țină — un gest omenește explicabil, dar care presupunea o neîncredere implicită în capacitatea Chivotului de a se apăra singur, sfințenia lui fiind mai presus de nevoia de sprijin fizic omenesc."},{"t":", căci boii îl mișcaseră."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „ki șametu habakar” — căci boii l-au clătinat și l-au mișcat, așa cum traduce Targum Ionatan „ari meragohi toraia”."},{"author":"Metzudat David","text":"„Uza și-a întins mâna” — a crezut că, dacă boii îl clatină, va cădea de pe car.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיָּבֹאוּ עַד־גֹּרֶן נָכוֹן...","translation":"„Au ajuns la aria lui Nahon...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ παραγίνονται ἕως ἅλω Ναχώρ, καὶ ἐξέτεινεν Ὀζὰ τὴν χεῖρα αὐτοῦ ἐπὶ τὴν κιβωτὸν τοῦ Θεοῦ κατασχεῖν αὐτὴν καὶ ἐκράτησεν αὐτήν, ὅτι περιέσπασεν αὐτὴν ὁ μόσχος.","greek":true,"translation":"„Și au ajuns până la aria lui Nahor, și Oza și-a întins mâna spre chivotul lui Dumnezeu ca să-l țină, și l-a apucat, căci vițelul l-a răsucit.”","note":"Divergență de nume propriu reală: Textul Masoretic are „Nahon” (נָכוֹן), Septuaginta are „Nahor” (Ναχώρ) — o citire diferită a numelui locului; și „boii” (habakar, plural generic) devin în greacă „vițelul” (ὁ μόσχος, singular) — o schimbare de număr."}],"refs":["1 Cronici 13:9","Numeri 4:15,19,20"]},{"v":"6:7","t":"Mânia DOMNULUI s-a aprins împotriva lui Uza și Dumnezeu l-a lovit acolo pentru greșeală, și Uza a murit acolo, alături de Chivotul lui Dumnezeu.","tokens":[{"t":"Mânia DOMNULUI s-a aprins împotriva lui Uza și Dumnezeu l-a lovit acolo pentru "},{"t":"greșeală","w":"greșeală","heb":"הַשַּׁל","translit":"hașal","strong":"H7944","pos":"substantiv, masculin singular","def_ro":"greșeala, eroarea neintenționată.","diff_ro":"Septuaginta nu menționează motivul exact („greșeala\") — spune simplu „Dumnezeu l-a lovit acolo\", fără termenul specific pentru vina/greșeala lui Uza.","dict_ro":"Șal — cuvânt extrem de rar (hapax legomenon în această formă), pe care Rashi îl citește ca „șgaga” (greșeală neintenționată, din neștiință) — Uza n-a acționat din răutate, ci dintr-o judecată greșită pe care ar fi trebuit s-o evite printr-un raționament simplu, a fortiori (kal vahomer): dacă cei ce purtau Chivotul pe umeri l-au trecut cu bine prin Iordan fără să-l atingă, cu atât mai puțin era nevoie ca el să-l atingă acum, pe uscat."},{"t":", și Uza a murit acolo, alături de Chivotul lui Dumnezeu."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „al hașal” — pentru greșeala [neintenționată], căci ar fi trebuit să raționeze a fortiori: dacă cei ce l-au purtat [pe Chivot] l-au purtat prin Iordan [fără să-l atingă cu mâna], cu atât mai mult el însuși [n-ar fi trebuit să-l atingă]."},{"author":"Metzudat David","text":"„S-a mâniat DOMNUL” — pentru puțina lui încredere în DOMNUL, gândind că Chivotul ar putea cădea la pământ; „pentru greșeală” — pentru fapta pe care a făcut-o din neștiință, ca și cum ar fi uitat că e Chivotul DOMNULUI.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיִּחַר־אַף יְהוָה בְּעֻזָּה...","translation":"„Mânia DOMNULUI s-a aprins împotriva lui Uza...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐθυμώθη ὀργῇ Κύριος τῷ Ὀζά, καὶ ἔπαισεν αὐτὸν ἐκεῖ ὁ Θεός, καὶ ἀπέθανεν ἐκεῖ παρὰ τὴν κιβωτὸν τοῦ Κυρίου ἐνώπιον τοῦ Θεοῦ.","greek":true,"translation":"„Și s-a mâniat cu mânie Domnul pe Oza, și l-a lovit acolo Dumnezeu, și a murit acolo lângă chivotul Domnului, înaintea lui Dumnezeu.”","note":"Divergență reală: cuvântul rar „al-hașal” (pentru greșeală/eroare) din Textul Masoretic nu are un echivalent distinct în Septuaginta, care redă doar structura generală a pedepsei, fără a preciza motivul printr-un termen separat — probabil pentru că traducătorii alexandrini n-au recunoscut sau n-au putut echivala acest cuvânt rar."}],"refs":["Levitic 10:1-3","1 Samuel 6:19","1 Cronici 13:10","1 Cronici 15:2,13"]},{"v":"6:8","t":"David s-a mâniat de răbufnirea cu care DOMNUL răbufnise împotriva lui Uza și a numit locul acela Pereț-Uza (n.t. Răbufnirea [contra] lui Uza), până în ziua de astăzi.","tokens":[{"t":"David s-a mâniat de "},{"t":"răbufnirea","w":"răbufnirea","heb":"פֶּרֶץ","translit":"pereț","strong":"H6556","pos":"substantiv, masculin singular","def_ro":"spărtura, izbucnirea bruscă.","greek":"διακοπή (diakope)","greek_def_ro":"διακοπή (diakope) — spărtură, izbucnire.","dict_ro":"Peretz — literal „spărtură”, imaginea unei bariere care cedează brusc sub presiune; Metzudat David citește „vayihar leDavid” nu ca mânie a lui David împotriva lui Dumnezeu, ci ca o tulburare interioară îndreptată spre sine însuși, în felul în care „vayihar leȘmuel” (1 Samuel 15:11) descrie neliniștea lui Samuel, nu furia lui — David e zguduit și îngrozit, nu supărat pe DOMNUL."},{"t":" cu care DOMNUL răbufnise împotriva lui Uza și a numit locul acela Pereț-Uza (n.t. Răbufnirea [contra] lui Uza), până în ziua de astăzi."}],"commentaries":[{"author":"Metzudat David","text":"„Vayihar leDavid” — s-a mâhnit și s-a tulburat pentru sine, în felul celui strâmtorat și înspăimântat, la fel cum se spune «și s-a mâhnit Samuel» (1 Samuel 15:11); „pentru spărtura” — din pricina neliniștii pe care i-a provocat-o acea spărtură.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיִּחַר לְדָוִד עַל אֲשֶׁר פָּרַץ יְהוָה פֶּרֶץ בְּעֻזָּה...","translation":"„David s-a mâniat de răbufnirea cu care DOMNUL răbufnise împotriva lui Uza...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἠθύμησε Δαυὶδ ὑπὲρ οὗ διέκοψε Κύριος διακοπὴν ἐν τῷ Ὀζά· καὶ ἐκλήθη ὁ τόπος ἐκεῖνος Διακοπὴ Ὀζὰ ἕως τῆς ἡμέρας ταύτης.","greek":true,"translation":"„Și s-a mâhnit David pentru că Domnul a făcut spărtură asupra lui Oza; și s-a numit locul acela Spărtura lui Oza până în ziua aceasta.”","note":"Divergență reală de nuanță emoțională: Textul Masoretic folosește „vayihar” (verbul „a se mânia/a se aprinde”, aceeași rădăcină ca la v.7 pentru mânia DOMNULUI), pe când Septuaginta alege „ἠθύμησε” („s-a mâhnit/descurajat”) — o redare mai blândă, care mută tonul de la o posibilă tulburare/mânie a lui David spre simplă tristețe."}],"refs":["1 Cronici 13:11,12","Iona 4:1,9"]},{"v":"6:9","t":"Și David s-a temut de DOMNUL în ziua aceea și a spus: „Cum să vină Chivotul DOMNULUI la mine?”","tokens":[{"t":"Și David s-a temut de DOMNUL în ziua aceea și a spus: „Cum să "},{"t":"vină","w":"vină","heb":"יָבוֹא","translit":"iavo","strong":"H935","pos":"verb, qal imperfect","def_ro":"să vină, să intre.","greek":"εἰσέρχομαι (eiserchomai)","greek_def_ro":"εἰσέρχομαι (eiserchomai) — a veni, a intra.","dict_ro":"Bo — Metzudat David explică teama lui David nu ca o îndoială privind valoarea Chivotului, ci ca o conștientizare bruscă a riscului practic al sfințeniei sale: dacă un act aparent minor precum atingerea Chivotului a adus moarte instantanee, David se întreabă legitim cum ar putea asigura o găzduire corespunzătoare, fără riscul unei noi greșeli fatale — aceeași teamă structurală ce apare la filisteni în 1 Samuel 6:20."},{"t":" Chivotul DOMNULUI la mine?”"}],"commentaries":[{"author":"Metzudat David","text":"„Et ADONAI” — Chivotul DOMNULUI, căci a gândit că nu se poate păzi cu adevărat sfințenia lui.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיִּרָא דָוִד אֶת־יְהוָה בַּיּוֹם הַהוּא...","translation":"„Și David s-a temut de DOMNUL în ziua aceea...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐφοβήθη Δαυὶδ τὸν Κύριον ἐν τῇ ἡμέρᾳ ἐκείνῃ λέγων· πῶς εἰσελεύσεται πρός με ἡ κιβωτὸς Κυρίου;","greek":true,"translation":"„Și s-a temut David de Domnul în ziua aceea, zicând: cum va intra la mine chivotul Domnului?”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Numeri 17:12,13","1 Samuel 6:20","1 Samuel 5:10,11"]},{"v":"6:10","t":"Și David n-a mai vrut să aducă Chivotul DOMNULUI la el, în Orașul lui David, ci David l-a deturnat către casa lui Oved-Edom, ghititul.","tokens":[{"t":"Și David n-a mai vrut să aducă Chivotul DOMNULUI la el, în Orașul lui David, ci David l-a deturnat către casa lui "},{"t":"Oved-Edom, ghititul","w":"Oved-Edom, ghititul","heb":"עֹבֵד אֱדוֹם","translit":"ovēd edom","strong":"H5654","pos":"nume propriu + nume propriu","def_ro":"Oved-Edom din Gat.","diff_ro":"Septuaginta transliterează acest nume „Ἀβεδδαρά\" („Abeddara\"), o formă destul de diferită de „Oved-Edom\" din ebraică — posibil o variantă textuală veche a numelui.","dict_ro":"Ha-Ghiti — epitetul „ghititul” (din Gat) ar sugera o origine filisteană, dar Rashi, citând 1 Cronici 15:18, îl identifică drept levit, unul dintre portarii sanctuarului — probabil numit „ghitit” după un oraș levitic cu acest nume sau după o perioadă petrecută acolo, nu după etnie. Alegerea unei case levite, nu oricare, pentru a găzdui Chivotul, sugerează că David, chiar înspăimântat, a rămas atent la rânduiala corectă."},{"t":"."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Oved-Edom” era levit, după cum stă scris la Cronici, „și dintre portari era” (1 Cronici 15:18)."},{"author":"Metzudat David","text":"„L-a deturnat” — l-a abătut de la drumul spre Cetatea lui David, spre casa lui Oved-Edom.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְלֹא־אָבָה דָוִד לְהָסִיר אֵלָיו...","translation":"„Și David n-a mai vrut să aducă Chivotul DOMNULUI la el...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ οὐκ ἐβούλετο Δαυὶδ τοῦ ἐκκλῖναι πρὸς αὐτὸν τὴν κιβωτὸν διαθήκης Κυρίου εἰς τὴν πόλιν Δαυίδ, καὶ ἀπέκλινεν αὐτὴν Δαυὶδ εἰς οἶκον Ἀβεδδαρὰ τοῦ Γεθαίου.","greek":true,"translation":"„Și n-a voit David să abată la el chivotul legământului Domnului, în cetatea lui David, și l-a abătut David spre casa lui Abeddara Gheteul.”","note":"Divergență reală de titulatură: Septuaginta adaugă „legământului” (διαθήκης) la „chivotul Domnului”, formulă absentă la acest verset în Textul Masoretic — o completare teologică explicativă."}],"refs":["1 Cronici 15:18","1 Cronici 16:5","1 Cronici 26:4-8","2 Samuel 15:19","2 Samuel 18:2","1 Cronici 13:13,14"]},{"v":"6:11","t":"Și Chivotul DOMNULUI a rămas în casa lui Oved-Edom, ghititul, timp de trei luni, iar DOMNUL l-a binecuvântat pe Oved-Edom împreună cu toată casa lui.","tokens":[{"t":"Și Chivotul DOMNULUI a rămas în casa lui Oved-Edom, ghititul, timp de trei luni, iar DOMNUL l-a "},{"t":"binecuvântat","w":"binecuvântat","heb":"וַיְבָרֶךְ","translit":"vaivareh","strong":"H1288","pos":"verb, piel imperfect consecutiv","def_ro":"și a binecuvântat.","greek":"εὐλογέω (eulogeo)","greek_def_ro":"εὐλογέω (eulogeo) — a binecuvânta.","dict_ro":"Barach — Rashi citează o tradiție (bazată pe 1 Cronici 26:5, unde Oved-Edom e numit „al optulea” între cei binecuvântați cu mulți fii) potrivit căreia soția lui Oved-Edom și cele opt nurori ale sale au născut fiecare câte șase fii dintr-o singură sarcină, în cele trei luni — o binecuvântare literalizată, fizică, ca răspuns direct la primirea cu credință a aceluiași Chivot care adusese moarte în casa lui Uza."},{"t":" pe Oved-Edom împreună cu toată casa lui."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: soția lui și cele opt nurori ale sale au născut șase fii fiecare, dintr-o singură sarcină, precum se spune: „lucrarea lui, al optulea” (1 Cronici 26:5) — șaizeci și doi [de fii] lui Oved-Edom."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיֵּשֶׁב אֲרוֹן יְהוָה בֵּית עֹבֵד אֱדוֹם...","translation":"„Și Chivotul DOMNULUI a rămas în casa lui Oved-Edom...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐκάθισεν ἡ κιβωτὸς τοῦ Κυρίου εἰς οἶκον Ἀβεδδαρὰ τοῦ Γεθαίου μῆνας τρεῖς· καὶ εὐλόγησε Κύριος ὅλον τὸν οἶκον Ἀβεδδαρὰ καὶ πάντα τὰ αὐτοῦ.","greek":true,"translation":"„Și a șezut chivotul Domnului în casa lui Abeddara Gheteul trei luni; și a binecuvântat Domnul toată casa lui Abeddara și toate ale lui.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Geneza 30:27","Geneza 39:5,23","Proverbe 3:9,10","Maleahi 3:10"]},{"v":"6:12","t":"Și i s-a vestit lui David că DOMNUL îl binecuvântase pe Oved-Edom și toată casa lui din pricina Chivotului DOMNULUI, și David a mers și a ridicat Chivotul lui Dumnezeu din casa lui Oved-Edom, către Orașul lui David, cu bucurie.","tokens":[{"t":"Și i s-a vestit lui David că DOMNUL îl binecuvântase pe Oved-Edom și toată casa lui din pricina Chivotului DOMNULUI, și David a mers și a ridicat Chivotul lui Dumnezeu din casa lui Oved-Edom, către Orașul lui David, cu "},{"t":"bucurie","w":"bucurie","heb":"בְּשִׂמְחָה","translit":"besimha","strong":"H8057","pos":"substantiv, feminin singular","def_ro":"cu bucurie, cu veselie.","greek":"εὐφροσύνη (euphrosyne)","greek_def_ro":"εὐφροσύνη (euphrosyne) — bucurie, veselie.","dict_ro":"Simha — Metzudat David identifică sursa concretă a bucuriei lui David: vestea binecuvântării revărsate asupra casei lui Oved-Edom l-a asigurat pe David că, de această dată, Chivotul poate fi mutat fără primejdie — bucuria nu e doar emoție religioasă generică, ci ușurarea practică a unui om care abia acum se simte liber să corecteze greșeala din urmă cu trei luni."},{"t":"."}],"commentaries":[{"author":"Metzudat David","text":"„Din pricina Chivotului” — care șade în casa lui, căci înainte de aceasta n-a ajuns la o asemenea binecuvântare; „Orașul lui David” — către cetatea lui David, adică Țion.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיֻּגַּד לַמֶּלֶךְ דָּוִד...","translation":"„Și i s-a vestit lui David...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἀπηγγέλη τῷ βασιλεῖ Δαυὶδ λέγοντες· εὐλόγησε Κύριος τὸν οἶκον Ἀβεδδαρὰ καὶ πάντα τὰ αὐτοῦ ἕνεκα τῆς κιβωτοῦ τοῦ Θεοῦ, καὶ ἐπορεύθη Δαυὶδ καὶ ἀνήγαγε τὴν κιβωτὸν τοῦ Κυρίου ἐκ τοῦ οἴκου Ἀβεδδαρὰ εἰς τὴν πόλιν Δαυὶδ ἐν εὐφροσύνῃ.","greek":true,"translation":"„Și s-a vestit regelui David, zicându-i: a binecuvântat Domnul casa lui Abeddara și toate ale lui, din pricina chivotului lui Dumnezeu; și a mers David și a suit chivotul Domnului din casa lui Abeddara în cetatea lui David, cu veselie.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["1 Cronici 15:1-3,25","Psalmii 24:7-10","Psalmii 68:24-27","Psalmii 132:6-8"]},{"v":"6:13","t":"La fiecare șase pași pe care îi făceau purtătorii Chivotului DOMNULUI, el jertfea un taur și un taur îngrășat.","tokens":[{"t":"La fiecare "},{"t":"șase pași","w":"șase pași","heb":"שִׁשָּׁה צְעָדִים","translit":"șișa țeadim","strong":"H6806","pos":"numeral + substantiv, masculin plural","def_ro":"șase pași.","dict_ro":"Una dintre cele mai mari divergențe din acest capitol: Septuaginta nu are deloc imaginea „la fiecare șase pași\" — în loc de asta, spune că „erau cu el, ducând Chivotul, șapte cete/coruri\" (ἑπτὰ χοροὶ), o imagine complet diferită, legată probabil de o lectură alternativă a termenului ebraic pentru „pași\". Și jertfele diferă: „un vițel și miei\" (plural), nu „un taur și un taur îngrășat\" ca în ebraică."},{"t":" pe care îi făceau purtătorii Chivotului DOMNULUI, el jertfea un taur și un taur îngrășat."}],"commentaries":[{"author":"Metzudat David","text":"„După fiecare șase pași” — de fiecare dată când purtătorii Chivotului făceau șase pași, David jertfea din nou, iar aceasta s-a repetat de-a lungul întregului drum.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיְהִי כִּי צָעֲדוּ נֹשְׂאֵי אֲרוֹן־יְהוָה...","translation":"„La fiecare șase pași pe care îi făceau purtătorii Chivotului DOMNULUI...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἦσαν μετ' αὐτοῦ αἴροντες τὴν κιβωτὸν ἑπτὰ χοροὶ καὶ θῦμα μόσχος καὶ ἄρνες.","greek":true,"translation":"„Și erau cu el, purtând chivotul, șapte coruri, și ca jertfă, un vițel și miei.”","note":"Divergență reală și substanțială: Textul Masoretic descrie jertfe repetate „la fiecare șase pași”, cu „un taur și un taur îngrășat”; Septuaginta redă cu totul altfel — „șapte coruri” de purtători/cântăreți și o singură jertfă, „un vițel și miei” — o versiune notabil diferită atât în structura procesiunii, cât și în natura jertfelor aduse."}],"refs":["Numeri 4:15","Numeri 7:9","Iosua 3:3","1 Împărați 8:5","2 Cronici 5:6","1 Cronici 15:2,15,25,26"]},{"v":"6:14","t":"Și David dansa cu toată puterea [lui] înaintea DOMNULUI, încins cu o tunică de in.","tokens":[{"t":"Și David dansa cu toată puterea [lui] înaintea DOMNULUI, încins cu o "},{"t":"tunică de in","w":"tunică de in","heb":"אֵפוֹד","translit":"ēfod","strong":"H646","pos":"substantiv, masculin singular construct","def_ro":"efod de in, veșmânt simplu de in.","diff_ro":"Septuaginta are aici „στολὴν ἔξαλλον\" („o robă neobișnuită/stranie\"), nu termenul tehnic „efod de in\" ca în ebraică — o descriere vagă, fără detaliul despre material sau despre tipul specific de veșmânt preoțesc.","dict_ro":"Efod bad — nu efodul bogat, împodobit cu pietre prețioase, al marelui preot, ci un veșmânt simplu de in, purtat de cei consacrați slujirii DOMNULUI într-un mod smerit — aceeași expresie exactă descrie veșmântul tânărului Samuel (1 Samuel 2:18). Metzudat David notează că David, deși rege, s-a îmbrăcat pentru acest moment nu în straie regale, ci în haina simplă a unui slujitor devotat."},{"t":"."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „mecharker” — dansa; „efod bad” — o mantie de in, tradusă de Targum Ionatan „kardut”, aceeași folosită și pentru mantiile Tamarei, sora lui Abșalom (2 Samuel 13:18)."},{"author":"Metzudat David","text":"„Efod bad” — un veșmânt făcut după chipul efodului marelui preot, dedicat celor ce se dedică în chip aparte slujirii DOMNULUI, precum se spune despre Samuel: „iar Samuel... încins cu un efod de in” (1 Samuel 2:18) — și David l-a îmbrăcat la ridicarea Chivotului.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְדָוִד מְכַרְכֵּר בְּכָל־עֹז לִפְנֵי יְהוָה...","translation":"„Și David dansa cu toată puterea [lui] înaintea DOMNULUI...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ Δαυὶδ ἀνεκρούετο ἐν ὀργάνοις ἡρμοσμένοις ἐνώπιον Κυρίου, καὶ ὁ Δαυὶδ ἐνδεδυκὼς στολὴν ἔξαλλον.","greek":true,"translation":"„Și David cânta la instrumente acordate înaintea Domnului, iar David era îmbrăcat cu o haină neobișnuită.”","note":"Divergență reală: acolo unde Textul Masoretic spune limpede că David „dansa” (mecharker), Septuaginta traduce „ἀνεκρούετο” — „cânta la instrumente” — o schimbare de acțiune, de la dans la interpretare muzicală; iar „efod bad” (tunică simplă de in) devine „στολὴν ἔξαλλον” („haină neobișnuită/ciudată”), o redare vagă a veșmântului specific."}],"refs":["Exod 15:20","Psalmii 149:3","Luca 15:25","1 Cronici 15:27"]},{"v":"6:15","t":"Și David și toată casa lui Israel au ridicat Chivotul DOMNULUI cu glas vesel și puternic, și cu sunet de corn.","tokens":[{"t":"Și David și toată casa lui Israel au ridicat Chivotul DOMNULUI cu "},{"t":"glas vesel și puternic","w":"glas vesel și puternic","heb":"בִּתְרוּעָה","translit":"bitrua","strong":"H8643","pos":"substantiv, feminin singular","def_ro":"cu strigăt, cu sunet de veselie.","greek":"κραυγή (krauge)","greek_def_ro":"κραυγή (krauge) — strigăt, chemare puternică.","dict_ro":"Terua — termen tehnic care desemnează atât strigătul uman de bucurie/luptă, cât și sunetul specific al trâmbiței (aceeași rădăcină din „Yom Terua”, numele biblic al Roș Hașana); asocierea directă cu „kol șofar” (sunetul cornului) în același verset arată o procesiune completă senzorial — voci umane și instrumente muzicale unite într-un singur act public de bucurie."},{"t":", și cu sunet de corn."}],"commentaries":[{"author":"Metzudat David","text":"„Bitrua” — cu glas de bucurie, așa cum e obiceiul la aducerea unui lucru de mare cinste, iar aceasta arată bucuria pe care o simțeau la ridicarea Chivotului.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְדָוִד וְכָל־בֵּית יִשְׂרָאֵל מַעֲלִים...","translation":"„Și David și toată casa lui Israel au ridicat Chivotul DOMNULUI...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ Δαυὶδ καὶ πᾶς ὁ οἶκος Ἰσραὴλ ἀνήγαγον τὴν κιβωτὸν Κυρίου μετὰ κραυγῆς καὶ μετὰ φωνῆς σάλπιγγος.","greek":true,"translation":"„Și David și toată casa lui Israel au suit chivotul Domnului cu strigăt și cu sunet de trâmbiță.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Numeri 10:1-10","Iosua 6:4,5","Psalmii 47:1,5,6","Ezra 3:10,11","1 Cronici 15:16,25,28"]},{"v":"6:16","t":"Când Chivotul a ajuns în Orașul lui David, Mihal, fiica lui Șaul, a privit pe fereastră și l-a văzut pe regele David sărind și dansând înaintea DOMNULUI, și l-a disprețuit în inima ei.","tokens":[{"t":"Când Chivotul a ajuns în Orașul lui David, Mihal, fiica lui Șaul, a privit pe fereastră și l-a văzut pe regele David sărind și dansând înaintea DOMNULUI, și l-a "},{"t":"disprețuit","w":"disprețuit","heb":"וַתִּבֶז","translit":"vativez","strong":"H959","pos":"verb, qal imperfect consecutiv","def_ro":"și l-a disprețuit.","greek":"ἐξουδενόω (exoudenoo)","greek_def_ro":"ἐξουδενόω (exoudenoo) — a disprețui, a nesocoti.","dict_ro":"Baza — Metzudat David citește disprețul Mihalei nu ca o reacție morală, ci ca o judecată de etichetă regală: ea a considerat dansul public al lui David nepotrivit pentru un rege, mai ales „chiar înaintea Chivotului”, adică într-un context solemn unde s-ar fi așteptat o demnitate rezervată, nu o exprimare corporală atât de dezinhibată — o neînțelegere fundamentală a naturii adevăratei smerenii regale."},{"t":" în inima ei."}],"commentaries":[{"author":"Metzudat David","text":"„L-a disprețuit în inima ei” — a socotit-o, în inima ei, o faptă necuvenită pentru un rege să facă asemenea lucruri, chiar înaintea Chivotului.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְהָיָה אֲרוֹן יְהוָה בָּא עִיר דָּוִד...","translation":"„Când Chivotul a ajuns în Orașul lui David...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐγένετο τῆς κιβωτοῦ παραγινομένης ἕως πόλεως Δαυὶδ καὶ Μελχὸλ ἡ θυγάτηρ Σαοὺλ διέκυπτε διὰ τῆς θυρίδος καὶ εἶδε τὸν βασιλέα Δαυὶδ ὀρχούμενον καὶ ἀνακρουόμενον ἐνώπιον Κυρίου καὶ ἐξουδένωσεν αὐτὸν ἐν τῇ καρδίᾳ αὐτῆς.","greek":true,"translation":"„Și a fost când chivotul ajungea la cetatea lui David, Melhol, fiica lui Saul, se pleca pe fereastră și l-a văzut pe regele David dansând și cântând la instrumente înaintea Domnului, și l-a disprețuit în inima ei.”","note":"Corespondență strânsă cu Textul Masoretic; numele „Mihal” apare în forma grecizată „Μελχὸλ”."}],"refs":["1 Cronici 15:29","2 Samuel 3:14","Psalmii 69:7","Isaia 53:3","Faptele apostolilor 2:13"]},{"v":"6:17","t":"Au adus Chivotul DOMNULUI și l-au așezat la locul lui, în cortul pe care David îl ridicase pentru el; și David a adus arderi-de-tot înaintea DOMNULUI și jertfe de pace.","tokens":[{"t":"Au adus Chivotul DOMNULUI și l-au așezat la "},{"t":"locul lui","w":"locul lui","heb":"בִּמְקוֹמוֹ","translit":"bimkomo","strong":"H4725","pos":"substantiv, masculin singular construct + sufix","def_ro":"la locul lui.","greek":"τόπος αὐτῆς (topos autes)","greek_def_ro":"τόπος αὐτῆς (topos autes) — locul lui/ei.","dict_ro":"Makom — Metzudat David precizează că „locul lui” desemnează poziția special pregătită dinainte de David, în interiorul cortului pe care el însuși îl ridicase în acest scop — nu un cort improvizat pe loc, ci o structură pregătită anticipat, semn al planificării serioase din partea lui David pentru primirea permanentă a Chivotului la Ierusalim."},{"t":", în cortul pe care David îl ridicase pentru el; și David a adus arderi-de-tot înaintea DOMNULUI și jertfe de pace."}],"commentaries":[{"author":"Metzudat David","text":"„Bimkomo” — la locul pregătit pentru el în mijlocul cortului pe care David îl întinsese anume pentru Chivot.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיָּבִאוּ אֶת־אֲרוֹן יְהוָה וַיַּצִּגוּ אֹתוֹ בִּמְקוֹמוֹ...","translation":"„Au adus Chivotul DOMNULUI și l-au așezat la locul lui...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ φέρουσι τὴν κιβωτὸν τοῦ Κυρίου καὶ ἀνέθησαν αὐτὴν εἰς τὸν τόπον αὐτῆς εἰς μέσον τῆς σκηνῆς, ἧς ἔπηξεν αὐτῇ Δαυίδ· καὶ ἀνήνεγκε Δαυὶδ ὁλοκαυτώματα ἐνώπιον Κυρίου καὶ εἰρηνικάς.","greek":true,"translation":"„Și aduc chivotul Domnului și l-au așezat la locul lui, în mijlocul cortului pe care i-l întinsese David; și a adus David arderi de tot înaintea Domnului, și [jertfe] de pace.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["1 Cronici 16:1","2 Cronici 1:4","Psalmii 132:8","2 Cronici 5:6","Ezra 6:16,17","1 Cronici 15:1"]},{"v":"6:18","t":"Când David a încheiat de adus arderea-de-tot și jertfa de pace, a binecuvântat poporul cu numele DOMNULUI Oștirilor.","tokens":[{"t":"Când David a încheiat de adus arderea-de-tot și jertfa de pace, a "},{"t":"binecuvântat","w":"binecuvântat","heb":"וַיְבָרֶךְ","translit":"vaivareh","strong":"H1288","pos":"verb, piel imperfect consecutiv","def_ro":"și a binecuvântat.","greek":"εὐλογέω (eulogeo)","greek_def_ro":"εὐλογέω (eulogeo) — a binecuvânta.","dict_ro":"Barach — deși binecuvântarea poporului era în mod tradițional prerogativa preoților (Leviticul 9:22-23) sau, ocazional, a figurilor regal-preoțești precum Melhisedec (Geneza 14:19), David, ca rege, binecuvântează poporul „în Numele DOMNULUI Oștirilor” — o formulă care subliniază că binecuvântarea nu vine din autoritatea lui personală, ci e rostită explicit ca reprezentant al lui Dumnezeu, într-un moment de bucurie liturgică excepțională."},{"t":" poporul cu numele DOMNULUI Oștirilor."}],"commentaries":[{"author":"Metzudat David","text":"David, ca rege, binecuvântează poporul în Numele DOMNULUI Oștirilor — la fel cum, mai târziu, la sfințirea Templului, Solomon va binecuvânta întreaga adunare a lui Israel (1 Împărați 8:55)."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיְכַל דָּוִד מֵהַעֲלוֹת הָעוֹלָה...","translation":"„Când David a încheiat de adus arderea-de-tot...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ συνετέλεσε Δαυὶδ συναναφέρων τὰς ὁλοκαυτώσεις καὶ τὰς εἰρηνικὰς καὶ εὐλόγησε τὸν λαὸν ἐν ὀνόματι Κυρίου τῶν δυνάμεων.","greek":true,"translation":"„Și a isprăvit David de adus arderile de tot și [jertfele] de pace, și a binecuvântat poporul în numele Domnului puterilor.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["1 Împărați 8:55","1 Cronici 16:2","2 Cronici 6:3","Geneza 14:19","Levitic 9:22,23","Evrei 7:1-7"]},{"v":"6:19","t":"Și a dat întregului popor, întregii multitudini a lui Israel, bărbaților și femeilor deopotrivă, câte o franzelă de pâine, o bucată de carne și o așișa (n.t. turtă cu stafide sau ulcior de vin); și apoi tot poporul, fiecare om, a mers la casa lui.","tokens":[{"t":"Și a dat întregului popor, întregii multitudini a lui Israel, bărbaților și femeilor deopotrivă, câte o franzelă de pâine, o bucată de carne și o "},{"t":"așișa","w":"așișa","heb":"וַאֲשִׁישָׁה","translit":"vaașișa","strong":"H809","pos":"substantiv, feminin singular","def_ro":"turtă cu stafide sau ulcior de vin.","greek":"λάγανον (laganon)","greek_def_ro":"λάγανον (laganon) — turtă, clătită (coaptă în tigaie).","diff_ro":"Septuaginta descrie acest aliment ca „turtă coaptă în tigaie\" (λάγανον ἀπὸ τηγάνου), o imagine culinară diferită de „turta cu stafide\" tradițională din ebraică.","dict_ro":"Așișa — cuvânt cu sens disputat; Rashi, urmând Talmudul (Pesahim 36b), identifică „eșpar” drept a șasea parte dintr-un taur (o porție de carne standardizată), iar „așișa” drept un urcior/butoiaș de vin — interpretare tradițională păstrată în paralel cu varianta „turtă cu stafide”, mai des întâlnită în traducerile moderne bazate pe context (cf. Osea 3:1, unde termenul apare în context clar culinar)."},{"t":" (n.t. turtă cu stafide sau ulcior de vin); și apoi tot poporul, fiecare om, a mers la casa lui."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „eșpar” — a șasea parte dintr-un taur (Talmud Bavli, Pesahim 36b); „așișa ahat” — un urcior de vin (ibidem)."},{"author":"Metzudat David","text":"„Le-am ish” — vrea să spună: fiecăruia, atât bărbat cât și femeie.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיְחַלֵּק לְכָל־הָעָם...","translation":"„Și a dat întregului popor...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ διεμέρισε παντὶ τῷ λαῷ εἰς πᾶσαν τὴν δύναμιν τοῦ Ἰσραὴλ ἀπὸ Δὰν ἕως Βηρσαβεὲ καὶ ἀπό ἀνδρὸς ἕως γυναικός, ἑκάστῳ κολλυρίδα ἄρτου καὶ ἐσχαρίτην καὶ λάγανον ἀπὸ τηγάνου· καὶ ἀπῆλθε πᾶς ὁ λαὸς ἕκαστος εἰς τὸν οἶκον αὐτοῦ.","greek":true,"translation":"„Și a împărțit întregului popor, întregii puteri a lui Israel, de la Dan până la Beer-Șeba, și de la bărbat până la femeie, fiecăruia o turtă de pâine, și o prăjitură de pe grătar, și o clătită din tigaie; și a plecat tot poporul, fiecare la casa lui.”","note":"Divergență lexicală reală: Septuaginta adaugă precizarea geografică „de la Dan până la Beer-Șeba” (absentă din Textul Masoretic la acest verset) și traduce cele trei daruri prin termeni culinari concreți diferiți — „turtă de pâine”, „prăjitură de pe grătar” și „clătită din tigaie” — variind sensibil de la lectura tradițională a lui „eșpar” și „așișa” ca porție de carne și, respectiv, vin sau turtă cu stafide."}],"refs":["1 Cronici 16:3","Neemia 8:10","1 Împărați 8:66","2 Cronici 30:24"]}]},{"num":4,"title":"Șemini (așkenaz) - A opta","ref":"2 Samuel 6:1-7:17","intro":"Haftarat Șemini, în tradiția așkenază, continuă dincolo de urcarea Chivotului (comună tuturor tradițiilor) până la promisiunea DOMNULUI către David, prin profetul Natan: nu David, ci fiul lui, va zidi Casa DOMNULUI — în schimb, DOMNUL Însuși îi va zidi lui David o casă, o dinastie a cărei domnie va fi statornicită pe vecie. Episodul disprețului Mihalei față de dansul lui David (6:16, 20-23) se leagă astfel direct de capitolul următor: cea care i-a reproșat lui David lipsa de demnitate regală rămâne fără urmași, în timp ce promisiunea unei case veșnice îi este făcută tocmai lui David, cel disprețuit pentru smerenia lui înaintea Chivotului.","verses":[{"v":"6:1","t":"David i-a adunat din nou pe toți aleșii din Israel, treizeci de mii [la număr].","tokens":[{"t":"David i-a adunat "},{"t":"din nou","w":"din nou","heb":"וַיֹּסֶף","translit":"vaiosef","strong":"H3254","pos":"verb, qal imperfect consecutiv","def_ro":"și a adăugat din nou, a continuat să adune.","greek":"ἔτι (eti)","greek_def_ro":"ἔτι (eti) — din nou, încă.","diff_ro":"Septuaginta are aici o cifră diferită de cea ebraică pentru numărul bărbaților aleși: „ἑβδομήκοντα χιλιάδας\" („șaptezeci de mii\"), nu „treizeci de mii\" — o divergență numerică reală.","dict_ro":"Iasaf od — Rashi explică precis „din nou”: poporul se strânsese deja o dată în jurul lui David când l-au uns rege la Hebron; aceasta este a doua adunare, distinctă de cea dintâi, de aceea textul marchează explicit repetiția cu „din nou”, nu doar „a adunat”."},{"t":" pe toți aleșii din Israel, treizeci de mii [la număr]."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „i-a adunat din nou” — pentru că se adunaseră deja la el când l-au făcut rege la Hebron, iar aceasta a fost o a doua adunare; de aceea se spune „din nou”."},{"author":"Metzudat David","text":"„Fiindcă mulți se adunau la el încă din vremea când a devenit rege, de aceea a spus că a mai adunat din nou la el pe aleșii din Israel, ca să ridice Chivotul.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיֹּסֶף עוֹד דָּוִד אֶת־כָּל־בָּחוּר בְּיִשְׂרָאֵל שְׁלֹשִׁים אָלֶף׃","translation":"„David i-a adunat din nou pe toți aleșii din Israel, treizeci de mii...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ΚΑΙ συνήγαγεν ἔτι Δαυὶδ πάντα νεανίαν ἐξ Ἰσραήλ, ὡς ἑβδομήκοντα χιλιάδας.","greek":true,"translation":"„Și David a adunat din nou pe toți tinerii din Israel, ca la șaptezeci de mii.”","note":"Divergență numerică reală și semnificativă: Textul Masoretic are 30.000 (șeloșim alef), pe când Septuaginta are 70.000 (ἑβδομήκοντα χιλιάδας) — o discrepanță substanțială, necorespunzătoare unei simple confuzii grafice de literă-cifră, documentată ca atare în critica textuală a cărților Samuel."}],"refs":["2 Samuel 5:1","1 Împărați 8:1","1 Cronici 13:1-4","Psalmii 132:1-6"]},{"v":"6:2","t":"Apoi David s-a ridicat și a mers, împreună cu tot poporul care era cu el, de la Baalei-Iuda, ca să ridice de acolo Chivotul lui Dumnezeu asupra căruia este invocat numele – numele DOMNULUI, Stăpânul Oștirilor, întronat pe heruvimi, este asupra lui.","tokens":[{"t":"Apoi David s-a ridicat și a mers, împreună cu tot poporul care era cu el, de la "},{"t":"Baalei-Iuda","w":"Baalei-Iuda","heb":"מִבַּעֲלֵי יְהוּדָה","translit":"mibaalē iehuda","strong":"H1184","pos":"nume propriu + nume propriu","def_ro":"Baale-Iuda, alt nume pentru Chiriat-Iearim.","diff_ro":"Septuaginta nu tratează acest nume ca toponim, ci îl traduce „ἀπὸ τῶν ἀρχόντων Ἰούδα\" („de la conducătorii lui Iuda\") — citind „Baalei\" ca termen generic („stăpâni/conducători\"), nu ca parte dintr-un nume de loc.","dict_ro":"Baale Yehuda — Rashi identifică locul, citând Iosua 15:9 și 1 Cronici 13:6, drept un alt nume pentru Chiriat-Iearim, unde Chivotul fusese adus și păstrat de la înfrângerea filistenilor (1 Samuel 7:1); cuvântul „baal” aici are, după Rashi, sensul de „câmpie/loc neted”, nu de zeitate."},{"t":", ca să ridice de acolo Chivotul lui Dumnezeu asupra căruia este invocat numele – numele DOMNULUI, Stăpânul Oștirilor, întronat pe heruvimi, este asupra lui."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „miBaalei Yehuda” — aceasta este Chiriat-Iearim, după cum se spune la Iosua: „și hotarul se întorcea și urca la Baala, aceasta e Chiriat-Iearim” (Iosua 15:9), și tot așa la Cronici: „și David și tot Israelul s-au suit la Baalata, aceasta e Chiriat-Iearim” (1 Cronici 13:6); „baal” e un termen de câmpie/loc neted."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיָּקָם וַיֵּלֶךְ דָּוִד...","translation":"„Apoi David s-a ridicat și a mers...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἀνέστη καὶ ἐπορεύθη Δαυὶδ καὶ πᾶς ὁ λαὸς ὁ μετ' αὐτοῦ καὶ ἀπὸ τῶν ἀρχόντων Ἰούδα ἐν ἀναβάσει τοῦ ἀναγαγεῖν ἐκεῖθεν τὴν κιβωτὸν τοῦ Θεοῦ, ἐφ' ἣν ἐπεκλήθη τὸ ὄνομα τοῦ Κυρίου τῶν δυνάμεων καθημένου ἐπὶ τῶν Χερουβὶν ἐπ' αὐτῆς.","greek":true,"translation":"„Și s-a ridicat și a mers David și tot poporul care era cu el, și dintre căpeteniile lui Iuda, în suire, ca să aducă de acolo chivotul lui Dumnezeu, peste care s-a chemat numele Domnului puterilor, care șade pe heruvimi, peste el.”","note":"Divergență de nume propriu: acolo unde Textul Masoretic are toponimul „Baale-Iuda”, Septuaginta traduce generic prin „căpeteniile lui Iuda” (τῶν ἀρχόντων Ἰούδα) — o citire diferită a consoanelor ebraice, tratând „baalei” ca „stăpânii/căpeteniile” lui Iuda, nu ca parte a unui nume de loc."}],"refs":["1 Cronici 13:5,6","1 Samuel 7:1","Exod 25:18-22","1 Samuel 4:4","Psalmii 80:1","1 Împărați 8:6,7"]},{"v":"6:3","t":"Și au pus Chivotul lui Dumnezeu într-un car nou și l-au purtat din casa lui Avinadav care era pe deal, iar Uza și Ahio, fiii lui Avinadav, conduceau carul cel nou.","tokens":[{"t":"Și au pus Chivotul lui Dumnezeu într-un "},{"t":"car nou","w":"car nou","heb":"עֲגָלָה","translit":"agala","strong":"H5699","pos":"substantiv, feminin singular","def_ro":"car nou, căruță nouă.","greek":"ἅμαξα καινή (hamaxa kaine)","greek_def_ro":"ἅμαξα καινή (hamaxa kaine) — car nou.","dict_ro":"Agala — greșeala fatală a lui David, spune Rashi, e una pe care „chiar copiii de școală o cunosc”: legea spune explicit că lucrurile sfinte trebuie purtate pe umeri (Numeri 7:9), nu transportate cu carul, oricât de nou. Metoda carului fusese folosită anterior doar de filisteni (1 Samuel 6:7), care nu erau ținuți de Lege — copierea metodei lor păgâne, nu a poruncii mozaice, e sursa reală a tragediei care urmează."},{"t":" și l-au purtat din casa lui Avinadav care era pe deal, iar Uza și Ahio, fiii lui Avinadav, conduceau carul cel nou."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: a greșit într-un lucru pe care chiar copiii de la școală îl cunosc — „căci slujba sfântă e a lor, pe umeri o vor purta” (Numeri 7:9); și fiindcă spusese [David]: „cântări au fost pentru mine hotărârile Tale, în casa pribegiei mele” (Psalmii 119:54), a fost pedepsit să ajungă la aceasta, și Uza a murit prin mâna lui — de aceea, când au adus-o din casa lui Oved, au adus-o pe umeri, precum se spune: „le-a zis: voi sunteți căpeteniile părinților leviților, sfințiți-vă voi și frații voștri și suiți Chivotul... căci întâia dată n-ați fost voi, de aceea DOMNUL Dumnezeul nostru a făcut spărtură în noi, căci nu L-am căutat după rânduială” (1 Cronici 15:12-13)."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיַּרְכִּבוּ אֶת־אֲרוֹן הָאֱלֹהִים...","translation":"„Și au pus Chivotul lui Dumnezeu într-un car nou...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐπεβίβασαν τὴν κιβωτὸν Κυρίου ἐφ' ἅμαξαν καινὴν καὶ ᾖραν αὐτὴν ἐξ οἴκου Ἀμιναδὰβ τοῦ ἐν τῷ βουνῷ· καὶ Ὀζὰ καὶ οἱ ἀδελφοὶ αὐτοῦ υἱοὶ Ἀμιναδὰβ ἦγον τὴν ἅμαξαν σὺν τῇ κιβωτῷ.","greek":true,"translation":"„Și au suit chivotul Domnului pe un car nou și l-au ridicat din casa lui Aminadab cea de pe deal; și Oza și frații lui, fiii lui Aminadab, mânau carul împreună cu chivotul.”","note":"Divergență reală de rudenie: Textul Masoretic numește explicit „Uza și Ahio” (nume propriu), pe când Septuaginta redă „Οζὰ καὶ οἱ ἀδελφοὶ αὐτοῦ” („Oza și frații lui”) — citind „Ahio” nu ca nume propriu, ci ca substantiv comun „ahav” (fratele lui) la plural, o interpretare gramaticală diferită a consoanelor ebraice."}],"refs":["Numeri 4:5-12","Numeri 7:9","1 Samuel 6:7"]},{"v":"6:4","t":"Și l-au purtat din casa lui Avinadav, care era pe deal, împreună cu Chivotul lui Dumnezeu, iar Ahio mergea înaintea carului.","tokens":[{"t":"Și l-au purtat din casa lui Avinadav, care era pe deal, împreună cu Chivotul lui Dumnezeu, iar Ahio mergea "},{"t":"înaintea","w":"înaintea","heb":"לִפְנֵי","translit":"lifnē","strong":"H6440","pos":"substantiv, masculin și feminin plural construct","def_ro":"înaintea, în fața.","greek":"ἔμπροσθεν (emprosthen)","greek_def_ro":"ἔμπροσθεν (emprosthen) — înainte, în fața.","dict_ro":"Lifnei — Metzudat David explică de ce Ahio, nu Uza, e menționat mergând „înaintea Chivotului”: Ahio conducea boii din față, în timp ce Uza mergea alături de Chivot, pe lateral — poziție care explică de ce doar Uza a simțit boii clătinând Chivotul și a întins mâna, în timp ce Ahio, aflat înainte, nu a observat nimic."},{"t":" carului."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"„Cu Chivotul lui Dumnezeu” — acesta e un verset scurtat; [înseamnă:] și ei veneau cu chivotul lui Dumnezeu."},{"author":"Metzudat David","text":"„Ahio mergea înaintea Chivotului” pentru a conduce boii din față, spre deosebire de Uza, care mergea alături de Chivot — de aceea doar el a simțit clătinarea boilor, iar Ahio, fiind în față, nu și-a dat seama.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיִּשָּׂאֻהוּ מִבֵּית אֲבִינָדָב...","translation":"„Și l-au purtat din casa lui Avinadav...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ οἱ ἀδελφοὶ αὐτοῦ ἐπορεύοντο ἔμπροσθεν τῆς κιβωτοῦ.","greek":true,"translation":"„Și frații lui mergeau înaintea chivotului.”","note":"Septuaginta e mult mai scurtă la acest verset, omițând repetarea „l-au purtat din casa lui Avinadav, care era pe deal” (deja spusă la v.3) și păstrând doar partea finală despre mersul înaintea Chivotului — coerent cu redarea de la v.3, unde „Ahio” fusese deja tradus la plural, „frații lui”."}],"refs":["1 Samuel 7:1,2","1 Cronici 13:7"]},{"v":"6:5","t":"Și David și toată casa lui Israel jucau înaintea DOMNULUI cu tot [soiul de] instrumente din lemn de chiparos, și cu harpe, și cu lire, și cu tobe, și cu tamburine, și cu talgere.","tokens":[{"t":"Și David și toată casa lui Israel jucau înaintea DOMNULUI cu tot [soiul de] instrumente din "},{"t":"lemn de chiparos","w":"lemn de chiparos","heb":"בְרוֹשִׁים","translit":"veroșim","strong":"H1265","pos":"substantiv, masculin plural","def_ro":"lemne de chiparos/brad.","diff_ro":"Septuaginta are aici „ἐν ὀργάνοις ἡρμοσμένοις ἐν ἰσχύϊ\" („cu instrumente bine acordate, cu putere\"), fără mențiunea specifică a lemnului de chiparos — o descriere generică a instrumentelor, nu un detaliu despre materialul lor.","dict_ro":"Beroș — Rashi precizează că expresia nu descrie pădurea prin care treceau, ci materialul din care erau confecționate instrumentele muzicale înșirate imediat după — harpe, lire, tobe, tamburine, talgere — toate lucrate din lemn de chiparos, cunoscut pentru rezonanța lui bună."},{"t":", și cu harpe, și cu lire, și cu tobe, și cu tamburine, și cu talgere."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „becol atzei veroșim” — cu instrumente muzicale lucrate din lemn de chiparos."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְדָוִד וְכָל־בֵּית יִשְׂרָאֵל מְשַׂחֲקִים...","translation":"„Și David și toată casa lui Israel jucau înaintea DOMNULUI...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ Δαυὶδ καὶ υἱοὶ Ἰσραὴλ παίζοντες ἐνώπιον Κυρίου ἐν ὀργάνοις ἡρμοσμένοις ἐν ἰσχύϊ, καὶ ἐν ᾠδαῖς καὶ ἐν κινύραις καὶ ἐν νάβλαις καὶ ἐν τυμπάνοις καὶ ἐν κυμβάλοις καὶ ἐν αὐλοῖς.","greek":true,"translation":"„Și David și fiii lui Israel jucau înaintea Domnului cu instrumente acordate cu putere, și cu cântări, și cu lire, și cu harpe, și cu tobe, și cu chimvale, și cu fluiere.”","note":"Divergență reală: acolo unde Textul Masoretic specifică „lemn de chiparos” ca material al instrumentelor, Septuaginta traduce generic „instrumente acordate cu putere” (ὀργάνοις ἡρμοσμένοις ἐν ἰσχύϊ) — pierzând referința la materialul lemnos — și adaugă „fluiere” (αὐλοῖς), instrument absent din lista ebraică."}],"refs":["1 Cronici 13:8","Psalmii 150:3-5","Amos 6:5","1 Samuel 16:16","1 Samuel 10:5","2 Împărați 3:15"]},{"v":"6:6","t":"Au ajuns la aria lui Nahon, și Uza s-a întins către Chivotul lui Dumnezeu și l-a apucat, căci boii îl mișcaseră.","tokens":[{"t":"Au ajuns la aria lui Nahon, și Uza s-a întins către Chivotul lui Dumnezeu și l-a "},{"t":"apucat","w":"apucat","heb":"וַיֹּאחֶז","translit":"vaiohez","strong":"H270","pos":"verb, qal imperfect consecutiv","def_ro":"și l-a prins, l-a apucat.","greek":"κρατέω (krateo)","greek_def_ro":"κρατέω (krateo) — a apuca, a ține strâns.","dict_ro":"Ahaz — Metzudat David explică motivul gestului: Uza a crezut că Chivotul e pe cale să cadă din car, din pricina zdruncinării provocate de boi, și a întins mâna instinctiv ca să-l țină — un gest omenește explicabil, dar care presupunea o neîncredere implicită în capacitatea Chivotului de a se apăra singur, sfințenia lui fiind mai presus de nevoia de sprijin fizic omenesc."},{"t":", căci boii îl mișcaseră."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „ki șametu habakar” — căci boii l-au clătinat și l-au mișcat, așa cum traduce Targum Ionatan „ari meragohi toraia”."},{"author":"Metzudat David","text":"„Uza și-a întins mâna” — a crezut că, dacă boii îl clatină, va cădea de pe car.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיָּבֹאוּ עַד־גֹּרֶן נָכוֹן...","translation":"„Au ajuns la aria lui Nahon...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ παραγίνονται ἕως ἅλω Ναχώρ, καὶ ἐξέτεινεν Ὀζὰ τὴν χεῖρα αὐτοῦ ἐπὶ τὴν κιβωτὸν τοῦ Θεοῦ κατασχεῖν αὐτὴν καὶ ἐκράτησεν αὐτήν, ὅτι περιέσπασεν αὐτὴν ὁ μόσχος.","greek":true,"translation":"„Și au ajuns până la aria lui Nahor, și Oza și-a întins mâna spre chivotul lui Dumnezeu ca să-l țină, și l-a apucat, căci vițelul l-a răsucit.”","note":"Divergență de nume propriu reală: Textul Masoretic are „Nahon” (נָכוֹן), Septuaginta are „Nahor” (Ναχώρ) — o citire diferită a numelui locului; și „boii” (habakar, plural generic) devin în greacă „vițelul” (ὁ μόσχος, singular) — o schimbare de număr."}],"refs":["1 Cronici 13:9","Numeri 4:15,19,20"]},{"v":"6:7","t":"Mânia DOMNULUI s-a aprins împotriva lui Uza și Dumnezeu l-a lovit acolo pentru greșeală, și Uza a murit acolo, alături de Chivotul lui Dumnezeu.","tokens":[{"t":"Mânia DOMNULUI s-a aprins împotriva lui Uza și Dumnezeu l-a lovit acolo pentru "},{"t":"greșeală","w":"greșeală","heb":"הַשַּׁל","translit":"hașal","strong":"H7944","pos":"substantiv, masculin singular","def_ro":"greșeala, eroarea neintenționată.","diff_ro":"Septuaginta nu menționează motivul exact („greșeala\") — spune simplu „Dumnezeu l-a lovit acolo\", fără termenul specific pentru vina/greșeala lui Uza.","dict_ro":"Șal — cuvânt extrem de rar (hapax legomenon în această formă), pe care Rashi îl citește ca „șgaga” (greșeală neintenționată, din neștiință) — Uza n-a acționat din răutate, ci dintr-o judecată greșită pe care ar fi trebuit s-o evite printr-un raționament simplu, a fortiori (kal vahomer): dacă cei ce purtau Chivotul pe umeri l-au trecut cu bine prin Iordan fără să-l atingă, cu atât mai puțin era nevoie ca el să-l atingă acum, pe uscat."},{"t":", și Uza a murit acolo, alături de Chivotul lui Dumnezeu."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „al hașal” — pentru greșeala [neintenționată], căci ar fi trebuit să raționeze a fortiori: dacă cei ce l-au purtat [pe Chivot] l-au purtat prin Iordan [fără să-l atingă cu mâna], cu atât mai mult el însuși [n-ar fi trebuit să-l atingă]."},{"author":"Metzudat David","text":"„S-a mâniat DOMNUL” — pentru puțina lui încredere în DOMNUL, gândind că Chivotul ar putea cădea la pământ; „pentru greșeală” — pentru fapta pe care a făcut-o din neștiință, ca și cum ar fi uitat că e Chivotul DOMNULUI.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיִּחַר־אַף יְהוָה בְּעֻזָּה...","translation":"„Mânia DOMNULUI s-a aprins împotriva lui Uza...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐθυμώθη ὀργῇ Κύριος τῷ Ὀζά, καὶ ἔπαισεν αὐτὸν ἐκεῖ ὁ Θεός, καὶ ἀπέθανεν ἐκεῖ παρὰ τὴν κιβωτὸν τοῦ Κυρίου ἐνώπιον τοῦ Θεοῦ.","greek":true,"translation":"„Și s-a mâniat cu mânie Domnul pe Oza, și l-a lovit acolo Dumnezeu, și a murit acolo lângă chivotul Domnului, înaintea lui Dumnezeu.”","note":"Divergență reală: cuvântul rar „al-hașal” (pentru greșeală/eroare) din Textul Masoretic nu are un echivalent distinct în Septuaginta, care redă doar structura generală a pedepsei, fără a preciza motivul printr-un termen separat — probabil pentru că traducătorii alexandrini n-au recunoscut sau n-au putut echivala acest cuvânt rar."}],"refs":["Levitic 10:1-3","1 Samuel 6:19","1 Cronici 13:10","1 Cronici 15:2,13"]},{"v":"6:8","t":"David s-a mâniat de răbufnirea cu care DOMNUL răbufnise împotriva lui Uza și a numit locul acela Pereț-Uza (n.t. Răbufnirea [contra] lui Uza), până în ziua de astăzi.","tokens":[{"t":"David s-a mâniat de "},{"t":"răbufnirea","w":"răbufnirea","heb":"פֶּרֶץ","translit":"pereț","strong":"H6556","pos":"substantiv, masculin singular","def_ro":"spărtura, izbucnirea bruscă.","greek":"διακοπή (diakope)","greek_def_ro":"διακοπή (diakope) — spărtură, izbucnire.","dict_ro":"Peretz — literal „spărtură”, imaginea unei bariere care cedează brusc sub presiune; Metzudat David citește „vayihar leDavid” nu ca mânie a lui David împotriva lui Dumnezeu, ci ca o tulburare interioară îndreptată spre sine însuși, în felul în care „vayihar leȘmuel” (1 Samuel 15:11) descrie neliniștea lui Samuel, nu furia lui — David e zguduit și îngrozit, nu supărat pe DOMNUL."},{"t":" cu care DOMNUL răbufnise împotriva lui Uza și a numit locul acela Pereț-Uza (n.t. Răbufnirea [contra] lui Uza), până în ziua de astăzi."}],"commentaries":[{"author":"Metzudat David","text":"„Vayihar leDavid” — s-a mâhnit și s-a tulburat pentru sine, în felul celui strâmtorat și înspăimântat, la fel cum se spune «și s-a mâhnit Samuel» (1 Samuel 15:11); „pentru spărtura” — din pricina neliniștii pe care i-a provocat-o acea spărtură.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיִּחַר לְדָוִד עַל אֲשֶׁר פָּרַץ יְהוָה פֶּרֶץ בְּעֻזָּה...","translation":"„David s-a mâniat de răbufnirea cu care DOMNUL răbufnise împotriva lui Uza...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἠθύμησε Δαυὶδ ὑπὲρ οὗ διέκοψε Κύριος διακοπὴν ἐν τῷ Ὀζά· καὶ ἐκλήθη ὁ τόπος ἐκεῖνος Διακοπὴ Ὀζὰ ἕως τῆς ἡμέρας ταύτης.","greek":true,"translation":"„Și s-a mâhnit David pentru că Domnul a făcut spărtură asupra lui Oza; și s-a numit locul acela Spărtura lui Oza până în ziua aceasta.”","note":"Divergență reală de nuanță emoțională: Textul Masoretic folosește „vayihar” (verbul „a se mânia/a se aprinde”, aceeași rădăcină ca la v.7 pentru mânia DOMNULUI), pe când Septuaginta alege „ἠθύμησε” („s-a mâhnit/descurajat”) — o redare mai blândă, care mută tonul de la o posibilă tulburare/mânie a lui David spre simplă tristețe."}],"refs":["1 Cronici 13:11,12","Iona 4:1,9"]},{"v":"6:9","t":"Și David s-a temut de DOMNUL în ziua aceea și a spus: „Cum să vină Chivotul DOMNULUI la mine?”","tokens":[{"t":"Și David s-a temut de DOMNUL în ziua aceea și a spus: „Cum să "},{"t":"vină","w":"vină","heb":"יָבוֹא","translit":"iavo","strong":"H935","pos":"verb, qal imperfect","def_ro":"să vină, să intre.","greek":"εἰσέρχομαι (eiserchomai)","greek_def_ro":"εἰσέρχομαι (eiserchomai) — a veni, a intra.","dict_ro":"Bo — Metzudat David explică teama lui David nu ca o îndoială privind valoarea Chivotului, ci ca o conștientizare bruscă a riscului practic al sfințeniei sale: dacă un act aparent minor precum atingerea Chivotului a adus moarte instantanee, David se întreabă legitim cum ar putea asigura o găzduire corespunzătoare, fără riscul unei noi greșeli fatale — aceeași teamă structurală ce apare la filisteni în 1 Samuel 6:20."},{"t":" Chivotul DOMNULUI la mine?”"}],"commentaries":[{"author":"Metzudat David","text":"„Et ADONAI” — Chivotul DOMNULUI, căci a gândit că nu se poate păzi cu adevărat sfințenia lui.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיִּרָא דָוִד אֶת־יְהוָה בַּיּוֹם הַהוּא...","translation":"„Și David s-a temut de DOMNUL în ziua aceea...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐφοβήθη Δαυὶδ τὸν Κύριον ἐν τῇ ἡμέρᾳ ἐκείνῃ λέγων· πῶς εἰσελεύσεται πρός με ἡ κιβωτὸς Κυρίου;","greek":true,"translation":"„Și s-a temut David de Domnul în ziua aceea, zicând: cum va intra la mine chivotul Domnului?”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Numeri 17:12,13","1 Samuel 6:20","1 Samuel 5:10,11"]},{"v":"6:10","t":"Și David n-a mai vrut să aducă Chivotul DOMNULUI la el, în Orașul lui David, ci David l-a deturnat către casa lui Oved-Edom, ghititul.","tokens":[{"t":"Și David n-a mai vrut să aducă Chivotul DOMNULUI la el, în Orașul lui David, ci David l-a deturnat către casa lui "},{"t":"Oved-Edom, ghititul","w":"Oved-Edom, ghititul","heb":"עֹבֵד אֱדוֹם","translit":"ovēd edom","strong":"H5654","pos":"nume propriu + nume propriu","def_ro":"Oved-Edom din Gat.","diff_ro":"Septuaginta transliterează acest nume „Ἀβεδδαρά\" („Abeddara\"), o formă destul de diferită de „Oved-Edom\" din ebraică — posibil o variantă textuală veche a numelui.","dict_ro":"Ha-Ghiti — epitetul „ghititul” (din Gat) ar sugera o origine filisteană, dar Rashi, citând 1 Cronici 15:18, îl identifică drept levit, unul dintre portarii sanctuarului — probabil numit „ghitit” după un oraș levitic cu acest nume sau după o perioadă petrecută acolo, nu după etnie. Alegerea unei case levite, nu oricare, pentru a găzdui Chivotul, sugerează că David, chiar înspăimântat, a rămas atent la rânduiala corectă."},{"t":"."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Oved-Edom” era levit, după cum stă scris la Cronici, „și dintre portari era” (1 Cronici 15:18)."},{"author":"Metzudat David","text":"„L-a deturnat” — l-a abătut de la drumul spre Cetatea lui David, spre casa lui Oved-Edom.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְלֹא־אָבָה דָוִד לְהָסִיר אֵלָיו...","translation":"„Și David n-a mai vrut să aducă Chivotul DOMNULUI la el...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ οὐκ ἐβούλετο Δαυὶδ τοῦ ἐκκλῖναι πρὸς αὐτὸν τὴν κιβωτὸν διαθήκης Κυρίου εἰς τὴν πόλιν Δαυίδ, καὶ ἀπέκλινεν αὐτὴν Δαυὶδ εἰς οἶκον Ἀβεδδαρὰ τοῦ Γεθαίου.","greek":true,"translation":"„Și n-a voit David să abată la el chivotul legământului Domnului, în cetatea lui David, și l-a abătut David spre casa lui Abeddara Gheteul.”","note":"Divergență reală de titulatură: Septuaginta adaugă „legământului” (διαθήκης) la „chivotul Domnului”, formulă absentă la acest verset în Textul Masoretic — o completare teologică explicativă."}],"refs":["1 Cronici 15:18","1 Cronici 16:5","1 Cronici 26:4-8","2 Samuel 15:19","2 Samuel 18:2","1 Cronici 13:13,14"]},{"v":"6:11","t":"Și Chivotul DOMNULUI a rămas în casa lui Oved-Edom, ghititul, timp de trei luni, iar DOMNUL l-a binecuvântat pe Oved-Edom împreună cu toată casa lui.","tokens":[{"t":"Și Chivotul DOMNULUI a rămas în casa lui Oved-Edom, ghititul, timp de trei luni, iar DOMNUL l-a "},{"t":"binecuvântat","w":"binecuvântat","heb":"וַיְבָרֶךְ","translit":"vaivareh","strong":"H1288","pos":"verb, piel imperfect consecutiv","def_ro":"și a binecuvântat.","greek":"εὐλογέω (eulogeo)","greek_def_ro":"εὐλογέω (eulogeo) — a binecuvânta.","dict_ro":"Barach — Rashi citează o tradiție (bazată pe 1 Cronici 26:5, unde Oved-Edom e numit „al optulea” între cei binecuvântați cu mulți fii) potrivit căreia soția lui Oved-Edom și cele opt nurori ale sale au născut fiecare câte șase fii dintr-o singură sarcină, în cele trei luni — o binecuvântare literalizată, fizică, ca răspuns direct la primirea cu credință a aceluiași Chivot care adusese moarte în casa lui Uza."},{"t":" pe Oved-Edom împreună cu toată casa lui."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: soția lui și cele opt nurori ale sale au născut șase fii fiecare, dintr-o singură sarcină, precum se spune: „lucrarea lui, al optulea” (1 Cronici 26:5) — șaizeci și doi [de fii] lui Oved-Edom."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיֵּשֶׁב אֲרוֹן יְהוָה בֵּית עֹבֵד אֱדוֹם...","translation":"„Și Chivotul DOMNULUI a rămas în casa lui Oved-Edom...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐκάθισεν ἡ κιβωτὸς τοῦ Κυρίου εἰς οἶκον Ἀβεδδαρὰ τοῦ Γεθαίου μῆνας τρεῖς· καὶ εὐλόγησε Κύριος ὅλον τὸν οἶκον Ἀβεδδαρὰ καὶ πάντα τὰ αὐτοῦ.","greek":true,"translation":"„Și a șezut chivotul Domnului în casa lui Abeddara Gheteul trei luni; și a binecuvântat Domnul toată casa lui Abeddara și toate ale lui.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Geneza 30:27","Geneza 39:5,23","Proverbe 3:9,10","Maleahi 3:10"]},{"v":"6:12","t":"Și i s-a vestit lui David că DOMNUL îl binecuvântase pe Oved-Edom și toată casa lui din pricina Chivotului DOMNULUI, și David a mers și a ridicat Chivotul lui Dumnezeu din casa lui Oved-Edom, către Orașul lui David, cu bucurie.","tokens":[{"t":"Și i s-a vestit lui David că DOMNUL îl binecuvântase pe Oved-Edom și toată casa lui din pricina Chivotului DOMNULUI, și David a mers și a ridicat Chivotul lui Dumnezeu din casa lui Oved-Edom, către Orașul lui David, cu "},{"t":"bucurie","w":"bucurie","heb":"בְּשִׂמְחָה","translit":"besimha","strong":"H8057","pos":"substantiv, feminin singular","def_ro":"cu bucurie, cu veselie.","greek":"εὐφροσύνη (euphrosyne)","greek_def_ro":"εὐφροσύνη (euphrosyne) — bucurie, veselie.","dict_ro":"Simha — Metzudat David identifică sursa concretă a bucuriei lui David: vestea binecuvântării revărsate asupra casei lui Oved-Edom l-a asigurat pe David că, de această dată, Chivotul poate fi mutat fără primejdie — bucuria nu e doar emoție religioasă generică, ci ușurarea practică a unui om care abia acum se simte liber să corecteze greșeala din urmă cu trei luni."},{"t":"."}],"commentaries":[{"author":"Metzudat David","text":"„Din pricina Chivotului” — care șade în casa lui, căci înainte de aceasta n-a ajuns la o asemenea binecuvântare; „Orașul lui David” — către cetatea lui David, adică Țion.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיֻּגַּד לַמֶּלֶךְ דָּוִד...","translation":"„Și i s-a vestit lui David...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἀπηγγέλη τῷ βασιλεῖ Δαυὶδ λέγοντες· εὐλόγησε Κύριος τὸν οἶκον Ἀβεδδαρὰ καὶ πάντα τὰ αὐτοῦ ἕνεκα τῆς κιβωτοῦ τοῦ Θεοῦ, καὶ ἐπορεύθη Δαυὶδ καὶ ἀνήγαγε τὴν κιβωτὸν τοῦ Κυρίου ἐκ τοῦ οἴκου Ἀβεδδαρὰ εἰς τὴν πόλιν Δαυὶδ ἐν εὐφροσύνῃ.","greek":true,"translation":"„Și s-a vestit regelui David, zicându-i: a binecuvântat Domnul casa lui Abeddara și toate ale lui, din pricina chivotului lui Dumnezeu; și a mers David și a suit chivotul Domnului din casa lui Abeddara în cetatea lui David, cu veselie.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["1 Cronici 15:1-3,25","Psalmii 24:7-10","Psalmii 68:24-27","Psalmii 132:6-8"]},{"v":"6:13","t":"La fiecare șase pași pe care îi făceau purtătorii Chivotului DOMNULUI, el jertfea un taur și un taur îngrășat.","tokens":[{"t":"La fiecare "},{"t":"șase pași","w":"șase pași","heb":"שִׁשָּׁה צְעָדִים","translit":"șișa țeadim","strong":"H6806","pos":"numeral + substantiv, masculin plural","def_ro":"șase pași.","dict_ro":"Una dintre cele mai mari divergențe din acest capitol: Septuaginta nu are deloc imaginea „la fiecare șase pași\" — în loc de asta, spune că „erau cu el, ducând Chivotul, șapte cete/coruri\" (ἑπτὰ χοροὶ), o imagine complet diferită, legată probabil de o lectură alternativă a termenului ebraic pentru „pași\". Și jertfele diferă: „un vițel și miei\" (plural), nu „un taur și un taur îngrășat\" ca în ebraică."},{"t":" pe care îi făceau purtătorii Chivotului DOMNULUI, el jertfea un taur și un taur îngrășat."}],"commentaries":[{"author":"Metzudat David","text":"„După fiecare șase pași” — de fiecare dată când purtătorii Chivotului făceau șase pași, David jertfea din nou, iar aceasta s-a repetat de-a lungul întregului drum.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיְהִי כִּי צָעֲדוּ נֹשְׂאֵי אֲרוֹן־יְהוָה...","translation":"„La fiecare șase pași pe care îi făceau purtătorii Chivotului DOMNULUI...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἦσαν μετ' αὐτοῦ αἴροντες τὴν κιβωτὸν ἑπτὰ χοροὶ καὶ θῦμα μόσχος καὶ ἄρνες.","greek":true,"translation":"„Și erau cu el, purtând chivotul, șapte coruri, și ca jertfă, un vițel și miei.”","note":"Divergență reală și substanțială: Textul Masoretic descrie jertfe repetate „la fiecare șase pași”, cu „un taur și un taur îngrășat”; Septuaginta redă cu totul altfel — „șapte coruri” de purtători/cântăreți și o singură jertfă, „un vițel și miei” — o versiune notabil diferită atât în structura procesiunii, cât și în natura jertfelor aduse."}],"refs":["Numeri 4:15","Numeri 7:9","Iosua 3:3","1 Împărați 8:5","2 Cronici 5:6","1 Cronici 15:2,15,25,26"]},{"v":"6:14","t":"Și David dansa cu toată puterea [lui] înaintea DOMNULUI, încins cu o tunică de in.","tokens":[{"t":"Și David dansa cu toată puterea [lui] înaintea DOMNULUI, încins cu o "},{"t":"tunică de in","w":"tunică de in","heb":"אֵפוֹד","translit":"ēfod","strong":"H646","pos":"substantiv, masculin singular construct","def_ro":"efod de in, veșmânt simplu de in.","diff_ro":"Septuaginta are aici „στολὴν ἔξαλλον\" („o robă neobișnuită/stranie\"), nu termenul tehnic „efod de in\" ca în ebraică — o descriere vagă, fără detaliul despre material sau despre tipul specific de veșmânt preoțesc.","dict_ro":"Efod bad — nu efodul bogat, împodobit cu pietre prețioase, al marelui preot, ci un veșmânt simplu de in, purtat de cei consacrați slujirii DOMNULUI într-un mod smerit — aceeași expresie exactă descrie veșmântul tânărului Samuel (1 Samuel 2:18). Metzudat David notează că David, deși rege, s-a îmbrăcat pentru acest moment nu în straie regale, ci în haina simplă a unui slujitor devotat."},{"t":"."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „mecharker” — dansa; „efod bad” — o mantie de in, tradusă de Targum Ionatan „kardut”, aceeași folosită și pentru mantiile Tamarei, sora lui Abșalom (2 Samuel 13:18)."},{"author":"Metzudat David","text":"„Efod bad” — un veșmânt făcut după chipul efodului marelui preot, dedicat celor ce se dedică în chip aparte slujirii DOMNULUI, precum se spune despre Samuel: „iar Samuel... încins cu un efod de in” (1 Samuel 2:18) — și David l-a îmbrăcat la ridicarea Chivotului.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְדָוִד מְכַרְכֵּר בְּכָל־עֹז לִפְנֵי יְהוָה...","translation":"„Și David dansa cu toată puterea [lui] înaintea DOMNULUI...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ Δαυὶδ ἀνεκρούετο ἐν ὀργάνοις ἡρμοσμένοις ἐνώπιον Κυρίου, καὶ ὁ Δαυὶδ ἐνδεδυκὼς στολὴν ἔξαλλον.","greek":true,"translation":"„Și David cânta la instrumente acordate înaintea Domnului, iar David era îmbrăcat cu o haină neobișnuită.”","note":"Divergență reală: acolo unde Textul Masoretic spune limpede că David „dansa” (mecharker), Septuaginta traduce „ἀνεκρούετο” — „cânta la instrumente” — o schimbare de acțiune, de la dans la interpretare muzicală; iar „efod bad” (tunică simplă de in) devine „στολὴν ἔξαλλον” („haină neobișnuită/ciudată”), o redare vagă a veșmântului specific."}],"refs":["Exod 15:20","Psalmii 149:3","Luca 15:25","1 Cronici 15:27"]},{"v":"6:15","t":"Și David și toată casa lui Israel au ridicat Chivotul DOMNULUI cu glas vesel și puternic, și cu sunet de corn.","tokens":[{"t":"Și David și toată casa lui Israel au ridicat Chivotul DOMNULUI cu "},{"t":"glas vesel și puternic","w":"glas vesel și puternic","heb":"בִּתְרוּעָה","translit":"bitrua","strong":"H8643","pos":"substantiv, feminin singular","def_ro":"cu strigăt, cu sunet de veselie.","greek":"κραυγή (krauge)","greek_def_ro":"κραυγή (krauge) — strigăt, chemare puternică.","dict_ro":"Terua — termen tehnic care desemnează atât strigătul uman de bucurie/luptă, cât și sunetul specific al trâmbiței (aceeași rădăcină din „Yom Terua”, numele biblic al Roș Hașana); asocierea directă cu „kol șofar” (sunetul cornului) în același verset arată o procesiune completă senzorial — voci umane și instrumente muzicale unite într-un singur act public de bucurie."},{"t":", și cu sunet de corn."}],"commentaries":[{"author":"Metzudat David","text":"„Bitrua” — cu glas de bucurie, așa cum e obiceiul la aducerea unui lucru de mare cinste, iar aceasta arată bucuria pe care o simțeau la ridicarea Chivotului.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְדָוִד וְכָל־בֵּית יִשְׂרָאֵל מַעֲלִים...","translation":"„Și David și toată casa lui Israel au ridicat Chivotul DOMNULUI...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ Δαυὶδ καὶ πᾶς ὁ οἶκος Ἰσραὴλ ἀνήγαγον τὴν κιβωτὸν Κυρίου μετὰ κραυγῆς καὶ μετὰ φωνῆς σάλπιγγος.","greek":true,"translation":"„Și David și toată casa lui Israel au suit chivotul Domnului cu strigăt și cu sunet de trâmbiță.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Numeri 10:1-10","Iosua 6:4,5","Psalmii 47:1,5,6","Ezra 3:10,11","1 Cronici 15:16,25,28"]},{"v":"6:16","t":"Când Chivotul a ajuns în Orașul lui David, Mihal, fiica lui Șaul, a privit pe fereastră și l-a văzut pe regele David sărind și dansând înaintea DOMNULUI, și l-a disprețuit în inima ei.","tokens":[{"t":"Când Chivotul a ajuns în Orașul lui David, Mihal, fiica lui Șaul, a privit pe fereastră și l-a văzut pe regele David sărind și dansând înaintea DOMNULUI, și l-a "},{"t":"disprețuit","w":"disprețuit","heb":"וַתִּבֶז","translit":"vativez","strong":"H959","pos":"verb, qal imperfect consecutiv","def_ro":"și l-a disprețuit.","greek":"ἐξουδενόω (exoudenoo)","greek_def_ro":"ἐξουδενόω (exoudenoo) — a disprețui, a nesocoti.","dict_ro":"Baza — Metzudat David citește disprețul Mihalei nu ca o reacție morală, ci ca o judecată de etichetă regală: ea a considerat dansul public al lui David nepotrivit pentru un rege, mai ales „chiar înaintea Chivotului”, adică într-un context solemn unde s-ar fi așteptat o demnitate rezervată, nu o exprimare corporală atât de dezinhibată — o neînțelegere fundamentală a naturii adevăratei smerenii regale."},{"t":" în inima ei."}],"commentaries":[{"author":"Metzudat David","text":"„L-a disprețuit în inima ei” — a socotit-o, în inima ei, o faptă necuvenită pentru un rege să facă asemenea lucruri, chiar înaintea Chivotului.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְהָיָה אֲרוֹן יְהוָה בָּא עִיר דָּוִד...","translation":"„Când Chivotul a ajuns în Orașul lui David...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐγένετο τῆς κιβωτοῦ παραγινομένης ἕως πόλεως Δαυὶδ καὶ Μελχὸλ ἡ θυγάτηρ Σαοὺλ διέκυπτε διὰ τῆς θυρίδος καὶ εἶδε τὸν βασιλέα Δαυὶδ ὀρχούμενον καὶ ἀνακρουόμενον ἐνώπιον Κυρίου καὶ ἐξουδένωσεν αὐτὸν ἐν τῇ καρδίᾳ αὐτῆς.","greek":true,"translation":"„Și a fost când chivotul ajungea la cetatea lui David, Melhol, fiica lui Saul, se pleca pe fereastră și l-a văzut pe regele David dansând și cântând la instrumente înaintea Domnului, și l-a disprețuit în inima ei.”","note":"Corespondență strânsă cu Textul Masoretic; numele „Mihal” apare în forma grecizată „Μελχὸλ”."}],"refs":["1 Cronici 15:29","2 Samuel 3:14","Psalmii 69:7","Isaia 53:3","Faptele apostolilor 2:13"]},{"v":"6:17","t":"Au adus Chivotul DOMNULUI și l-au așezat la locul lui, în cortul pe care David îl ridicase pentru el; și David a adus arderi-de-tot înaintea DOMNULUI și jertfe de pace.","tokens":[{"t":"Au adus Chivotul DOMNULUI și l-au așezat la "},{"t":"locul lui","w":"locul lui","heb":"בִּמְקוֹמוֹ","translit":"bimkomo","strong":"H4725","pos":"substantiv, masculin singular construct + sufix","def_ro":"la locul lui.","greek":"τόπος αὐτῆς (topos autes)","greek_def_ro":"τόπος αὐτῆς (topos autes) — locul lui/ei.","dict_ro":"Makom — Metzudat David precizează că „locul lui” desemnează poziția special pregătită dinainte de David, în interiorul cortului pe care el însuși îl ridicase în acest scop — nu un cort improvizat pe loc, ci o structură pregătită anticipat, semn al planificării serioase din partea lui David pentru primirea permanentă a Chivotului la Ierusalim."},{"t":", în cortul pe care David îl ridicase pentru el; și David a adus arderi-de-tot înaintea DOMNULUI și jertfe de pace."}],"commentaries":[{"author":"Metzudat David","text":"„Bimkomo” — la locul pregătit pentru el în mijlocul cortului pe care David îl întinsese anume pentru Chivot.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיָּבִאוּ אֶת־אֲרוֹן יְהוָה וַיַּצִּגוּ אֹתוֹ בִּמְקוֹמוֹ...","translation":"„Au adus Chivotul DOMNULUI și l-au așezat la locul lui...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ φέρουσι τὴν κιβωτὸν τοῦ Κυρίου καὶ ἀνέθησαν αὐτὴν εἰς τὸν τόπον αὐτῆς εἰς μέσον τῆς σκηνῆς, ἧς ἔπηξεν αὐτῇ Δαυίδ· καὶ ἀνήνεγκε Δαυὶδ ὁλοκαυτώματα ἐνώπιον Κυρίου καὶ εἰρηνικάς.","greek":true,"translation":"„Și aduc chivotul Domnului și l-au așezat la locul lui, în mijlocul cortului pe care i-l întinsese David; și a adus David arderi de tot înaintea Domnului, și [jertfe] de pace.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["1 Cronici 16:1","2 Cronici 1:4","Psalmii 132:8","2 Cronici 5:6","Ezra 6:16,17","1 Cronici 15:1"]},{"v":"6:18","t":"Când David a încheiat de adus arderea-de-tot și jertfa de pace, a binecuvântat poporul cu numele DOMNULUI Oștirilor.","tokens":[{"t":"Când David a încheiat de adus arderea-de-tot și jertfa de pace, a "},{"t":"binecuvântat","w":"binecuvântat","heb":"וַיְבָרֶךְ","translit":"vaivareh","strong":"H1288","pos":"verb, piel imperfect consecutiv","def_ro":"și a binecuvântat.","greek":"εὐλογέω (eulogeo)","greek_def_ro":"εὐλογέω (eulogeo) — a binecuvânta.","dict_ro":"Barach — deși binecuvântarea poporului era în mod tradițional prerogativa preoților (Leviticul 9:22-23) sau, ocazional, a figurilor regal-preoțești precum Melhisedec (Geneza 14:19), David, ca rege, binecuvântează poporul „în Numele DOMNULUI Oștirilor” — o formulă care subliniază că binecuvântarea nu vine din autoritatea lui personală, ci e rostită explicit ca reprezentant al lui Dumnezeu, într-un moment de bucurie liturgică excepțională."},{"t":" poporul cu numele DOMNULUI Oștirilor."}],"commentaries":[{"author":"Metzudat David","text":"David, ca rege, binecuvântează poporul în Numele DOMNULUI Oștirilor — la fel cum, mai târziu, la sfințirea Templului, Solomon va binecuvânta întreaga adunare a lui Israel (1 Împărați 8:55)."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיְכַל דָּוִד מֵהַעֲלוֹת הָעוֹלָה...","translation":"„Când David a încheiat de adus arderea-de-tot...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ συνετέλεσε Δαυὶδ συναναφέρων τὰς ὁλοκαυτώσεις καὶ τὰς εἰρηνικὰς καὶ εὐλόγησε τὸν λαὸν ἐν ὀνόματι Κυρίου τῶν δυνάμεων.","greek":true,"translation":"„Și a isprăvit David de adus arderile de tot și [jertfele] de pace, și a binecuvântat poporul în numele Domnului puterilor.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["1 Împărați 8:55","1 Cronici 16:2","2 Cronici 6:3","Geneza 14:19","Levitic 9:22,23","Evrei 7:1-7"]},{"v":"6:19","t":"Și a dat întregului popor, întregii multitudini a lui Israel, bărbaților și femeilor deopotrivă, câte o franzelă de pâine, o bucată de carne și o așișa (n.t. turtă cu stafide sau ulcior de vin); și apoi tot poporul, fiecare om, a mers la casa lui.","tokens":[{"t":"Și a dat întregului popor, întregii multitudini a lui Israel, bărbaților și femeilor deopotrivă, câte o franzelă de pâine, o bucată de carne și o "},{"t":"așișa","w":"așișa","heb":"וַאֲשִׁישָׁה","translit":"vaașișa","strong":"H809","pos":"substantiv, feminin singular","def_ro":"turtă cu stafide sau ulcior de vin.","greek":"λάγανον (laganon)","greek_def_ro":"λάγανον (laganon) — turtă, clătită (coaptă în tigaie).","diff_ro":"Septuaginta descrie acest aliment ca „turtă coaptă în tigaie\" (λάγανον ἀπὸ τηγάνου), o imagine culinară diferită de „turta cu stafide\" tradițională din ebraică.","dict_ro":"Așișa — cuvânt cu sens disputat; Rashi, urmând Talmudul (Pesahim 36b), identifică „eșpar” drept a șasea parte dintr-un taur (o porție de carne standardizată), iar „așișa” drept un urcior/butoiaș de vin — interpretare tradițională păstrată în paralel cu varianta „turtă cu stafide”, mai des întâlnită în traducerile moderne bazate pe context (cf. Osea 3:1, unde termenul apare în context clar culinar)."},{"t":" (n.t. turtă cu stafide sau ulcior de vin); și apoi tot poporul, fiecare om, a mers la casa lui."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „eșpar” — a șasea parte dintr-un taur (Talmud Bavli, Pesahim 36b); „așișa ahat” — un urcior de vin (ibidem)."},{"author":"Metzudat David","text":"„Le-am ish” — vrea să spună: fiecăruia, atât bărbat cât și femeie.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיְחַלֵּק לְכָל־הָעָם...","translation":"„Și a dat întregului popor...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ διεμέρισε παντὶ τῷ λαῷ εἰς πᾶσαν τὴν δύναμιν τοῦ Ἰσραὴλ ἀπὸ Δὰν ἕως Βηρσαβεὲ καὶ ἀπό ἀνδρὸς ἕως γυναικός, ἑκάστῳ κολλυρίδα ἄρτου καὶ ἐσχαρίτην καὶ λάγανον ἀπὸ τηγάνου· καὶ ἀπῆλθε πᾶς ὁ λαὸς ἕκαστος εἰς τὸν οἶκον αὐτοῦ.","greek":true,"translation":"„Și a împărțit întregului popor, întregii puteri a lui Israel, de la Dan până la Beer-Șeba, și de la bărbat până la femeie, fiecăruia o turtă de pâine, și o prăjitură de pe grătar, și o clătită din tigaie; și a plecat tot poporul, fiecare la casa lui.”","note":"Divergență lexicală reală: Septuaginta adaugă precizarea geografică „de la Dan până la Beer-Șeba” (absentă din Textul Masoretic la acest verset) și traduce cele trei daruri prin termeni culinari concreți diferiți — „turtă de pâine”, „prăjitură de pe grătar” și „clătită din tigaie” — variind sensibil de la lectura tradițională a lui „eșpar” și „așișa” ca porție de carne și, respectiv, vin sau turtă cu stafide."}],"refs":["1 Cronici 16:3","Neemia 8:10","1 Împărați 8:66","2 Cronici 30:24"]},{"v":"6:20","t":"Și David s-a întors și și-a binecuvântat familia. Mihal, fiica lui Șaul, a ieșit să-l întâmpine pe David și a spus: „Cât de onorat este regele Israelului astăzi, care s-a descoperit sub ochii slujnicelor slujitorilor săi, așa cum s-ar fi descoperit un om de nimic!”","tokens":[{"t":"Și David s-a întors și și-a binecuvântat familia. Mihal, fiica lui Șaul, a ieșit să-l întâmpine pe David și a spus: „Cât de onorat este regele Israelului astăzi, care s-a descoperit sub ochii slujnicelor slujitorilor săi, așa cum s-ar fi descoperit "},{"t":"un om de nimic","w":"un om de nimic","heb":"הָרֵקִים","translit":"harēkim","strong":"H7386","pos":"adjectiv, masculin plural","def_ro":"unul dintre cei de nimic, un om ușuratic.","diff_ro":"Septuaginta are aici „εἷς τῶν ὀρχουμένων\" („unul dintre dansatori\"), nu „un om de nimic\" (reikim) ca în ebraică — o imagine complet diferită, centrată pe dans, nu pe disprețul social.","dict_ro":"Rekim — „cei goi/de nimic”, termen disprețuitor pentru oameni fără valoare socială; Metzudat David citește tonul Mihalei ca sarcasm făcut public — „cât de onorat” nu e laudă, ci ironie amară, care lasă de înțeles exact opusul: cât de dezonorat s-a făcut regele. Rashi notează că Targum Ionatan redă expresia prin „unul dintre cei ușuratici/deșerți”."},{"t":"!”"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „ahad harekim” — Targum Ionatan: „unul dintre cei ușuratici”."},{"author":"Metzudat David","text":"„Mah nichbad” — cât de mult te-ai făcut astăzi de cinste în ochii tuturor — a spus aceasta în batjocură, ca și cum ar fi zis: cât de mult te-ai făcut de disprețuit în ochii tuturor; „așer nigla hayom” — pentru că în timp ce dansa, i se vedea ceva din trup, iar slujnicele slujitorilor lui priveau, așa cum fac cei de nimic, care nu se sfiesc să-și arate trupul.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיָּשָׁב דָּוִד לְבָרֵךְ אֶת־בֵּיתוֹ...","translation":"„Și David s-a întors și și-a binecuvântat familia...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐπέστρεψε Δαυὶδ εὐλογῆσαι τὸν οἶκον αὐτοῦ, καὶ ἐξῆλθε Μελχὸλ ἡ θυγάτηρ Σαοὺλ εἰς ἀπάντησιν Δαυὶδ καὶ εὐλόγησεν αὐτὸν καὶ εἶπε· τί δεδόξασται σήμερον ὁ βασιλεὺς Ἰσραήλ, ὃς ἀπεκαλύφθη σήμερον ἐν ὀφθαλμοῖς παιδισκῶν τῶν δούλων ἑαυτοῦ, καθὼς ἀποκαλύπτεται ἀποκαλυφθεὶς εἷς τῶν ὀρχουμένων;","greek":true,"translation":"„Și s-a întors David să binecuvânteze casa lui, și a ieșit Melhol, fiica lui Saul, în întâmpinarea lui David, și l-a binecuvântat și a zis: cât s-a mărit astăzi regele lui Israel, care s-a descoperit astăzi înaintea ochilor slujnicelor robilor săi, așa cum se descoperă, descoperindu-se, unul dintre cei ce dansează!”","note":"Divergență reală: Septuaginta adaugă explicit „καὶ εὐλόγησεν αὐτὸν” („și l-a binecuvântat”) — Mihal însăși îl binecuvântează întâi pe David, un gest absent din Textul Masoretic — înainte de a rosti cuvintele ironice; iar „ahad harekim” („unul dintre cei de nimic”) devine „εἷς τῶν ὀρχουμένων” („unul dintre cei ce dansează”), o redare mai neutră, descriptivă, nu disprețuitoare."}],"refs":["Psalmii 69:7-9","Filipeni 2:7,8","1 Corinteni 4:10-13","1 Samuel 19:23,24","Judecători 9:4"]},{"v":"6:21","t":"David i-a răspuns lui Mihal: „Înaintea DOMNULUI care m-a ales față de tatăl tău și față de toată casa lui, ca să mă instaureze conducător peste poporul DOMNULUI, peste Israel – înaintea DOMNULUI am jucat.","tokens":[{"t":"David i-a răspuns lui Mihal: „Înaintea DOMNULUI care m-a "},{"t":"ales","w":"ales","heb":"בָּחַר","translit":"bahar","strong":"H977","pos":"verb, qal perfect","def_ro":"m-a ales.","greek":"ἐκλέγομαι (eklegomai)","greek_def_ro":"ἐκλέγομαι (eklegomai) — a alege.","dict_ro":"Bahar — David nu respinge acuzația Mihalei ca fiind falsă din punct de vedere factual, ci îi contestă premisa: onoarea regală nu vine din descendența dinastică (așa cum crede Mihal, fiica lui Saul), ci din alegerea directă a DOMNULUI, care l-a preferat pe David „față de tatăl tău și față de toată casa lui” — o replică ce transformă critica ei de etichetă regală într-o discuție despre sursa reală a legitimității puterii."},{"t":" față de tatăl tău și față de toată casa lui, ca să mă instaureze conducător peste poporul DOMNULUI, peste Israel – înaintea DOMNULUI am jucat."}],"commentaries":[{"author":"Metzudat David","text":"„Lifnei ADONAI” — vrea să spună: oare dansul meu n-a fost înaintea DOMNULUI, iar cinstea regilor e ca nimic pe lângă aceasta? „Vesihakti” — și tocmai de aceea am jucat înaintea Lui.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיֹּאמֶר דָּוִד אֶל־מִיכַל...","translation":"„David i-a răspuns lui Mihal...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ εἶπε Δαυὶδ πρὸς Μελχόλ· ἐνώπιον Κυρίου ὀρχήσομαι· εὐλογητὸς Κύριος, ὃς ἐξελέξατό με ὑπὲρ τὸν πατέρα σου καὶ ὑπὲρ πάντα τὸν οἶκον αὐτοῦ τοῦ καταστῆσαί με εἰς ἡγούμενον ἐπὶ τὸν λαὸν αὐτοῦ ἐπὶ τὸν Ἰσραήλ· καὶ παίξομαι καὶ ὀρχήσομαι ἐνώπιον Κυρίου.","greek":true,"translation":"„Și a zis David către Melhol: înaintea Domnului voi dansa; binecuvântat este Domnul, care m-a ales pe mine mai presus de tatăl tău și de toată casa lui, ca să mă pună povățuitor peste poporul Său, peste Israel; și mă voi juca și voi dansa înaintea Domnului.”","note":"Divergență de timp verbal: Textul Masoretic folosește trecutul „am jucat” (vesihakti), descriind fapta deja săvârșită, pe când Septuaginta trece la viitor, „ὀρχήσομαι... παίξομαι” („voi dansa... mă voi juca”) — transformând răspunsul lui David într-o promisiune fermă pentru viitor, nu doar o apărare a trecutului."}],"refs":["1 Samuel 13:14","Psalmii 78:70-72","Faptele apostolilor 13:22","1 Cronici 15:29","2 Samuel 6:14,16"]},{"v":"6:22","t":"Dacă m-aș fi purtat chiar și mai de nimic decât atât și chiar de m-aș fi înjosit în ochii mei – împreună cu slujnicele despre care ai vorbit, printre ele voi fi onorat!”","tokens":[{"t":"Dacă m-aș fi purtat chiar și mai de nimic decât atât și chiar de m-aș fi "},{"t":"înjosit","w":"înjosit","heb":"שָׁפָל","translit":"șafal","strong":"H8217","pos":"adjectiv, masculin singular","def_ro":"smerit, coborât, de rang jos.","greek":"ἀχρεῖος (achreios)","greek_def_ro":"ἀχρεῖος (achreios) — de nimic, lipsit de valoare.","dict_ro":"Șafal — David radicalizează deliberat propriul argument: nu doar acceptă critica, ci o depășește, afirmând că s-ar înjosi și mai mult, dacă asta ar însemna cinste înaintea DOMNULUI. Rashi citește finalul versetului nu ca resemnare, ci ca certitudine: „nu mă vor disprețui, ci voi fi important în ochii lor tocmai pentru aceasta” — smerenia publică, în slujba lui Dumnezeu, aduce, paradoxal, respect, nu rușine."},{"t":" în ochii mei – împreună cu slujnicele despre care ai vorbit, printre ele voi fi onorat!”"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „unekaloti od” — mă voi înjosi și mai mult decât atât înaintea Lui, mai mult decât m-am înjosit acum pe mine însumi."},{"author":"Metzudat David","text":"„Veim haamahot” — și cu asemenea fapte voi fi și mai cinstit, nu disprețuit, de vreme ce sunt făcute spre cinstea Chivotului.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וּנְקַלֹּתִי עוֹד מִזֹּאת...","translation":"„Dacă m-aș fi purtat chiar și mai de nimic decât atât...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἀποκαλυφθήσομαι ἔτι οὕτως καὶ ἔσομαι ἀχρεῖος ἐν ὀφθαλμοῖς σου καὶ μετὰ τῶν παιδισκῶν, ὧν εἶπάς με μὴ δοξασθῆναι.","greek":true,"translation":"„Și mă voi descoperi încă și așa, și voi fi de nimic în ochii tăi, și cu slujnicele despre care ai zis că nu voi fi mărit.”","note":"Corespondență generală de sens, cu diferență de subiect al judecății: Textul Masoretic are David înjosit „în ochii mei” (beeinai — propria lui perspectivă), pe când Septuaginta are „ἐν ὀφθαλμοῖς σου” („în ochii tăi” — perspectiva Mihalei) — o schimbare reală a punctului de vedere din care e evaluată smerenia lui David."}],"refs":["Iov 40:4","1 Petru 5:6","1 Samuel 2:30"]},{"v":"6:23","t":"Și Mihal, fiica lui Șaul, nu a avut copii până în ziua morții ei.","tokens":[{"t":"Și Mihal, fiica lui Șaul, nu a avut "},{"t":"copii","w":"copii","heb":"יָלֶד","translit":"ialed","strong":"H3206","pos":"substantiv, masculin singular","def_ro":"copil, prunc.","greek":"παιδίον (paidion)","greek_def_ro":"παιδίον (paidion) — copil.","dict_ro":"Yeled — versetul încheie episodul cu o consecință care leagă direct disprețul rostit de Mihal la v.16 și v.20 de sterilitatea ei ulterioară, prezentată ca pedeapsă — Rashi precizează explicit „din acea zi înainte”, indicând că nu era vorba de o incapacitate preexistentă, ci de o schimbare survenită exact în urma acestui incident."},{"t":" până în ziua morții ei."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „n-a avut copii” — din ziua aceea încolo."},{"author":"Metzudat David","text":"„În pedeapsa faptei ei, de a-l fi disprețuit pe David pentru că și-a înjosit cinstea înaintea Chivotului lui Dumnezeu.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וּלְמִיכַל בַּת־שָׁאוּל לֹא־הָיָה לָהּ יָלֶד...","translation":"„Și Mihal, fiica lui Șaul, nu a avut copii...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ τῇ Μελχὸλ θυγατρὶ Σαοὺλ οὐκ ἐγένετο παιδίον ἕως τῆς ἡμέρας τοῦ ἀποθανεῖν αὐτήν.","greek":true,"translation":"„Și Melholei, fiica lui Saul, nu i s-a născut copil până în ziua morții ei.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["1 Samuel 1:6-8","Luca 1:25","Isaia 22:14","1 Samuel 15:35"]},{"v":"7:1","t":"Și a fost, când regele s-a așezat la casa lui și DOMNUL i-a dat odihnă de toți dușmanii săi, de jur împrejur,","tokens":[{"t":"Și a fost, când regele s-a așezat la casa lui și DOMNUL i-a dat "},{"t":"odihnă","w":"odihnă","heb":"הֵנִיחַ","translit":"hēniah","strong":"H5117","pos":"verb, hifil perfect","def_ro":"i-a dat odihnă, l-a liniștit.","diff_ro":"Septuaginta are „κατεκληρονόμησεν\" („i-a dat în stăpânire/moștenire\"), nu „i-a dat odihnă\" (heniah) ca în ebraică — o imagine diferită, de transfer de teritoriu, nu de repaus.","dict_ro":"Nuah — Rashi leagă direct acest verset de o promisiune explicită din Tora: „vă va da odihnă de toți vrăjmașii voștri de jur împrejur” (Deuteronomul 12:10), urmată imediat, în același pasaj, de porunca privind „locul pe care-l va alege DOMNUL” pentru cult centralizat — semn, pentru Rashi, că această odihnă militară obținută de David marchează exact momentul în care obligația construirii unui Templu permanent devine posibilă, nu doar dorită."},{"t":" de toți dușmanii săi, de jur împrejur,"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: a spus [David]: iată s-a împlinit „și vă va da odihnă de toți vrăjmașii voștri” (Deuteronom 12:10) — ce scrie imediat după aceea? „și va fi locul pe care-l va alege...” — de acum înainte, ne revine nouă să zidim Casa cea aleasă."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיְהִי כִּי־יָשַׁב הַמֶּלֶךְ בְּבֵיתוֹ...","translation":"„Și a fost, când regele s-a așezat la casa lui...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ΚΑΙ ἐγένετο ὅτε ἐκάθισεν ὁ βασιλεὺς ἐν τῷ οἴκῳ αὐτοῦ, καὶ Κύριος κατεκληρονόμησεν αὐτὸν κύκλῳ ἀπὸ πάντων τῶν ἐχθρῶν αὐτοῦ τῶν κύκλῳ.","greek":true,"translation":"„Și a fost când a șezut regele în casa lui, și Domnul l-a moștenit de jur împrejur, de la toți vrăjmașii lui dimprejur.”","note":"Divergență reală de verb: Textul Masoretic are „heniah-lo” („i-a dat odihnă”), pe când Septuaginta traduce „κατεκληρονόμησεν αὐτὸν” („l-a moștenit/i-a dat ca moștenire”) — o schimbare semantică reală, de la ideea de odihnă/pace la cea de posesiune/moștenire teritorială."}],"refs":["1 Cronici 17:1-15","Iosua 21:44","Iosua 23:1","1 Împărați 5:4","Luca 1:74,75"]},{"v":"7:2","t":"că regele i-a spus profetului Natan: „Privește, te rog, eu locuiesc într-o casă din lemn de cedru, iar Chivotul lui Dumnezeu stă în mijlocul [spațiului separat] de draperie.”","tokens":[{"t":"că regele i-a spus profetului Natan: „Privește, te rog, eu locuiesc într-o casă din "},{"t":"lemn de cedru","w":"lemn de cedru","heb":"אֲרָזִים","translit":"arazim","strong":"H730","pos":"substantiv, masculin plural","def_ro":"cedri, lemn de cedru.","greek":"κέδρινος (kedrinos)","greek_def_ro":"κέδρινος (kedrinos) — de cedru.","dict_ro":"Erez — casa de cedru a lui David (construită cu ajutorul lui Hiram al Tirului, 2 Samuel 5:11) era un semn vizibil de prestigiu regal consolidat; Metzudat David subliniază contrastul retoric intenționat: „aceasta e casa potrivită pentru Chivotul lui Dumnezeu?” — David nu enunță o plângere directă, ci lasă disproporția să vorbească de la sine, pentru ca Natan să înțeleagă implicit dorința lui."},{"t":", iar Chivotul lui Dumnezeu stă în mijlocul [spațiului separat] de draperie.”"}],"commentaries":[{"author":"Metzudat David","text":"„Beveit arazim” — cum se cuvine rangului meu; „betoch hayeria” — acesta e cortul amintit mai sus, și vrea să spună: oare aceasta este casa potrivită pentru Chivotul lui Dumnezeu?”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיֹּאמֶר הַמֶּלֶךְ אֶל־נָתָן הַנָּבִיא...","translation":"„Regele i-a spus profetului Natan...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ εἶπεν ὁ βασιλεὺς πρὸς Νάθαν τὸν προφήτην· ἰδοὺ δὴ ἐγὼ κατοικῶ ἐν οἴκῳ κεδρίνῳ, καὶ ἡ κιβωτὸς τοῦ Θεοῦ κάθηται ἐν μέσῳ τῆς σκηνῆς.","greek":true,"translation":"„Și a zis regele către Natan profetul: iată, eu locuiesc într-o casă de cedru, iar chivotul lui Dumnezeu șade în mijlocul cortului.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["2 Samuel 6:17","Exod 26:1-14","Psalmii 132:5","Hagai 1:4","2 Samuel 12:1"]},{"v":"7:3","t":"Și Natan i-a spus regelui: „Orice ai în inimă, mergi și înfăptuiește, căci DOMNUL este cu tine.”","tokens":[{"t":"Și Natan i-a spus regelui: „Orice ai în "},{"t":"inimă","w":"inimă","heb":"בִּלְבָבְךָ","translit":"bilvavha","strong":"H3824","pos":"substantiv, masculin singular construct + sufix","def_ro":"în inima ta.","greek":"καρδία (kardia)","greek_def_ro":"καρδία (kardia) — inimă.","dict_ro":"Levav — Natan răspunde spontan, din propria lui judecată omenească, nu dintr-o revelație primită — un fapt pe care versetul următor îl va corecta explicit prin cuvântul direct al DOMNULUI. Metzudat David citește răspunsul lui Natan ca aprobare firească, întemeiată pe intenția evident bună a lui David, nu ca o autorizație profetică formală — distincție importantă, care explică de ce Natan trebuie să revină, fără rușine, cu un mesaj corector."},{"t":", mergi și înfăptuiește, căci DOMNUL este cu tine.”"}],"commentaries":[{"author":"Metzudat David","text":"„Kol așer bilvavcha” — ca și când ar spune: dacă dorința ta este să zidești o casă DOMNULUI, fă-ți dorința.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיֹּאמֶר נָתָן אֶל־הַמֶּלֶךְ...","translation":"„Natan i-a spus regelui...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ εἶπε Νάθαν πρὸς τὸν βασιλέα· πάντα, ὅσα ἂν ἐν τῇ καρδίᾳ σου, βάδιζε καὶ ποίει, ὅτι Κύριος μετὰ σοῦ.","greek":true,"translation":"„Și a zis Natan către rege: tot ce este în inima ta, mergi și fă, căci Domnul este cu tine.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["1 Împărați 8:17,18","1 Cronici 22:7","1 Cronici 28:2"]},{"v":"7:4","t":"Și a fost în noaptea aceea: și a venit cuvântul DOMNULUI la Natan, spunând:","tokens":[{"t":"Și a fost în "},{"t":"noaptea aceea","w":"noaptea aceea","heb":"בַּלַּיְלָה","translit":"balaila","strong":"H3915","pos":"substantiv, masculin singular","def_ro":"în noaptea aceea.","greek":"νύξ ἐκείνη (nyx ekeine)","greek_def_ro":"νύξ ἐκείνη (nyx ekeine) — noaptea aceea.","dict_ro":"Layla — Talmudul (citat de Rashi prin numele lui Rabi Chanina bar Papa) explică graba corecției divine chiar în aceeași noapte: DOMNUL știa că David era un om al faptei, gata să angajeze lucrători a doua zi de dimineață, sau, după o altă opinie, un om al jurămintelor, gata să se lege să nu mănânce sau să nu bea până nu începe construcția — de aceea mesajul corector trebuia să ajungă la Natan fără nicio întârziere, înainte ca David să apuce să acționeze."},{"t":": și a venit cuvântul DOMNULUI la Natan, spunând:"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi, citând pe Rabi Chanina bar Papa: Sfântul, binecuvântat fie El, i-a spus lui Natan: „acest om la care te trimit e om al faptei — ca nu cumva să angajeze lucrători și să-l fac să piardă, grăbește-te și spune-i: nu tu vei zidi Casa”. Rabi Simon spune: e om al jurămintelor, ca la Psalmii 132:2-3 — „ca nu cumva să zică nu voi mânca și nu voi bea până nu voi face aceasta”, și l-aș face să piardă (din Yalkut Șimoni 143)."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיְהִי בַּלַּיְלָה הַהוּא...","translation":"„Și a fost în noaptea aceea...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐγένετο τῇ νυκτὶ ἐκείνῃ καὶ ἐγένετο ῥῆμα Κυρίου πρὸς Νάθαν λέγων.","greek":true,"translation":"„Și a fost în noaptea aceea, și a fost cuvântul Domnului către Natan, zicând.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Numeri 12:6","1 Cronici 17:3","Amos 3:7"]},{"v":"7:5","t":"„Mergi și spune-i slujitorului Meu, lui David: «Așa a spus DOMNUL: oare vei construi tu o casă ca să mă așez în ea?","tokens":[{"t":"„Mergi și spune-i slujitorului Meu, lui David: «Așa a spus DOMNUL: oare "},{"t":"vei construi tu","w":"vei construi tu","heb":"תִּבְנֶה","translit":"tivne","strong":"H1129","pos":"verb, qal imperfect","def_ro":"oare tu vei zidi?","diff_ro":"Septuaginta transformă întrebarea retorică ebraică („oare vei construi tu...?\") într-o afirmație negativă directă, „οὐ σὺ οἰκοδομήσεις\" („nu TU vei construi\"), eliminând forma interogativă.","dict_ro":"Bana — Metzudat David citește particula interogativă „ha-” de la începutul frazei ca marcând o mirare retorică, nu o simplă întrebare: „oare tu vei zidi Mie o casă?” în sensul „ajunge-ți binele pe care ți l-am făcut deja, cum se arată în versetele următoare” — răspunsul negativ nu e o respingere a proiectului în sine, ci o amânare a lui pentru generația următoare."},{"t":" o casă ca să mă așez în ea?"}],"commentaries":[{"author":"Metzudat David","text":"„Haata” — cu mirare, ca și când ar spune: ajunge-ți binele pe care ți l-am făcut deja, precum se va explica mai jos.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"לֵךְ וְאָמַרְתָּ אֶל־עַבְדִּי אֶל־דָּוִד...","translation":"„Mergi și spune-i slujitorului Meu, lui David...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"πορεύου, καὶ εἰπὸν πρὸς τὸν δοῦλόν μου Δαυίδ· τάδε λέγει Κύριος· οὐ σὺ οἰκοδομήσεις μοι οἶκον τοῦ κατοικῆσαί με.","greek":true,"translation":"„Mergi și spune robului Meu David: așa zice Domnul: nu tu Îmi vei zidi casă ca să locuiesc.”","note":"Divergență de formă gramaticală: Textul Masoretic pune întrebarea retoric, „oare tu vei zidi?” (haata tivne), pe când Septuaginta o transformă într-o afirmație negativă directă, „οὐ σὺ οἰκοδομήσεις” („nu tu vei zidi”) — o formulare mai categorică decât interogația ebraică."}],"refs":["1 Împărați 5:3","1 Împărați 8:16-19","1 Cronici 17:4","1 Cronici 22:7,8","1 Cronici 23:3-32"]},{"v":"7:6","t":"Căci nu am locuit într-o casă din ziua în care i-am ridicat pe copiii lui Israel din Egipt și până în ziua aceasta, ci M-am plimbat într-un cort și într-un tabernacol.","tokens":[{"t":"Căci nu am locuit într-o casă din ziua în care i-am ridicat pe copiii lui Israel din Egipt și până în ziua aceasta, ci M-am plimbat într-un "},{"t":"cort și într-un tabernacol","w":"cort și într-un tabernacol","heb":"וּבְמִשְׁכָּן","translit":"uvmișkan","strong":"H4908","pos":"substantiv, masculin singular","def_ro":"cort și lăcaș.","greek":"κατάλυμα καὶ σκηνή (katalyma kai skene)","greek_def_ro":"κατάλυμα καὶ σκηνή (katalyma kai skene) — popas și cort.","dict_ro":"Mișkan — Rashi observă o distincție tehnică reală între cele două structuri istorice: Cortul din Șilo, spre deosebire de Cortul Întâlnirii din pustie, nu mai avea un acoperiș din piei, ci era construit din piatră la bază, cu draperii doar în partea superioară — o structură hibridă, intermediară între cortul mobil originar și Templul de piatră permanent care va urma."},{"t":"."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „beohel uvemișkan” — lăcașul din Șilo nu avea acoperiș, ci era o casă de piatră pe dedesubt, cu draperii pe deasupra."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"כִּי לֹא יָשַׁבְתִּי בְּבַיִת...","translation":"„Căci nu am locuit într-o casă...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ὅτι οὐ κατῴκηκα ἐν οἴκῳ ἀφ' ἧς ἡμέρας ἀνήγαγον τοὺς υἱοὺς Ἰσραὴλ ἐξ Αἰγύπτου ἕως τῆς ἡμέρας ταύτης καὶ ἤμην ἐμπεριπατῶν ἐν καταλύματι καὶ ἐν σκηνῇ.","greek":true,"translation":"„Căci n-am locuit într-o casă din ziua în care am scos pe fiii lui Israel din Egipt și până în ziua aceasta, și am umblat într-un adăpost și într-un cort.”","note":"Corespondență apropiată; Septuaginta redă „mișkan” prin „καταλύματι” („adăpost/loc de popas”), un termen mai general decât ebraicul tehnic „tabernacol”."}],"refs":["Iosua 18:1","Numeri 10:33-36","2 Corinteni 6:16","Faptele apostolilor 7:44","1 Cronici 17:5,6","Exod 33:14,15"]},{"v":"7:7","t":"Oriunde am umblat printre toți copiii lui Israel, oare am vorbit Eu vreo vorbă aceluia pe care l-am numit să-Mi păstorească poporul, pe Israel, spunând: ‘De ce nu Mi-ați construit o casă de lemn de cedru?’","tokens":[{"t":"Oriunde am umblat printre toți copiii lui Israel, oare am vorbit Eu vreo vorbă aceluia pe care l-am numit să-Mi "},{"t":"păstorească","w":"păstorească","heb":"לִרְעוֹת","translit":"lirot","strong":"H7462","pos":"verb, qal infinitiv","def_ro":"să pască, să păstorească.","greek":"ποιμαίνω (poimaino)","greek_def_ro":"ποιμαίνω (poimaino) — a păstori.","dict_ro":"Raa — verbul „a păstori” aplicat conducerii politice (aceeași imagine folosită și pentru David la 2 Samuel 5:2 și pentru mesia davidic la Ezechiel 34:23) descrie autoritatea ca îngrijire, nu ca stăpânire — un conducător legitim „paște” poporul, cum un păstor își paște turma, cu grijă pentru bunăstarea ei, nu pentru propriul interes."},{"t":" poporul, pe Israel, spunând: ‘De ce nu Mi-ați construit o casă de lemn de cedru?’"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „hadavar dibarti” — e o formă de mirare, de aceea e punctată cu hataf-patah [nu cu articolul obișnuit], iar litera dalet e lene [fără accent dublu]."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"בְּכֹל אֲשֶׁר־הִתְהַלַּכְתִּי בְּכָל־בְּנֵי יִשְׂרָאֵל...","translation":"„Oriunde am umblat printre toți copiii lui Israel...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ἐν πᾶσιν, οἷς διῆλθον ἐν παντὶ Ἰσραήλ, εἰ λαλῶν ἐλάλησα πρὸς μίαν φυλὴν τοῦ Ἰσραήλ, ᾧ ἐνετειλάμην ποιμαίνειν τὸν λαόν μου Ἰσραὴλ λέγων· ἱνατί οὐκ ᾠκοδομήκατέ μοι οἶκον κέδρινον;","greek":true,"translation":"„În toate prin care am trecut, în tot Israelul, oare am vorbit vreodată vreunei seminții a lui Israel, căreia i-am poruncit să păstorească pe poporul Meu Israel, zicând: pentru ce nu Mi-ați zidit casă de cedru?”","note":"Corespondență apropiată de sens; Septuaginta specifică „vreunei seminții” (μίαν φυλὴν), interpretând mai explicit „ahad șivtei Israel” din ebraică."}],"refs":["2 Samuel 5:2","Psalmii 78:71,72","Ioan 21:15-17","Faptele apostolilor 20:28","Levitic 26:11,12"]},{"v":"7:8","t":"Și acum, așa să-i spui slujitorului Meu, lui David: ‘Așa a spus DOMNUL Oștirilor: Eu te-am luat de la stână, de la păstoritul turmelor, ca să fii conducător peste poporul Meu, peste Israel.","tokens":[{"t":"Și acum, așa să-i spui slujitorului Meu, lui David: ‘Așa a spus DOMNUL Oștirilor: Eu te-am luat de la "},{"t":"stână","w":"stână","heb":"הַנָּוֶה","translit":"hanave","strong":"H5116","pos":"substantiv, masculin și feminin singular","def_ro":"stâna, staulul.","greek":"μάνδρα (mandra)","greek_def_ro":"μάνδρα (mandra) — stână, ocol de turmă.","dict_ro":"Nave — Rashi identifică termenul cu „nevot cherot roim” din Țefania 2:6 (stânele ciobanilor), confirmând sensul pastoral concret al cuvântului; reamintirea originii umile a lui David — de la oi, nu de la un tron — funcționează retoric ca argument suplimentar pentru amânarea cererii lui: cel care a primit deja atât de mult de la DOMNUL n-are nevoie să ceară mai mult prin construirea grabnică a unui Templu."},{"t":", de la păstoritul turmelor, ca să fii conducător peste poporul Meu, peste Israel."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „min-hanave” — de la staulul ciobanilor, ca la „nevot cherot roim” (Țefania 2:6)."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְעַתָּה כֹּה־תֹאמַר לְעַבְדִּי לְדָוִד...","translation":"„Și acum, așa să-i spui slujitorului Meu, lui David...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ νῦν τάδε ἐρεῖς τῷ δούλῳ μου Δαυίδ· τάδε λέγει Κύριος παντοκράτωρ· ἔλαβόν σε ἐκ τῆς μάνδρας τῶν προβάτων τοῦ εἶναί σε εἰς ἡγούμενον ἐπὶ τὸν λαόν μου ἐπὶ τὸν Ἰσραήλ.","greek":true,"translation":"„Și acum, așa vei spune robului Meu David: așa zice Domnul Atotțiitorul: te-am luat din staulul oilor, ca să fii povățuitor peste poporul Meu, peste Israel.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["1 Samuel 16:11,12","1 Cronici 17:7","Psalmii 78:70","2 Samuel 6:21","1 Samuel 9:16","1 Samuel 10:1"]},{"v":"7:9","t":"Și am fost cu tine oriunde ai mers, și i-am nimicit pe toți dușmanii tăi dinaintea ta și ți-am făcut un renume mare, aidoma renumelui celor mari de pe pământ.","tokens":[{"t":"Și am fost cu tine oriunde ai mers, și i-am nimicit pe toți dușmanii tăi dinaintea ta și ți-am făcut un "},{"t":"renume mare","w":"renume mare","heb":"שֵׁם","translit":"șēm","strong":"H8034","pos":"substantiv, masculin singular","def_ro":"nume mare, renume mare.","greek":"ὀνομαστός (onomastos)","greek_def_ro":"ὀνομαστός (onomastos) — vestit, cu renume.","dict_ro":"Șem gadol — Rashi citează o tradiție talmudică (Pesahim 117b) potrivit căreia acest „nume mare” se referă concret la formula liturgică „Scutul lui David” (Magen David), rostită încă din vechime în rugăciune, ca ecou direct al acestei promisiuni divine — o legătură explicită între textul biblic și practica de cult ulterioară."},{"t":", aidoma renumelui celor mari de pe pământ."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „keșem hagedolim” — aceasta e ceea ce se spune [în rugăciune]: „Scutul lui David” (după Talmud Bavli, Pesahim 117b); „și i-am nimicit pe toți vrăjmașii tăi” — de aceea ți-a venit în inimă să zidești Casa, precum stă scris în Tora."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וָאֶהְיֶה עִמְּךָ בְּכֹל אֲשֶׁר הָלַכְתָּ...","translation":"„Și am fost cu tine oriunde ai mers...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἤμην μετὰ σοῦ ἐν πᾶσιν, οἷς ἐπορεύου, καὶ ἐξωλόθρευσα πάντας τοὺς ἐχθρούς σου ἀπὸ προσώπου σου καὶ ἐποίησά σε ὀνομαστὸν κατὰ τὸ ὄνομα τῶν μεγάλων τῶν ἐπὶ τῆς γῆς.","greek":true,"translation":"„Și am fost cu tine în toate pe unde ai mers, și i-am nimicit pe toți vrăjmașii tăi de la fața ta, și te-am făcut vestit după numele celor mari de pe pământ.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["2 Samuel 22:1","Geneza 12:2","1 Samuel 2:8","Psalmii 89:23"]},{"v":"7:10","t":"Și am păstrat un loc pentru poporul Meu, pentru Israel, și l-am plantat, iar el a locuit la locul lui, ca să nu mai tremure, ca nedrepții să nu-l mai chinuie ca înainte.","tokens":[{"t":"Și am păstrat un loc pentru poporul Meu, pentru Israel, și l-am plantat, iar el a locuit la locul lui, ca să nu mai "},{"t":"tremure","w":"tremure","heb":"יִרְגַּז","translit":"irgaz","strong":"H7264","pos":"verb, qal imperfect","def_ro":"să tremure, să fie neliniștit.","greek":"μεριμνάω (merimnao)","greek_def_ro":"μεριμνάω (merimnao) — a se îngrijora, a fi neliniștit.","diff_ro":"Septuaginta are nuanța de „a se îngrijora\" (μεριμνήσει), nu strict „a tremura\" (yirgaz) ca în ebraică — o imagine mai degrabă de neliniște interioară decât de tremur fizic.","dict_ro":"Ragaz — Metzudat David explică timpul viitor al promisiunii: „am pus un loc” înseamnă, în vremea lui David, un loc de odihnă stabil și sigur, pe pământul propriu al lui Israel, definitiv statornicit — spre deosebire de neliniștea și strămutările frecvente din epoca anterioară, marcată de opresiuni repetate „ca înainte” (kaasher barișona), referire directă la perioada Judecătorilor."},{"t":", ca nedrepții să nu-l mai chinuie ca înainte."}],"commentaries":[{"author":"Metzudat David","text":"„Vesamti makom” — în zilele tale am pus un loc de odihnă statornic poporului Meu Israel, l-am sădit pe pământul lui și a locuit la locul lui; „kaasher barișona” — vrea să spună: înainte de ridicarea judecătorilor.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְשַׂמְתִּי מָקוֹם לְעַמִּי לְיִשְׂרָאֵל...","translation":"„Și am păstrat un loc pentru poporul Meu, pentru Israel...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ θήσομαι τόπον τῷ λαῷ μου τῷ Ἰσραὴλ καὶ καταφυτεύσω αὐτόν, καὶ κατασκηνώσει καθ' ἑαυτὸν καὶ οὐ μεριμνήσει οὐκέτι, καὶ οὐ προσθήσει υἱὸς ἀδικίας τοῦ ταπεινῶσαι αὐτὸν καθὼς ἀπ' ἀρχῆς.","greek":true,"translation":"„Și voi pune loc poporului Meu Israel și-l voi sădi, și va locui de sine stătător și nu se va mai îngrijora, și fiul nedreptății nu-l va mai apăsa ca de la început.”","note":"Divergență de timp verbal: Textul Masoretic are trecutul „am păstrat/am plantat” (vesamti/netativ), tratând promisiunea ca deja înfăptuită parțial; Septuaginta trece la viitor, „θήσομαι... καταφυτεύσω” („voi pune... voi sădi”), redând-o ca o făgăduință încă neîmplinită."}],"refs":["Ezechiel 37:25-27","Amos 9:15","Isaia 60:18","Judecători 6:2-6","1 Cronici 17:9"]},{"v":"7:11","t":"Din ziua aceea, am desemnat judecători peste poporul Meu Israel, și ți-am dăruit odihnă de toți dușmanii tăi; și DOMNUL ți-a vestit că DOMNUL îți va face o casă.","tokens":[{"t":"Din ziua aceea, am desemnat "},{"t":"judecători","w":"judecători","heb":"שֹׁפְטִים","translit":"șoftim","strong":"H8199","pos":"verb, qal participiu","def_ro":"judecători.","greek":"κριτής (krites)","greek_def_ro":"κριτής (krites) — judecător.","dict_ro":"Șoftim — perioada Judecătorilor (Sefer Șoftim) e evocată aici explicit ca punct de comparație istorică: pacea și stabilitatea din vremea lui David sunt măsurate față de instabilitatea structurală a epocii anterioare, marcată de cicluri repetate de opresiune și eliberare, fără o conducere centralizată permanentă — David reprezintă, în această retorică, împlinirea unei tranziții istorice complete, nu doar o victorie militară izolată."},{"t":" peste poporul Meu Israel, și ți-am dăruit odihnă de toți dușmanii tăi; și DOMNUL ți-a vestit că DOMNUL îți va face o casă."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"„Și din ziua în care am poruncit” — se leagă de ce e mai sus: nu-l vor mai asupri ca la început, înainte de judecători, și cum au făcut din zilele judecătorilor până acum. „Și îți voi da odihnă” — din ce în ce mai mult, până te vei odihni de toți vrăjmașii tăi. „Și DOMNUL îți vestește” — astăzi, prin mine, că îți va face o casă, ca să-l așeze pe fiul tău pe tronul tău, iar domnia ta va rămâne în picioare; și el va zidi casa."},{"author":"Metzudat David","text":"„Vehigid lecha ADONAI” — azi, prin mine, îți vestește DOMNUL că îți va face o casă, adică o casă regală care va dăinui pentru tine și urmașii tăi, așa cum a spus Abigail: „căci DOMNUL îți va face o casă trainică” (1 Samuel 25:28) — atât de mult ți-a făcut bine, așadar ajunge-ți aceasta, chiar dacă nu vei zidi tu Casa.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וּלְמִן־הַיּוֹם אֲשֶׁר צִוִּיתִי שֹׁפְטִים...","translation":"„Din ziua aceea, am desemnat judecători...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ἀπὸ τῶν ἡμερῶν, ὧν ἔταξα κριτὰς ἐπὶ τὸν λαόν μου Ἰσραήλ, καὶ ἀναπαύσω σε ἀπὸ πάντων τῶν ἐχθρῶν σου, καὶ ἀπαγγελεῖ σοι Κύριος ὅτι οἶκον οἰκοδομήσεις αὐτῷ.","greek":true,"translation":"„Din zilele în care am rânduit judecători peste poporul Meu Israel, și te voi odihni de toți vrăjmașii tăi, și îți va vesti Domnul că îi vei zidi casă.”","note":"Divergență reală și semnificativă: Textul Masoretic promite „DOMNUL îți va face o casă” (bayit yaase-lecha ADONAI — Dumnezeu zidește casa lui David, adică dinastia), pe când Septuaginta inversează complet sensul: „ὅτι οἶκον οἰκοδομήσεις αὐτῷ” („că îi vei zidi casă [Lui]” — David e cel care zidește Templul lui Dumnezeu) — o schimbare majoră de agent și obiect, care contrazice tocmai punctul central al pasajului (că nu David, ci fiul lui, va zidi Templul)."}],"refs":["Judecători 2:14-16","2 Samuel 7:1","2 Samuel 7:27","1 Cronici 22:10","Psalmii 127:1","1 Împărați 11:38"]},{"v":"7:12","t":"Când zilele îți vor fi împlinite și te vei culca alături de strămoșii tăi, voi statornici pe urmașul tău după tine, cel care va ieși dintre coapsele tale, și îi voi statornici domnia.","tokens":[{"t":"Când zilele îți vor fi împlinite și te vei culca alături de strămoșii tăi, voi statornici pe "},{"t":"urmașul tău","w":"urmașul tău","heb":"זַרְעֲךָ","translit":"zaraha","strong":"H2233","pos":"substantiv, masculin singular construct + sufix","def_ro":"sămânța ta, urmașul tău.","greek":"σπέρμα σου (sperma sou)","greek_def_ro":"σπέρμα σου (sperma sou) — sămânța/urmașul tău.","dict_ro":"Zera — cuvântul „zera” (sămânță) desemnează aici, gramatical, un singular colectiv, dar precizarea „care va ieși dintre coapsele tale” (yetze mimeecha) îl restrânge explicit la un fiu direct, biologic, nu la o descendență generală — punctul de plecare al unei promisiuni dinastice care va fi citită ulterior atât ca împlinire imediată în Solomon, cât și, în tradiția mesianică ulterioară, ca profeție cu împlinire finală mult mai îndepărtată."},{"t":" după tine, cel care va ieși dintre coapsele tale, și îi voi statornici domnia."}],"commentaries":[{"author":"Metzudat David","text":"„Ki yimleu yamecha” — vrea să spună: nu tu, ci abia atunci când zilele tale se vor împlini și fiul tău va urma la domnie, el va zidi Casa.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"כִּי יִמְלְאוּ יָמֶיךָ...","translation":"„Când zilele îți vor fi împlinite...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἔσται ἐὰν πληρωθῶσιν αἱ ἡμέραι σου καὶ κοιμηθήσῃ μετὰ τῶν πατέρων σου, καὶ ἀναστήσω τὸ σπέρμα σου μετὰ σέ, ὃς ἔσται ἐκ τῆς κοιλίας σου, καὶ ἑτοιμάσω τὴν βασιλείαν αὐτοῦ.","greek":true,"translation":"„Și va fi, când se vor împlini zilele tale și vei adormi cu părinții tăi, voi ridica sămânța ta după tine, care va fi din pântecele tău, și voi pregăti împărăția lui.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["1 Împărați 2:1","Geneza 15:4","Psalmii 89:29","Psalmii 132:11,12","Isaia 9:7","Matei 22:42-44"]},{"v":"7:13","t":"El este cel care va construi o casă de dragul numelui Meu și Eu voi statornici tronul regatului său, veșnic.","tokens":[{"t":"El este cel care va construi o casă de dragul numelui Meu și Eu voi statornici "},{"t":"tronul regatului său, veșnic","w":"tronul regatului său, veșnic","heb":"כִּסֵּא","translit":"kisē","strong":"H3678","pos":"substantiv, masculin singular construct","def_ro":"tronul domniei lui, pe vecie.","greek":"θρόνος αὐτοῦ (thronos autou)","greek_def_ro":"θρόνος αὐτοῦ (thronos autou) — tronul lui.","dict_ro":"Kise — promisiunea unui tron „veșnic” (ad-olam) devine, în tradiția mesianică ulterioară, temeiul textual central al așteptării unui urmaș final, nesfârșit, al lui David — deși împlinirea imediată a versetului e Solomon (v.12-13 descriu explicit construirea Templului, realizată de Solomon), formula „pe vecie” depășește orice domnie individuală limitată în timp, deschizând spațiu pentru o citire mesianică suplimentară, dezvoltată mai târziu de profeți precum Isaia (9:6-7)."},{"t":"."}],"commentaries":[{"author":"Metzudat David","text":"„Hu yivne” — lui îi este păstrată mărirea numelui prin zidirea Casei Mele; „ad-olam” — pentru urmașii lui după el.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"הוּא יִבְנֶה־בַּיִת לִשְׁמִי...","translation":"„El este cel care va construi o casă de dragul numelui Meu...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"αὐτὸς οἰκοδομήσει μοι οἶκον τῷ ὀνόματί μου, καὶ ἀνορθώσω τὸν θρόνον αὐτοῦ ἕως εἰς τὸν αἰῶνα.","greek":true,"translation":"„El Îmi va zidi Mie o casă pentru numele Meu, și voi ridica scaunul lui de domnie până în veac.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["1 Împărați 5:5","1 Împărați 8:19","Zaharia 6:13","Matei 16:18","Luca 1:32,33","Evrei 3:3"]},{"v":"7:14","t":"Voi fi ca un Părinte pentru el și el va fi ca un fiu pentru Mine; de aceea, când păcătuiește, îl voi mustra cu toiagul oamenilor și cu chinurile omenești.","tokens":[{"t":"Voi fi ca un Părinte pentru el și el va fi ca un fiu pentru Mine; de aceea, când păcătuiește, îl voi mustra cu "},{"t":"toiagul oamenilor","w":"toiagul oamenilor","heb":"בְּשֵׁבֶט","translit":"beșēvet","strong":"H7626","pos":"substantiv, masculin singular construct","def_ro":"cu toiagul oamenilor.","greek":"ῥάβδος ἀνδρῶν (rhabdos andron)","greek_def_ro":"ῥάβδος ἀνδρῶν (rhabdos andron) — toiagul oamenilor.","dict_ro":"Șevet anașim — Rashi identifică aceste pedepse concrete cu evenimente istorice din domnia lui Solomon: „toiagul oamenilor” ar fi Hadad edomitul și Rezon, fiul lui Eliada, adversari politici ridicați împotriva lui Solomon (1 Împărați 11:14-25), iar „chinurile fiilor omului” ar fi Așmodai, care, potrivit unei tradiții aggadice, l-ar fi alungat vremelnic pe Solomon de pe tron — o lectură care leagă limbajul general al versetului de episoade narative precise din cartea 1 Regi."},{"t":" și cu chinurile omenești."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „beșevet anașim” — aceștia sunt Hadad și Rezon, fiul lui Eliada; „uvigei venei adam” — acesta e Așmodai, care l-a alungat de pe tron, iar duhurile sunt fiii lui Adam cel dintâi, căci în cei o sută treizeci de ani cât Adam s-a despărțit de soția lui după moartea lui Abel, duhurile se împerecheau și nășteau din el (după Yalkut Șimoni 146)."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"אֲנִי אֶהְיֶה־לּוֹ לְאָב...","translation":"„Voi fi ca un Părinte pentru el...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ἐγὼ ἔσομαι αὐτῷ εἰς πατέρα, καὶ αὐτὸς ἔσται μοι εἰς υἱόν· καὶ ἐὰν ἔλθῃ ἡ ἀδικία αὐτοῦ, καὶ ἐλέγξω αὐτὸν ἐν ράβδῳ ἀνδρῶν καὶ ἐν ἁφαῖς υἱῶν ἀνθρώπων.","greek":true,"translation":"„Eu Îi voi fi Tată, și El Îmi va fi Fiu; și dacă va veni nedreptatea lui, îl voi mustra cu toiagul bărbaților și cu loviturile fiilor oamenilor.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["1 Cronici 17:13","Evrei 1:5","Proverbe 3:11,12","Evrei 12:5-11","Psalmii 89:30-35"]},{"v":"7:15","t":"Dar bunăvoința Mea nu o voi îndepărta de el așa cum am îndepărtat-o de la Șaul, pe care l-am dat la o parte înaintea ta.","tokens":[{"t":"Dar "},{"t":"bunăvoința Mea","w":"bunăvoința Mea","heb":"וְחַסְדִּי","translit":"vehasdi","strong":"H2617","pos":"substantiv, masculin singular construct + sufix","def_ro":"și îndurarea/bunăvoința Mea.","greek":"ἔλεός μου (eleos mou)","greek_def_ro":"ἔλεός μου (eleos mou) — mila/bunăvoința mea.","dict_ro":"Hesed — promisiunea limitează pedeapsa la corecție (v.14), dar exclude explicit retragerea definitivă a bunăvoinței divine, contrastând direct cu soarta lui Saul; important, formula ebraică nu spune „așa cum am îndepărtat-o de la Șaul, pe care l-am dat la o parte”, numind explicit doar rezultatul, nu motivul — spre deosebire de comentariile rabinice, care leagă explicit îndepărtarea de la Saul de neascultarea lui concretă (1 Samuel 15)."},{"t":" nu o voi îndepărta de el așa cum am îndepărtat-o de la Șaul, pe care l-am dat la o parte înaintea ta."}],"commentaries":[{"author":"Metzudat David","text":"„Vehasdi” — dar mila Mea nu o voi îndepărta de la el ca să-l resping, așa cum am îndepărtat mila Mea de la Șaul, care, din pricina păcatului lui, l-am îndepărtat dinaintea ta, ca să moștenești tu domnia lui.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְחַסְדִּי לֹא־יָסוּר מִמֶּנּוּ...","translation":"„Dar bunăvoința Mea nu o voi îndepărta de el...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"τὸ δὲ ἔλεός μου οὐκ ἀποστήσω ἀπ' αὐτοῦ, καθὼς ἀπέστησα ἀφ' ὧν ἀπέστησα ἐκ προσώπου μου.","greek":true,"translation":"„Iar mila Mea n-o voi depărta de la el, cum am depărtat-o de la aceia de la care am depărtat-o dinaintea feței Mele.”","note":"Divergență reală și notabilă: Textul Masoretic numește explicit „Șaul” ca punct de comparație; Septuaginta omite complet numele, redând vag „ἀφ' ὧν ἀπέστησα” („de la aceia de la care am depărtat-o”) — o generalizare impersonală, fără referire directă la primul rege al lui Israel."}],"refs":["1 Samuel 15:23,28","1 Samuel 16:14","Isaia 55:3","1 Samuel 19:24","Psalmii 89:28,34"]},{"v":"7:16","t":"Trăinicia casei tale și a regatului tău vor fi veșnice înaintea ta, tronul tău va fi statornicit veșnic.’»”","tokens":[{"t":"Trăinicia casei tale și a regatului tău vor fi "},{"t":"veșnice","w":"veșnice","heb":"עוֹלָם","translit":"olam","strong":"H5769","pos":"substantiv, masculin singular","def_ro":"pe vecie, pentru totdeauna.","greek":"αἰών (aion)","greek_def_ro":"αἰών (aion) — veac, eternitate.","dict_ro":"Olam — repetiția formulei „ad-olam” (pe vecie) de trei ori în tot pasajul (v.13, 16 de două ori) subliniază intenționat caracterul necondiționat al promisiunii dinastice, spre deosebire de legământul condiționat de la Sinai — Metzudat David citește versetul ca o încheiere solemnă, care rotunjește întregul discurs profetic, reafirmând stabilitatea casei lui David chiar în fața eșecurilor viitoare individuale ale urmașilor săi."},{"t":" înaintea ta, tronul tău va fi statornicit veșnic.’»”"}],"commentaries":[{"author":"Metzudat David","text":"„Neeman beitcha” — statornicia casei tale și a regatului tău va dăinui pe vecie; și tot așa scaunul tău de domnie va rămâne întărit pe vecie.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְנֶאְמַן בֵּיתְךָ וּמַמְלַכְתְּךָ...","translation":"„Trăinicia casei tale și a regatului tău vor fi veșnice...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ πιστωθήσεται ὁ οἶκος αὐτοῦ καὶ ἡ βασιλεία αὐτοῦ ἕως αἰῶνος ἐνώπιόν μου. καὶ ὁ θρόνος αὐτοῦ ἔσται ἀνωρθωμένος εἰς τὸν αἰῶνα.","greek":true,"translation":"„Și se va întări casa lui și împărăția lui până în veac înaintea Mea; și scaunul lui de domnie va fi ridicat în veac.”","note":"Divergență reală de persoană gramaticală: Textul Masoretic vorbește la persoana a II-a, direct către David („casa TA”, „înaintea TA”), pe când Septuaginta trece la persoana a III-a, despre urmașul lui David („casa LUI”, „înaintea Mea”) — o schimbare de destinatar imediat al promisiunii, de la David însuși spre fiul său."}],"refs":["Geneza 49:10","Psalmii 89:36,37","Isaia 9:7","Daniel 2:44","Apocalipsa 11:15","2 Samuel 7:13"]},{"v":"7:17","t":"Întocmai tuturor acestor cuvinte și întocmai cu toată această viziune i-a vorbit Natan lui David.","tokens":[{"t":"Întocmai tuturor acestor cuvinte și întocmai cu toată această "},{"t":"viziune","w":"viziune","heb":"הַחִזָּיוֹן","translit":"hahizaion","strong":"H2377","pos":"substantiv, masculin singular","def_ro":"viziunea, vedenia.","greek":"ὅρασις (horasis)","greek_def_ro":"ὅρασις (horasis) — vedenie, viziune.","dict_ro":"Hazon — Metzudat David subliniază semnificația finalului versetului: chiar dacă la v.3 Natan aprobase inițial proiectul lui David din propria lui judecată, fără nicio ezitare, el nu s-a rușinat să revină și să transmită corect mesajul corector primit de la DOMNUL — o notă discretă despre integritatea profetică, mai importantă decât consecvența aparentă a propriului cuvânt dintâi."},{"t":" i-a vorbit Natan lui David."}],"commentaries":[{"author":"Metzudat David","text":"„Ken diber Natan” — cu toate că la început a fost de acord din propria lui judecată, spunându-i «orice ai în inimă, mergi și înfăptuiește», nu s-a rușinat să revină și să-l mustre cu cuvântul DOMNULUI.”"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"כְּכֹל הַדְּבָרִים הָאֵלֶּה...","translation":"„Întocmai tuturor acestor cuvinte...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"κατὰ πάντας τοὺς λόγους τούτους καὶ κατὰ πᾶσαν τὴν ὅρασιν ταύτην, οὕτως ἐλάλησε Νάθαν πρὸς Δαυίδ.","greek":true,"translation":"„După toate cuvintele acestea și după toată vedenia aceasta, așa a vorbit Natan către David.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["1 Cronici 17:15","Faptele apostolilor 20:20,27","1 Corinteni 15:3"]}]},{"num":5,"title":"Tazria - Va zămisli","ref":"2 Împărați 4:42-5:19","intro":"Haftarat Tazria însoțește pericopa în care Tora descrie țaraat — boala de piele numită îndeobște lepră — și ritualul de declarare a leprosului curat sau necurat. Haftara aduce același subiect în mijlocul istoriei: Naaman, generalul victorios al Aramului, om mare, onorat și erou, este totuși lepros. Vindecarea lui nu vine prin daruri scumpe, scrisori regale sau un ritual spectaculos, ci prin ascultarea de un cuvânt simplu al profetului Elișa — cufundarea de șapte ori în Iordan —, la sfatul unei sclave captive și al propriilor slujitori. Naaman iese din apă cu trupul ca al unui copil mic și mărturisește că nu există Dumnezeu pe tot pământul decât în Israel. Haftara începe cu o minune mai mică, dar de același tipar: douăzeci de pâini de orz care, după cuvântul DOMNULUI, hrănesc o sută de oameni, ba mai și rămâne din ele.","verses":[{"v":"4:42","t":"Și a venit un om din Baal-Șalișa și a adus la omul lui Dumnezeu mâncare din primele roade: douăzeci de franzele de pâine de orz și spice proaspete de grâu cu pleava lor. [Elișa] i-a spus: „Dă-le poporului să le mănânce.”","tokens":[{"t":"Și a venit un om din Baal-Șalișa și a adus la omul lui Dumnezeu mâncare din "},{"t":"primele roade","w":"primele roade","heb":"בִּכּוּרִים","translit":"bikurim","strong":"H1061","pos":"substantiv, masculin și feminin plural","def_ro":"primele roade, pârga recoltei.","greek":"πρωτογέννημα (protogennema)","greek_def_ro":"πρωτογέννημα (protogennema) — primele roade.","dict_ro":"Bikurim — „cele dintâi coapte”, rădăcina bakhar („a se coace devreme, a fi întâi-născut”); de obicei termenul desemnează ofranda pârgii adusă la Templu (Exodul 23:16), dar aici e vorba de pâine din prima recoltă — Rashi notează că era în timpul lui Pesah, când se coace orzul. Talmudul (Sanhedrin 12a) deduce din acest verset că, deși Baal-Șalișa era locul unde roadele se coceau cel mai repede în toată Țara, doar orzul ajunsese la maturitate — deci anul ar fi trebuit prelungit cu o lună, iar Elișa nu l-a prelungit numai din cauza foametei."},{"t":": douăzeci de franzele de pâine de orz și spice proaspete de grâu cu pleava lor. [Elișa] i-a spus: „Dă-le poporului să le mănânce.”"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „din Baal-Șalișa” — numele unui ținut; Targum Ionatan însă traduce „din țara de spre miazăzi”, căci „baal” înseamnă câmpie. „Pâine din primele roade” — era în timpul lui Pesah, când se coace orzul. „Betziklono” — în învelișul lui. „Dă poporului” — ucenicilor [profeților], pe care îi întreținea."},{"author":"Metzudat David","text":"Pâine făcută din prima recoltă — douăzeci [de pâini], făcute din soiuri de orz; iar „karmel betziklono” sunt spice moi și pline, ca și cum ar fi fost încă în pleava lor."},{"author":"Talmud Bavli, Sanhedrin 12a","text":"Rabi [Iehuda HaNasi] spune: nu există în toată Țara Israelului loc în care roadele să se coacă mai repede decât în Baal-Șalișa, și totuși nu se copsese decât un singur soi din cele șapte, căci scrie „pâine din primele roade” — și ca nu cumva să spui că e vorba de grâu, scrie „de orz”; și ca nu cumva să spui că era înainte de aducerea omerului, scrie „dă poporului să mănânce”. Anul era deci potrivit pentru a fi prelungit — și de ce nu l-a prelungit Elișa? Pentru că era an de foamete și toți alergau la arie."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְאִישׁ בָּא מִבַּעַל שָׁלִשָׁה...","translation":"„Și a venit un om din...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἀνὴρ διῆλθεν ἐκ Βαιθσαρισὰ καὶ ἤνεγκε πρὸς τὸν ἄνθρωπον τοῦ Θεοῦ πρωτογεννημάτων εἴκοσιν ἄρτους κριθίνους καὶ παλάθας, καὶ εἶπε· δότε τῷ λαῷ καὶ ἐσθιέτωσαν.","greek":true,"translation":"„Și un om a trecut din Baitsarisa și a adus omului lui Dumnezeu, din pârgă, douăzeci de pâini de orz și turte de smochine, și a zis: dați poporului și să mănânce.”","note":"Septuaginta redă numele locului ca „Baitsarisa” și înlocuiește „spice proaspete de grâu cu pleava lor” (karmel betziklono) prin „turte de smochine” (παλάθας) — o divergență reală de conținut; în plus, porunca e pusă la plural („dați”), nu la singular."}],"refs":["1 Samuel 9:4,7","2 Împărați 4:38","Exod 23:16","Deuteronom 26:2-10","Proverbe 3:9,10","Ioan 6:9,13"]},{"v":"4:43","t":"Slujitorul lui a spus: „Cum pot să pun aceasta înaintea a o sută de oameni?” Așa că el a spus: „Dă poporului să le mănânce, căci așa a spus DOMNUL: «Vor mânca și va mai rămâne.»”","tokens":[{"t":"Slujitorul lui a spus: „Cum pot să pun aceasta înaintea a o sută de oameni?” Așa că el a spus: „Dă poporului să le mănânce, căci așa a spus DOMNUL: «Vor mânca și "},{"t":"va mai rămâne","w":"va mai rămâne","heb":"וְהוֹתֵר","translit":"vehotēr","strong":"H3498","pos":"verb, hifil infinitiv absolut","def_ro":"a lăsa să rămână, a prisosi.","greek":"καταλείπω (kataleipo)","greek_def_ro":"καταλείπω (kataleipo) — va rămâne, va mai fi.","dict_ro":"Iatar — „a rămâne, a prisosi”; infinitivul absolut dublat („achol vehoter”, „a mânca și a lăsa rest”) are forța unei promisiuni categorice: nu doar că va ajunge, ci va și prisosi. Metzudat David subliniază contrastul: slujitorul vede „foarte puțin”, dar cuvântul DOMNULUI garantează îndestulare pentru toți, cu rest — tiparul pe care tradiția creștină îl recunoaște în înmulțirea pâinilor din Evanghelii (Matei 14:20)."},{"t":".»”"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Cum să pun aceasta” — adică fiecare pâine [înaintea atâtor oameni]."},{"author":"Metzudat David","text":"„Cum să pun aceasta înaintea a o sută de oameni” — ca și cum ar spune: e foarte puțină [mâncare] aici. „Vor mânca și va mai rămâne” — va fi destulă hrană pentru toți și va mai și rămâne."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיֹּאמֶר מְשָׁרְתוֹ מָה אֶתֵּן...","translation":"„Slujitorul lui a spus: „Cum pot...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ εἶπεν ὁ λειτουργὸς αὐτοῦ· τί δῶ τοῦτο ἐνώπιον ἑκατὸν ἀνδρῶν; καὶ εἶπε· δὸς τῷ λαῷ καὶ ἐσθιέτωσαν, ὅτι τάδε λέγει Κύριος· φάγονται καὶ καταλείψουσι.","greek":true,"translation":"„Și a zis slujitorul lui: cum să dau aceasta înaintea a o sută de oameni? Și a zis: dă poporului și să mănânce, căci așa zice Domnul: vor mânca și vor lăsa rest.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Matei 14:16,17","Marcu 6:37-39","Ioan 6:9","Matei 14:20","Ioan 6:11-13"]},{"v":"4:44","t":"El le-a pus înaintea lor și ei au mâncat și a mai și rămas, precum spusese DOMNUL.","tokens":[{"t":"El le-a pus înaintea lor și ei au mâncat și a mai și rămas, "},{"t":"precum spusese DOMNUL","w":"precum spusese DOMNUL","heb":"כִּדְבַר","translit":"kidvar","strong":"H1697","pos":"substantiv, masculin singular construct","def_ro":"după cuvântul DOMNULUI.","greek":"ῥῆμα Κυρίου (rhema Kyriou)","greek_def_ro":"ῥῆμα Κυρίου (rhema Kyriou) — cuvântul DOMNULUI.","dict_ro":"Kidvar ADONAI — formula de împlinire care încheie episodul: nu puterea lui Elișa e în centru, ci cuvântul DOMNULUI rostit dinainte (v. 43) și împlinit întocmai. Aceeași construcție încheie și vindecarea lui Naaman, care urmează imediat în haftara („după cuvântul omului lui Dumnezeu”, 5:14), legând cele două minuni printr-un singur principiu: ascultarea de cuvânt aduce împlinirea."},{"t":"."}],"commentaries":[],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיִּתֵּן לִפְנֵיהֶם וַיֹּאכְלוּ וַיּוֹתִרוּ...","translation":"„El le-a pus înaintea lor și...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἔφαγον καὶ κατέλιπον κατὰ τὸ ρῆμα Κυρίου.","greek":true,"translation":"„Și au mâncat și au lăsat rest, după cuvântul Domnului.”","note":"Septuaginta omite fraza de deschidere „el le-a pus înaintea lor” (vayiten lifneihem) din Textul Masoretic."}],"refs":[]},{"v":"5:1","t":"Naaman, un general în oștirea regelui Aramului, era om de seamă înaintea stăpânului său, și foarte respectat, căci prin el dăduse DOMNUL biruință Aramului. El era mare luptător, [dar] era lepros.","tokens":[{"t":"Naaman, un general în oștirea regelui Aramului, era om de seamă înaintea stăpânului său, și foarte respectat, căci prin el dăduse DOMNUL biruință Aramului. El era mare luptător, [dar] era "},{"t":"lepros","w":"lepros","heb":"מְצֹרָע","translit":"mețora","strong":"H6879","pos":"verb, pual participiu pasiv","def_ro":"lovit de țaraat, lepros.","greek":"λεπρόομαι (leproomai)","greek_def_ro":"λεπρόομαι (leproomai) — lepros.","dict_ro":"Metzora — cel lovit de țaraat, boala de piele descrisă pe larg în pericopa Tazria (Levitic 13), de unde și alegerea acestei haftare. Versetul adună toate titlurile de glorie ale lui Naaman — general, om mare, onorat, erou — și le răstoarnă cu un singur cuvânt final: „lepros”. Metzudat David explică durerea din spatele cuvântului: fiind un mare luptător, Naaman dorea să iasă mereu la război, dar boala îl împiedica, și suferea din această pricină."},{"t":"."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Naaman, generalul” — [Scriptura] continuă să înșire minunile care s-au făcut prin Elișa. „Biruință Aramului” — el a tras cu arcul fără țintă și l-a ucis pe Ahab."},{"author":"Metzudat David","text":"„Om de seamă” — adică prețuit înaintea lui. „Foarte respectat” — toți îl cinsteau, pentru că prin el venise biruința Aramului; iar înțelepții noștri au spus (Yalkut Șimoni) că el a tras cu arcul fără să țintească și l-a ucis pe Ahab. „Mare luptător, lepros” — ca și cum ar spune: fiind mare luptător, dorea să coboare mereu la război, dar din cauza leprei era împiedicat, și suferea din această pricină."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְנַעֲמָן שַׂר־צְבָא מֶלֶךְ־אֲרָם הָיָה...","translation":"„Naaman, un general în oștirea regelui...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"Καὶ Ναιμὰν ὁ ἄρχων τῆς δυνάμεως Συρίας ἦν ἀνὴρ μέγας ἐνώπιον τοῦ κυρίου αὐτοῦ καὶ τεθαυμασμένος προσώπῳ, ὅτι ἐν αὐτῷ ἔδωκε Κύριος σωτηρίαν Συρίᾳ· καὶ ὁ ἀνὴρ ἦν δυνατὸς ἰσχύϊ, λελεπρωμένος.","greek":true,"translation":"„Și Naiman, căpetenia oștirii Siriei, era om mare înaintea stăpânului său și admirat la față, căci prin el dăduse Domnul mântuire Siriei; și omul era puternic în tărie, [dar] lepros.”","note":"Septuaginta redă „Aram” prin „Siria” (Συρία) și numele eroului ca „Naiman”; „biruință” (teșua) devine „mântuire” (σωτηρία) — același cuvânt grec folosit ulterior în Noul Testament."}],"refs":["Luca 4:27","Exod 11:3","Proverbe 21:31","Isaia 10:5,6","Levitic 13:2,3,44-46"]},{"v":"5:2","t":"Aram ieșise la luptă în cete și luaseră prizonieră o tânără fată din țara Israelului și ea îi slujea soției lui Naaman.","tokens":[{"t":"Aram ieșise la luptă în cete și luaseră prizonieră "},{"t":"o tânără fată","w":"o tânără fată","heb":"נַעֲרָה","translit":"naara","strong":"H5291","pos":"substantiv, feminin singular","def_ro":"o fată tânără, o fetiță.","greek":"νεανίς μικρά (neanis mikra)","greek_def_ro":"νεανίς μικρά (neanis mikra) — o tânără fetiță.","dict_ro":"Naara ketana — expresia pare redundantă (naara desemnează deja o fată tânără), de aceea Rashi propune că naara indică proveniența ei din orașul Naaran (1 Cronici 7:28), iar Metzudat David răspunde că și o copilă mică poate fi numită naara (ca în Isaia 11:6, „un copil mic îi va mâna”). Contrastul e intenționat: cea mai mică și mai lipsită de putere persoană din poveste, o sclavă captivă, devine veriga prin care generalul atotputernic ajunge la vindecare."},{"t":" din țara Israelului și ea îi slujea soției lui Naaman."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Au ieșit cete” — când oamenii merg de capul lor, câte o sută sau două sute, ca să jefuiască tot ce găsesc, aceasta se numește gedud. „O tânără fată” — o fată din orașul Naaran. „Și ea îi slujea” — [Targum Ionatan traduce:] „și slujea înaintea soției lui Naaman”."},{"author":"Metzudat David","text":"„Au ieșit cete” — când merg de la sine câțiva oameni ca să prade ce găsesc, se numește gedud. „O tânără fată” — și una mică se numește naara, ca în „și un copil mic îi va mâna” (Isaia 11:6). „Și ea îi slujea” — slujea înaintea soției lui Naaman."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַאֲרָם יָצְאוּ גְדוּדִים וַיִּשְׁבּוּ...","translation":"„Aram ieșise la luptă în cete...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ Συρία ἐξῆλθον μονόζωνοι καὶ ᾐχμαλώτευσαν ἐκ γῆς ᾿Ισραὴλ νεάνιδα μικράν, καὶ ἦν ἐνώπιον τῆς γυναικὸς Ναιμάν.","greek":true,"translation":"„Și Siria ieșiseră [oameni] cu arme ușoare și luaseră robă din țara lui Israel o fată mică, și ea era înaintea soției lui Naiman.”","note":"Septuaginta redă „cete” (gedudim) prin „oameni încinși ușor / cu armură ușoară” (μονόζωνοι) — o interpretare militară precisă a cuvântului ebraic, nu o traducere literală."}],"refs":["2 Împărați 6:23","2 Împărați 13:20","Judecători 9:34","1 Samuel 13:17,18","Psalmii 123:2"]},{"v":"5:3","t":"Ea i-a spus stăpânei ei: „Rugămințile stăpânului meu să fie aduse în fața profetului care este în Samaria, și atunci el îl va vindeca de lepră.”","tokens":[{"t":"Ea i-a spus stăpânei ei: „Rugămințile stăpânului meu să fie aduse în fața profetului care este în Samaria, și atunci el "},{"t":"îl va vindeca","w":"îl va vindeca","heb":"יֶאֱסֹף","translit":"ieesof","strong":"H622","pos":"verb, qal imperfect","def_ro":"îl va aduna, adică îl va vindeca de lepră.","greek":"ἀποσυνάγω (aposynago)","greek_def_ro":"ἀποσυνάγω (aposynago) — a-l elibera, a-l curăți (idiom: a-l aduna de la boala lui).","dict_ro":"Asaf — literal „a aduna, a strânge înăuntru”; aplicat leprosului, înseamnă vindecarea, pentru că, explică Rashi, în timpul bolii toți se țin departe de el, iar când se vindecă e din nou „adunat” printre oameni. Metzudat David adaugă temeiul biblic: leprosul locuia în afara taberei și, vindecat, era primit înapoi — ca Miriam, la care scrie „până ce a fost adunată [primită înapoi] Miriam” (Numeri 12:15)."},{"t":" de lepră.”"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Ahaléi” — o expresie de rugăminte, ca „și Moise L-a rugat” (Exod 32:11): rugămințile tuturor celor ce se roagă pentru el să fie ca minunea să vină înaintea profetului. „Îl va vindeca” — „adunarea” spusă despre lepros înseamnă vindecarea lui, căci când se vindecă e adunat din nou printre oameni, iar în timpul bolii toți se țin departe de el."},{"author":"Metzudat David","text":"„Ahaléi adoni” — dacă rugămintea stăpânului meu ar ajunge înaintea profetului, atunci fără îndoială l-ar vindeca de lepra lui; iar vindecarea leprosului se numește „adunare”, pentru că, atâta timp cât e bolnav, locuiește în afara taberei, iar când se vindecă e adunat și intră în tabără, precum s-a spus: „până ce a fost adunată Miriam” (Numeri 12:15)."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַתֹּאמֶר אֶל־גְּבִרְתָּהּ אַחֲלֵי אֲדֹנִי...","translation":"„Ea i-a spus stăpânei ei: „Rugămințile...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ἡ δὲ εἶπε τῇ κυρίᾳ αὐτῆς· ὄφελον ὁ κύριός μου ἐνώπιον τοῦ προφήτου τοῦ Θεοῦ τοῦ ἐν Σαμαρείᾳ, τότε ἀποσυνάξει αὐτὸν ἀπὸ τῆς λέπρας αὐτοῦ.","greek":true,"translation":"„Iar ea a zis stăpânei ei: o, de-ar fi stăpânul meu înaintea profetului lui Dumnezeu din Samaria! Atunci l-ar aduna [vindeca] de lepra lui.”","note":"Septuaginta adaugă „al lui Dumnezeu” după „profetul” și păstrează literal metafora ebraică a „adunării” (ἀποσυνάξει) pentru vindecare."}],"refs":["Numeri 11:29","Faptele apostolilor 26:29","2 Împărați 5:8","Matei 8:2,3","Luca 17:12-14"]},{"v":"5:4","t":"[Naaman] a mers și i-a povestit stăpânului său, spunând: „Precum aceste [cuvinte] a vorbit fata din țara Israelului.”","tokens":[{"t":"[Naaman] a mers și i-a povestit stăpânului său, spunând: „"},{"t":"Precum aceste","w":"Precum aceste","heb":"כָּזֹאת וְכָזֹאת","translit":"kazot vehazot","strong":"H2063","pos":"pronume demonstrativ + pronume demonstrativ","def_ro":"așa și așa, în cutare fel.","greek":"οὕτως καὶ οὕτως (houtos kai houtos)","greek_def_ro":"οὕτως καὶ οὕτως (houtos kai houtos) — așa și așa.","dict_ro":"Kazot vechazot — „așa și așa”, formulă de rezumare prin care naratorul evită să repete cuvintele fetei deja citate. Rashi și Metzudat David precizează cine vorbește cu cine: Naaman însuși a venit și i-a povestit stăpânului său, regele Aramului. Faptul că un general de rang înalt ia în serios cuvântul unei sclave captive și îl duce până la rege arată cât de disperată era situația lui."},{"t":" [cuvinte] a vorbit fata din țara Israelului.”"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „A mers” — Naaman. „Și i-a povestit stăpânului său” — regelui Aramului."},{"author":"Metzudat David","text":"„A mers și i-a povestit” — Naaman a povestit lucrul acesta înaintea regelui."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיָּבֹא וַיַּגֵּד לַאדֹנָיו לֵאמֹר...","translation":"„[Naaman] a mers și i-a povestit...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ εἰσῆλθε καὶ ἀπήγγειλε τῷ κυρίῳ ἑαυτῆς καὶ εἶπεν· οὕτως καὶ οὕτως ἐλάλησεν ἡ νεᾶνις ἡ ἐκ γῆς ᾿Ισραήλ.","greek":true,"translation":"„Și a intrat și a vestit stăpânului ei și a zis: așa și așa a vorbit fata din țara lui Israel.”","note":"Divergență reală: în Septuaginta pronumele e feminin („stăpânului ei”, τῷ κυρίῳ ἑαυτῆς), sugerând că soția lui Naaman i-a vestit soțului ei; în Textul Masoretic Naaman însuși merge și îi povestește regelui, stăpânului său."}],"refs":["2 Împărați 7:9-11","Ioan 4:28,29"]},{"v":"5:5","t":"Regele Aramului i-a spus: „Mergi la el și eu voi trimite o scrisoare regelui Israelului.” El a mers și a luat cu sine zece talanți de argint, șase mii de monede de aur și zece schimburi de haine.","tokens":[{"t":"Regele Aramului i-a spus: „Mergi la el și eu voi trimite o scrisoare regelui Israelului.” El a mers și a luat cu sine zece talanți de argint, șase mii de monede de aur și "},{"t":"zece schimburi de haine","w":"zece schimburi de haine","heb":"חֲלִיפוֹת","translit":"halifot","strong":"H2487","pos":"substantiv, feminin plural construct","def_ro":"zece rânduri de haine de schimb.","greek":"ἀλλασσόμεναι στολαί (allassomenai stolai)","greek_def_ro":"ἀλλασσόμεναι στολαί (allassomenai stolai) — veșminte de schimb.","dict_ro":"Halifot begadim — „schimburi de haine”, veșminte de sărbătoare, un dar prețios în lumea antică (vezi Geneza 45:22, darurile lui Iosif pentru frații săi). Împreună cu cei zece talanți de argint și cele șase mii [de sicli] de aur, darul arată cum își imagina Naaman vindecarea: ca pe un serviciu cumpărat de la un vraci de curte. Rashi și Metzudat David precizează că darul era destinat profetului, nu regelui — iar refuzul lui Elișa (v. 16) va răsturna tocmai această logică."},{"t":"."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Și a luat în mâna lui” — un dar pentru profet. „Șase mii de aur” — monede de aur."},{"author":"Metzudat David","text":"„Mergi” — la profet. „Regelui Israelului” — ca el să-i poruncească profetului să facă aceasta. „Și a luat în mâna lui” — un dar pentru profet."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיֹּאמֶר מֶלֶךְ־אֲרָם לֶךְ־בֹּא וְאֶשְׁלְחָה...","translation":"„Regele Aramului i-a spus: „Mergi la...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ εἶπε βασιλεὺς Συρίας πρὸς Ναιμάν· δεῦρο εἴσελθε, καὶ ἐξαποστελῶ βιβλίον πρὸς βασιλέα ᾿Ισραήλ· καὶ ἐπορεύθη καὶ ἔλαβεν ἐν τῇ χειρὶ αὐτοῦ δέκα τάλαντα ἀργυρίου καὶ ἑξακισχιλίους χρυσοῦς καὶ δέκα ἀλλασσομένας στολάς.","greek":true,"translation":"„Și a zis regele Siriei către Naiman: vino, intră, și voi trimite o carte regelui lui Israel. Și a mers și a luat în mâna lui zece talanți de argint și șase mii de [monede de] aur și zece veșminte de schimb.”","note":"Septuaginta numește explicit destinatarul poruncii („către Naiman”), implicit în Textul Masoretic; în rest, corespondență strânsă."}],"refs":["2 Împărați 8:8,9","Numeri 22:7,17,18","1 Samuel 9:8","Faptele apostolilor 8:18-20","Geneza 45:22","Judecători 14:12"]},{"v":"5:6","t":"Și i-a adus regelui Israelului o scrisoare care spunea: „Și acum, când această scrisoare va ajunge la tine, iată, l-am trimis la tine pe slujitorul meu Naaman, ca să-l vindeci de lepra lui.”","tokens":[{"t":"Și i-a adus regelui Israelului o "},{"t":"scrisoare","w":"scrisoare","heb":"הַסֵּפֶר","translit":"hasēfer","strong":"H5612","pos":"substantiv, masculin singular","def_ro":"scrisoarea, înscrisul.","greek":"βιβλίον (biblion)","greek_def_ro":"βιβλίον (biblion) — scrisoare, carte.","dict_ro":"Sefer — orice document scris: carte, sul, scrisoare oficială. Metzudat David observă că Scriptura redă doar finalul scrisorii („și acum...”), pentru că începutul cuprindea salutările obișnuite; iar regele Aramului nu se aștepta ca regele Israelului să-l vindece el însuși, ci ca acesta să-i poruncească profetului. Formularea ambiguă — „ca să-l vindeci” — e tocmai ceea ce va provoca panica regelui din versetul următor."},{"t":" care spunea: „Și acum, când această scrisoare va ajunge la tine, iată, l-am trimis la tine pe slujitorul meu Naaman, ca să-l vindeci de lepra lui.”"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Spunând: «Și acum, când va ajunge scrisoarea»” — scrisoarea îi spunea: „Și acum, când va ajunge...”. „Ca să-l vindeci de lepră” — „adunarea” spusă despre lepros înseamnă vindecarea lui, căci când se vindecă e adunat din nou printre oameni, iar în timpul bolii toți se țin departe de el."},{"author":"Metzudat David","text":"„Și acum” — Scriptura nu explică ce scria la începutul cuvintelor lui, pentru că era după obicei, ca să-l salute; iar sfârșitul cuvintelor lui era: „și acum...”. „Ca să-l vindeci” — regele Aramului nu gândea că regele Israelului îl va vindeca de lepra lui, ci cuvintele lui însemnau că acesta îi va porunci profetului să-l vindece."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיָּבֵא הַסֵּפֶר אֶל־מֶלֶךְ יִשְׂרָאֵל...","translation":"„Și i-a adus regelui Israelului o...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἤνεγκε τὸ βιβλίον πρὸς τὸν βασιλέα ᾿Ισραὴλ λέγων· καὶ νῦν ὡς ἂν ἔλθῃ τὸ βιβλίον τοῦτο πρὸς σέ, ἰδοὺ ἀπέστειλα πρός σε Ναιμὰν τὸν δοῦλόν μου, καὶ ἀποσυνάξεις αὐτὸν ἀπὸ τῆς λέπρας αὐτοῦ.","greek":true,"translation":"„Și a adus cartea regelui lui Israel, zicând: și acum, când va ajunge cartea aceasta la tine, iată, l-am trimis la tine pe Naiman, robul meu, și îl vei aduna [vindeca] de lepra lui.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":[]},{"v":"5:7","t":"Când regele Israelului a citit scrisoarea, și-a sfâșiat veșmintele și a spus: „Sunt eu oare Dumnezeu ca să pot ucide și să pot da viață, că omul acesta trimite la mine pe cineva să-l vindec de lepră? Să știi și să vezi că el caută pricină împotriva mea!”","tokens":[{"t":"Când regele Israelului a citit scrisoarea, și-a sfâșiat veșmintele și a spus: „Sunt eu oare Dumnezeu ca să pot ucide și să pot da viață, că omul acesta trimite la mine pe cineva să-l vindec de lepră? Să știi și să vezi că el "},{"t":"caută pricină","w":"caută pricină","heb":"מִתְאַנֶּה","translit":"mitane","strong":"H579","pos":"verb, hitpael participiu","def_ro":"caută prilej, caută pretext de ceartă.","greek":"προφασίζομαι (prophasizomai)","greek_def_ro":"προφασίζομαι (prophasizomai) — a căuta pricină, a invoca un pretext.","dict_ro":"Ana, la forma hitpael — „a căuta prilej, a pândi o ocazie” împotriva cuiva; Rashi îl leagă de „alilot devarim” (învinuiri mincinoase, Deuteronomul 22:14): regele crede că Aramul caută un pretext de război. Metzudat David vede aici și un diagnostic spiritual: din pricina răutății lui, regele Israelului nici nu s-a gândit la profetul din țara lui, ci a crezut că i se cere lui însuși o minune pe care numai Cel ce „omoară și dă viață” o poate face."},{"t":" împotriva mea!”"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Sunt eu oare Dumnezeu?” — litera he [de la început] e vocalizată cu patah, ca să arate că e o întrebare. „Caută pricină” — caută un pretext ca să mă atace; e o expresie de „învinuiri mincinoase” (Deuteronom 22:14)."},{"author":"Metzudat David","text":"„Și-a sfâșiat veșmintele” — de spaimă. „Sunt eu oare Dumnezeu” — oare sunt eu Dumnezeu, să fie în puterea mea să omor și să dau viață? Căci nimeni nu poate vindeca leprosul decât Cel în a cărui mână e să omoare și să dea viață; iar din pricina marii lui răutăți n-a crezut în profet și a crezut că [regele Aramului] îl trimisese ca să-l vindece el însuși. „Să știi și să vezi” — ca și cum ar spune: nu-i e ascuns că nu pot aceasta, ci intenția lui e să găsească pretext ca să se lupte cu mine."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיְהִי כִּקְרֹא מֶלֶךְ־יִשְׂרָאֵל אֶת־הַסֵּפֶר...","translation":"„Când regele Israelului a citit scrisoarea...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐγένετο ὡς ἀνέγνω βασιλεὺς ᾿Ισραὴλ τὸ βιβλίον, διέρρηξε τὰ ἱμάτια αὐτοῦ καὶ εἶπεν· ὁ Θεὸς ἐγὼ τοῦ θανατῶσαι καὶ ζωοποιῆσαι, ὅτι οὖτος ἀποστέλλει πρός με ἀποσυνάξαι ἄνδρα ἀπὸ τῆς λέπρας αὐτοῦ; ὅτι πλὴν γνῶτε δὴ καὶ ἴδετε ὅτι προφασίζεται οὗτός μοι.","greek":true,"translation":"„Și a fost că, după ce a citit regele lui Israel cartea, și-a rupt hainele și a zis: sunt eu Dumnezeu, ca să omor și să dau viață, că acesta trimite la mine să adun [vindec] un om de lepra lui? Numai să știți și să vedeți că acesta își caută pretext împotriva mea.”","note":"Corespondență strânsă; „caută pricină” e redat prin προφασίζεται („își face un pretext”)."}],"refs":["2 Împărați 19:1","Matei 26:65","Geneza 30:2","1 Samuel 2:6","Osea 6:1","1 Împărați 20:7"]},{"v":"5:8","t":"Când Elișa, omul lui Dumnezeu, a auzit că regele Israelului și-a sfâșiat veșmintele, a trimis [veste] la rege, spunând: „De ce ți-ai sfâșiat veșmintele? Dă-i voie să vină la mine și va ști că există un profet în Israel.”","tokens":[{"t":"Când Elișa, omul lui Dumnezeu, a auzit că regele Israelului și-a sfâșiat veșmintele, a trimis [veste] la rege, spunând: „De ce ți-ai sfâșiat veșmintele? Dă-i voie să vină la mine și va ști că există "},{"t":"un profet","w":"un profet","heb":"נָבִיא","translit":"navi","strong":"H5030","pos":"substantiv, masculin singular","def_ro":"profet, purtător al cuvântului divin.","greek":"προφήτης (prophetes)","greek_def_ro":"προφήτης (prophetes) — profet.","dict_ro":"Navi — cel chemat să vestească cuvântul lui Dumnezeu. Răspunsul lui Elișa corectează ironic panica regelui: nu regele trebuie să facă minunea, ci Naaman trebuie să afle că „există un profet în Israel”. Metzudat David precizează motivul: nu pentru gloria regelui îl va vindeca, ci „pentru sfințirea Numelui” — ca un străin să cunoască puterea Dumnezeului lui Israel, ceea ce se și împlinește în mărturisirea lui Naaman din v. 15."},{"t":" în Israel.”"}],"commentaries":[{"author":"Metzudat David","text":"„Și va ști” — nu de dragul tău îl voi vindeca, ci pentru sfințirea Numelui [lui Dumnezeu]."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיְהִי כִּשְׁמֹעַ אֱלִישָׁע אִישׁ־הָאֱלֹהִים...","translation":"„Când Elișa, omul lui Dumnezeu, a...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐγένετο ὡς ἤκουσεν ῾Ελισαιὲ ὅτι διέρρηξεν ὁ βασιλεὺς ᾿Ισραὴλ τὰ ἱμάτια αὐτοῦ, καὶ ἀπέστειλε πρὸς τὸν βασιλέα ᾿Ισραὴλ λέγων· ἱνατὶ διέρρηξας τὰ ἱμάτιά σου; ἐλθέτω δὴ πρός με Ναιμὰν καὶ γνώτω ὅτι ἐστὶ προφήτης ἐν ᾿Ισραήλ.","greek":true,"translation":"„Și a fost că, după ce a auzit Elisaie că regele lui Israel și-a rupt hainele, a trimis la regele lui Israel zicând: de ce ți-ai rupt hainele? Să vină Naiman la mine și să știe că este profet în Israel.”","note":"Septuaginta omite titlul „omul lui Dumnezeu” după numele lui Elișa și numește explicit pe Naiman ca subiect al lui „să vină”, implicit în Textul Masoretic."}],"refs":["2 Împărați 5:3,15","2 Împărați 1:6","1 Împărați 17:24","1 Împărați 18:36,37","Ezechiel 2:5","Osea 12:13"]},{"v":"5:9","t":"Naaman a venit cu caii lui și carul lui și a stat la ușa casei lui Elișa.","tokens":[{"t":"Naaman a venit cu caii lui și carul lui și a stat "},{"t":"la ușa casei","w":"la ușa casei","heb":"פֶּתַח","translit":"petah","strong":"H6607","pos":"substantiv, masculin singular construct","def_ro":"la intrarea casei.","greek":"θύρα οἴκου (thyra oikou)","greek_def_ro":"θύρα οἴκου (thyra oikou) — ușa casei.","dict_ro":"Petah — deschizătura, intrarea. Imaginea e voit teatrală: generalul străin vine cu toată pompa — cai și car de luptă — și se oprește la ușa unei case modeste de profet, așteptând să fie întâmpinat cu onoruri. Versetul pregătește astfel contrastul din versetul următor, în care Elișa nici nu iese la el, ci îi trimite doar un sol."},{"t":" lui Elișa."}],"commentaries":[{"author":"Radak (1160–1235)","text":"Radak: „Cu caii lui” — așa e scris, besuso, „cu calul lui”, iar citirea e besusav, la plural: scrisul spune despre el însuși, că el călărea pe calul lui, iar citirea se referă la cei care veneau cu el."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיָּבֹא נַעֲמָן בְּסוּסוֹ וּבְרִכְבּוֹ...","translation":"„Naaman a venit cu caii lui...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἦλθε Ναιμὰν ἐν ἵππῳ καὶ ἅρματι καὶ ἔστη ἐπὶ θύρας οἴκου ῾Ελισαιέ.","greek":true,"translation":"„Și a venit Naiman cu cal și car și a stat la ușa casei lui Elisaie.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["2 Împărați 3:12","2 Împărați 6:32","Isaia 60:14","Faptele apostolilor 16:29,30,37-39"]},{"v":"5:10","t":"Elișa a trimis la el un sol, spunând: „Mergi și cufundă-te de șapte ori în Iordan și carnea ta își va reveni și vei fi curățit.”","tokens":[{"t":"Elișa a trimis la el un sol, spunând: „Mergi și cufundă-te "},{"t":"de șapte ori","w":"de șapte ori","heb":"שֶׁבַע","translit":"șeva","strong":"H7651","pos":"numeral","def_ro":"de șapte ori.","greek":"ἑπτάκις (heptakis)","greek_def_ro":"ἑπτάκις (heptakis) — de șapte ori.","dict_ro":"Șeva peamim — numărul șapte străbate ritualul de curățire a leprosului din Tora: stropirea de șapte ori cu sângele păsării (Leviticul 14:7) și cu untdelemn (Leviticul 14:16), la fel ca stropirea cu apa de curățire (Numeri 19:4). Metzudat David explică și făgăduința „carnea ta își va reveni”: prin lepră carnea slăbise și se topise, iar acum nu doar că va fi curățit, ci îi va reveni și carnea sănătoasă."},{"t":" în Iordan și carnea ta își va reveni și vei fi curățit.”"}],"commentaries":[{"author":"Metzudat David","text":"„Și carnea ta își va reveni” — căci din cauza leprei carnea slăbise din grăsimea ei, iar de acum carnea ți se va întoarce și vei fi și curat de lepră."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיִּשְׁלַח אֵלָיו אֱלִישָׁע מַלְאָךְ...","translation":"„Elișa a trimis la el un...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἀπέστειλεν ῾Ελισαιὲ ἄγγελον πρὸς αὐτὸν λέγων· πορευθεὶς λοῦσαι ἑπτάκις ἐν τῷ ᾿Ιορδάνῃ, καὶ ἐπιστρέψει ἡ σάρξ σού σοι, καὶ καθαρισθήσῃ.","greek":true,"translation":"„Și a trimis Elisaie un sol la el zicând: mergând, spală-te de șapte ori în Iordan, și carnea ta se va întoarce la tine, și vei fi curățit.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Matei 15:23-26","2 Împărați 2:21","Ioan 9:7","Levitic 14:7,16,51","Numeri 19:4,19","Exod 4:6,7"]},{"v":"5:11","t":"Naaman s-a mâniat și a plecat; și a spus: „Iată, mi-am spus că va ieși negreșit în întâmpinarea mea și că va sta în picioare și va chema în numele DOMNULUI, Dumnezeului lui, și își va ridica mâinile către [Cel] Omniprezent și leprosul se va vindeca.","tokens":[{"t":"Naaman s-a mâniat și a plecat; și a spus: „Iată, mi-am spus că va ieși negreșit în întâmpinarea mea și că va sta în picioare și va chema în numele DOMNULUI, Dumnezeului lui, și își va ridica mâinile către "},{"t":"[Cel] Omniprezent","w":"[Cel] Omniprezent","heb":"הַמָּקוֹם","translit":"hamakom","strong":"H4725","pos":"substantiv, masculin singular","def_ro":"locul; în tradiția rabinică, și nume al lui Dumnezeu („Cel Omniprezent”).","diff_ro":"Septuaginta are aici sensul literal, „ἐπὶ τὸν τόπον\" („asupra locului\"), nu ca epitet divin („Cel Omniprezent\", traducerea tradițională a eufemismului ebraic „HaMakom\" pentru Dumnezeu) — o diferență de interpretare teologică, nu doar lingvistică.","dict_ro":"Makom — literal „loc”; în literatura rabinică „HaMakom” devine un nume al lui Dumnezeu (Cel Omniprezent, „locul lumii”), sens pe care îl reflectă traducerea de aici. Rashi însă citește simplu: Naaman se aștepta ca profetul să-și fluture mâna „spre locul” bolii, iar Metzudat David completează — ca să reverse vindecarea acolo prin minune. Versetul dezvăluie așteptarea lui Naaman: un ritual spectaculos, cu onoruri și gesturi, nu o simplă poruncă."},{"t":" și leprosul se va vindeca."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Iată, mi-am spus” — mă gândeam că profetul va ieși și va vorbi cu mine și va vedea boala. „Și își va ridica mâna către locul” — [locul] leprei."},{"author":"Metzudat David","text":"„Va ieși la mine” — mă gândeam că va ieși la mine pentru cinstea mea și va sta în picioare înaintea mea, după obiceiul de cinste pe care oamenii îl arată marilor dregători. Iar în privința vindecării, mă gândeam că va chema numele DOMNULUI și își va flutura mâna spre locul leprei, ca să reverse acolo vindecarea prin minune, și în felul acesta leprosul va fi vindecat."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיִּקְצֹף נַעֲמָן וַיֵּלַךְ וַיֹּאמֶר...","translation":"„Naaman s-a mâniat și a plecat...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐθυμώθη Ναιμὰν καὶ ἀπῆλθε καὶ εἶπεν· ἰδοὺ εἶπον ὅτι πρός με πάντως ἐξελεύσεται καὶ στήσεται καὶ ἐπικαλέσεται ἐν ὀνόματι Θεοῦ αὐτοῦ καὶ ἐπιθήσει τὴν χεῖρα αὐτοῦ ἐπὶ τὸν τόπον καὶ ἀποσυνάξει τὸ λεπρόν·","greek":true,"translation":"„Și s-a mâniat Naiman și a plecat și a zis: iată, am zis că negreșit va ieși la mine și va sta și va chema numele Dumnezeului său și își va pune mâna pe loc și va aduna [vindeca] lepra.”","note":"Septuaginta omite numele divin („în numele DOMNULUI, Dumnezeului lui” devine doar „în numele Dumnezeului său”), transformă gestul „va flutura mâna” în „își va pune mâna” și înțelege „makom” strict ca loc fizic (τὸν τόπον) — sprijinind lectura lui Rashi."}],"refs":["Proverbe 13:10","Matei 8:8","Proverbe 3:7","Isaia 55:8,9","1 Corinteni 1:21-25"]},{"v":"5:12","t":"Nu sunt oare Amana și Farpar, râurile Damascului, mai bune decât toate apele din Israel? Mă voi scălda în ele și voi fi curățit.” Și s-a întors și a plecat mânios.","tokens":[{"t":"Nu sunt oare "},{"t":"Amana","w":"Amana","heb":"אֲמָנָה","translit":"amana","strong":"H71","pos":"nume propriu","def_ro":"Amana (citit Avana), râu al Damascului.","greek":"Ἀβανά (Abana)","greek_def_ro":"Ἀβανά (Abana) — Amana (râu/munte lângă Damasc).","dict_ro":"Amana / Avana — textul scris (ketiv) are Amana, iar citirea tradițională (keri) e Avana; e râul identificat de obicei cu Barada de azi, care traversează Damascul, iar Farpar cu un râu vecin din aceeași regiune, ambele cu ape limpezi, spre deosebire de Iordanul tulbure. Metzudat David redă logica lui Naaman: dacă spălarea ar fi un leac natural, râurile Damascului, în care se spăla mereu, l-ar fi vindecat deja — de ce ar ajuta Iordanul?"},{"t":" și Farpar, râurile Damascului, mai bune decât toate apele din Israel? Mă voi scălda în ele și voi fi curățit.” Și s-a întors și a plecat mânios."}],"commentaries":[{"author":"Metzudat David","text":"„Nu sunt oare mai bune” — ca și cum ar spune: dar prin faptul că a zis „spală-te și fii curățit”, pare că a vorbit despre un leac natural; și, desigur, nu e nimic în cuvintele lui, căci râurile Damascului sunt mai bune decât toate apele Israelului, și eu mă spăl mereu în ele — și oare sunt curat? Deci, precum nu mi-au folosit râurile Damascului, tot așa nu-mi vor folosi apele Iordanului."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"הֲלֹא טוֹב אֲמָנָה וּפַרְפַּר...","translation":"„Nu sunt oare Amana și Farpar...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"οὐχὶ ἀγαθὸς ᾿Αβανὰ καὶ Φαρφὰρ ποταμοὶ Δαμασκοῦ ὑπὲρ πάντα τὰ ὕδατα ᾿Ισραήλ; οὐχὶ πορευθεὶς λούσομαι ἐν αὐτοῖς καὶ καθαρισθήσομαι; καὶ ἐξέκλινε καὶ ἀπῆλθεν ἐν θυμῷ.","greek":true,"translation":"„Nu sunt Abana și Farfar, râurile Damascului, mai bune decât toate apele lui Israel? Nu mă voi duce să mă spăl în ele și să fiu curățit? Și s-a întors și a plecat cu mânie.”","note":"Septuaginta urmează citirea tradițională (keri) „Abana” (᾿Αβανὰ), nu forma scrisă (ketiv) „Amana” din textul ebraic consonantic."}],"refs":["2 Împărați 5:17","Iosua 3:15-17","Ezechiel 47:1-8","Zaharia 14:8"]},{"v":"5:13","t":"Dar slujitorii lui s-au apropiat și i-au vorbit, spunând: „Părinte, dacă profetul îți spunea un lucru greu, oare nu l-ai fi făcut? [Cu atât mai mult acum,] când ți-a spus doar «cufundă-te și vei fi curățit.»”","tokens":[{"t":"Dar slujitorii lui s-au apropiat și i-au vorbit, spunând: „"},{"t":"Părinte","w":"Părinte","heb":"אָבִי","translit":"avi","strong":"H1","pos":"interjecție","def_ro":"tatăl meu; aici, formulă de respect: „stăpâne”.","diff_ro":"Septuaginta nu redă acest vocativ respectuos („Părinte\"), adresat lui Naaman de slujitorii săi — trece direct la conținutul mustrării lor.","dict_ro":"Avi — „tatăl meu”; Rashi explică că aici e echivalentul lui „adoni” (stăpâne), titlu de respect pentru un om de rang înalt — la fel cum Iosif spune că Dumnezeu l-a pus „tată pentru Faraon” (Geneza 45:8). Argumentul slujitorilor e un „kal vahomer” (de la mai greu la mai ușor) clasic: dacă profetul ți-ar fi cerut ceva greu, l-ai fi făcut — cu atât mai mult un lucru atât de ușor."},{"t":", dacă profetul îți spunea un lucru greu, oare nu l-ai fi făcut? [Cu atât mai mult acum,] când ți-a spus doar «cufundă-te și vei fi curățit.»”"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Părinte” — avi e același lucru cu adoni (stăpâne). „Oare nu l-ai fi făcut?” — n-ai fi făcut-o, chiar dacă ți-ar fi spus să faci ceva ce cere osteneală? „Cu atât mai mult” — printr-o deducție de la mai greu la mai ușor, căci ți-a spus un lucru ușor: „cufundă-te și vei fi curățit”."},{"author":"Metzudat David","text":"„Un lucru greu” — dacă profetul ți-ar fi spus un lucru de mare osteneală ca să fii curățit, n-ar fi fost cuvenit să-l faci? Cu atât mai mult când ți-a spus un lucru ușor — spală-te și prin aceasta vei fi curățit; de ce, atunci, te împotrivești să-l faci?"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיִּגְּשׁוּ עֲבָדָיו וַיְדַבְּרוּ אֵלָיו...","translation":"„Dar slujitorii lui s-au apropiat și...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἤγγισαν οἱ παῖδες αὐτοῦ καὶ ἐλάλησαν πρὸς αὐτόν· μέγα λόγον ἐλάλησεν ὁ προφήτης πρὸς σέ· οὐχὶ ποιήσεις; καὶ ὅτι εἶπε πρὸς σέ, λοῦσαι καὶ καθαρίσθητι.","greek":true,"translation":"„Și s-au apropiat slujitorii lui și au vorbit către el: un cuvânt mare ți-a vorbit profetul; nu-l vei face? Și încă, fiindcă ți-a zis: spală-te și fii curățit.”","note":"Septuaginta omite adresarea „Părinte” (avi) și redă condiționalul ebraic („dacă ți-ar fi poruncit un lucru greu”) ca afirmație („un cuvânt mare ți-a vorbit”), slăbind argumentul „de la greu la ușor” al slujitorilor."}],"refs":["1 Samuel 25:14-17","2 Împărați 2:12","2 Împărați 6:21","Maleahi 1:6","1 Corinteni 1:21,27"]},{"v":"5:14","t":"Așa că el a coborât și s-a cufundat de șapte ori în Iordan, după vorba omului lui Dumnezeu, și carnea sa a întinerit și a fost curățit.","tokens":[{"t":"Așa că el a coborât și "},{"t":"s-a cufundat","w":"s-a cufundat","heb":"וַיִּטְבֹּל","translit":"vaitbol","strong":"H2881","pos":"verb, qal imperfect consecutiv","def_ro":"s-a cufundat, s-a scufundat în apă.","greek":"βαπτίζομαι (baptizomai)","greek_def_ro":"βαπτίζομαι (baptizomai) — a se cufunda, a se scălda.","dict_ro":"Taval — „a (se) cufunda”, rădăcina din care vine în limbajul rabinic „tevila”, cufundarea rituală în mikve. E semnificativ că Elișa spusese „rahatz” (spală-te, v. 10), iar Naaman face mai mult — „taval”, cufundare completă, de șapte ori. Metzudat David explică „ca trupul unui copil mic”: carnea i-a devenit curată și strălucitoare, deci nu doar vindecată, ci înnoită."},{"t":" de șapte ori în Iordan, după vorba omului lui Dumnezeu, și carnea sa a întinerit și a fost curățit."}],"commentaries":[{"author":"Metzudat David","text":"„Carnea sa a întinerit” [kivsar naar katon, „ca trupul unui copil mic”] — adică curată și strălucitoare. „Și a fost curățit” — a devenit curat de lepră."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיֵּרֶד וַיִּטְבֹּל בַּיַּרְדֵּן שֶׁבַע...","translation":"„Așa că el a coborât și...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ κατέβη Ναιμὰν καὶ ἐβαπτίσατο ἐν τῷ ᾿Ιορδάνῃ ἑπτάκις κατὰ τὸ ῥῆμα ῾Ελισαιέ, καὶ ἐπέστρεψεν ἡ σάρξ αὐτοῦ ὡς σάρξ παιδαρίου μικροῦ, καὶ ἐκαθαρίσθη.","greek":true,"translation":"„Și s-a coborât Naiman și s-a cufundat în Iordan de șapte ori, după cuvântul lui Elisaie, și carnea lui s-a întors ca a unui copil mic, și a fost curățit.”","note":"Septuaginta redă „s-a cufundat” prin ἐβαπτίσατο — verbul din care vine „botez” — și înlocuiește „omul lui Dumnezeu” cu numele „Elisaie”."}],"refs":["2 Cronici 20:20","Ioan 2:5","Evrei 11:7,8","Iov 33:25","Luca 4:27","Luca 5:13"]},{"v":"5:15","t":"El s-a întors la omul lui Dumnezeu, el și întregul său alai. A venit la el și a stat înaintea lui și a spus: „Iată, acum știu că nu este Dumnezeu în toată lumea, în afară de în Israel; primește așadar prinosul de la slujitorul tău.”","tokens":[{"t":"El s-a întors la omul lui Dumnezeu, el și întregul său alai. A venit la el și a stat înaintea lui și a spus: „Iată, acum știu că nu este Dumnezeu în toată lumea, în afară de în Israel; primește așadar "},{"t":"prinosul","w":"prinosul","heb":"בְרָכָה","translit":"veraha","strong":"H1293","pos":"substantiv, feminin singular","def_ro":"binecuvântare; aici, dar oferit în semn de recunoștință.","greek":"εὐλογία (eulogia)","greek_def_ro":"εὐλογία (eulogia) — dar, prinos (literal: binecuvântare).","dict_ro":"Beraha — literal „binecuvântare”; Rashi explică că e un dar de pace oferit la salut, cum dă ucenicul sau slujitorul stăpânului său; același cuvânt desemnează darul lui Iacov pentru Esau (Geneza 33:11). Mărturisirea care o precede — „nu este Dumnezeu în toată lumea, în afară de în Israel” — e punctul culminant al haftarei; Talmudul (Ghitin 57b) precizează totuși că Naaman nu s-a convertit, ci a rămas „ger toșav”, un neevreu care păzește cele șapte porunci ale urmașilor lui Noe."},{"t":" de la slujitorul tău.”"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Prinosul” [beraha] — un dar de pace, la salut, precum [dă] un ucenic sau un slujitor stăpânului său."},{"author":"Metzudat David","text":"„A stat înaintea lui” — ca un slujitor înaintea stăpânului. „Primește așadar” — pentru vindecarea și mărturisirea aceasta, primește de la mine un dar."},{"author":"Talmud Bavli, Ghitin 57b","text":"Un înțelept a învățat [într-o baraita]: Naaman a fost ger toșav — un neevreu care păzește cele șapte porunci ale urmașilor lui Noe —, iar Nebuzaradan a fost un convertit deplin."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיָּשָׁב אֶל־אִישׁ הָאֱלֹהִים הוּא...","translation":"„El s-a întors la omul lui...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐπέστρεψε πρὸς ῾Ελισαιὲ αὐτὸς καὶ πᾶσα ἡ παρεμβολὴ αὐτοῦ, καὶ ἦλθε καὶ ἔστη ἐνώπιον αὐτοῦ καὶ εἶπεν· ἰδοὺ δὴ ἔγνωκα ὅτι οὐκ ἔστι Θεὸς ἐν πάσῃ τῇ γῇ, ὅτι ἀλλ᾿ ἢ ἐν τῷ ᾿Ισραήλ· καὶ νῦν λαβὲ τὴν εὐλογίαν παρὰ τοῦ δούλου σου.","greek":true,"translation":"„Și s-a întors la Elisaie, el și toată tabăra lui, și a venit și a stat înaintea lui și a zis: iată, am cunoscut că nu este Dumnezeu pe tot pământul, decât în Israel; și acum ia binecuvântarea de la robul tău.”","note":"Septuaginta înlocuiește „omul lui Dumnezeu” cu numele „Elisaie” și păstrează literal „binecuvântarea” (εὐλογία) pentru dar."}],"refs":["Luca 17:15-18","Iosua 2:9-11","1 Samuel 17:46,47","Daniel 2:47","Daniel 3:29","Geneza 33:11"]},{"v":"5:16","t":"Dar [Elișa] a răspuns: „Pe viața DOMNULUI înaintea Căruia am stat, nu voi primi.” El a stăruit față de el să primească, dar [profetul] a refuzat.","tokens":[{"t":"Dar [Elișa] a răspuns: „Pe viața DOMNULUI înaintea Căruia am stat, nu voi primi.” El "},{"t":"a stăruit","w":"a stăruit","heb":"וַיִּפְצַר","translit":"vaifțar","strong":"H6484","pos":"verb, qal imperfect consecutiv","def_ro":"a stăruit, a insistat, l-a presat.","greek":"παραβιάζομαι (parabiazomai)","greek_def_ro":"παραβιάζομαι (parabiazomai) — a stărui, a insista cu forță.","dict_ro":"Pațar — „a stărui, a presa pe cineva” (aceeași rădăcină ca la Lot, care „a stăruit mult” pe lângă îngeri, Geneza 19:3). Insistența lui Naaman se lovește de jurământul lui Elișa: „Pe viața DOMNULUI înaintea Căruia am stat”. Metzudat David explică expresia ca „înaintea Căruia obișnuiesc să stau în rugăciune” și că formula e un jurământ propriu-zis: pedeapsa jurământului să fie asupra mea dacă voi lua. Rashi adaugă motivul refuzului: printre banii aceia se aflau bani legați de idolatrie."},{"t":" față de el să primească, dar [profetul] a refuzat."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Nu voi primi” — pentru că printre ei sunt amestecați bani legați de idolatrie."},{"author":"Metzudat David","text":"„Înaintea Căruia am stat” — înaintea Căruia obișnuiesc să stau în rugăciune. „Că nu voi primi” — adică pedeapsa jurământului să fie asupra mea, dacă voi lua."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיֹּאמֶר חַי־יְהוָה אֲשֶׁר־עָמַדְתִּי לְפָנָיו...","translation":"„Dar [Elișa] a răspuns: „Pe viața...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ εἶπεν ῾Ελισαιέ· ζῇ Κύριος, ᾧ παρέστην ἐνώπιον αὐτοῦ, εἰ λήψομαι· καὶ παρεβιάσατο αὐτὸν λαβεῖν, καὶ ἠπείθησε.","greek":true,"translation":"„Și a zis Elisaie: viu este Domnul, înaintea căruia am stat, că nu voi lua. Și l-a silit să ia, dar el n-a ascultat.”","note":"Septuaginta numește explicit vorbitorul („Elisaie”) și redă insistența lui Naaman printr-un verb mai tare, „l-a silit” (παρεβιάσατο)."}],"refs":["1 Împărați 17:1","1 Împărați 18:15","2 Împărați 5:20,26","Geneza 14:22,23","Matei 10:8","Faptele apostolilor 20:33-35"]},{"v":"5:17","t":"Naaman a spus: „Măcar dă-i voie slujitorului tău să ia doi măgari încărcați cu pământ, căci slujitorul tău nu va mai aduce niciodată vreo ardere-de-tot sau vreo jertfă de pace altor dumnezei, ci numai DOMNULUI.","tokens":[{"t":"Naaman a spus: „Măcar dă-i voie slujitorului tău să ia doi măgari încărcați cu "},{"t":"pământ","w":"pământ","heb":"אֲדָמָה","translit":"adama","strong":"H127","pos":"substantiv, feminin singular","def_ro":"pământ, țărână, sol.","diff_ro":"Septuaginta nu menționează conținutul încărcăturii („pământ\"), ci spune doar „o încărcătură, o pereche de catâri\" — omite detaliul despre pământul sfânt pe care Naaman voia să-l ia cu el.","dict_ro":"Adama — pământul, solul roditor. Cererea lui Naaman pornește din credința antică potrivit căreia fiecare zeitate e legată de pământul ei: ca să se închine DOMNULUI în Aram, vrea să ia cu el țărână din Țara Israelului. Rashi explică: din pământul acesta al Țării, care e sfânt, va face un altar în orașul lui; iar Metzudat David subliniază delicatețea lui — n-a vrut să ia nici măcar pământ fără permisiunea profetului."},{"t":", căci slujitorul tău nu va mai aduce niciodată vreo ardere-de-tot sau vreo jertfă de pace altor dumnezei, ci numai DOMNULUI."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Măcar” [valo] — e o expresie de rugăminte, ca „o, de-ar fi așa!”. „Să i se dea” — din pământul acesta al Țării Israelului, care e sfânt, o povară cât poartă o pereche de catâri, și îl voi duce în orașul meu și îl voi face altar."},{"author":"Metzudat David","text":"„Să i se dea” — a cerut în formă de întrebare să i se dea pământ din țărâna Țării Israelului, cât poartă doi catâri, ca să-l ducă în țara lui și să umple din el un altar pe care să jertfească DOMNULUI; și n-a vrut să-l ia fără permisiunea profetului. „Căci nu va mai aduce” — de acum încolo nu voi mai aduce ardere-de-tot [altor dumnezei]."},{"author":"Talmud Bavli, Ghitin 57b","text":"Naaman a fost ger toșav — a primit asupra lui cele șapte porunci ale urmașilor lui Noe, nu toate poruncile Torei; spre deosebire de el, Nebuzaradan a fost un convertit deplin."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיֹּאמֶר נַעֲמָן וָלֹא יֻתַּן־נָא...","translation":"„Naaman a spus: „Măcar dă-i voie...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ εἶπε Ναιμάν· καὶ εἰ μή, δοθήτω δὴ τῷ δούλῳ σου γόμος ζεῦγος ἡμιόνων, ὅτι οὐ ποιήσει ἔτι ὁ δοῦλός σου ὁλοκαύτωμα καὶ θυσίασμα θεοῖς ἑτέροις, ἀλλ᾿ ἢ τῷ Κυρίῳ μόνῳ·","greek":true,"translation":"„Și a zis Naiman: și dacă nu, să i se dea robului tău povara unei perechi de catâri, căci robul tău nu va mai face ardere de tot și jertfă altor dumnezei, ci numai Domnului singur.”","note":"Divergență reală: în această formă a textului grec lipsește cuvântul „pământ” (adama) — rămâne doar „povara unei perechi de catâri”, fără să se spună ce anume; în plus, Septuaginta adaugă „singur” (μόνῳ) după „Domnului”, accentuând monoteismul mărturisit de Naaman."}],"refs":["2 Împărați 5:12","Faptele apostolilor 26:18","1 Tesaloniceni 1:9","1 Petru 4:3"]},{"v":"5:18","t":"Și fie ca DOMNUL să-l ierte pe slujitorul tău în legătură cu aceasta: când stăpânul meu vine la templul de la Rimon să se prosterneze acolo, el se sprijină de mâna mea, așa că trebuie [și eu] să mă înclin în templul din Rimon – DOMNUL să-i ierte slujitorului tău acest lucru.”","tokens":[{"t":"Și fie ca DOMNUL să-l ierte pe slujitorul tău în legătură cu aceasta: când stăpânul meu vine la "},{"t":"templul de la Rimon","w":"templul de la Rimon","heb":"רִמּוֹן","translit":"rimon","strong":"H7417","pos":"nume propriu","def_ro":"templul lui Rimon, zeitatea Damascului.","greek":"οἶκος Ῥεμμάν (oikos Rhemman)","greek_def_ro":"οἶκος Ῥεμμάν (oikos Rhemman) — templul lui Rimon.","dict_ro":"Rimon — zeul principal al Damascului, identificat de obicei cu zeul furtunii Hadad (Rammanu în textele asiro-babiloniene); numele sună în ebraică la fel ca „rodie”. Rashi explică situația lui Naaman: e o închinare silită — când regele intră în templu, se sprijină de mâna generalului, iar acesta trebuie să se aplece odată cu el. Cererea lui nu e o permisiune de idolatrie, ci o rugăciune de iertare pentru un gest exterior pe care nu-l poate evita."},{"t":" să se prosterneze acolo, el se sprijină de mâna mea, așa că trebuie [și eu] să mă înclin în templul din Rimon – DOMNUL să-i ierte slujitorului tău acest lucru.”"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Templul de la Rimon” — [Rimon este] numele unei zeități idolatre. „Să se prosterneze acolo” — împotriva voii mele, când stăpânul meu se închină, pentru că se sprijină de mâna mea."},{"author":"Metzudat David","text":"„În legătură cu aceasta” — l-a rugat pe profet să mijlocească pentru el înaintea DOMNULUI, ca să-l ierte pentru lucrul spus aici. „El se sprijină de mâna mea” — când vine să se închine, iar eu, fără voia mea, mă închin și eu împreună cu el. „Să mă înclin” — pentru acea închinare să mă ierte DOMNUL."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"לַדָּבָר הַזֶּה יִסְלַח יְהוָה...","translation":"„Și fie ca DOMNUL să-l ierte...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἱλάσεται Κύριος τῷ δούλῳ σου ἐν τῷ εἰσπορεύεσθαι τὸν κύριόν μου εἰς οἶκον Ῥεμμὰν προσκυνῆσαι ἐκεῖ καὶ αὐτὸς ἐπαναπαύσεται ἐπὶ τῆς χειρός μου καὶ προσκυνήσω ἐν οἴκῳ Ῥεμμὰν ἐν τῷ προσκυνεῖν αὐτὸν ἐν οἴκῳ Ῥεμμάν, καὶ ἱλάσεται δὴ Κύριος τῷ δούλῳ σου ἐν τῷ λόγῳ τούτῳ.","greek":true,"translation":"„Și Domnul va fi îndurător cu robul tău, când stăpânul meu intră în casa lui Remman să se închine acolo, și el se va sprijini de mâna mea, și mă voi închina în casa lui Remman, când se închină el în casa lui Remman — și Domnul va fi îndurător cu robul tău în lucrul acesta.”","note":"Septuaginta redă numele zeului ca „Remman” și formulează iertarea ca o afirmație la viitor („Domnul va fi îndurător”), nu ca o rugăminte; precizează și că Naaman se închină „când se închină el [regele]”, subliniind caracterul silit al gestului."}],"refs":["2 Împărați 7:2,17","2 Împărați 17:35","Exod 20:5","1 Împărați 19:18","2 Cronici 30:18,19","Ieremia 50:20"]},{"v":"5:19","t":"[Elișa] i-a spus: „Mergi în pace” și el s-a dus de la el o distanță oarecare.","tokens":[{"t":"[Elișa] i-a spus: „Mergi în pace” și el s-a dus de la el "},{"t":"o distanță oarecare","w":"o distanță oarecare","heb":"כִּבְרַת","translit":"kivrat","strong":"H3530","pos":"substantiv, feminin singular construct","def_ro":"o întindere de pământ, o distanță (ca măsură de drum).","dict_ro":"Una dintre cele mai cunoscute divergențe din această poveste: expresia ebraică obscură „kivrat ha'areț\" (o anumită distanță/întindere de pământ, de sens incert) este citită de Septuaginta ca un TOPONIM, „εἰς δεβραθὰ\" („spre Debratha\") — tratând o expresie de măsură ca pe numele unui loc, din cauza rarității și ambiguității termenului ebraic."},{"t":"."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „O distanță oarecare” — kivrat eretz e numele unei măsuri de pământ, ca „zece pogoane de vie” (Isaia 5:10)."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיֹּאמֶר לוֹ לֵךְ לְשָׁלוֹם...","translation":"„[Elișa] i-a spus: „Mergi în pace”...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ εἶπεν ῾Ελισαιὲ πρὸς Ναιμάν· δεῦρο εἰς εἰρήνην. καὶ ἀπῆλθεν ἀπ αὐτοῦ εἰς δεβραθὰ τῆς γῆς.","greek":true,"translation":"„Și a zis Elisaie către Naiman: mergi în pace. Și a plecat de la el cale de «debrata» de pământ.”","note":"Septuaginta nu traduce termenul kivrat, ci îl transliterează (δεβραθὰ), semn că sensul exact al măsurii nu era cunoscut traducătorilor; numește și explicit vorbitorul și interlocutorul („Elisaie către Naiman”)."}],"refs":["Exod 4:18","1 Samuel 1:17","Marcu 5:34","Luca 7:50","Luca 8:48","Geneza 35:16"]}]},{"num":6,"title":"Mețora - Lepra","ref":"2 Împărați 7:3-20","intro":"Haftarat Mețora însoțește pericopa despre curățirea leprosului și rămâne, ca și cea precedentă, în ciclul lui Elișa: Samaria e asediată de arameii lui Ben-Hadad, iar foametea a ajuns atât de cumplită încât prețurile au devenit de neconceput. Elișa vestise că a doua zi, la aceeași oră, făina și orzul se vor vinde ieftin la poarta Samariei — iar ofițerul regelui își bătuse joc de profeție. Salvarea vine prin cei mai disprețuiți oameni din cetate: patru leproși, ținuți afară de lege la poartă, care descoperă că DOMNUL a pus pe fugă întreaga oaste aramee printr-un simplu zgomot de care și cai. După ce își potolesc foamea, conștiința îi împinge să vestească „ziua de veste bună”. Profeția se împlinește întocmai, în ambele ei părți: poporul se îndestulează, iar ofițerul necredincios vede minunea, dar moare călcat în picioare la poartă, fără să guste din ea.","verses":[{"v":"7:3","t":"Și patru oameni erau leproși [care stăteau] la poartă și fiecare a spus semenului său: „De ce stăm aici până când vom muri?","tokens":[{"t":"Și patru oameni erau "},{"t":"leproși","w":"leproși","heb":"מְצֹרָעִים","translit":"mețoraim","strong":"H6879","pos":"verb, pual participiu pasiv","def_ro":"loviți de țaraat, leproși.","greek":"λεπρός (lepros)","greek_def_ro":"λεπρός (lepros) — lepros.","dict_ro":"Metzoraim — leproșii, legătura directă cu pericopa Mețora (Levitic 14), care descrie curățirea leprosului. Ei stau „la poartă” pentru că Tora poruncește ca leprosul să locuiască „în afara taberei” (Leviticul 13:46), explică atât Rashi, cât și Metzudat David. Talmudul (Sanhedrin 107b) îi identifică: Rabi Iohanan spune că erau Ghehazi și cei trei fii ai lui — lovit de lepra lui Naaman pentru lăcomia lui (2 Împărați 5:27), ucenicul alungat al lui Elișa devine, fără să știe, primul vestitor al împlinirii profeției învățătorului său."},{"t":" [care stăteau] la poartă și fiecare a spus semenului său: „De ce stăm aici până când vom muri?"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Patru oameni” — Ghehazi și fiii lui. „La intrarea porții” — precum s-a spus: „să locuiască singur, în afara taberei să-i fie locuința” (Levitic 13:46)."},{"author":"Metzudat David","text":"„La intrarea porții” — stăteau la intrarea porții, după legea leprosului, precum s-a spus: „în afara taberei să-i fie locuința” (Levitic 13:46). „Până vom muri” — până vom muri de foame."},{"author":"Talmud Bavli, Sanhedrin 107b","text":"„Și patru oameni erau leproși la intrarea porții” (2 Împărați 7:3) — Rabi Iohanan spune: aceștia erau Ghehazi și cei trei fii ai lui."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְאַרְבָּעָה אֲנָשִׁים הָיוּ מְצֹרָעִים...","translation":"„Și patru oameni erau leproși [care...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ τέσσαρες ἄνδρες ἦσαν λεπροὶ παρὰ τὴν θύραν τῆς πόλεως, καὶ εἶπεν ἀνὴρ πρὸς τὸν πλησίον αὐτοῦ· τί ἡμεῖς καθήμεθα ὧδε, ἕως ἀποθάνωμεν;","greek":true,"translation":"„Și patru oameni erau leproși la poarta cetății, și a zis fiecare către aproapele său: de ce stăm noi aici până vom muri?”","note":"Septuaginta precizează „poarta cetății”, unde Textul Masoretic spune doar „la intrarea porții”; în rest, corespondență strânsă."}],"refs":["Levitic 13:46","Numeri 5:2-4","Numeri 12:14","Ieremia 8:14"]},{"v":"7:4","t":"Dacă ne gândim să mergem în oraș, foametea este în oraș și vom muri acolo; iar dacă vom sta aici, vom muri. Haideți așadar să mergem să ne predăm în tabăra arameilor: dacă ne vor cruța, vom trăi, iar dacă ne vor ucide, vom muri.”","tokens":[{"t":"Dacă ne gândim să mergem în oraș, foametea este în oraș și vom muri acolo; iar dacă vom sta aici, vom muri. Haideți așadar să mergem "},{"t":"să ne predăm","w":"să ne predăm","heb":"וְנִפְּלָה","translit":"venipla","strong":"H5307","pos":"verb, qal cohortativ","def_ro":"să cădem, să trecem de partea cuiva, să ne predăm.","greek":"ἐμπίπτω (empipto)","greek_def_ro":"ἐμπίπτω (empipto) — a se preda, a cădea în mâna cuiva.","dict_ro":"Nafal — literal „a cădea”; cu prepoziția „el” capătă sensul de „a trece la dușman, a dezerta”, cum explică Metzudat Țion, comparând cu acuzația adusă lui Ieremia: „tu treci la caldeeni” (Ieremia 37:13). Logica leproșilor e un calcul lucid al disperării: orașul înseamnă moarte sigură, locul lor tot moarte sigură, iar tabăra dușmană e singura variantă în care au măcar o șansă — Metzudat David o rezumă ca „oricum am alege, suntem sortiți morții”."},{"t":" în tabăra arameilor: dacă ne vor cruța, vom trăi, iar dacă ne vor ucide, vom muri.”"}],"commentaries":[{"author":"Metzudat David","text":"„Vom trăi” — căci acolo se găsește pâine. „Vom muri” — ca și cum ar spune: ce contează dacă murim, căci, oricum am alege, suntem sortiți morții."},{"author":"Metzudat Țion","text":"„Venipla” — cu sensul de a se abate [de partea cuiva], ca în „tu treci la caldeeni” (Ieremia 37:13)."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"אִם־אָמַרְנוּ נָבוֹא הָעִיר וְהָרָעָב...","translation":"„Dacă ne gândim să mergem în...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ἐὰν εἴπωμεν, εἰσέλθωμεν εἰς τὴν πόλιν, καὶ ὁ λιμὸς ἐν τῇ πόλει καὶ ἀποθανούμεθα ἐκεῖ· καὶ ἐὰν καθίσωμεν ὧδε, καὶ ἀποθανούμεθα. καὶ νῦν δεῦτε καὶ ἐμπέσωμεν εἰς τὴν παρεμβολὴν Συρίας· ἐὰν ζωογονήσωσιν ἡμᾶς, καὶ ζησόμεθα· καὶ ἐὰν θανατώσωσιν ἡμᾶς, καὶ ἀποθανούμεθα.","greek":true,"translation":"„Dacă zicem: să intrăm în cetate — foametea e în cetate și vom muri acolo; și dacă stăm aici, vom muri. Și acum, veniți să cădem în tabăra Siriei: dacă ne vor lăsa în viață, vom trăi; și dacă ne vor omorî, vom muri.”","note":"Corespondență strânsă cu Textul Masoretic; „să ne predăm” e redat literal, „să cădem în” (ἐμπέσωμεν)."}],"refs":["Ieremia 14:18","Ieremia 37:13,14","Estera 4:16","Iona 3:9","Luca 15:17-19","2 Samuel 14:14"]},{"v":"7:5","t":"Și s-au ridicat, și în amurg au ajuns la tabăra arameilor și au ajuns la marginea taberei arameilor și iată, nu era nimeni acolo.","tokens":[{"t":"Și s-au ridicat, și "},{"t":"în amurg","w":"în amurg","heb":"בַנֶּשֶׁף","translit":"vaneșef","strong":"H5399","pos":"substantiv, masculin singular","def_ro":"în amurg, la căderea serii.","greek":"σκότος (skotos)","greek_def_ro":"σκότος (skotos) — întuneric.","diff_ro":"Septuaginta are generic „în întuneric\" (ἐν τῷ σκότει), nu specific „în amurg\" (neșef, momentul crepuscular) ca în ebraică.","dict_ro":"Neșef — ora de trecere dintre zi și noapte (sau dintre noapte și zi); Metzudat Țion îl explică prin „seară”, comparând cu Isaia 5:11, „cei ce zăbovesc până în amurg”. Același cuvânt revine în v. 7: arameii fugiseră tocmai „în amurg” — leproșii pornesc la aceeași oră la care tabăra fusese părăsită, astfel încât ajung imediat după fugă, înaintea oricui altcuiva."},{"t":" au ajuns la tabăra arameilor și au ajuns la marginea taberei arameilor și iată, nu era nimeni acolo."}],"commentaries":[{"author":"Metzudat Țion","text":"„Baneșef” — seara, ca în „cei ce zăbovesc până în amurg” (Isaia 5:11)."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיָּקֻמוּ בַנֶּשֶׁף לָבוֹא אֶל־מַחֲנֵה...","translation":"„Și s-au ridicat, și în amurg...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἀνέστησαν ἐν τῷ σκότει εἰσελθεῖν εἰς τὴν παρεμβολὴν Συρίας καὶ ἦλθον εἰς μέρος παρεμβολῆς Συρίας, καὶ ἰδοὺ οὐκ ἔστιν ἀνὴρ ἐκεῖ.","greek":true,"translation":"„Și s-au sculat în întuneric să intre în tabăra Siriei și au venit la o parte a taberei Siriei, și iată, nu era niciun om acolo.”","note":"Septuaginta redă „amurg” prin „întuneric” (ἐν τῷ σκότει) și „marginea taberei” prin „o parte a taberei” (μέρος)."}],"refs":["1 Samuel 30:17","Ezechiel 12:6,7,12","Deuteronom 28:7","Deuteronom 32:25,30"]},{"v":"7:6","t":"Iar Domnul făcuse ca tabăra arameilor să audă zgomotul carelor, zgomotul cailor și zgomotul unei mari oștiri, și fiecare a spus către fratele său: „Iată, regele Israelului i-a tocmit pe regii hitiților și pe regii Egiptului să vină peste noi!”","tokens":[{"t":"Iar Domnul făcuse ca tabăra arameilor să audă "},{"t":"zgomotul carelor","w":"zgomotul carelor","heb":"קוֹל","translit":"kol","strong":"H6963","pos":"substantiv, masculin singular construct","def_ro":"sunetul, vuietul carelor de luptă.","greek":"φωνή ἅρματος (phone harmatos)","greek_def_ro":"φωνή ἅρματος (phone harmatos) — zgomotul carului.","dict_ro":"Kol — „glas, sunet, zgomot”; repetat de trei ori în verset (car, cal, oaste mare), creează un crescendo auditiv. Rashi și Metzudat David subliniază că nu era un zgomot real, ci o percepție trimisă de DOMNUL: „li se părea că aud” — biruința vine fără nicio armă, doar printr-un sunet. Pomenirea regilor hitiților și a Egiptului reflectă realitatea politică a vremii: carele egiptene și caii din nord erau marile forțe militare pe care Israelul le putea tocmi cu plată (vezi 1 Împărați 10:29)."},{"t":", zgomotul cailor și zgomotul unei mari oștiri, și fiecare a spus către fratele său: „Iată, regele Israelului i-a tocmit pe regii hitiților și pe regii Egiptului să vină peste noi!”"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Făcuse ca tabăra Aramului să audă” — li se părea ca și cum ar auzi."},{"author":"Metzudat David","text":"„Și DOMNUL făcuse să audă” — pricina pentru care n-au găsit acolo pe nimeni era că DOMNUL făcuse să se audă..., adică, prin purtarea de grijă a DOMNULUI, li s-a părut ca și cum ar auzi. „Să vină peste noi” — și acesta e zgomotul pe care îl auzim."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַאדֹנָי הִשְׁמִיעַ אֶת־מַחֲנֵה אֲרָם...","translation":"„Iar Domnul făcuse ca tabăra arameilor...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ κύριος ἀκουστὴν ἐποίησε παρεμβολὴν τὴν Συρίας φωνὴν ἅρματος καὶ φωνὴν ἵππου, φωνὴν δυνάμεως μεγάλης, καὶ εἶπεν ἀνὴρ πρὸς τὸν ἀδελφὸν αὐτοῦ· νῦν ἐμισθώσατο ἐφ᾿ ἡμᾶς ὁ βασιλεὺς ᾿Ισραὴλ τοὺς βασιλέας τῶν Χετταίων καὶ τοὺς βασιλέας Αἰγύπτου τοῦ ἐλθεῖν ἐφ᾿ ἡμᾶς.","greek":true,"translation":"„Și Domnul a făcut ca tabăra Siriei să audă glas de car și glas de cal, glas de oaste mare; și a zis fiecare către fratele său: acum a tocmit împotriva noastră regele lui Israel pe regii hetiților și pe regii Egiptului, ca să vină asupra noastră.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["2 Împărați 19:7","2 Samuel 5:24","Iov 15:21","Psalmii 14:5","1 Împărați 10:29","Isaia 31:1"]},{"v":"7:7","t":"Astfel că s-au ridicat și au fugit în amurg, și și-au părăsit corturile și caii și măgarii – tabăra așa cum era ea – și au fugit să-și salveze viețile.","tokens":[{"t":"Astfel că s-au ridicat și au fugit în amurg, și și-au părăsit corturile și caii și măgarii – tabăra așa cum era ea – și au fugit "},{"t":"să-și salveze viețile","w":"să-și salveze viețile","heb":"נַפְשָׁם","translit":"nafșam","strong":"H5315","pos":"substantiv, masculin și feminin singular construct + sufix","def_ro":"pentru viața lor, ca să scape cu viață.","greek":"ψυχή ἑαυτῶν (psyche heauton)","greek_def_ro":"ψυχή ἑαυτῶν (psyche heauton) — viața lor.","dict_ro":"Nefeș — suflet, viață, ființă vie; „a fugi el-nafșo” înseamnă a fugi doar cu viața, lăsând totul în urmă, iar Metzudat David explică: „ca să-și salveze sufletele”. Detaliul „tabăra așa cum era ea” — pe care Metzudat David îl citește ca „totul întreg, cum fusese cât timp erau acolo” — pregătește ironia poveștii: o oaste întreagă își abandonează proviziile tocmai în fața unui oraș care murea de foame."},{"t":"."}],"commentaries":[{"author":"Metzudat David","text":"„Tabăra așa cum era ea” — totul întreg, așa cum fusese cât timp erau ei acolo. „Să-și salveze viețile” — ca să-și scape sufletele."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיָּקוּמוּ וַיָּנוּסוּ בַנֶּשֶׁף וַיַּעַזְבוּ...","translation":"„Astfel că s-au ridicat și au...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἀνέστησαν καὶ ἀπέδρασαν ἐν τῷ σκότει καὶ ἐγκατέλιπαν τὰς σκηνὰς αὐτῶν καὶ τοὺς ἵππους αὐτῶν καὶ τοὺς ὄνους αὐτῶν ἐν τῇ παρεμβολῇ ὥς ἐστι καὶ ἔφυγον πρὸς τὴν ψυχὴν ἑαυτῶν.","greek":true,"translation":"„Și s-au sculat și au fugit în întuneric și și-au părăsit corturile și caii și măgarii în tabără, cum era, și au fugit pentru sufletul lor.”","note":"Corespondență strânsă; „amurg” e redat din nou prin „întuneric”."}],"refs":["Iov 18:11","Psalmii 48:4-6","Proverbe 28:1","Psalmii 33:17","Amos 2:14-16"]},{"v":"7:8","t":"Și acești leproși au ajuns până la marginea taberei, au intrat într-un cort și au mâncat și au băut. Din el, au luat argint și aur și veșminte și au mers și le-au ascuns. Apoi s-au întors și au mers într-un alt cort, au luat și de acolo [lucruri de preț] și au mers și le-au ascuns.","tokens":[{"t":"Și acești leproși au ajuns până la marginea taberei, au intrat într-un cort și au mâncat și au băut. Din el, au luat argint și aur și veșminte și au mers și "},{"t":"le-au ascuns","w":"le-au ascuns","heb":"וַיַּטְמִנוּ","translit":"vaiatminu","strong":"H2934","pos":"verb, hifil imperfect consecutiv","def_ro":"au ascuns, au îngropat [ca să păstreze].","greek":"κατακρύπτω (katakrypto)","greek_def_ro":"κατακρύπτω (katakrypto) — a ascunde bine.","dict_ro":"Taman — „a ascunde, a îngropa”, de obicei în pământ, ca să păstrezi ceva de valoare (ca Acan, care a ascuns prada în cortul lui, Iosua 7:21). Primul impuls al leproșilor, după foamea potolită, e să-și asigure bogăția — de două ori, cort după cort. Tocmai această repetiție face cu atât mai puternică întoarcerea de conștiință din versetul următor: „nu procedăm corect!”."},{"t":". Apoi s-au întors și au mers într-un alt cort, au luat și de acolo [lucruri de preț] și au mers și le-au ascuns."}],"commentaries":[],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיָּבֹאוּ הַמְצֹרָעִים הָאֵלֶּה עַד־קְצֵה...","translation":"„Și acești leproși au ajuns până...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ εἰσῆλθον οἱ λεπροὶ οὗτοι ἕως μέρους τῆς παρεμβολῆς καὶ εἰσῆλθον εἰς σκηνὴν μίαν καὶ ἔφαγον καὶ ἔπιον καὶ ᾖραν ἐκεῖθεν ἀργύριον καὶ χρυσίον καὶ ἱματισμὸν καὶ ἐπορεύθησαν· καὶ ἐπέστρεψαν ἐκεῖθεν καὶ εἰσῆλθον εἰς σκηνὴν ἄλλην καὶ ἔλαβον ἐκεῖθεν καὶ ἐπορεύθησαν καὶ κατέκρυψαν.","greek":true,"translation":"„Și au intrat leproșii aceștia până la o parte a taberei și au intrat într-un cort și au mâncat și au băut și au luat de acolo argint și aur și îmbrăcăminte și s-au dus; și s-au întors de acolo și au intrat în alt cort și au luat de acolo și s-au dus și le-au ascuns.”","note":"Septuaginta omite prima mențiune „și le-au ascuns” (după primul cort), păstrând-o doar la final."}],"refs":["2 Împărați 5:24","Iosua 7:21","Ieremia 41:8","Matei 13:44","Matei 25:18"]},{"v":"7:9","t":"Și și-au spus unul către celălalt: „Nu procedăm corect! Această zi este o zi a veștilor bune, și totuși noi tăcem! Dacă mai așteptăm până dimineața în zori, vom fi socotiți ca păcătoși. Și acum, haide să mergem așadar și să ajungem să vestim la palatul regelui!”","tokens":[{"t":"Și și-au spus unul către celălalt: „Nu procedăm corect! Această zi este "},{"t":"o zi a veștilor bune","w":"o zi a veștilor bune","heb":"בְּשֹׂרָה","translit":"besora","strong":"H1309","pos":"substantiv, feminin singular","def_ro":"zi de vestire bună, zi de vești bune.","greek":"ἡμέρα εὐαγγελίας (hemera euangelias)","greek_def_ro":"ἡμέρα εὐαγγελίας (hemera euangelias) — zi de veste bună.","dict_ro":"Besora — „veste (bună)”, din rădăcina basar, „a vesti”; Septuaginta o redă aici prin εὐαγγελία, din aceeași familie cu „evanghelie”. Metzudat David explică de ce tăcerea ar fi vinovată: dacă așteaptă până dimineață, regele va afla de la alții și îi va socoti vinovați că n-au alergat să vestească. Tradiția creștină a citit în acest verset principiul că vestea bună nu poate fi păstrată doar pentru sine (vezi Isaia 52:7)."},{"t":", și totuși noi tăcem! Dacă mai așteptăm până dimineața în zori, vom fi socotiți ca păcătoși. Și acum, haide să mergem așadar și să ajungem să vestim la palatul regelui!”"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Vom fi socotiți ca păcătoși” — vom fi socotiți vinovați de către domnie."},{"author":"Metzudat David","text":"„Nu procedăm corect” — nu e bine și drept. „Această zi...” — căci astăzi e ceva de vestit, iar noi tăcem de la a vesti; și dacă vom aștepta până dimineață, oare nu va afla regele prin alții, și vom fi vinovați în ochii lui că nu ne-am grăbit să venim să vestim?"},{"author":"Metzudat Țion","text":"„Mahșim” — tăcem, ca în „și eu știu, tăceți” (2 Împărați 2:3). „Vehikinu” — cu sensul de întârziere și așteptare."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיֹּאמְרוּ אִישׁ אֶל־רֵעֵהוּ לֹא־כֵן...","translation":"„Și și-au spus unul către celălalt...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ εἶπεν ἀνὴρ πρὸς τὸν πλησίον αὐτοῦ· οὐχ οὕτως ἡμεῖς ποιοῦμεν· ἡ ἡμέρα αὕτη ἡμέρα εὐαγγελίας ἐστί, καὶ ἡμεῖς σιωπῶμεν καὶ μένομεν ἕως φωτὸς τοῦ πρωΐ καὶ εὑρήσομεν ἀνομίαν· καὶ νῦν δεῦρο καὶ εἰσέλθωμεν καὶ ἀναγγείλωμεν εἰς τὸν οἶκον τοῦ βασιλέως.","greek":true,"translation":"„Și a zis fiecare către aproapele său: nu facem bine; ziua aceasta e zi de veste bună, și noi tăcem și rămânem până la lumina dimineții și vom găsi fărădelege; și acum, veniți să intrăm și să vestim în casa regelui.”","note":"Corespondență strânsă; „veste bună” e redată prin εὐαγγελία, din aceeași familie de cuvinte cu „evanghelie”."}],"refs":["Isaia 41:27","Isaia 52:7","Naum 1:15","Luca 2:10","Numeri 32:23"]},{"v":"7:10","t":"Au ajuns și au strigat la străjerii orașului și le-au vestit, spunând: „Am ajuns în tabăra arameilor și iată, nu este nimeni acolo și nici vreun glas de om, ci doar caii legați și măgarii legați, și corturile așa cum erau.”","tokens":[{"t":"Au ajuns și au strigat la "},{"t":"străjerii orașului","w":"străjerii orașului","heb":"שֹׁעֵר","translit":"șoēr","strong":"H7778","pos":"substantiv, masculin singular construct","def_ro":"paznicul porții orașului.","diff_ro":"Septuaginta are „πρὸς τὴν πύλην τῆς πόλεως\" („către poarta cetății\"), nu explicit „străjerii orașului\" — poarta însăși, nu portarii, e numită ca destinatar al strigătului.","dict_ro":"Șoer — portarul, paznicul porții, din șaar („poartă”). Leproșii nu pot intra în oraș — legea îi ține afară —, așa că vestea trebuie strigată de dinafară către paznic, iar de la el trece mai departe, din mână în mână, până la rege (v. 11). Detaliile raportului — cai și măgari legați, corturi neatinse — sunt, după Rashi și Metzudat David, semnul că tabăra fusese lăsată întocmai cum era, cu toate proviziile înăuntru."},{"t":" și le-au vestit, spunând: „Am ajuns în tabăra arameilor și iată, nu este nimeni acolo și nici vreun glas de om, ci doar caii legați și măgarii legați, și corturile așa cum erau.”"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Așa cum erau” — pline, ca de la început; nu scoseseră ce era în ele."},{"author":"Metzudat David","text":"„Străjerii orașului” [șoer hair] — paznicul porții orașului. „Legați” — legați la iesle, după obicei. „Așa cum erau” — cum fuseseră dintotdeauna, cât timp stătuseră acolo."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיָּבֹאוּ וַיִּקְרְאוּ אֶל־שֹׁעֵר הָעִיר...","translation":"„Au ajuns și au strigat la...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ εἰσῆλθον καὶ ἐβόησαν πρὸς τὴν πύλην τῆς πόλεως καὶ ἀνήγγειλαν αὐτοῖς, λέγοντες· εἰσήλθομεν εἰς τὴν παρεμβολὴν Συρίας, καὶ ἰδοὺ οὐκ ἔστιν ἐκεῖ ἀνὴρ καὶ φωνὴ ἀνθρώπου, ὅτι εἰ μὴ ἵππος δεδεμένος καὶ ὄνος καὶ αἱ σκηναὶ αὐτῶν ὡς εἰσί.","greek":true,"translation":"„Și au venit și au strigat către poarta cetății și le-au vestit, zicând: am intrat în tabăra Siriei, și iată, nu e acolo niciun om, nici glas de om, ci doar cal legat și măgar, și corturile lor cum sunt.”","note":"Septuaginta spune că au strigat „către poarta cetății”, nu „către portar” (probabil citind șaar în loc de șoer), și omite „legat” la măgar."}],"refs":["2 Împărați 7:11","2 Samuel 18:26","Marcu 13:34,35","2 Împărați 7:6,7"]},{"v":"7:11","t":"Străjerii au anunțat și [lucrul] a fost vestit înăuntrul palatului regelui.","tokens":[{"t":"Străjerii au anunțat și [lucrul] a fost vestit "},{"t":"înăuntrul","w":"înăuntrul","heb":"פְּנִימָה","translit":"penima","strong":"H6441","pos":"adverb","def_ro":"înăuntru, spre interior.","greek":"ἔσω (eso)","greek_def_ro":"ἔσω (eso) — înăuntru.","dict_ro":"Penima — „spre înăuntru”; Metzudat David descrie lanțul vestirii: portarul orașului a strigat către paznicii porților palatului, iar aceștia au dus vestea „înăuntru”, în încăperea interioară unde locuia regele. Distanța dintre leproșii de la poartă și regele din camera cea mai dinăuntru e, simbolic, distanța pe care o străbate vestea bună — de la cei mai de jos până la cel mai de sus."},{"t":" palatului regelui."}],"commentaries":[{"author":"Metzudat David","text":"„Străjerii au anunțat” — portarul orașului a strigat către paznicii porților casei regelui și le-a spus lucrurile acestea, iar ei au vestit lucrul în casa dinăuntru, locul unde stătea regele."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיִּקְרָא הַשֹּׁעֲרִים וַיַּגִּידוּ בֵּית...","translation":"„Străjerii au anunțat și [lucrul] a...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐβόησαν οἱ θυρωροὶ καὶ ἀνήγγειλαν εἰς τὸν οἶκον τοῦ βασιλέως ἔσω.","greek":true,"translation":"„Și au strigat portarii și au vestit în casa regelui, înăuntru.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":[]},{"v":"7:12","t":"Regele s-a sculat noaptea și le-a spus slujitorilor săi: „Vă voi spune acum ce ne-a făcut Aram; au știut că suntem înfometați și au plecat din tabără ca să se ascundă pe câmp, spunând [în sinea lor]: «Când vor ieși din oraș, îi vom prinde vii și apoi vom intra în oraș.»","tokens":[{"t":"Regele s-a sculat noaptea și le-a spus slujitorilor săi: „Vă voi spune acum ce ne-a făcut Aram; au știut că suntem înfometați și au plecat din tabără ca "},{"t":"să se ascundă","w":"să se ascundă","heb":"לְהֵחָבֵה","translit":"lehēhavē","strong":"H2244","pos":"verb, nifal infinitiv","def_ro":"a se ascunde, a sta la pândă.","greek":"κρύπτομαι (kryptomai)","greek_def_ro":"κρύπτομαι (kryptomai) — a se ascunde.","dict_ro":"Hava — „a se ascunde”; regele bănuiește o ambuscadă clasică: tabăra pare părăsită, dar oastea stă ascunsă pe câmp, așteptând ca flămânzii să iasă. Metzudat David explică de ce planul ar fi părut plauzibil: din cauza marii foamete, asediații n-ar mai sta să cerceteze lucrurile înainte de a ieși. Neîncrederea regelui contrastează cu profeția lui Elișa din versetele anterioare (7:1), pe care el nici nu o ia în calcul."},{"t":" pe câmp, spunând [în sinea lor]: «Când vor ieși din oraș, îi vom prinde vii și apoi vom intra în oraș.»"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Suntem înfometați” — și dornici să ieșim după pradă și după mâncare."},{"author":"Metzudat David","text":"„Ce ne-a făcut Aram” — viclenia și șiretlicul pe care le-au făcut. „Când vor ieși” — ca să găsească ceva de mâncare; căci, din cauza marii foamete, nu vor aștepta să cerceteze lucrul."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיָּקָם הַמֶּלֶךְ לַיְלָה וַיֹּאמֶר...","translation":"„Regele s-a sculat noaptea și le-a...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἀνέστη ὁ βασιλεὺς νυκτὸς καὶ εἶπε πρὸς τοὺς παῖδας αὐτοῦ· ἀναγγελῶ δὴ ὑμῖν ἃ ἐποίησεν ὑμῖν Συρία· ἔγνωσαν ὅτι πεινῶμεν ἡμεῖς, καὶ ἐξῆλθαν ἐκ τῆς παρεμβολῆς καὶ ἐκρύβησαν ἐν τῷ ἀγρῷ λέγοντες· ὅτι ἐξελεύσονται ἐκ τῆς πόλεως, καὶ συλληψόμεθα αὐτοὺς ζῶντας καὶ εἰς τὴν πόλιν εἰσελευσόμεθα.","greek":true,"translation":"„Și s-a sculat regele noaptea și a zis slujitorilor săi: vă voi vesti ce v-a făcut Siria; au știut că suntem flămânzi și au ieșit din tabără și s-au ascuns în câmp, zicând: vor ieși din cetate și îi vom prinde vii și vom intra în cetate.”","note":"Septuaginta are „ce v-a făcut” (ὑμῖν), acolo unde Textul Masoretic are „ce ne-au făcut”; în rest, corespondență strânsă."}],"refs":[]},{"v":"7:13","t":"Și atunci a răspuns unul dintre slujitorii săi și a spus: „Să se ia așadar cinci dintre caii rămași, cei care se află încă aici – ei sunt ca toată mulțimea lui Israel care a rămas, care sunt ca toată mulțimea lui Israel care a pierit. Să-i trimitem și vom vedea.”","tokens":[{"t":"Și atunci a răspuns unul dintre slujitorii săi și a spus: „Să se ia așadar cinci dintre caii rămași, cei care se află încă aici – ei sunt ca toată "},{"t":"mulțimea","w":"mulțimea","heb":"הֲמוֹן","translit":"hamon","strong":"H1995","pos":"substantiv, masculin singular construct","def_ro":"mulțime, gloată, vuiet de popor.","greek":"πλῆθος (plethos)","greek_def_ro":"πλῆθος (plethos) — mulțime.","dict_ro":"Hamon — mulțime zgomotoasă, din rădăcina hama, „a vui, a face zgomot”; Metzudat Țion îl explică simplu: „mulțime de popor”. Repetiția din text (ketiv și keri diferă ușor) exprimă argumentul slujitorului, pe care Rashi și Metzudat David îl desfac în două: dacă cei cinci călăreți rămân în oraș, vor muri de foame ca toți cei rămași; dacă mor uciși de aramei, vor fi doar ca mulțimea care a pierit deja — deci nu se pierde nimic trimițându-i."},{"t":" lui Israel care a rămas, care sunt ca toată mulțimea lui Israel care a pierit. Să-i trimitem și vom vedea.”"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Cei care se află încă aici” [așer nișaru va, „care au rămas în ea”] — în oraș, care n-au murit de foame. „Iată, ei sunt ca toată mulțimea lui Israel care a rămas” — dacă vor spune că sunt în primejdie să fie uciși de aramei, iată, [dacă rămân] în oraș sunt în primejdie ca toată mulțimea lui Israel care a rămas acolo; iar dacă mor, sunt ca toată mulțimea lui Israel care a pierit de foame."},{"author":"Metzudat David","text":"„Cei care se află încă aici...” — ca și cum ar spune: chiar dacă dușmanul îi va ucide pe călăreți, nu e nicio pagubă, căci vor fi ca toată mulțimea lui Israel rămasă în oraș, fiindcă toți suntem sortiți să murim de foame, iar călăreții sunt ca unul dintre noi dacă rămân aici; și dacă e să ne temem că moartea le va veni mai devreme, oare nu vor fi ca toată mulțimea lui Israel care a pierit deja înaintea lor? De aceea, să trimitem și să vedem."},{"author":"Metzudat Țion","text":"„Hinam” — iată-i. „Hamon” — cu sensul de mulțime de popor. „Tamu” — s-au sfârșit."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיַּעַן אֶחָד מֵעֲבָדָיו וַיֹּאמֶר...","translation":"„Și atunci a răspuns unul dintre...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἀπεκρίθη εἷς τῶν παίδων αὐτοῦ καὶ εἶπε· λαβέτωσαν δὴ πέντε τῶν ἵππων τῶν ὑπολελειμμένων, οἳ κατελείφθησαν ὧδε, ἰδού εἰσι πρὸς πᾶν τὸ πλῆθος ᾿Ισραὴλ τὸ ἐκλεῖπον· καὶ ἀποστελοῦμεν ἐκεῖ καὶ ὀψόμεθα.","greek":true,"translation":"„Și a răspuns unul din slujitorii lui și a zis: să se ia cinci din caii rămași, care au fost lăsați aici — iată, ei sunt ca toată mulțimea lui Israel care se stinge; și vom trimite acolo și vom vedea.”","note":"Divergență reală: Septuaginta are o singură comparație („ca toată mulțimea lui Israel care se stinge”), omițând complet fraza dublată din Textul Masoretic („ca toată mulțimea care a rămas... ca toată mulțimea care a pierit”)."}],"refs":["2 Împărați 5:13","2 Împărați 7:4","Plângerile lui Ieremia 4:9"]},{"v":"7:14","t":"Au luat doi călăreți și regele i-a trimis pe urma taberei Aramului, spunând: „Mergeți și uitați-vă!”","tokens":[{"t":"Au luat "},{"t":"doi călăreți","w":"doi călăreți","heb":"שְׁנֵי רֶכֶב","translit":"șenē rehev","strong":"H7393","pos":"numeral + substantiv, masculin singular","def_ro":"două atelaje de cai, două care cu caii lor.","greek":"δύο ἐπιβάτας ἵππων (dyo epibatas hippon)","greek_def_ro":"δύο ἐπιβάτας ἵππων (dyo epibatas hippon) — doi călăreți pe cai.","dict_ro":"Reveh susim — literal „două [care cu] atelaj de cai”, adică două echipaje de cercetare. Slujitorul propusese cinci cai, dar s-au trimis doar doi: Metzudat David explică că, în ciuda argumentului că nu se pierde nimic, n-au vrut să pună în primejdie decât pe doi. Direcția urmăririi — „pe urma taberei” — înseamnă, după același comentator, pe drumul spre țara lor."},{"t":" și regele i-a trimis pe urma taberei Aramului, spunând: „Mergeți și uitați-vă!”"}],"commentaries":[{"author":"Metzudat David","text":"„Doi călăreți” — căci, cu toate acestea, n-au vrut să bage în primejdie decât doi. „Pe urma taberei” — adică pe drumul spre țara lor."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיִּקְחוּ שְׁנֵי רֶכֶב סוּסִים...","translation":"„Au luat doi călăreți și regele...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἔλαβον δύο ἐπιβάτας ἵππων, καὶ ἀπέστειλεν ὁ βασιλεὺς ᾿Ισραὴλ ὀπίσω τοῦ βασιλέως Συρίας λέγων· δεῦτε καὶ ἴδετε.","greek":true,"translation":"„Și au luat doi călăreți de cai, și a trimis regele lui Israel după regele Siriei, zicând: mergeți și vedeți.”","note":"Septuaginta îi trimite pe cercetași „după regele Siriei”, nu „după tabăra Aramului”, și numește explicit „regele lui Israel”."}],"refs":[]},{"v":"7:15","t":"I-au urmărit până la Iordan și iată, tot drumul era plin cu haine și lucruri pe care arameii le aruncaseră în goana lor; și solii s-au întors și i-au vestit regelui.","tokens":[{"t":"I-au urmărit până la Iordan și iată, tot drumul era plin cu haine și lucruri pe care arameii le aruncaseră "},{"t":"în goana lor","w":"în goana lor","heb":"בְּחָפְזָם","translit":"behafzam","strong":"H2648","pos":"verb, qal infinitiv + sufix","def_ro":"în graba lor, în fuga lor panicată.","diff_ro":"Septuaginta are „ἐν τῷ θαμβεῖσθαι αὐτούς\" („în înspăimântarea lor\"), nu „în goana lor\" (hafzam, grabă) ca în ebraică — accentul cade pe teroare, nu pe viteza fugii.","dict_ro":"Hafaz — „a se grăbi cu spaimă”, graba celui care fuge îngrozit; Metzudat Țion compară cu fuga doicii lui Mefiboșet, „în graba ei de a fugi” (2 Samuel 4:4). Metzudat David explică de ce drumul era plin de lucruri: arameii își aruncau poverile ca să fugă mai ușor. Drumul până la Iordan, presărat cu haine și vase, devine dovada vizibilă că tabăra fusese părăsită cu adevărat, nu o capcană."},{"t":"; și solii s-au întors și i-au vestit regelui."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „În goana lor” — în graba lor de a fugi."},{"author":"Metzudat David","text":"„Pe care le aruncaseră” — ca să-și ușureze povara, din pricina grabei fugii."},{"author":"Metzudat Țion","text":"„Behofzam” — cu sensul de grabă, ca în „și în graba ei de a fugi” (2 Samuel 4:4)."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיֵּלְכוּ אַחֲרֵיהֶם עַד־הַיַּרְדֵּן וְהִנֵּה...","translation":"„I-au urmărit până la Iordan și...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐπορεύθησαν ὀπίσω αὐτῶν ἕως τοῦ ᾿Ιορδάνου, καὶ ἰδοὺ πᾶσα ἡ ὁδὸς πλήρης ἱματίων καὶ σκευῶν, ὧν ἔρριψε Συρία ἐν τῷ θαμβεῖσθαι αὐτούς· καὶ ἐπέστρεψαν οἱ ἄγγελοι καὶ ἀνήγγειλαν τῷ βασιλεῖ.","greek":true,"translation":"„Și au mers după ei până la Iordan, și iată, tot drumul era plin de haine și vase, pe care le aruncase Siria în spaima lor; și s-au întors solii și au vestit regelui.”","note":"Septuaginta redă „în graba lor” prin „în spaima lor” (ἐν τῷ θαμβεῖσθαι), punând accentul pe groază, nu pe grabă — de altfel, ambele nuanțe sunt prezente în verbul ebraic hafaz."}],"refs":["Estera 1:7","Iov 2:4","Isaia 2:20","Isaia 31:7"]},{"v":"7:16","t":"Poporul a ieșit și a prădat tabăra arameilor; iar o măsură de făină fină costa un siclu și două măsuri de orz costau un siclu – după cuvântul DOMNULUI.","tokens":[{"t":"Poporul a ieșit și a prădat tabăra arameilor; iar "},{"t":"o măsură de făină fină","w":"o măsură de făină fină","heb":"סְאָה","translit":"sea","strong":"H5429","pos":"substantiv, feminin singular","def_ro":"o sea (măsură de capacitate) de făină aleasă.","greek":"μέτρον σεμιδάλεως (metron semidaleos)","greek_def_ro":"μέτρον σεμιδάλεως (metron semidaleos) — o măsură de făină fină.","dict_ro":"Sea — unitate de măsură pentru cereale, a treia parte dintr-o efa (cam 7-13 litri, după diferite estimări); solet e făina cea mai fină, cea folosită la ofrandele de la Templu. Cu o zi înainte, în foametea asediului, un cap de măgar se vindea cu optzeci de sicli de argint (2 Împărați 6:25); acum, într-o singură zi, prețurile scad exact la nivelul vestit de Elișa (7:1) — „după cuvântul DOMNULUI”, cum subliniază textul."},{"t":" costa un siclu și două măsuri de orz costau un siclu – după cuvântul DOMNULUI."}],"commentaries":[],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיֵּצֵא הָעָם וַיָּבֹזּוּ אֵת...","translation":"„Poporul a ieșit și a prădat...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐξῆλθεν ὁ λαὸς καὶ διήρπασαν τὴν παρεμβολὴν Συρίας, καὶ ἐγένετο μέτρον σεμιδάλεως σίκλου, κατὰ τὸ ρῆμα Κυρίου, καὶ δίμετρον κριθῶν σίκλου.","greek":true,"translation":"„Și a ieșit poporul și a prădat tabăra Siriei, și a fost o măsură de făină aleasă un siclu, după cuvântul Domnului, și două măsuri de orz un siclu.”","note":"Septuaginta mută formula „după cuvântul Domnului” între cele două prețuri, în loc să o lase la sfârșitul versetului."}],"refs":["2 Împărați 7:1","1 Samuel 17:53","2 Cronici 20:25","Isaia 33:1,4,23","Numeri 23:19","Matei 24:35"]},{"v":"7:17","t":"Regele încredințase paza porții ofițerului pe mâna căruia se sprijinea; oamenii l-au călcat în picioare la poartă și el a murit, după cum vorbise omul lui Dumnezeu, și [după cum] vorbise el când regele coborâse la el.","tokens":[{"t":"Regele încredințase paza porții "},{"t":"ofițerului","w":"ofițerului","heb":"הַשָּׁלִישׁ","translit":"hașaliș","strong":"H7991","pos":"substantiv, masculin singular","def_ro":"ofițerul, adjutantul regelui (al treilea om din car).","greek":"τριστάτης (tristates)","greek_def_ro":"τριστάτης (tristates) — ofițer, al treilea în rang.","dict_ro":"Șaliș — din rădăcina „trei”: la origine „al treilea om” din carul de luptă, apoi ofițer de rang înalt, adjutant personal; de aici și redarea greacă „tristatis”. E ofițerul care își bătuse joc de profeția lui Elișa (7:2). Rashi precizează că „mâna pe care se sprijinea regele” se referă la ziua dinainte, când regele venise la casa lui Elișa; Metzudat David explică moartea lui: mulțimea care se grăbea spre pradă l-a călcat în picioare la poartă, din pricina îmbulzelii."},{"t":" pe mâna căruia se sprijinea; oamenii l-au călcat în picioare la poartă și el a murit, după cum vorbise omul lui Dumnezeu, și [după cum] vorbise el când regele coborâse la el."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Pe mâna căruia se sprijinea” — în ziua dinainte, când venise la casa lui Elișa."},{"author":"Metzudat David","text":"„Încredințase” — l-a numit atunci să fie paznicul porții. „L-au călcat în picioare” — din pricina marii îmbulzeli, poporul care mergea să ia pradă l-a călcat cu picioarele."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְהַמֶּלֶךְ הִפְקִיד אֶת־הַשָּׁלִישׁ אֲשֶׁר־נִשְׁעָן...","translation":"„Regele încredințase paza porții ofițerului pe...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ὁ βασιλεὺς κατέστησε τὸν τριστάτην, ἐφ᾿ ὃν ὁ βασιλεὺς ἐπανεπαύσατο τῇ χειρὶ αὐτοῦ, ἐπὶ τῆς πύλης. καὶ συνεπάτησεν αὐτὸν ὁ λαὸς ἐν τῇ πύλῃ, καὶ ἀπέθανε, καθὰ ἐλάλησεν ὁ ἄνθρωπος τοῦ Θεοῦ, ὃς ἐλάλησεν ἐν τῷ καταβῆναι τὸν ἄγγελον πρὸς αὐτόν.","greek":true,"translation":"„Și regele l-a pus pe tristat, pe a cărui mână se sprijinea regele, peste poartă; și l-a călcat poporul în poartă, și a murit, după cum grăise omul lui Dumnezeu, care grăise când coborâse solul la el.”","note":"Divergență reală la final: Septuaginta are „când coborâse solul (ἄγγελον) la el”, acolo unde Textul Masoretic are „când coborâse regele la el” — diferența dintre malah (sol) și meleh (rege), care apare și la 2 Împărați 6:33."}],"refs":["2 Împărați 9:33","Judecători 20:43","Mica 7:10"]},{"v":"7:18","t":"Și s-a împlinit întocmai cum îi profetise omul lui Dumnezeu regelui, spunând: „Două măsuri de orz vor costa un siclu și o măsură de făină fină va costa un siclu mâine pe vremea aceasta, la poarta Samariei.”","tokens":[{"t":"Și s-a împlinit întocmai cum îi profetise omul lui Dumnezeu regelui, spunând: „Două măsuri de orz vor costa un siclu și o măsură de făină fină va costa un siclu "},{"t":"mâine pe vremea aceasta","w":"mâine pe vremea aceasta","heb":"כָּעֵת מָחָר","translit":"kaēt mahar","strong":"H4279","pos":"substantiv, masculin și feminin singular + substantiv, masculin singular","def_ro":"mâine, la ora aceasta.","greek":"ὡς ἡ ὥρα αὔριον (hos he hora aurion)","greek_def_ro":"ὡς ἡ ὥρα αὔριον (hos he hora aurion) — ca la ceasul de mâine.","dict_ro":"Mahar — „mâine”; precizia temporală a profeției (nu „curând”, ci „mâine la ora aceasta”, „la poarta Samariei”) face ca împlinirea să fie verificabilă de oricine. Metzudat David explică de ce naratorul repetă profeția întreagă: ca să lămurească de ce a vestit profetul și moartea ofițerului — pentru că acesta își bătuse joc de un cuvânt atât de precis al lui Dumnezeu."},{"t":", la poarta Samariei.”"}],"commentaries":[{"author":"Metzudat David","text":"„Și s-a împlinit întocmai” — [Scriptura] revine și explică de ce a spus profetul că ofițerul va muri, zicând: pentru că, atunci când a vorbit omul lui Dumnezeu..."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיְהִי כְּדַבֵּר אִישׁ הָאֱלֹהִים...","translation":"„Și s-a împlinit întocmai cum îi...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐγένετο καθὰ ἐλάλησεν ῾Ελισαιὲ πρὸς τὸν βασιλέα λέγων· δίμετρον κριθῆς σίκλου καὶ μέτρον σεμιδάλεως σίκλου καὶ ἔσται ὡς ἡ ὥρα αὔριον ἐν τῇ πύλῃ Σαμαρείας·","greek":true,"translation":"„Și a fost după cum grăise Elisaie către rege, zicând: două măsuri de orz un siclu și o măsură de făină aleasă un siclu, și va fi mâine la ora aceasta în poarta Samariei.”","note":"Septuaginta înlocuiește „omul lui Dumnezeu” cu numele „Elisaie”."}],"refs":["2 Împărați 7:1,2","2 Împărați 6:32","Geneza 18:14"]},{"v":"7:19","t":"Iar acel ofițer îi răspunsese omului lui Dumnezeu și spusese: „Privește, chiar dacă DOMNUL ar face ferestre în ceruri, s-ar putea oare întâmpla așa ceva?” Dar [profetul] a spus: „Vei vedea cu ochii tăi, dar tu nu vei mânca din ele!”","tokens":[{"t":"Iar acel ofițer îi răspunsese omului lui Dumnezeu și spusese: „Privește, chiar dacă DOMNUL ar face "},{"t":"ferestre în ceruri","w":"ferestre în ceruri","heb":"אֲרֻבּוֹת","translit":"arubot","strong":"H699","pos":"substantiv, feminin plural","def_ro":"deschizături, zăgazuri în cer.","diff_ro":"Septuaginta are „καταράκτας\" („cataracte/zăgazuri\"), nu „ferestre\" (arubot) ca în ebraică — o imagine diferită pentru deschiderile prin care ar putea curge belșugul din ceruri.","dict_ro":"Arubot — „ferestre, zăgazuri”, aceleași „stăvilare ale cerurilor” care se deschid la potop (Geneza 7:11) și pe care Maleahi le promite deschise pentru binecuvântare (Maleahi 3:10). Batjocura ofițerului e totală: nici dacă DOMNUL ar deschide cerul ca la potop n-ar putea scădea prețurile peste noapte. Răspunsul profetului — „vei vedea, dar nu vei mânca” — face din necredință însăși pedeapsa: martor al minunii, dar exclus de la ea."},{"t":", s-ar putea oare întâmpla așa ceva?” Dar [profetul] a spus: „Vei vedea cu ochii tăi, dar tu nu vei mânca din ele!”"}],"commentaries":[{"author":"Metzudat David","text":"„Și a răspuns” — atunci ofițerul a răspuns... „Și a spus” — atunci profetul i-a spus: „vei vedea cu ochii tăi...”."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיַּעַן הַשָּׁלִישׁ אֶת־אִישׁ הָאֱלֹהִים...","translation":"„Iar acel ofițer îi răspunsese omului...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἀπεκρίθη ὁ τριστάτης τῷ ῾Ελισαιὲ καὶ εἶπεν· ἰδοὺ Κύριος ποιεῖ καταράκτας ἐν τῷ οὐρανῷ, μὴ ἔσται τὸ ρῆμα τοῦτο; καὶ εἶπεν ῾Ελισαιέ· ἰδοὺ ὄψῃ τοῖς ὀφθαλμοῖς σου καὶ ἐκεῖθεν οὐ μὴ φάγῃ.","greek":true,"translation":"„Și a răspuns tristatul lui Elisaie și a zis: iată, Domnul face cataracte în cer — oare va fi lucrul acesta? Și a zis Elisaie: iată, vei vedea cu ochii tăi, dar de acolo nicidecum nu vei mânca.”","note":"Septuaginta folosește pentru „ferestre” cuvântul καταράκτας — același termen ca la „cataractele cerului” din relatarea potopului (Geneza 7:11) —, numește explicit pe Elisaie ca vorbitor și întărește negația finală („nicidecum”, οὐ μὴ)."}],"refs":[]},{"v":"7:20","t":"Și într-adevăr așa a pățit: poporul l-a călcat în picioare la poartă și el a murit.","tokens":[{"t":"Și într-adevăr așa a pățit: poporul "},{"t":"l-a călcat în picioare","w":"l-a călcat în picioare","heb":"וַיִּרְמְסוּ","translit":"vairmesu","strong":"H7429","pos":"verb, qal imperfect consecutiv","def_ro":"l-au călcat în picioare, l-au strivit.","greek":"συμπατέω (sympateo)","greek_def_ro":"συμπατέω (sympateo) — a călca în picioare.","dict_ro":"Ramas — „a călca în picioare, a zdrobi sub tălpi”; cuvântul revine identic din v. 17, ca o pecete a împlinirii. Metzudat David rezumă întregul verset în patru cuvinte: „cum a spus profetul, așa a fost”. Haftara se încheie astfel cu două împliniri paralele ale aceluiași cuvânt profetic: îndestularea poporului și moartea celui care l-a batjocorit."},{"t":" la poartă și el a murit."}],"commentaries":[{"author":"Metzudat David","text":"„Și într-adevăr așa a pățit” — cum a spus profetul, așa a fost."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיְהִי־לוֹ כֵּן וַיִּרְמְסוּ אֹתוֹ...","translation":"„Și într-adevăr așa a pățit: poporul...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐγένετο οὕτως, καὶ συνεπάτησεν αὐτὸν ὁ λαὸς ἐν τῇ πύλῃ καὶ ἀπέθανε.","greek":true,"translation":"„Și a fost așa: și l-a călcat poporul în poartă, și a murit.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Numeri 20:12","2 Cronici 20:20","Isaia 7:9","Evrei 3:18,19"]}]},{"num":7,"title":"Aharéi Mot - După moarte","ref":"Amos 9:7-15","intro":"Haftarat Aharéi Mot se leagă de pericopa omonimă prin tema exilului pe care poporul îl va îndura pentru păcatele sale. Amos începe cu o întrebare incomodă: nu sunt fiii lui Israel pentru DOMNUL ca oricare alt popor, dacă nu se întorc la El? Pedeapsa va lovi însă regatul păcătos și pe păcătoșii încrezători că „răul nu ne va ajunge” — nu legământul cu poporul: casa lui Iacov va fi cernută printre neamuri ca într-o sită, dar nu va fi nimicită. Profeția se încheie cu una dintre cele mai luminoase imagini din profeți: coliba căzută a lui David ridicată din nou, un belșug în care plugarul îl ajunge pe secerător, cetățile pustii rezidite și Israel sădit în pământul lui, fără să mai fie vreodată smuls din el. Tradiția sefardă citește această haftara la Kedoșim; tradiția așkenază, la Aharéi Mot sau când cele două pericope se citesc împreună.","verses":[{"v":"9:7","t":"Nu sunteți voi oare pentru Mine ca și copiii etiopienilor, copii ai lui Israel? – rostirea DOMNULUI. Nu l-am scos Eu oare pe Israel din țara Egiptului, pe filisteni din Caftor și pe Aram din Kir?","tokens":[{"t":"Nu sunteți voi oare pentru Mine ca și copiii "},{"t":"etiopienilor","w":"etiopienilor","heb":"כֻשִׁיִּים","translit":"hușim","strong":"H3569","pos":"nume de neam","def_ro":"cușiți, etiopieni — locuitorii țării Cuș.","greek":"Αἰθίοψ (Aithiops)","greek_def_ro":"Αἰθίοψ (Aithiops) — etiopian.","dict_ro":"Cușiim — urmașii lui Cuș, fiul lui Ham (Geneza 10:6), locuitorii ținutului de la sud de Egipt; Metzudat Țion îi descrie simplu: „oamenii negri, din fiii lui Cuș”. Comparația a primit interpretări foarte diferite: Rashi o leagă de Ieremia 13:23 („poate un cușit să-și schimbe pielea?”) — sunteți la fel de neschimbați în răutatea voastră; Metzudat David și Radak văd în cușiți imaginea robilor pe viață: cum ei aparțin stăpânilor, așa Israel, răscumpărat din casa robiei, Îi aparține lui Dumnezeu pentru totdeauna."},{"t":", copii ai lui Israel? – rostirea DOMNULUI. Nu l-am scos Eu oare pe Israel din țara Egiptului, pe filisteni din Caftor și pe Aram din Kir?"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Nu sunteți voi oare pentru Mine ca fiii cușiților” — de ce M-aș opri să vă pedepsesc, de vreme ce nu vă întoarceți la Mine? Oare nu veniți și voi din fiii lui Noe, ca celelalte neamuri? Ca cușiții, cu care v-ați asemănat, precum s-a spus: „poate un cușit să-și schimbe pielea?... tot așa ați putea voi să faceți binele” (Ieremia 13:23). „Nu l-am scos Eu” — oare nu din bunătatea Mea a fost începutul alegerii voastre, scoaterea din țara Egiptului? Și ce-Mi pasă de aceasta? Și pe filisteni i-am scos la fel din Caftor... și totuși nu i-am făcut poporul Meu."},{"author":"Metzudat David","text":"„Nu sunteți voi oare ca fiii cușiților” — precum fiii cușiților sunt robi ai stăpânilor lor pe vecie, așa sunteți voi robii Mei în toate zilele, căci v-am scos din țara Egiptului, din casa robiei. „Și pe filisteni din Caftor” — adică: oare i-am ridicat Eu pe filisteni din locul în care fuseseră exilați? Ca și cum ar spune: de vreme ce n-am făcut și nu voi face pentru alt neam ce am făcut pentru voi, sunteți dobândiți ai Mei ca robi."},{"author":"Radak (1160–1235)","text":"Radak: ca fiii cușiților, care sunt robi — oamenii negri din fiii lui Cuș, fiul lui Ham, care sunt vânduți ca robi — tot așa se cuvenea să fiți voi robii Mei, căci v-am dobândit din casa robiei. Iar despre filisteni și aram: oare i-am ridicat Eu din exilul lor așa cum v-am ridicat pe voi din Egipt? Pe ei i-am exilat din pricina iubirii Mele pentru voi, căci erau vecinii voștri și v-au făcut mult rău, și nu i-am mai adus înapoi."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"הֲלוֹא כִבְנֵי כֻשִׁיִּים אַתֶּם...","translation":"„Nu sunteți voi oare pentru Mine...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"οὐχ ὡς υἱοὶ Αἰθιόπων ὑμεῖς ἐστε ἐμοί, υἱοὶ ᾿Ισραήλ; λέγει Κύριος. οὐ τὸν ᾿Ισραὴλ ἀνήγαγον ἐκ γῆς Αἰγύπτου καὶ τοὺς ἀλλοφύλους ἐκ Καππαδοκίας καὶ τοὺς Σύρους ἐκ βόθρου;","greek":true,"translation":"„Nu sunteți voi pentru Mine ca fiii etiopienilor, fii ai lui Israel? zice Domnul. Nu l-am scos Eu pe Israel din țara Egiptului, și pe cei de alt neam din Capadocia, și pe sirieni din groapă?”","note":"Septuaginta redă „Caftor” prin „Capadocia” și „Kir” prin „groapă” (βόθρου) — o interpretare a numelui de loc ca substantiv comun; „filistenii” devin generic „cei de alt neam” (ἀλλόφυλοι), ca în toată Septuaginta."}],"refs":["Ieremia 9:25,26","Ieremia 13:23","Amos 2:10","Deuteronom 2:23","Amos 1:5","2 Împărați 16:9"]},{"v":"9:8","t":"Iată, ochii Stăpânului meu, Domnul DUMNEZEU, sunt asupra monarhiei păcătoase și o voi nimici de pe fața pământului. Dar nu voi nimici casa lui Iacov – rostirea DOMNULUI.","tokens":[{"t":"Iată, ochii Stăpânului meu, Domnul DUMNEZEU, sunt asupra "},{"t":"monarhiei păcătoase","w":"monarhiei păcătoase","heb":"בַּמַּמְלָכָה","translit":"bamamlaha","strong":"H4467","pos":"substantiv, feminin singular","def_ro":"regatul păcătos, domnia vinovată.","greek":"βασιλεία τῶν ἁμαρτωλῶν (basileia ton hamartolon)","greek_def_ro":"βασιλεία τῶν ἁμαρτωλῶν (basileia ton hamartolon) — monarhia păcătoșilor.","dict_ro":"Mamlaha — regatul, domnia; Radak și Metzudat David o identifică cu regatul lui Efraim (Israelul de nord), în care toți regii, de la Ieroboam fiul lui Nebat până la Hoșea fiul lui Ela, au fost răi. Distincția versetului e esențială: e nimicită instituția regală vinovată, nu poporul — „dar nu voi nimici cu totul casa lui Iacov”; Rashi precizează că regatul este casa lui Iehu. Introducerea ediției Rosen rezumă chiar această idee: pedeapsa îi lovește pe regi și conducători, legământul cu poporul rămâne veșnic."},{"t":" și o voi nimici de pe fața pământului. Dar nu voi nimici casa lui Iacov – rostirea DOMNULUI."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Și o voi nimici” — regatul este casa lui Iehu; dar casa lui Iacov n-o voi nimici."},{"author":"Metzudat David","text":"„Iată, ochii Stăpânului” — adică: de vreme ce așa stau lucrurile și voi ați păcătuit împotriva Mea, iată, ochii DOMNULUI și purtarea Lui de grijă sunt asupra regatului păcătos, adică regatul lui Efraim, ca să-l nimicească. „Dar nu” — doar că nu voi nimici casa lui Iacov, mulțimea poporului; numai domnia o voi nimici, și nu vor mai avea rege."},{"author":"Radak (1160–1235)","text":"Radak: „Regatul păcătos” — este regatul lui Efraim, căci toți regii au fost răi și păcătoși, de la Ieroboam fiul lui Nebat până la Hoșea fiul lui Ela. „Și o voi nimici” — domnia o voi nimici, ca să nu mai fie din ei rege, dar casa lui Iacov n-o voi nimici."},{"author":"Metzudat Țion","text":"„Efes” — înseamnă „doar”, ca în „doar cuvântul [pe care ți-l voi spune]” (Numeri 22)."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"הִנֵּה עֵינֵי אֲדֹנָי יְהוִה...","translation":"„Iată, ochii Stăpânului meu, Domnul DUMNEZEU...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"᾿Ιδοὺ οἱ ὀφθαλμοὶ Κυρίου τοῦ Θεοῦ ἐπὶ τὴν βασιλείαν τῶν ἁμαρτωλῶν καὶ ἐξαρῶ αὐτὴν ἀπὸ προσώπου τῆς γῆς· πλὴν ὅτι οὐκ εἰς τέλος ἐξαρῶ τὸν οἶκον ᾿Ιακώβ, λέγει Κύριος.","greek":true,"translation":"„Iată, ochii Domnului Dumnezeu sunt asupra împărăției păcătoșilor, și o voi stârpi de pe fața pământului; numai că nu voi stârpi până la capăt casa lui Iacov, zice Domnul.”","note":"Septuaginta redă „monarhia păcătoasă” prin „împărăția păcătoșilor” și traduce corect infinitivul absolut ebraic (lo hașmeid așmid) prin „nu... până la capăt” (οὐκ εἰς τέλος)."}],"refs":["Amos 9:4","Psalmii 11:4-6","Proverbe 15:3","Osea 1:6","Ieremia 30:11","Romani 11:1-7,28,29"]},{"v":"9:9","t":"Căci iată, poruncesc: Voi scutura casa lui Israel între toate neamurile, precum se scutură [grânele] într-o sită și nicio piatră nu va cădea la pământ.","tokens":[{"t":"Căci iată, poruncesc: Voi scutura casa lui Israel între toate neamurile, precum se scutură [grânele] "},{"t":"într-o sită","w":"într-o sită","heb":"בַּכְּבָרָה","translit":"bakvara","strong":"H3531","pos":"substantiv, feminin singular","def_ro":"în sită, în ciur.","diff_ro":"Septuaginta are „ἐν τῷ λικμῷ\" („în lopata de vânturat\"), nu „într-o sită\" (kevara) ca în ebraică — un alt instrument agricol pentru aceeași imagine a cernerii.","dict_ro":"Kevara — sita sau ciurul în care se cerne grâul; Metzudat Țion o compară cu sita de făină și cu „grătarul” (mikhbar) al altarului (Exodul 27:4). Imaginea e dublă: exilul îl va scutura pe Israel printre toate neamurile, dar sita păstrează ce e prețios. Radak și Metzudat David explică: praful și pleava cad prin găuri, dar boabele bune și pietricelele mari rămân sus — tot așa vor pieri în exil păcătoșii, dar cei drepți nu se vor pierde, ci vor vedea mântuirea."},{"t":" și nicio piatră nu va cădea la pământ."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Căci iată, poruncesc” — să-i exilez printre toate neamurile, o risipire neobișnuit de mare. „Precum se scutură” — ce se cerne cu sita, după ce tărâța fină a ieșit din ea și rămâne cea groasă, care nu poate ieși, și atunci cel ce scutură o scutură din toate puterile."},{"author":"Metzudat David","text":"„Și voi scutura” — îi voi clătina pe Israel în exil printre neamuri, precum se scutură grânele în sită ca să cadă țărâna prin găurile ei; și cu toate acestea, pietricelele mari nu cad pe pământ prin găurile sitei, căci găurile sunt prea strâmte pentru ele. Tot așa Israel: chiar dacă vor fi rătăcitori și pribegi în exil, nu se vor sfârși acolo cei drepți, ci doar cei nelegiuiți și răzvrătiți."},{"author":"Radak (1160–1235)","text":"Radak: așa cum se clatină bobul de grâu în sită, iar țărâna și pleava cad la pământ, și boabele bune, cele mari, rămân sus — tot așa Israel va fi clătinat și purtat printre toate neamurile, și nu vor cădea la pământ decât păcătoșii dintre ei, asemenea țărânii și plevei, care n-au nădejde în mântuire; ceilalți, care vor fi vii în vremea mântuirii, și cei ce vor muri în exil cu pocăință, toți vor vedea mântuirea."},{"author":"Metzudat Țion","text":"„Bakevara” — un fel de sită în care se cerne făina, asemenea lui „și să-i faci un grătar” (Exod 27:4). „Țeror” — o bucată groasă de pământ."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"כִּי־הִנֵּה אָנֹכִי מְצַוֶּה וַהֲנִעוֹתִי...","translation":"„Căci iată, poruncesc: Voi scutura casa...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"διότι ἰδοὺ ἐγὼ ἐντέλλομαι καὶ λικμήσω ἐν πᾶσι τοῖς ἔθνεσι τὸν οἶκον ᾿Ισραήλ, ὃν τρόπον λικμᾶται ἐν τῷ λικμῷ καὶ οὐ μὴ πέσῃ σύντριμμα ἐπὶ τὴν γῆν.","greek":true,"translation":"„Căci iată, Eu poruncesc și voi vântura casa lui Israel printre toate neamurile, precum se vântură cu lopata de vânturat, și nu va cădea nicio fărâmă pe pământ.”","note":"Septuaginta schimbă imaginea din „cernere în sită” în „vânturare” (λικμάω) și redă „piatră” (țeror) prin „fărâmă” (σύντριμμα)."}],"refs":["Levitic 26:33","Deuteronom 28:64"]},{"v":"9:10","t":"De sabie vor peri toți păcătoșii din poporul Meu, aceia care spun: „Răul nu se va apropia de noi și nu ne va ajunge!”","tokens":[{"t":"De sabie vor peri toți "},{"t":"păcătoșii","w":"păcătoșii","heb":"חַטָּאֵי","translit":"hataē","strong":"H2400","pos":"adjectiv, masculin plural","def_ro":"păcătoșii, cei vinovați.","greek":"ἁμαρτωλός (hamartolos)","greek_def_ro":"ἁμαρτωλός (hamartolos) — păcătos.","dict_ro":"Hataim — păcătoșii statornici, cei al căror caracter e definit de păcat. Radak precizează că profetul nu vorbește despre toți păcătoșii, ci despre cei care spuneau „răul nu se va apropia de noi” — care negau legătura dintre faptă și urmare și socoteau orice nenorocire o simplă întâmplare, cum avertizează Tora: „dacă veți umbla cu Mine la întâmplare” (Leviticul 26:21). Metzudat David rezumă: ei spuneau că nu există răsplată și pedeapsă."},{"t":" din poporul Meu, aceia care spun: „Răul nu se va apropia de noi și nu ne va ajunge!”"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Răul nu se va apropia și nu ne va ajunge” — din pricina nelegiuirilor noastre, răul nu se va grăbi să se apropie și să vină."},{"author":"Metzudat David","text":"„De sabie vor peri” — cei ce vor muri de sabia neamurilor vor fi toți păcătoșii din poporul Meu, care spun: nu va veni răul asupra noastră, căci nu există răsplată și pedeapsă; dar cei drepți vor rămâne și sabia nu-i va mistui."},{"author":"Radak (1160–1235)","text":"Radak: profetul a vorbit despre păcătoșii din generația lui, și nu despre toți păcătoșii, căci mulți dintre ei au fost exilați, ci despre cei care spuneau „răul nu se va apropia și nu ne va ajunge”: deznădăjduiau de pedeapsă și ziceau: vom face după pofta inimii noastre, iar dacă va veni răul, nu va veni din pricina faptelor noastre, ci e o întâmplare în lume, precum a spus Tora: „și veți umbla cu Mine la întâmplare”."},{"author":"Metzudat Țion","text":"„Tagiș” — cu sensul de apropiere. „Vetakdim” — cu sensul de grabă. „Baadeinu” — adică asupra noastră."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"בַּחֶרֶב יָמוּתוּ כֹּל חַטָּאֵי...","translation":"„De sabie vor peri toți păcătoșii...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ἐν ρομφαίᾳ τελευτήσουσι πάντες ἁμαρτωλοὶ λαοῦ μου οἱ λέγοντες· οὐ μὴ ἐγγίσῃ οὐδ᾿ οὐ μὴ γένηται ἐφ᾿ ἡμᾶς τὰ κακά.","greek":true,"translation":"„De sabie vor muri toți păcătoșii poporului Meu, cei ce zic: nicidecum nu se vor apropia și nicidecum nu vor veni asupra noastră relele.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Isaia 33:14","Ezechiel 20:38","Psalmii 10:11","Eclesiastul 8:11"]},{"v":"9:11","t":"În ziua aceea, voi ridica coliba prăbușită a lui David, voi repara crăpăturile ei și îi voi ridica ruinele și o voi reclădi cum era în zilele de odinioară,","tokens":[{"t":"În ziua aceea, voi ridica "},{"t":"coliba prăbușită a lui David","w":"coliba prăbușită a lui David","heb":"סֻכַּת","translit":"sukat","strong":"H5521","pos":"substantiv, feminin singular construct","def_ro":"coliba căzută, cortul prăbușit.","greek":"σκηνὴ Δαυίδ ἡ πεπτωκυῖα (skene Dauid he peptokyia)","greek_def_ro":"σκηνὴ Δαυίδ ἡ πεπτωκυῖα (skene Dauid he peptokyia) — coliba lui David, cea prăbușită.","dict_ro":"Suka — coliba de ramuri, adăpostul fragil (același cuvânt ca la sărbătoarea Sucot); Radak explică imaginea: domnia lui David e numită „colibă” pentru că îl acoperă și îl adăpostește pe popor, iar Targum Ionatan, citat de Rashi, traduce direct „regatul casei lui David”. Talmudul (Sanhedrin 96b-97a) numește de aici pe Mesia „bar nifli” — „fiul celei căzute”. Iacov, fratele Domnului, citează versetul la Sinodul din Ierusalim (Faptele apostolilor 15:16-17), după forma lui din Septuaginta."},{"t":", voi repara crăpăturile ei și îi voi ridica ruinele și o voi reclădi cum era în zilele de odinioară,"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „În ziua aceea” — după ce toate acestea vor veni asupra lui, va veni ziua aceea, ziua hotărâtă pentru mântuire, și atunci... „Voi ridica coliba prăbușită a lui David” — Ionatan traduce: regatul casei lui David."},{"author":"Metzudat David","text":"„În ziua aceea” — când se vor sfârși nelegiuiții. „Voi ridica” — adică voi întoarce domnia la casa lui David, care a căzut și a fost umilită în zilele exilului. „Și ruinele” — ceea ce a fost dărâmat din domnia casei lui David în toate zilele exilului, în care n-au domnit deloc, atunci o voi ridica și o voi zidi ca să fie zidită și întocmită ca în zilele de odinioară, adică așa cum a fost în zilele lui David însuși."},{"author":"Radak (1160–1235)","text":"Radak: „În ziua aceea” — în ziua mântuirii voi ridica coliba căzută a lui David; pentru că a spus că domnia lui Efraim va înceta, a spus că domnia lui David se va ridica. Iar ea e numită „colibă” ca pildă, pentru că acoperă poporul [ca un adăpost]."},{"author":"Talmud Bavli, Sanhedrin 96b-97a","text":"Rav Nahman i-a spus lui Rabi Ițhak: ai auzit când va veni „bar nifli”? Rabi Ițhak i-a spus: cine este bar nifli? I-a răspuns: Mesia. Îl numești pe Mesia „bar nifli”? Da, căci scrie: „În ziua aceea voi ridica coliba lui David cea căzută (hanofelet)” (Amos 9:11) — de aceea Mesia e numit „fiul celei căzute”."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"בַּיּוֹם הַהוּא אָקִים אֶת־סֻכַּת...","translation":"„În ziua aceea, voi ridica coliba...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ἐν τῇ ἡμέρᾳ ἐκείνῃ ἀναστήσω τὴν σκηνὴν Δαυὶδ τὴν πεπτωκυῖαν καὶ ἀνοικοδομήσω τὰ πεπτωκότα αὐτῆς καὶ τὰ κατεσκαμμένα αὐτῆς ἀναστήσω καὶ ἀνοικοδομήσω αὐτὴν καθὼς αἱ ἡμέραι τοῦ αἰῶνος,","greek":true,"translation":"„În ziua aceea voi ridica cortul lui David cel căzut și voi rezidi cele căzute ale lui și cele dărâmate ale lui le voi ridica și îl voi rezidi ca în zilele veacului,”","note":"Corespondență strânsă; „coliba” e redată prin „cort” (σκηνή), iar „crăpăturile” prin „cele căzute”."}],"refs":["Faptele apostolilor 15:15-17","Isaia 9:6,7","Ieremia 23:5,6","Ezechiel 34:23,24","Osea 3:5","Isaia 16:5"]},{"v":"9:12","t":"pentru ca să cucerească rămășița Edomului și toate neamurile, căci numele Meu este asupra lor – rostirea DOMNULUI care înfăptuiește aceasta.","tokens":[{"t":"pentru ca să cucerească "},{"t":"rămășița Edomului","w":"rămășița Edomului","heb":"שְׁאֵרִית","translit":"șeērit","strong":"H7611","pos":"substantiv, feminin singular construct","def_ro":"rămășița lui Edom, ce a rămas din Edom.","dict_ro":"Una dintre cele mai cunoscute și influente divergențe din toată Septuaginta: textul grecesc are aici „οἱ κατάλοιποι τῶν ἀνθρώπων\" („rămășița OAMENILOR/omenirii\"), nu „rămășița Edomului\" ca în ebraică — o confuzie veche între consoanele ebraice pentru „Edom\" (אדום) și „adam\" (אדם, „om\"). Această variantă e citată explicit de apostolul Iacov la Sinodul de la Ierusalim, în cartea Faptele Apostolilor, ca argument biblic pentru primirea neamurilor (non-iudeilor) în Biserică — un exemplu rar în care o diferență textuală minoră a avut consecințe teologice și istorice majore."},{"t":" și toate neamurile, căci numele Meu este asupra lor – rostirea DOMNULUI care înfăptuiește aceasta."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Pentru ca să cucerească” — [adică] Israel [să moștenească] rămășița Edomului etc., pentru că numele Meu este chemat asupra lor; „așer” are aici sensul de „căci”."},{"author":"Metzudat David","text":"„Pentru ca să cucerească” — versetul e inversat, ca și cum ar fi spus: „ca să moștenească cei peste care e chemat numele Meu”; adică domnia va fi astfel încât poporul peste care e chemat numele Meu, ca să fie numit poporul DOMNULUI, să moștenească rămășița ce va rămâne din toate neamurile. „Care înfăptuiește aceasta” — Cel ce face binele acela."},{"author":"Radak (1160–1235)","text":"Radak: voi zidi [coliba] ca în zilele de odinioară, ca să-i moștenească pe dușmanii lor vecini — Edom, filisteni, Moab și Amon, adică „toate neamurile”; căci David, regele lui Israel, a pus garnizoane în Edom și i-a supus pe toți ceilalți înaintea lui, și tot așa va fi în viitor. „Care înfăptuiește aceasta” — hotărârea pe care am rostit-o o voi împlini, căci puterea e în mâna Mea."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"לְמַעַן יִירְשׁוּ אֶת־שְׁאֵרִית אֱדוֹם...","translation":"„pentru ca să cucerească rămășița Edomului...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ὅπως ἐκζητήσωσιν οἱ κατάλοιποι τῶν ἀνθρώπων καὶ πάντα τὰ ἔθνη, ἐφ᾿ οὓς ἐπικέκληται τὸ ὄνομά μου ἐπ᾿ αὐτούς, λέγει Κύριος ὁ Θεὸς ὁ ποιῶν πάντα ταῦτα.","greek":true,"translation":"„ca să caute [pe Domnul] rămășița oamenilor și toate neamurile peste care s-a chemat numele Meu, zice Domnul Dumnezeu, Cel ce face toate acestea.”","note":"Divergență majoră: Septuaginta are „ca să caute rămășița oamenilor”, acolo unde Textul Masoretic are „ca să cucerească rămășița Edomului” — traducătorii au citit Adam (oameni) în loc de Edom și idreșu (vor căuta) în loc de yirșu (vor moșteni). Forma greacă e cea citată în Faptele apostolilor 15:17."}],"refs":["Isaia 11:14","Obadia 1:18-21","Numeri 24:17","Maleahi 1:4","Isaia 43:7","Ieremia 14:9"]},{"v":"9:13","t":"Iată, vin zile – rostirea DOMNULUI – când cel care ară va întâlni pe cel care culege și cel care stoarce strugurii va întâlni pe cel care aduce semințele. Din munți va picura vin și dealurile se vor topi.","tokens":[{"t":"Iată, vin zile – rostirea DOMNULUI – când "},{"t":"cel care ară","w":"cel care ară","heb":"חוֹרֵשׁ","translit":"horēș","strong":"H2790","pos":"verb, qal participiu","def_ro":"plugarul, cel ce ară.","diff_ro":"Septuaginta are „ὁ ἀμητὸς\" („secerișul\"), nu „cel care ară\" (choresh, plugarul) ca în ebraică — imaginea devine „secerișul va întâlni culesul viei\", nu „plugarul îl va întâlni pe secerător\".","dict_ro":"Hareș — „a ara, a brăzda”; imaginea plugarului care îl ajunge pe secerător reia binecuvântarea din Leviticul 26:5 („treieratul vă va ține până la culesul viei”), dar o întrece: recolta va fi atât de mare încât seceratul nu se va termina până nu vine vremea aratului următor. Radak și Metzudat David citesc și „munții vor picura must” și „dealurile se vor topi” ca pilde ale belșugului — dealurile par să se topească din pricina laptelui care curge din turme (compară Ioel 3:18)."},{"t":" va întâlni pe cel care culege și cel care stoarce strugurii va întâlni pe cel care aduce semințele. Din munți va picura vin și dealurile se vor topi."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Cel care ară va întâlni pe cel care culege” — „treieratul vă va ține până la culesul viei, iar culesul viei până la semănat” (Levitic 26:5): nu vor termina de arat până nu vine secerișul, și nu vor termina de secerat până nu vine vremea semănatului. „Se vor topi” — Ionatan traduce: se vor despica; pământul lucrat se despică atunci când vin ploile. „Asis” — vin bun și dulce."},{"author":"Metzudat David","text":"„Cel care ară va întâlni pe cel care culege” — adică va crește multă recoltă și se vor ocupa cu seceratul până la vremea aratului, iar plugarul și secerătorul se vor apropia și se vor întâlni unul cu altul; la fel, cel ce calcă strugurii îl va întâlni pe cel ce duce sămânța la semănat. „Și dealurile se vor topi” — adică va fi pășune grasă și laptele va curge din turme, ca și cum dealurile s-ar topi din belșugul laptelui."},{"author":"Radak (1160–1235)","text":"Radak: atât de mare va fi recolta, încât se vor îndeletnici cu seceratul până la vremea aratului și se vor întâlni unul cu altul, plugarul cu secerătorul, după cum a spus Tora: „treieratul vă va ține până la culesul viei” — dar aceasta e mai mult. „Munții vor picura must” — ca pildă, din belșugul vinului și al roadelor, asemenea expresiei „[țară] în care curge lapte și miere”."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"הִנֵּה יָמִים בָּאִים נְאֻם־יְהוָה...","translation":"„Iată, vin zile – rostirea DOMNULUI...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ἰδοὺ ἡμέραι ἔρχονται, λέγει Κύριος, καὶ καταλήψεται ὁ ἀμητὸς τὸν τρυγητόν, καὶ περκάσει ἡ σταφυλὴ ἐν τῷ σπόρῳ, καὶ ἀποσταλάξει τὰ ὄρη γλυκασμόν, καὶ πάντες οἱ βουνοὶ σύμφυτοι ἔσονται·","greek":true,"translation":"„Iată, vin zile, zice Domnul, și secerișul va ajunge culesul viei, și strugurele se va pârgui în vremea semănatului, și munții vor picura dulceață, și toate dealurile vor fi sădite.”","note":"Septuaginta reformulează imaginile agricole („secerișul va ajunge culesul viei”, „strugurele se va pârgui la semănat”) și redă „dealurile se vor topi” prin „dealurile vor fi sădite” (σύμφυτοι) — o divergență reală de sens."}],"refs":["Levitic 26:5","Ezechiel 36:35","Osea 2:21-23","Ioel 3:18,20","Isaia 35:1,2"]},{"v":"9:14","t":"Voi aduce înapoi pe prizonierii poporului Meu Israel și ei vor reconstrui orașele pustiite și ei se vor întoarce și vor planta vii și le vor bea vinul, vor face grădini și le vor mânca rodul.","tokens":[{"t":"Voi aduce înapoi pe "},{"t":"prizonierii","w":"prizonierii","heb":"שְׁבוּת","translit":"șevut","strong":"H7622","pos":"substantiv, feminin singular construct","def_ro":"captivitatea, cei robiți; „a întoarce șevut” — a restatornici.","greek":"αἰχμαλωσία (aichmalosia)","greek_def_ro":"αἰχμαλωσία (aichmalosia) — captivitate, prizonierat.","dict_ro":"Șevut — de la șava, „a lua captiv”; expresia șav șevut („a întoarce captivitatea”) ajunge să însemne restatornicirea deplină a unui popor. Metzudat Țion leagă verbul „veșavti” și de „șuva”, liniște și odihnă (Isaia 30:15), iar Metzudat David explică: voi așeza în liniște și odihnă pe fiii robiei poporului Meu. Radak subliniază inversarea blestemului: altădată dușmanii mâncau roadele muncii lor (Deuteronomul 28:30), acum ei înșiși vor bea vinul viilor pe care le-au sădit."},{"t":" poporului Meu Israel și ei vor reconstrui orașele pustiite și ei se vor întoarce și vor planta vii și le vor bea vinul, vor face grădini și le vor mânca rodul."}],"commentaries":[{"author":"Metzudat David","text":"„Voi aduce înapoi” — îi voi așeza în liniște și odihnă pe fiii robiei poporului Meu Israel. „Orașele pustiite” — care fuseseră pustii în vremea exilului. „Și se vor întoarce” — vor locui în orașele acelea și nu vor mai fi exilați din ele. „Și le vor bea vinul” — ei vor bea vinul, și neamurile nu vor mai veni să-l bea."},{"author":"Radak (1160–1235)","text":"Radak: „Și le vor bea vinul și le vor mânca rodul” — adică osteneala lor nu va fi în zadar, să-și lucreze pământul și să-l mănânce dușmanii lor vecini, cum făceau când erau în țara lor înainte de nimicirea ei, când nu făceau voia lui Dumnezeu; și tot așa a spus în profeția lui Isaia: „vor zidi case și le vor locui, vor sădi vii și le vor mânca rodul” (Isaia 65:21)."},{"author":"Metzudat Țion","text":"„Veșavti” — cu sensul de liniște și odihnă, ca în „prin întoarcere și odihnă veți fi mântuiți” (Isaia 30:15). „Șevut” — din „robia” exilului. „Neșamot” — din „pustiire”."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְשַׁבְתִּי אֶת־שְׁבוּת עַמִּי יִשְׂרָאֵל...","translation":"„Voi aduce înapoi pe prizonierii poporului...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐπιστρέψω τὴν αἰχμαλωσίαν τοῦ λαοῦ μου ᾿Ισραήλ, καὶ οἰκοδομήσουσι πόλεις τὰς ἠφανισμένας καὶ κατοικήσουσι καὶ φυτεύσουσιν ἀμπελῶνας καὶ πίονται τὸν οἶνον αὐτῶν καὶ ποιήσουσι κήπους καὶ φάγονται τὸν καρπὸν αὐτῶν·","greek":true,"translation":"„Și voi întoarce robia poporului Meu Israel, și vor zidi cetățile pustiite și le vor locui și vor sădi vii și vor bea vinul lor și vor face grădini și vor mânca rodul lor.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Psalmii 53:6","Ieremia 30:3,18","Ezechiel 39:25","Isaia 61:4","Isaia 65:21","Isaia 62:8,9"]},{"v":"9:15","t":"Îi voi planta pe pământul lor și nu vor mai fi niciodată dezrădăcinați de pe pământul lor pe care li l-am dat – a spus DOMNUL, Dumnezeul tău.","tokens":[{"t":"Îi voi planta","w":"Îi voi planta","heb":"וּנְטַעְתִּים","translit":"untatim","strong":"H5193","pos":"verb, qal perfect consecutiv + sufix","def_ro":"îi voi sădi, îi voi înrădăcina.","greek":"καταφυτεύω (kataphyteuo)","greek_def_ro":"καταφυτεύω (kataphyteuo) — a sădi, a planta temeinic.","dict_ro":"Nata — „a sădi, a planta”; după versetul precedent, în care oamenii plantează vii și grădini, acum Dumnezeu Însuși îl plantează pe Israel în pământul lui. Contrapunctul e verbul nataș — „a smulge din rădăcină” —, pe care Metzudat Țion îl leagă de misiunea lui Ieremia, „să smulgi și să dărâmi” (Ieremia 1:10). Radak explică: ca pomul sădit, care nu se mișcă din locul lui, nu vor mai fi exilați — și aceasta pentru că vor sluji mereu lui Dumnezeu și vor face voia Lui."},{"t":" pe pământul lor și nu vor mai fi niciodată dezrădăcinați de pe pământul lor pe care li l-am dat – a spus DOMNUL, Dumnezeul tău."}],"commentaries":[{"author":"Metzudat David","text":"„Îi voi planta” — vor fi înrădăcinați ca un pom sădit. „Și nu vor mai fi dezrădăcinați” — nu vor mai fi smulși de pe pământul pe care li l-am dat de la început, adică nu vor mai fi exilați din el, căci vor locui acolo pe vecie."},{"author":"Radak (1160–1235)","text":"Radak: „Îi voi planta” — ca pomul sădit, care nu se mișcă din locul lui; iar sensul este că nu vor mai fi exilați din țara lor, și aceasta pentru că vor sluji mereu lui Dumnezeu și vor face voia Lui. „A spus DOMNUL, Dumnezeul tău” — este cuvântul lui Dumnezeu adresat profetului."},{"author":"Metzudat Țion","text":"„Yinatșu” — cu sensul de smulgere din rădăcină, ca în „să smulgi și să dărâmi” (Ieremia 1:10)."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וּנְטַעְתִּים עַל־אַדְמָתָם וְלֹא יִנָּתְשׁוּ...","translation":"„Îi voi planta pe pământul lor...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ καταφυτεύσω αὐτοὺς ἐπὶ τῆς γῆς αὐτῶν καὶ οὐ μὴ ἐκσπασθῶσιν οὐκέτι ἀπὸ τῆς γῆς, ἧς ἔδωκα αὐτοῖς, λέγει Κύριος ὁ Θεὸς ὁ παντοκράτωρ.","greek":true,"translation":"„Și îi voi sădi în pământul lor, și nicidecum nu vor mai fi smulși din pământul pe care li l-am dat, zice Domnul Dumnezeu Atotțiitorul.”","note":"Septuaginta încheie cu „Domnul Dumnezeu Atotțiitorul” (ὁ παντοκράτωρ), acolo unde Textul Masoretic are „DOMNUL, Dumnezeul tău” — adresarea personală către Israel („al tău”) dispare."}],"refs":["Isaia 60:21","Ieremia 24:6","Ieremia 32:41","Ezechiel 34:28","Ioel 3:20"]}]},{"num":8,"title":"Kedoșim (așkenaz) - Sfinți","ref":"Ezechiel 22:1-16","intro":"Pericopa Kedoșim cheamă poporul la sfințenie și înșiră poruncile care o alcătuiesc: cinstirea părinților, ocrotirea străinului, a orfanului și a văduvei, păzirea Sabatului, interzicerea clevetirii, a relațiilor oprite și a dobânzii. Haftara așkenază, din Ezechiel, este oglinda ei întunecată: profetul acuză Ierusalimul — „cetatea vărsărilor de sânge” — că a călcat exact aceste porunci, una după alta, de la prinții care își folosesc puterea ca să verse sânge până la cei care iau mită și camătă și Îl uită pe Dumnezeu. Rashi observă că toate urâciunile din pericopa Kedoșim sunt înșirate aici. Pedeapsa anunțată este exilul, care va pune însă capăt necurăției, pentru ca poporul să ajungă, în cele din urmă, să-L cunoască pe DOMNUL.","verses":[{"v":"22:1","t":"Cuvântul DOMNULUI a venit la mine, spunând:","tokens":[{"t":"Cuvântul DOMNULUI","w":"Cuvântul DOMNULUI","heb":"דְבַר־יְהוָה","translit":"devar-ADONAI","strong":"H1697","pos":"substantiv, masculin singular, în construcție + nume divin","def_ro":"cuvântul DOMNULUI.","dict_ro":"Devar ADONAI — formula prin care Ezechiel își deschide fiecare nouă unitate profetică; davar înseamnă deopotrivă „cuvânt” și „lucru, faptă”, astfel încât cuvântul divin e înțeles ca realitate activă, nu doar ca mesaj. Capitolul 22 deschide un nou oracol, rostit înainte de căderea Ierusalimului: un rechizitoriu al cetății, păcat cu păcat."},{"t":" a venit la mine, spunând:"}],"commentaries":[],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיְהִי דְבַר־יְהוָה אֵלַי לֵאמֹר׃...","translation":"„Cuvântul DOMNULUI a venit la mine...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ΚΑΙ ἐγένετο λόγος Κυρίου πρός με λέγων·","greek":true,"translation":"„Și a fost cuvântul Domnului către mine, zicând:”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":[]},{"v":"22:2","t":"„Iar tu, fiu al omului, vei dojeni, vei dojeni oare orașul vărsărilor de sânge și îi vei face cunoscute toate ororile?","tokens":[{"t":"„Iar tu, fiu al omului, vei dojeni, vei dojeni oare "},{"t":"orașul vărsărilor de sânge","w":"orașul vărsărilor de sânge","heb":"עִיר הַדָּמִים","translit":"ir hadamim","strong":"H1818","pos":"substantiv, feminin singular, în construcție + substantiv, masculin plural, cu articol","def_ro":"cetatea sângiurilor, orașul vărsării de sânge.","dict_ro":"Ir hadamim — pluralul damim („sânguri”) desemnează sângele vărsat cu violență; Rashi precizează că e vorba de Ierusalim, iar Radak explică de ce acesta e primul titlu de acuzare: deși cetatea era plină de idoli și alte urâciuni, păcatul cel mai greu era vărsarea de sânge nevinovat, ca în zilele lui Manase (2 Împărați 21:16). Același epitet îl dă Naum Ninivei (Naum 3:1), punând astfel Ierusalimul pe aceeași treaptă cu capitala asiriană."},{"t":" și îi vei face cunoscute toate ororile?"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Vei judeca cetatea sângiurilor” — Ierusalimul. „Și îi vei face cunoscute” — he-ul din „vehodatah” e vocalizat astfel încât sensul e „și fă-o să cunoască”."},{"author":"Radak (1160–1235)","text":"Radak: dublarea verbului întărește lucrul, ca și cum ar spune: dacă o vei judeca, privește-i faptele. „Cetatea sângiurilor” — deși era o cetate a idolilor și a altor urâciuni, nelegiuirea cea mare este vărsarea de sânge nevinovat, precum s-a spus despre Manase, după ce i-au fost amintite toate urâciunile: „și sânge nevinovat a vărsat Manase” (2 Împărați 21:16)."},{"author":"Metzudat Țion","text":"„Hatișpot” — cu sensul de ceartă, dezbatere [în judecată]."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְאַתָּה בֶן־אָדָם הֲתִשְׁפֹּט הֲתִשְׁפֹּט...","translation":"„„Iar tu, fiu al omului, vei...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ σὺ υἱὲ ἀνθρώπου, εἰ κρινεῖς τὴν πόλιν τῶν αἱμάτων; καὶ παράδειξον αὐτῇ πάσας τὰς ἀνομίας αὐτῆς","greek":true,"translation":"„Și tu, fiul omului, vei judeca cetatea sângiurilor? Arată-i toate fărădelegile ei.”","note":"Septuaginta nu reia verbul dublat din Textul Masoretic („vei dojeni, vei dojeni”) și redă „orori” (toevot) prin „fărădelegi” (ἀνομίας)."}],"refs":["Ezechiel 20:4","Ezechiel 23:36","2 Împărați 21:16","Naum 3:1","Matei 23:35","Ezechiel 16:2"]},{"v":"22:3","t":"Și să spui: «Așa a spus Stăpânul meu, Domnul DUMNEZEU: Orașule în mijlocul căruia este vărsat sânge pentru ca să-ți vină [mai degrabă] ceasul și care ți-ai făurit idoli pentru tine ca să te pângărești,","tokens":[{"t":"Și să spui: «Așa a spus Stăpânul meu, Domnul DUMNEZEU: Orașule în mijlocul căruia este vărsat sânge pentru ca să-ți vină [mai degrabă] ceasul și care ți-ai făurit "},{"t":"idoli","w":"idoli","heb":"גִלּוּלִים","translit":"ghilulim","strong":"H1544","pos":"substantiv, masculin plural","def_ro":"idoli (termen disprețuitor).","dict_ro":"Ghilulim — cuvânt preferat de Ezechiel (peste 35 de apariții) pentru idoli, derivat probabil din gel, „baligă”, sau din galal, „a rostogoli” (bușteni, pietre fără viață) — un joc de cuvinte batjocoritor. Radak observă că textul spune „asupra ei”, pentru că idolii stăteau pe munți și pe dealuri, și explică gradația necurăției: idolatria e „necurăția sufletului”, cea mai grea dintre toate, de aceea profetul o numește explicit „ca să te pângărești”."},{"t":" pentru tine ca să te pângărești,"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Cetate care verși sânge în mijlocul ei, ca să-i vină vremea” — e un verset inversat, iar sensul lui este: o cetate care varsă sânge în mijlocul ei — Domnul DUMNEZEU a spus că vremea ei vine. „Și care faci idoli” — adică „și care face idoli...”."},{"author":"Radak (1160–1235)","text":"Radak: „Cetate care varsă sânge” — o cetate ai cărei oameni varsă sânge; așa obișnuiește limba să pomenească cetatea în locul locuitorilor ei. „În mijlocul ei” — pentru două motive: întâi, pentru că vărsarea de sânge sub ochii tuturor e un rău mai mare decât pe drumuri și în ascuns; al doilea, pentru că mijlocul ei e plin de sânge, cum s-a spus despre Manase, „până a umplut Ierusalimul de la un capăt la altul”. „Ca să-i vină vremea” — vărsarea de sânge i-a adus vremea nimicirii."},{"author":"Metzudat Țion","text":"„Ita” — din cuvântul „vreme, timp”."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְאָמַרְתָּ כֹּה אָמַר אֲדֹנָי...","translation":"„Și să spui: «Așa a spus...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐρεῖς· τάδε λέγει Κύριος Κύριος· ὦ πόλις ἐκχέουσα αἵματα ἐν μέσῳ αὐτῆς τοῦ ἐλθεῖν καιρὸν αὐτῆς καὶ ποιοῦσα ἐνθυμήματα καθ’ ἑαυτῆς, τοῦ μιαίνειν αὐτήν,","greek":true,"translation":"„Și vei zice: Așa zice Domnul Domnul: O, cetate care verși sânge în mijlocul tău, ca să-ți vină vremea, și care faci născociri împotriva ta, ca să te pângărești,”","note":"Septuaginta redă „idoli” (ghilulim) prin „născociri, gânduri” (ἐνθυμήματα) — o traducere interpretativă care evită numirea directă a idolilor."}],"refs":["Ezechiel 22:27","Ezechiel 24:6-9","Țefania 3:3","Ezechiel 7:2-12","2 Împărați 21:2-9"]},{"v":"22:4","t":"prin sângele tău pe care l-ai vărsat te-ai făcut vinovat și prin idolii pe care i-ai făurit te-ai pângărit. Astfel, ți-ai grăbit ceasul și ai ajuns la capătul anilor tăi și de aceea te-am făcut de batjocura neamurilor, de râsul tuturor țărilor.","tokens":[{"t":"prin sângele tău pe care l-ai vărsat te-ai făcut vinovat și prin idolii pe care i-ai făurit te-ai pângărit. Astfel, "},{"t":"ți-ai grăbit ceasul","w":"ți-ai grăbit ceasul","heb":"וַתַּקְרִיבִי יָמַיִךְ","translit":"vatakrivi iamaih","strong":"H7126","pos":"verb, hifil, imperfect consecutiv, persoana a II-a feminin singular + substantiv plural cu sufix","def_ro":"ți-ai apropiat zilele, ți-ai grăbit sfârșitul.","dict_ro":"Karav, la forma hifil — „a apropia, a aduce aproape”; aceeași rădăcină din care vine korban, jertfa „adusă aproape” de altar, ceea ce dă expresiei o ironie amară: în loc de jertfe, cetatea își „aduce aproape” propriul sfârșit. Radak explică: prin faptele tale rele ți-ai apropiat zilele exilului și ale nimicirii. Rashi leagă „anii tăi” de avertismentul lui Moise din Deuteronom 4:25 („și veți îmbătrâni în țară”), a cărui valoare numerică indica termenul exilului."},{"t":" și ai ajuns la capătul anilor tăi și de aceea te-am făcut de batjocura neamurilor, de râsul tuturor țărilor."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Până la anii tăi” — decretul din „și veți îmbătrâni [în țară]” (Deuteronom 4:25), după valoarea lui numerică, pe care l-a spus Moise. „Și de batjocură” — vorbă de clevetire, ca toată lumea să vorbească despre tine."},{"author":"Radak (1160–1235)","text":"Radak: „Ți-ai apropiat zilele” — prin faptele tale rele ai apropiat zilele exilului și ale nimicirii tale. „De aceea te-am dat de ocară neamurilor” — neamurile te ocărăsc și te disprețuiesc pentru că ai părăsit Tora Dumnezeului tău, pe când ele n-au părăsit legea dumnezeilor lor. Toți stăpânesc peste tine și nu se tem să te batjocorească — opusul cinstei și al temerii pe care le-ai fi avut dacă ai fi făcut voia Mea."},{"author":"Metzudat Țion","text":"„Așamt” — din „vină, nelegiuire”. „Vekalasa” — cu sensul de batjocură, ca „spre ocară și batjocură” (Ieremia 20:8)."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"בְּדָמֵךְ אֲשֶׁר־שָׁפַכְתְּ אָשַׁמְתְּ וּבְגִלּוּלַיִךְ...","translation":"„prin sângele tău pe care l-ai...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ἐν τοῖς αἵμασιν αὐτῶν, οἷς ἐξέχεας, παραπέπτωκας καὶ ἐν τοῖς ἐνθυμήμασί σου, οἷς ἐποίεις, ἐμιαίνου, καὶ ἤγγισας τὰς ἡμέρας σου καὶ ἤγαγες καιρὸν ἐτῶν σου. διὰ τοῦτο δέδωκά σε εἰς ὀνειδισμὸν τοῖς ἔθνεσι, καὶ εἰς ἐμπαιγμὸν πάσαις ταῖς χώραις","greek":true,"translation":"„în sângiurile lor pe care le-ai vărsat ai căzut, și în născocirile tale pe care le-ai făcut te-ai pângărit, și ți-ai apropiat zilele și ai adus vremea anilor tăi. De aceea te-am dat de ocară neamurilor și de batjocură tuturor ținuturilor”","note":"Septuaginta are „în sângiurile lor” (αὐτῶν) în loc de „prin sângele tău”, și redă din nou idolii prin „născociri”."}],"refs":["2 Împărați 21:16","Matei 23:32,33","Ezechiel 5:14,15","Deuteronom 28:37","1 Împărați 9:7","Plângerile lui Ieremia 2:15,16"]},{"v":"22:5","t":"Cele de aproape și cele de departe de tine te vor batjocori: ‘Pângărita numelui! Plină de tulburări!’","tokens":[{"t":"Cele de aproape și cele de departe de tine te vor batjocori: ‘Pângărita numelui! "},{"t":"Plină de tulburări","w":"Plină de tulburări","heb":"רַבַּת הַמְּהוּמָה","translit":"rabat hamehuma","strong":"H4103","pos":"adjectiv, feminin singular, în construcție + substantiv cu articol","def_ro":"plină de tumult, de învălmășeală.","dict_ro":"Mehuma — tumultul, zarva, panica; Metzudat Țion o explică drept „vuiet de glasuri”, iar Radak o citește ca suma nenorocirilor care vor veni: foamete, sabie și ciumă. „Pângărita numelui” adaugă o dimensiune a rușinii: Rashi explică că poporul chemat „neam sfânt, fii ai Creatorului” și-a atras singur numele de „popor cu buze necurate” (Isaia 6:5)."},{"t":"!’"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Te vor batjocori” — și care e batjocura? „Pângărita numelui” — aceasta este cea care și-a pângărit numele: ei erau numiți popor sfânt, fii ai Creatorului lor, și au făcut să fie numiți „popor cu buze necurate” (Isaia 6:5)."},{"author":"Radak (1160–1235)","text":"Radak: „Pângărita numelui” — ai un nume de necurăție printre neamuri; căci, pe lângă faptul că ești necurată în trupul tău, ești necurată și în numele tău. „Plină de tulburări” — căci tulburările tale sunt multe: foamete, sabie și ciumă."},{"author":"Metzudat Țion","text":"„Rabat” — din „mulțime”. „Hamehuma” — cu sensul de vuiet de glasuri."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"הַקְּרֹבוֹת וְהָרְחֹקוֹת מִמֵּךְ יִתְקַלְּסוּ־בָךְ...","translation":"„Cele de aproape și cele de...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ταῖς ἐγγιζούσαις πρὸς σὲ καὶ ταῖς μακρὰν ἀπεχούσαις ἀπὸ σοῦ, καὶ ἐμπαίξονται ἐν σοί· ἀκάθαρτος ἡ ὀνομαστὴ καὶ πολλὴ ἐν ταῖς ἀνομίαις.","greek":true,"translation":"„celor ce se apropie de tine și celor ce sunt departe de tine, și își vor bate joc de tine: necurată cea vestită și plină de fărădelegi.”","note":"Septuaginta redă „plină de tulburări” prin „plină de fărădelegi” (ἐν ταῖς ἀνομίαις) și leagă începutul versetului de sfârșitul versetului 4."}],"refs":["Ieremia 15:2,3"]},{"v":"22:6","t":"Iată, prinții lui Israel, fiecare [dintre ei] era în tine pentru propria putere, de dragul vărsării de sânge.","tokens":[{"t":"Iată, "},{"t":"prinții lui Israel","w":"prinții lui Israel","heb":"נְשִׂיאֵי יִשְׂרָאֵל","translit":"nesiei Israël","strong":"H5387","pos":"substantiv, masculin plural, în construcție + nume propriu","def_ro":"căpeteniile, prinții lui Israel.","dict_ro":"Nasi — „cel ridicat”, căpetenie, din rădăcina nasa, „a ridica”; Radak îi identifică pe regi și pe dregători. Expresia „fiecare după brațul lui” (redată „pentru propria putere”) descrie, după Rashi, legea celui mai tare: oricine era mai puternic îl călca în picioare pe celălalt; iar Radak adaugă că fiecare își folosea puterea — bogăția sau rudele — ca să facă rău și să verse sânge."},{"t":", fiecare [dintre ei] era în tine pentru propria putere, de dragul vărsării de sânge."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Fiecare după brațul lui” — cine era mai tare îl copleșea [pe celălalt]."},{"author":"Radak (1160–1235)","text":"Radak: „Prinții lui Israel” — regii și dregătorii. „Fiecare după brațul lui” — adică fiecare, după tăria lui, făcea rău și vărsa sânge; „după brațul lui” înseamnă după puterea lui și după cum se întărea prin bogăția sau prin rudele lui, ca în „omul cu braț, al lui e țara” (Iov 22:8)."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"הִנֵּה נְשִׂיאֵי יִשְׂרָאֵל אִישׁ...","translation":"„Iată, prinții lui Israel, fiecare [dintre...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ἰδοὺ οἱ ἀφηγούμενοι οἴκου ᾿Ισραήλ, ἕκαστος πρὸς τοὺς συγγενεῖς αὐτοῦ συνανεφύροντο ἐν σοί, ὅπως ἐκχέωσιν αἷμα·","greek":true,"translation":"„Iată, căpeteniile casei lui Israel, fiecare cu rudele lui, se amestecau în tine, ca să verse sânge;”","note":"Septuaginta are „fiecare cu rudele lui se amestecau în tine”, acolo unde Textul Masoretic are „fiecare după brațul [puterea] lui” — o divergență reală de sens."}],"refs":["Ezechiel 22:27","Isaia 1:23","Ieremia 5:5","Mica 3:1-3,9-11","Mica 2:1","Neemia 9:34"]},{"v":"22:7","t":"Tată și mamă au călcat strâmb în tine, pe străin l-au oprimat în mijlocul tău, față de orfan și de văduvă au greșit în tine.","tokens":[{"t":"Tată și mamă au călcat strâmb în tine, pe "},{"t":"străin","w":"străin","heb":"לַגֵּר","translit":"lagher","strong":"H1616","pos":"prepoziție + substantiv, masculin singular, cu articol","def_ro":"străinul, cel venit să locuiască printre voi.","dict_ro":"Gher — străinul stabilit în mijlocul poporului, fără pământ și fără rude, pe care Tora îl ocrotește de zeci de ori, alături de orfan și văduvă (Exod 22:21-22). Rashi observă că profetul enumeră aici chiar urâciunile din pericopa Kedoșim (Levitic 19-20), de care fuseseră avertizați — cinstirea părinților, ocrotirea străinului — ceea ce explică alegerea acestei haftare. Radak adaugă că străinul era asuprit tocmai pentru că n-avea rude și ajutoare."},{"t":" l-au oprimat în mijlocul tău, față de orfan și de văduvă au greșit în tine."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Tată și mamă au fost disprețuiți în tine” — toate urâciunile din pericopa „Sfinți să fiți” (Levitic 19, 20), de care fuseseră avertizați, sunt înșirate aici."},{"author":"Radak (1160–1235)","text":"Radak: le-a înșirat dintre păcatele grele care erau la ei, pe care se cuvine ca orice om să le țină departe, chiar dacă Tora nu l-ar fi avertizat. „Au asuprit în mijlocul tău” — tot ce făceau cu străinul era cu asuprire, pentru că n-avea rude și ajutoare; și tot așa l-au nedreptățit pe orfan și pe văduvă, pentru că sunt slabi, lipsiți de soț și de tată."},{"author":"Metzudat Țion","text":"„Hekalu” — din ușurătate și dispreț. „Honu” — din înșelăciune și asuprire a averii."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"אָב וָאֵם הֵקַלּוּ בָךְ...","translation":"„Tată și mamă au călcat strâmb...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"πατέρα καὶ μητέρα ἐκακολόγουν ἐν σοί, καὶ πρὸς τὸν προσήλυτον ἀνεστρέφοντο ἐν ἀδικίαις ἐν σοί, ὀρφανὸν καὶ χήραν κατεδυνάστευον ἐν σοί·","greek":true,"translation":"„pe tată și pe mamă îi vorbeau de rău în tine, și cu străinul se purtau cu nedreptate în tine, pe orfan și pe văduvă îi asupreau în tine;”","note":"Corespondență strânsă; „au disprețuit” (hekalu) e redat prin „vorbeau de rău” (ἐκακολόγουν)."}],"refs":["Exod 21:17","Levitic 20:9","Deuteronom 27:16","Exod 22:21,22","Deuteronom 27:19","Maleahi 3:5"]},{"v":"22:8","t":"Sfințeniile Mele le-ai nesocotit și Șabaturile Mele le-ai pângărit.","tokens":[{"t":"Sfințeniile Mele le-ai nesocotit și "},{"t":"Șabaturile Mele","w":"Șabaturile Mele","heb":"שַׁבְּתֹתַי","translit":"șabtotai","strong":"H7676","pos":"substantiv, feminin plural + sufix persoana I","def_ro":"Sabatele Mele.","dict_ro":"Șabat — ziua de odihnă, numită „Sabatele Mele” pentru că e semnul legământului dintre Dumnezeu și Israel (Exod 31:13); aceeași formulare stă în pericopa Kedoșim: „Sabatele Mele să le păziți și Sanctuarul Meu să-l cinstiți” (Levitic 19:30). Radak amintește că pângărirea Sabatului în Ierusalim e documentată și de Ieremia (Ieremia 17:21-27), iar „sfințeniile disprețuite” sunt jertfele aduse cu dispreț — animale furate, șchioape sau bolnave (Maleahi 1:13)."},{"t":" le-ai pângărit."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Sfințeniile Mele le-ai disprețuit” — și nu cum am spus: „să-l jertfiți după voia voastră” (Levitic 22:29)."},{"author":"Radak (1160–1235)","text":"Radak: „Sfințeniile Mele le-ai disprețuit” — cum s-a spus: „și aduceți ce e furat, și ce e șchiop, și ce e bolnav” (Maleahi 1:13); toate acestea sunt dispreț. „Și Sabatele Mele le-ai pângărit” — cum am văzut că i-a avertizat Ieremia despre pângărirea Sabatului."},{"author":"Metzudat Țion","text":"„Hilalt” — din „profan”, opusul lui „sfânt”."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"קָדָשַׁי בָּזִית וְאֶת־שַׁבְּתֹתַי חִלָּלְתְּ׃...","translation":"„Sfințeniile Mele le-ai nesocotit și Șabaturile...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ τὰ ἅγιά μου ἐξουθένουν καὶ τὰ σάββατά μου ἐβεβήλουν ἐν σοί.","greek":true,"translation":"„și cele sfinte ale Mele le nesocoteau și Sabatele Mele le pângăreau în tine.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Ezechiel 22:26","Ezechiel 20:13,21,24","Levitic 19:30","Amos 8:4-6","Maleahi 1:6-8,12"]},{"v":"22:9","t":"Cei care defăimează au fost în tine, pentru ca să verse sânge; și pe munți au mâncat în tine, complot au înfăptuit în mijlocul tău.","tokens":[{"t":"Cei care defăimează","w":"Cei care defăimează","heb":"אַנְשֵׁי רָכִיל","translit":"anșei rahil","strong":"H7400","pos":"substantiv, masculin plural, în construcție + substantiv","def_ro":"oameni ai bârfei, clevetitori, denunțători.","dict_ro":"Rahil — clevetirea, bârfa purtată din om în om; aceeași interdicție ca în pericopa Kedoșim: „să nu umbli cu clevetiri în poporul tău; să nu stai împotriva sângelui aproapelui tău” (Levitic 19:16). Legătura dintre cele două jumătăți ale versetului din Levitic e exact acuzația lui Ezechiel: Radak explică că acești oameni duceau vorbe de la cei slabi la cei puternici, „ca să verse sânge nevinovat fără motiv”, ca martorii mincinoși împotriva lui Nabot (1 Împărați 21:10-13)."},{"t":" au fost în tine, pentru ca să verse sânge; și pe munți au mâncat în tine, complot au înfăptuit în mijlocul tău."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Și pe munți au mâncat în tine” — pe munți slujeau în tine zeilor străini. „Complot” — gânduri de nelegiuire."},{"author":"Radak (1160–1235)","text":"Radak: „Cei care defăimează” — care umblau cu clevetiri de la cei slabi la cei tari, ca să verse sânge nevinovat fără motiv. „Pe munți au mâncat” — cum am explicat mai sus la versetul „și pe munți n-a mâncat” (Ezechiel 18:6). „Complot au înfăptuit” — a spus „zima” ca termen general pentru toate relațiile oprite, și apoi le-a înșirat pe unele."},{"author":"Metzudat Țion","text":"„Rahil” — cu sensul de vorbire de rău. „Vehel heharim” — „el” e pus în locul lui „be” (pe munți). „Zima” — sensul lui e rușine și nelegiuire, ca în „căci zima au făcut” (Osea 6:9)."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"אַנְשֵׁי רָכִיל הָיוּ בָךְ...","translation":"„Cei care defăimează au fost în...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ἄνδρες λῃσταὶ ἦσαν ἐν σοί, ὅπως ἐκχέωσιν ἐν σοὶ αἷμα, καὶ ἐπὶ τῶν ὀρέων ἤσθιον ἐν σοί, ἀνόσια ἐποίουν ἐν μέσῳ σου.","greek":true,"translation":"„Oameni tâlhari erau în tine, ca să verse sânge în tine, și pe munți mâncau în tine, lucruri nelegiuite făceau în mijlocul tău.”","note":"Septuaginta redă „clevetitori” (anșei rahil) prin „tâlhari” (λῃσταί) — o divergență reală de sens."}],"refs":["Levitic 19:16","1 Împărați 21:10-13","Ezechiel 18:6,11,15","Psalmii 106:28","Osea 6:9"]},{"v":"22:10","t":"Goliciunea tatălui a fost descoperită în tine, au necinstit femeia în vremea necurățeniei ei, în tine.","tokens":[{"t":"Goliciunea tatălui","w":"Goliciunea tatălui","heb":"עֶרְוַת־אָב","translit":"ervat-av","strong":"H6172","pos":"substantiv, feminin singular, în construcție + substantiv","def_ro":"goliciunea tatălui (eufemism pentru relația cu soția tatălui).","dict_ro":"Erva — goliciunea, termenul tehnic din Levitic 18 și 20 pentru relațiile interzise; „a descoperi goliciunea tatălui” înseamnă, după Levitic 18:8, relația cu soția tatălui. Radak observă că verbul e la singular, spre deosebire de celelalte, și vede aici o aluzie la tradiția talmudică despre regele Amon, care a păcătuit cu propria mamă (Sanhedrin 103b). A doua jumătate a versetului reia interdicția apropierii de femeie în timpul necurăției (Levitic 18:19; 20:18)."},{"t":" a fost descoperită în tine, au necinstit femeia în vremea necurățeniei ei, în tine."}],"commentaries":[{"author":"Radak (1160–1235)","text":"Radak: „Goliciunea tatălui” — a amintit-o pe cea mai grea dintre relațiile oprite, cea despre care Tora spune „goliciunea tatălui tău”, adică soția tatălui; iar faptul că „a descoperit” e la singular, pe când celelalte sunt la plural, cuprinde o aluzie la ce au spus înțelepții noștri: că Amon și-a înmulțit vina, venind la mama lui. „Necurăția niddei” — femeia aflată în sângele ei; și a spus „au necinstit”, căci este o necinstire dacă o iau în timpul necurăției ei."},{"author":"Talmud Bavli, Sanhedrin 103b","text":"Amon a avut relații cu mama lui, precum s-a spus: „și Amon și-a înmulțit vina” (2 Cronici 33:23) — adică a săvârșit o fărădelege mai mare și mai rușinoasă decât oricine altul."},{"author":"Metzudat Țion","text":"„Inu” — adică au silit-o, și de aceea i se socotește drept umilire."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"עֶרְוַת־אָב גִּלָּה־בָךְ טְמֵאַת הַנִּדָּה...","translation":"„Goliciunea tatălui a fost descoperită în...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"αἰσχύνην πατρὸς ἀπεκάλυψαν ἐν σοὶ καὶ ἐν ἀκαθαρσίαις ἀποκαθημένην ἐταπείνουν ἐν σοί·","greek":true,"translation":"„Rușinea tatălui au descoperit-o în tine și pe cea care stătea deoparte în necurății au umilit-o în tine;”","note":"Corespondență strânsă; „goliciune” e redată prin „rușine” (αἰσχύνην), iar femeia „în necurăție” prin „cea care stătea deoparte” (ἀποκαθημένην)."}],"refs":["Levitic 18:7,8","Levitic 20:11","Deuteronom 27:20,23","Amos 2:7","Levitic 18:19","1 Corinteni 5:1"]},{"v":"22:11","t":"În tine, un om se dedă la orori cu soția semenului său, altul își pângărește nora, și altul își pângărește sora, fiica tatălui său, în tine.","tokens":[{"t":"În tine, un om se dedă la orori cu soția semenului său, altul își pângărește "},{"t":"nora","w":"nora","heb":"כַּלָּתוֹ","translit":"kalato","strong":"H3618","pos":"substantiv, feminin singular + sufix persoana a III-a masculin","def_ro":"nora lui.","dict_ro":"Kala — nora, dar și „mireasa”; relația cu nora e interzisă explicit în Levitic 18:15 și 20:12, iar cea cu sora, fiica tatălui, în Levitic 18:9 și 20:17 — o nouă trimitere directă la pericopa Kedoșim. Radak subliniază că formularea „un om... altul... altul” nu descrie un caz izolat, ci un fenomen răspândit: fiecare dintre aceste urâciuni era săvârșită de mulți."},{"t":", și altul își pângărește sora, fiica tatălui său, în tine."}],"commentaries":[{"author":"Radak (1160–1235)","text":"Radak: „Și un om cu soția semenului său” — nu vorbește despre un singur om, ci spune „un om și alt om”, ca în „orice om din sămânța ta”; și tot așa „altul cu nora lui” și „altul cu sora lui”. Și a spus „a umilit-o în tine”, pentru că, de cele mai multe ori, cel ce se culcă cu sora lui se culcă cu ea în casa tatălui său, când ea e încă fecioară."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְאִישׁ אֶת־אֵשֶׁת רֵעֵהוּ עָשָׂה...","translation":"„În tine, un om se dedă...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ἕκαστος τὴν γυναῖκα τοῦ πλησίον αὐτοῦ ἠνομοῦσαν, καὶ ἕκαστος τὴν νύμφην αὐτοῦ ἐμίαινεν ἐν ἀσεβείᾳ, καὶ ἕκαστος τὴν ἀδελφὴν αὐτοῦ θυγατέρα τοῦ πατρὸς αὐτοῦ ἐταπείνουν ἐν σοί.","greek":true,"translation":"„fiecare cu femeia aproapelui său făceau fărădelege, și fiecare își pângărea nora cu nelegiuire, și fiecare își umilea sora, fiica tatălui său, în tine.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Levitic 18:20","Levitic 18:15","Levitic 18:9","2 Samuel 13:1,14,28,29","Ieremia 5:7,8"]},{"v":"22:12","t":"Au luat mită în tine, ca să verse sânge. Dobândă și camătă ai luat și ți-ai îmbogățit prietenii cu lucru furat, iar pe Mine M-ai uitat – vorba Stăpânului meu, Domnul DUMNEZEU.","tokens":[{"t":"Au luat mită în tine, ca să verse sânge. "},{"t":"Dobândă și camătă","w":"Dobândă și camătă","heb":"נֶשֶׁךְ וְתַרְבִּית","translit":"neșeh vetarbit","strong":"H5392","pos":"substantiv, masculin singular + substantiv, feminin singular","def_ro":"dobândă și camătă (două denumiri ale împrumutului cu dobândă).","dict_ro":"Neșeh și tarbit — literal „mușcătură” și „înmulțire”, cele două denumiri biblice ale dobânzii interzise între frați (Levitic 25:35-37). Radak citează tradiția rabinică potrivit căreia e unul și același lucru, numit de două ori pentru ca împrumutul cu dobândă să încalce două interdicții — învățătura lui Rava din Bava Meția 60b. Rashi dă două lecturi pentru „ți-ai îmbogățit prietenii”: fie cu câștigul necinstit luat de la săraci, fie „i-ai jefuit pe prietenii tăi prin asuprire”."},{"t":" ai luat și ți-ai îmbogățit prietenii cu lucru furat, iar pe Mine M-ai uitat – vorba Stăpânului meu, Domnul DUMNEZEU."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Ți-ai îmbogățit prietenii cu lucru furat” — i-ai făcut bogați pe prietenii tăi cu câștigul necinstit pe care l-ai luat pe nedrept de la săraci. O altă explicație: „vatevațí” e un cuvânt pentru jaf, ca „și jefuitorul se binecuvântează” (Psalmii 10:3); după aceasta, sensul este: și i-ai jefuit pe prietenii tăi prin asuprire."},{"author":"Radak (1160–1235)","text":"Radak: „Mită” — regele și dregătorii tăi luau mită de la cel cu pricina, ca să verse sânge nevinovat. „Dobândă și camătă ai luat” — același lucru în cuvinte diferite, iar înțelepții noștri au spus: aceasta e dobândă și aceasta e camătă, și Scriptura le-a despărțit doar ca să fie încălcate prin două interdicții. „Și pe Mine M-ai uitat” — pentru că nu te-ai încrezut în Mine și n-ai cerut ajutor de la Mine, ci de la neamurile care te nimicesc."},{"author":"Talmud Bavli, Bava Meția 60b","text":"Rava a spus: nu găsești dobândă (neșeh) fără camătă (tarbit), nici camătă fără dobândă; iar Scriptura le-a despărțit doar pentru ca [cel ce împrumută cu dobândă] să încalce două interdicții."},{"author":"Metzudat Țion","text":"„Vatevațí” — așa se numește pofta de avere, ca în „și s-au abătut după câștig” (1 Samuel 8:3)."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"שֹׁחַד לָקְחוּ־בָךְ לְמַעַן שְׁפָךְ־דָּם...","translation":"„Au luat mită în tine, ca...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"δῶρα ἐλαμβάνοσαν ἐν σοί, ὅπως ἐκχέωσιν αἷμα, τόκον καὶ πλεονασμὸν ἐλαμβάνοσαν ἐν σοί· καὶ συνετελέσω συντέλειαν κακίας σου τὴν ἐν καταδυναστείᾳ, ἐμοῦ δὲ ἐπελάθου, λέγει Κύριος.","greek":true,"translation":"„Daruri primeau în tine ca să verse sânge; dobândă și câștig în plus luau în tine; și ai împlinit măsura răutății tale prin asuprire, iar pe Mine M-ai uitat, zice Domnul.”","note":"Septuaginta are „ai împlinit măsura răutății tale prin asuprire” în loc de „ți-ai îmbogățit prietenii cu lucru furat” și prescurtează formula finală la „zice Domnul”."}],"refs":["Exod 23:7,8","Deuteronom 16:19","Levitic 25:35,36","Psalmii 15:5","Ieremia 2:32","Iacov 5:1-4"]},{"v":"22:13","t":"Și iată, Mi-am lovit palmele din pricina tâlhăriei tale pe care ai comis-o și datorită vărsării tale de sânge care a fost în mijlocul tău.","tokens":[{"t":"Și iată, "},{"t":"Mi-am lovit palmele","w":"Mi-am lovit palmele","heb":"הִכֵּיתִי כַפִּי","translit":"hikeiti hapi","strong":"H3709","pos":"verb, hifil, perfect, persoana I singular + substantiv cu sufix","def_ro":"Mi-am bătut palmele (gest de durere și mânie).","dict_ro":"Kaf — palma; „a bate din palme” e în Ezechiel un gest de jale și indignare (Ezechiel 21:14, 17), Rashi îl explică prin „am strigat «vai!» și bocet”. Aici se află una dintre cele mai cunoscute învățături rabinice despre acest capitol: dintre toate cele 24 de păcate înșirate de Ezechiel, sentința a fost pecetluită doar pentru jaf — „din pricina tâlhăriei tale” —, de unde Rashi deduce că jaful e mai grav decât toate celelalte."},{"t":" din pricina tâlhăriei tale pe care ai comis-o și datorită vărsării tale de sânge care a fost în mijlocul tău."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Mi-am lovit palmele” — am strigat „vai!” și bocet. „Din pricina tâlhăriei tale” — de aici învățăm că jaful e mai grav decât toate, căci sentința lor a fost pecetluită din pricina lui."},{"author":"Radak (1160–1235)","text":"Radak: „Mi-am lovit palmele” — ca pildă, precum omul îndurerat, cum a spus: „și Eu voi bate din palme” (Ezechiel 21:17). Și în cuvintele înțelepților noștri: douăzeci și patru de păcate a înșirat Ezechiel, și dintre toate n-a pecetluit decât cu jaful, căci s-a spus: „Mi-am lovit palmele din pricina tâlhăriei tale”."},{"author":"Metzudat Țion","text":"„Bițeh” — așa se numește și asuprirea, ca în „cel ce strânge câștig rău pentru casa lui” (Habacuc 2:9)."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְהִנֵּה הִכֵּיתִי כַפִּי אֶל־בִּצְעֵךְ...","translation":"„Și iată, Mi-am lovit palmele din...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ἐὰν δὲ πατάξω χεῖρά μου πρὸς χεῖρά μου ἐφ’ οἷς συντετέλεσαι, οἷς ἐποίησας, καὶ ἐπὶ τοῖς αἵμασί σου τοῖς γεγενημένοις ἐν μέσῳ σου,","greek":true,"translation":"„Iar dacă voi bate cu mâna Mea în mâna Mea pentru cele ce ai săvârșit, cele ce ai făcut, și pentru sângiurile tale care au fost în mijlocul tău,”","note":"Septuaginta transformă afirmația („Mi-am lovit palmele”) într-o condițională („iar dacă voi bate”), legând versetul de întrebarea din versetul următor."}],"refs":["Ezechiel 21:14,17","Numeri 24:10","Amos 8:4-6","Mica 6:10,11"]},{"v":"22:14","t":"Poate oare rezista inima ta, pot fi mâinile tale tari în zilele când mă voi ocupa de tine? Eu, DOMNUL, am vorbit și am înfăptuit.","tokens":[{"t":"Poate oare "},{"t":"rezista inima ta","w":"rezista inima ta","heb":"הֲיַעֲמֹד לִבֵּךְ","translit":"hayaamod libeh","strong":"H3820","pos":"verb, qal, imperfect (interogativ) + substantiv cu sufix","def_ro":"va putea sta în picioare inima ta?","dict_ro":"Lev — inima, sediul curajului și al puterii de a îndura; întrebarea „va sta în picioare inima ta?” e retorică: nimeni nu poate rezista judecății divine (compară Evrei 10:31). Radak explică: poate inima ta să îndure mulțimea necazurilor pe care le aduc asupra ta? — iar încheierea „am vorbit și am înfăptuit” înseamnă că la Dumnezeu cuvântul și fapta sunt unul, pentru că puterea e în mâna Lui."},{"t":", pot fi mâinile tale tari în zilele când mă voi ocupa de tine? Eu, DOMNUL, am vorbit și am înfăptuit."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Când mă voi ocupa de tine” — când voi face cu tine după faptele tale."},{"author":"Radak (1160–1235)","text":"Radak: „Poate oare rezista inima ta” — va putea inima ta să stea în fața mulțimii necazurilor pe care le aduc asupra ta? Aceasta e „în zilele când voi lucra cu tine” — adică zilele necazurilor. „Am vorbit și am înfăptuit” — cum am vorbit, așa voi împlini, căci Eu sunt DOMNUL și puterea este în mâna Mea."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"הֲיַעֲמֹד לִבֵּךְ אִם־תֶּחֱזַקְנָה יָדַיִךְ...","translation":"„Poate oare rezista inima ta, pot...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"εἰ ὑποστήσεται ἡ καρδία σου; εἰ κρατήσουσιν αἱ χεῖρές σου ἐν ταῖς ἡμέραις, αἷς ἐγὼ ποιῶ ἐν σοί; ἐγὼ Κύριος λελάληκα καὶ ποιήσω.","greek":true,"translation":"„oare va rezista inima ta? Oare vor fi tari mâinile tale în zilele în care Eu lucrez în tine? Eu, Domnul, am grăit și voi face.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Ezechiel 21:7","Iov 40:9","1 Corinteni 10:22","Ezechiel 24:14"]},{"v":"22:15","t":"Apoi te voi împrăștia printre neamuri și te voi risipi prin țări străine și voi pune capăt necurățeniei tale din tine.","tokens":[{"t":"Apoi "},{"t":"te voi împrăștia","w":"te voi împrăștia","heb":"וַהֲפִיצוֹתִי","translit":"vahafițoti","strong":"H6327","pos":"verb, hifil, perfect consecutiv, persoana I singular","def_ro":"te voi risipi, te voi împrăștia.","dict_ro":"Puț — „a risipi, a împrăștia”, verbul exilului, anunțat încă din Tora (Levitic 26:33; Deuteronom 28:64). Ezechiel dă însă exilului și un rost purificator: „voi pune capăt necurăției tale din tine”. Radak explică concret: în exil nu vor mai sluji idolilor, care sunt necurăția cea mare — iar istoria confirmă că după exilul babilonian idolatria a dispărut din Israel."},{"t":" printre neamuri și te voi risipi prin țări străine și voi pune capăt necurățeniei tale din tine."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Și voi pune capăt” — și voi sfârși [necurăția ta]."},{"author":"Radak (1160–1235)","text":"Radak: „Voi pune capăt necurăției tale din tine” — căci în exil nu vor mai sluji idolilor, care sunt necurăția cea mare."},{"author":"Metzudat Țion","text":"„Vezeritih” — cu sensul de risipire. „Vahatimoti” — din „sfârșit, încheiere și nimicire”."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַהֲפִיצוֹתִי אוֹתָךְ בַּגּוֹיִם וְזֵרִיתִיךְ...","translation":"„Apoi te voi împrăștia printre neamuri...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ διασκορπιῶ σε ἐν τοῖς ἔθνεσι καὶ διασπερῶ σε ἐν ταῖς χώραις, καὶ ἐκλείψει ἡ ἀκαθαρσία σου ἐκ σοῦ,","greek":true,"translation":"„și te voi risipi printre neamuri și te voi semăna prin ținuturi, și va pieri necurăția ta din tine,”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Levitic 26:33","Deuteronom 28:25,64","Neemia 1:8","Isaia 1:25","Zaharia 13:9","Maleahi 3:3"]},{"v":"22:16","t":"Și vei fi întinat în tine însuți sub ochii neamurilor și vei ști că Eu sunt DOMNUL.","tokens":[{"t":"Și "},{"t":"vei fi întinat","w":"vei fi întinat","heb":"וְנִחַלְתְּ","translit":"venihalt","strong":"H2490","pos":"verb, nifal, perfect consecutiv, persoana a II-a feminin singular","def_ro":"vei fi pângărit, profanat.","dict_ro":"Halal — „a profana, a face profan”, opusul lui „sfânt”; Rashi și Metzudat Țion citesc „vei fi pângărit în tine însuți, pentru ce ai făcut”. Radak propune și o altă lectură, de la nahala („moștenire”): „vei fi moștenită în tine însăți” — până acum erai moștenirea Mea, de acum nu mai ești, iar neamurile vor vedea aceasta; lectură pe care o reflectă și Septuaginta. Încheierea „și vei ști că Eu sunt DOMNUL” e refrenul lui Ezechiel: judecata are drept scop cunoașterea lui Dumnezeu."},{"t":" în tine însuți sub ochii neamurilor și vei ști că Eu sunt DOMNUL."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Și vei fi pângărit în tine” — vei fi pângărit în tine însuți pentru ce ai făcut."},{"author":"Radak (1160–1235)","text":"Radak: „Venihalt bah” — rădăcina e „nahal”, și sensul este: vei fi moștenită în tine însăți, căci până acum erai moștenirea Mea, iar de acum nu mai ești moștenirea Mea; unii explică „venihalt” cu sensul de pângărire. „Sub ochii neamurilor” — căci ele vor vedea că nu mai ești socotită moștenirea Mea, fiind în exil printre ele. „Și vei ști că Eu sunt DOMNUL” — atunci vei ști și vei recunoaște, când vor veni asupra ta toate relele pe care ți le-am spus prin profeții Mei, că Eu sunt DOMNUL, care spune și face, hotărăște și împlinește."},{"author":"Metzudat Țion","text":"„Venihalt” — din „pângărire”."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְנִחַלְתְּ בָּךְ לְעֵינֵי גוֹיִם...","translation":"„Și vei fi întinat în tine...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ κατακληρονομήσω ἐν σοὶ κατ’ ὀφθαλμοὺς τῶν ἐθνῶν· καὶ γνώσεσθε διότι ἐγὼ Κύριος.","greek":true,"translation":"„și Îmi voi lua moștenire în tine înaintea ochilor neamurilor; și veți cunoaște că Eu sunt Domnul.”","note":"Divergență reală: Septuaginta are „Îmi voi lua moștenire în tine” (κατακληρονομήσω), citind verbul de la nahal („a moșteni”), nu de la halal („a pângări”) — aceeași lectură alternativă pe care o menționează și Radak."}],"refs":["Ezechiel 7:24","Isaia 43:28","Isaia 47:6","Ezechiel 6:7","Psalmii 83:18"]}]},{"num":9,"title":"Kedoșim (sefard) - Sfinți","ref":"Ezechiel 20:2-20","intro":"În tradiția sefardă și în comunitățile Chabad, haftara pericopei Kedoșim este din Ezechiel 20; ea se citește și atunci când pericopele Aharéi Mot și Kedoșim se citesc împreună. Bătrânii lui Israel vin să-L caute pe DOMNUL prin profet, iar răspunsul este o lecție de istorie: din Egipt și până în pustie, poporul s-a răzvrătit iar și iar, părăsind decretele, judecățile și Sabatele pe care Dumnezeu i le dăduse „ca omul să le înfăptuiască și să trăiască prin ele”. De fiecare dată, Dumnezeu i-a cruțat „de dragul Numelui Său”, ca să nu fie pângărit înaintea neamurilor. Haftara se încheie cu îndemnul adresat noii generații — să nu urmeze decretele părinților, ci să sfințească Sabatele, semnul dintre Dumnezeu și poporul Său —, făcând ecou chemării pericopei: „sfinți să fiți”.","verses":[{"v":"20:2","t":"Atunci cuvântul DOMNULUI a venit la mine, spunând:","tokens":[{"t":"Atunci "},{"t":"cuvântul DOMNULUI","w":"cuvântul DOMNULUI","heb":"דְבַר־יְהוָה","translit":"devar-ADONAI","strong":"H1697","pos":"substantiv, masculin singular, în construcție + nume divin","def_ro":"cuvântul DOMNULUI.","dict_ro":"Devar ADONAI — formula care deschide oracolul; capitolul 20 e datat precis (20:1), în al șaptelea an al exilului lui Iehoiahin, când bătrânii lui Israel vin să-l întrebe pe profet. Răspunsul pe care îl primesc nu e cel așteptat: în loc de o profeție despre viitor, Ezechiel face istoria răzvrătirilor lui Israel, de la Egipt până la pustie."},{"t":" a venit la mine, spunând:"}],"commentaries":[],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיְהִי דְבַר־יְהוָה אֵלַי לֵאמֹר׃...","translation":"„Atunci cuvântul DOMNULUI a venit la...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐγένετο λόγος Κυρίου πρός με λέγων·","greek":true,"translation":"„Și a fost cuvântul Domnului către mine, zicând:”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":[]},{"v":"20:3","t":"„Fiu al omului, vorbește bătrânilor lui Israel și spune-le: «Așa a spus Stăpânul meu, Domnul DUMNEZEU: Ca să Mă căutați ați venit? Precum Eu sunt viu, nu Mă voi lăsa căutat de voi – rostirea Stăpânului meu, Domnul DUMNEZEU.»","tokens":[{"t":"„Fiu al omului, vorbește "},{"t":"bătrânilor lui Israel","w":"bătrânilor lui Israel","heb":"זִקְנֵי יִשְׂרָאֵל","translit":"ziknei Israël","strong":"H2205","pos":"adjectiv substantivat, masculin plural, în construcție + nume propriu","def_ro":"bătrânii, conducătorii lui Israel.","dict_ro":"Zekenim — bătrânii, conducătorii comunității exilate, care vin „să-L caute” pe DOMNUL prin profet; Metzudat David explică „a căuta” ca rugăciune: de aceea jurământul „nu Mă voi lăsa căutat” înseamnă „nu vă voi primi rugăciunea”. Rashi observă însă că la sfârșitul cărții (Ezechiel 36:37) Dumnezeu spune „Mă voi lăsa căutat de casa lui Israel” — unul dintre locurile care arată că Sfântul, binecuvântat fie El, Se întoarce de la rău."},{"t":" și spune-le: «Așa a spus Stăpânul meu, Domnul DUMNEZEU: Ca să Mă căutați ați venit? Precum Eu sunt viu, nu Mă voi lăsa căutat de voi – rostirea Stăpânului meu, Domnul DUMNEZEU.»"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Nu Mă voi lăsa căutat de voi” — în cererea voastră. Și totuși, la sfârșitul acestei cărți (36:37), El spune: „Mă voi lăsa căutat de casa lui Israel” — acesta e unul dintre locurile care ne învață că Sfântul, binecuvântat fie El, Se răzgândește de la rău; și despre lucruri asemănătoare s-a spus: „El spune, dar nu face” (după Midrash Tanhuma)."},{"author":"Metzudat David","text":"„Ca să Mă căutați” — cu he interogativ: oare ați venit să Mă căutați prin rugăciune? Iată, să știți: Mă jur, viu sunt Eu, că nu Mă voi lăsa căutat de voi, ca să vă primesc rugăciunea."},{"author":"Metzudat Țion","text":"„Hălidroș” — cu sensul de rugăciune, ca în „eu L-aș căuta pe Dumnezeu” (Iov 5:8)."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"בֶּן־אָדָם דַּבֵּר אֶת־זִקְנֵי יִשְׂרָאֵל...","translation":"„„Fiu al omului, vorbește bătrânilor lui...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"υἱὲ ἀνθρώπου, λάλησον πρὸς τοὺς πρεσβυτέρους τοῦ οἴκου ᾿Ισραὴλ καὶ ἐρεῖς πρὸς αὐτούς· τάδε λέγει Κύριος· εἰ ἐπερωτῆσαί με ὑμεῖς ἔρχεσθε; ζῶ ἐγὼ εἰ ἀποκριθήσομαι ὑμῖν, λέγει Κύριος·","greek":true,"translation":"„Fiul omului, vorbește bătrânilor casei lui Israel și le vei zice: Așa zice Domnul: Oare ca să Mă întrebați veniți voi? Viu sunt Eu, că nu vă voi răspunde, zice Domnul.”","note":"Septuaginta redă „nu Mă voi lăsa căutat de voi” prin „nu vă voi răspunde” (ἀποκριθήσομαι) și adaugă „casei” (bătrânii casei lui Israel)."}],"refs":["Isaia 1:12","Ezechiel 14:3,4,7,8","1 Samuel 28:6","Proverbe 15:8","Isaia 1:15"]},{"v":"20:4","t":"Îi vei dojeni, [îi] vei dojeni, fiu al omului? Fă-le cunoscute ororile părinților lor","tokens":[{"t":"Îi vei dojeni, [îi] vei dojeni, fiu al omului? Fă-le cunoscute "},{"t":"ororile","w":"ororile","heb":"תּוֹעֲבֹת","translit":"toavot","strong":"H8441","pos":"substantiv, feminin plural, în construcție","def_ro":"urâciunile, lucrurile abominabile.","dict_ro":"Toeva — urâciunea, ceea ce e respingător înaintea lui Dumnezeu, termen folosit mai ales pentru idolatrie și relațiile oprite. Radak explică sensul dojanei: profetul trebuie să le arate nu doar faptele lor, ci și „ororile părinților”, căci încă de la început aceștia Îl mâniaseră prin lucrarea mâinilor lor; Metzudat David adaugă că astfel se arată că judecata e dreaptă, păcatele lor venind peste cele moștenite."},{"t":" părinților lor"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Îi vei dojeni” — „hatișpot” e o expresie de dispută, de ceartă în judecată."},{"author":"Metzudat David","text":"„Îi vei dojeni” — oare te vei certa cu ei ca să le arăți că dreptatea e de partea Mea? Fă aceasta: fă-le cunoscute ororile părinților lor, împreună cu cele pe care le-au adăugat ei."},{"author":"Radak (1160–1235)","text":"Radak: Ionatan traduce „ceartă-te cu ei, ceartă-te, fiu al omului” — adică, dacă vrei să-i judeci pentru răutatea lor, mustră-i pentru faptele lor rele și fă-le cunoscute și ororile părinților lor, căci încă de demult M-au mâniat prin lucrarea mâinilor lor."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"הֲתִשְׁפֹּט אֹתָם הֲתִשְׁפֹּט בֶּן־אָדָם...","translation":"„Îi vei dojeni, [îi] vei dojeni...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"εἰ ἐκδικήσω αὐτοὺς ἐκδικήσει, υἱὲ ἀνθρώπου, τὰς ἀνομίας τῶν πατέρων αὐτῶν διαμάρτυραι αὐτοῖς","greek":true,"translation":"„Oare îi voi pedepsi cu pedeapsă, fiul omului? Mărturisește-le fărădelegile părinților lor”","note":"Septuaginta redă „îi vei dojeni?” prin „îi voi pedepsi cu pedeapsă?” (ἐκδικήσω), mutând acțiunea de la profet la Dumnezeu."}],"refs":["Ezechiel 22:2","Ezechiel 23:36,45","Ezechiel 16:2,3","Matei 23:29-37","Faptele apostolilor 7:51,52"]},{"v":"20:5","t":"și spune-le: Așa a spus Stăpânul meu, Domnul DUMNEZEU: «În ziua în care l-am ales pe Israel, când Mi-am ridicat mâna [în jurământ] către seminția casei lui Iacov și M-am făcut cunoscut lor în Egipt și le-am jurat, spunând: ‘Eu sunt DOMNUL, Dumnezeul vostru’,","tokens":[{"t":"și spune-le: Așa a spus Stăpânul meu, Domnul DUMNEZEU: «În ziua în care l-am ales pe Israel, când "},{"t":"Mi-am ridicat mâna","w":"Mi-am ridicat mâna","heb":"וָאֶשָּׂא יָדִי","translit":"vaesa iadi","strong":"H5375","pos":"verb, qal, imperfect consecutiv, persoana I singular + substantiv cu sufix","def_ro":"Mi-am ridicat mâna (gest de jurământ).","dict_ro":"Nasa iad — „a ridica mâna”, gestul jurământului solemn (compară Geneza 14:22; Deuteronom 32:40); Radak explică jurământul prin formula „Eu sunt DOMNUL”, ca promisiunea de a da Țara „pe care Mi-am ridicat mâna s-o dau lui Avraham, Isaac și Iacov” (Exod 6:8). Rashi aduce aici o tradiție surprinzătoare: această ură a stat ascunsă înaintea lui Dumnezeu aproape nouă sute de ani, din Egipt până la Ezechiel, acoperită de iubire, și s-a trezit acum, când păcatele s-au înmulțit — „ura stârnește certuri, dar iubirea acoperă toate greșelile” (Proverbe 10:12)."},{"t":" [în jurământ] către seminția casei lui Iacov și M-am făcut cunoscut lor în Egipt și le-am jurat, spunând: ‘Eu sunt DOMNUL, Dumnezeul vostru’,"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „În ziua în care l-am ales pe Israel” — această ură a stat ascunsă înaintea Celui Omniprezent aproape nouă sute de ani, din vremea când erau în Egipt până la Ezechiel, dar iubirea Lui îi acoperea; acum însă, că și-au înmulțit fărădelegile, s-a trezit, și despre aceasta s-a spus: „ura stârnește certuri” (Proverbe 10:12)."},{"author":"Metzudat David","text":"„În ziua în care l-am ales pe Israel” — când i-am ales, fiind ei în Egipt. „Mi-am ridicat mâna” — atunci Mi-am ridicat mâna în jurământ să-i scot de acolo. „M-am făcut cunoscut lor” — prin sălășluirea Prezenței Mele asupra lui Aaron, jurând: „Eu sunt DOMNUL, Dumnezeul vostru” — adică Eu vă voi conduce și vă voi purta de grijă, nu ca neamurilor de odinioară, conduse prin mijlocirea ordinii cerești."},{"author":"Radak (1160–1235)","text":"Radak: „Mi-am ridicat mâna” — ca în „pe care Mi-am ridicat mâna s-o dau lui Avraham, lui Isaac și lui Iacov”; și aici a precizat „seminției lui Iacov”, căci ce a dat lui Avraham și lui Isaac a dat de dragul seminției lui Iacov. „Eu sunt DOMNUL” — acesta e jurământul."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְאָמַרְתָּ אֲלֵיהֶם כֹּה־אָמַר אֲדֹנָי...","translation":"„și spune-le: Așa a spus Stăpânul...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐρεῖς πρὸς αὐτούς· τάδε λέγει Κύριος· ἀφ’ ἧς ἡμέρας ᾑρέτισα τὸν οἶκον ᾿Ισραὴλ καὶ ἐγνωρίσθην τῷ σπέρματι οἴκου ᾿Ιακὼβ καὶ ἐγνώσθην αὐτοῖς ἐν γῇ Αἰγύπτου καὶ ἀντελαβόμην τῇ χειρί μου αὐτῶν λέγων· ἐγὼ Κύριος ὁ Θεὸς ὑμῶν,","greek":true,"translation":"„și le vei zice: Așa zice Domnul: Din ziua în care am ales casa lui Israel și M-am făcut cunoscut seminței casei lui Iacov și M-am făcut cunoscut lor în țara Egiptului și i-am sprijinit cu mâna Mea, zicând: Eu sunt Domnul Dumnezeul vostru,”","note":"Septuaginta redă gestul jurământului („Mi-am ridicat mâna”) prin „i-am sprijinit cu mâna Mea” (ἀντελαβόμην τῇ χειρί μου) — din jurământ devine ocrotire."}],"refs":["Exod 6:6,7","Deuteronom 7:6","Isaia 41:8,9","Geneza 14:22","Deuteronom 32:40","Exod 20:2,3"]},{"v":"20:6","t":"în acea zi Mi-am ridicat mâna [în jurământ] că îi voi scoate din țara Egiptului și îi voi duce într-o țară pe care am căutat-o pentru ei, în care curge lapte și miere, ea fiind o splendoare pentru toate țările.","tokens":[{"t":"în acea zi Mi-am ridicat mâna [în jurământ] că îi voi scoate din țara Egiptului și îi voi duce într-o țară pe care am căutat-o pentru ei, în care curge lapte și miere, ea fiind "},{"t":"o splendoare","w":"o splendoare","heb":"צְבִי","translit":"țevi","strong":"H6643","pos":"substantiv, masculin singular","def_ro":"podoabă, splendoare, frumusețe.","dict_ro":"Țevi — podoaba, strălucirea; de aici denumirea Țării „eretz hațevi”, „țara cea frumoasă” (Daniel 8:9; 11:16). Radak explică de ce: e ținutul din mijloc, lăudat mai presus de celelalte, cu aerul cel mai bine temperat dintre toate țările, precum s-a spus „frumoasă pe înălțime, bucuria întregului pământ” (Psalmii 48:2). Metzudat Țion explică „am căutat-o” (tarti) ca „cercetare”, ca în Eclesiastul 2:3 — o țară aleasă după cercetare, anume pentru ei."},{"t":" pentru toate țările."}],"commentaries":[{"author":"Metzudat David","text":"„În acea zi” — adică în chiar ziua în care le-am jurat că le voi fi Conducător și Ocrotitor, atunci am jurat să-i scot din Egipt într-o țară pe care am căutat-o pentru ei, în care curge lapte și miere, și care este cea mai strălucită dintre toate țările."},{"author":"Radak (1160–1235)","text":"Radak: „O splendoare pentru toate țările” — podoabă și desfătare pentru toate țările este ea, căci este ținutul din mijloc, lăudat mai presus de celelalte ținuturi, iar aerul ei este cel mai bine temperat și mai bun dintre toate țările; și tot așa s-a spus: „frumoasă pe înălțime, bucuria întregului pământ”."},{"author":"Metzudat Țion","text":"„Tarti” — cu sensul de cercetare, ca în „am cercetat în inima mea” (Eclesiastul 2:3). „Zavat” — din curgere și picurare. „Țevi” — cu sensul de podoabă și frumusețe."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"בַּיּוֹם הַהוּא נָשָׂאתִי יָדִי...","translation":"„în acea zi Mi-am ridicat mâna...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ἐν ἐκείνῃ τῇ ἡμέρᾳ ἀντελαβόμην τῇ χειρί μου αὐτῶν τοῦ ἐξαγαγεῖν αὐτοὺς ἐκ γῆς Αἰγύπτου εἰς τὴν γῆν, ἣν ἡτοίμασα αὐτοῖς, γῆν ῥέουσαν γάλα καὶ μέλι, κηρίον ἐστὶ παρὰ πᾶσαν τὴν γῆν.","greek":true,"translation":"„în ziua aceea i-am sprijinit cu mâna Mea, ca să-i scot din țara Egiptului în țara pe care le-am pregătit-o, țară în care curge lapte și miere; fagure de miere este ea peste tot pământul.”","note":"Septuaginta redă „am căutat-o pentru ei” prin „le-am pregătit-o” (ἡτοίμασα) și „splendoare” (țevi) prin „fagure de miere” (κηρίον) — o divergență reală de imagine."}],"refs":["Exod 3:8,17","Deuteronom 8:7-9","Exod 13:5","Numeri 14:8","Psalmii 48:2","Daniel 8:9"]},{"v":"20:7","t":"Și le-am spus: ‘Fiecare om să își arunce scârboșeniile ochilor săi și să nu se [mai] pângărească cu idolii Egiptului – Eu sunt DOMNUL, Dumnezeul vostru.’","tokens":[{"t":"Și le-am spus: ‘Fiecare om să își arunce "},{"t":"scârboșeniile ochilor săi","w":"scârboșeniile ochilor săi","heb":"שִׁקּוּצֵי עֵינָיו","translit":"șikuței einav","strong":"H8251","pos":"substantiv, masculin plural, în construcție + substantiv cu sufix","def_ro":"urâciunile pe care le privesc ochii lui (idolii).","dict_ro":"Șikuț — lucrul scârbos, termen disprețuitor pentru idoli; „scârboșeniile ochilor” sunt idolii la care ochii se uită cu poftă. Radak explică expresia prin rolul ochilor în păcat — „să nu vă luați după inima voastră și după ochii voștri” (Numeri 15:39) — și citează vorba înțelepților: „ochiul și inima sunt cei doi agenți ai păcatului” (Talmud Ierușalmi, Berahot 1:5). Rashi și Metzudat David adaugă că porunca le-a fost dată în Egipt prin Aaron, înainte ca Dumnezeu să i se descopere lui Moise în rug."},{"t":" și să nu se [mai] pângărească cu idolii Egiptului – Eu sunt DOMNUL, Dumnezeul vostru.’"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Și le-am spus” — Aaron le-a vestit această profeție înainte ca Sfântul, binecuvântat fie El, să i Se descopere lui Moise în rug; aceasta s-a spus lui Eli: „M-am descoperit Eu casei tatălui tău când erau în Egipt...?” (1 Samuel 2:27)."},{"author":"Metzudat David","text":"„Și le-am spus” — prin Aaron le-am spus: fiecare om să lepede scârboșenia și urâciunea pe care i-o arată ochii lui, căci ochiul este mijlocitorul păcatului. „Și cu idolii Egiptului” — să nu vă pângăriți mergând după ei. „Eu sunt DOMNUL, Dumnezeul vostru” — ca și cum ar spune: cum Mă puteți schimba, atunci, cu idolii?"},{"author":"Radak (1160–1235)","text":"Radak: „Fiecare să-și arunce scârboșeniile ochilor săi” — căci ochii îl aduc pe om la păcat, cum s-a spus: „să nu vă luați după inima voastră și după ochii voștri” (Numeri 15:39); și au spus înțelepții noștri: ochiul și inima sunt cei doi agenți ai păcatului."},{"author":"Talmud Ierușalmi, Berahot 1:5","text":"Rabi Levi a spus: inima și ochiul sunt cei doi agenți ai păcatului, căci scrie: „Fiul meu, dă-Mi inima ta și ochii tăi să păzească drumurile Mele” (Proverbe 23:26) — Sfântul, binecuvântat fie El, spune: dacă Îmi dai inima și ochii tăi, știu că ești al Meu."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וָאֹמַר אֲלֵהֶם אִישׁ שִׁקּוּצֵי...","translation":"„Și le-am spus: ‘Fiecare om să...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ εἶπα πρὸς αὐτούς· ἕκαστος βδελύγματα τῶν ὀφθαλμῶν αὐτοῦ ἀπορριψάτω, καὶ ἐν τοῖς ἐπιτηδεύμασιν Αἰγύπτου μὴ μιαίνεσθε, ἐγὼ Κύριος ὁ Θεὸς ὑμῶν.","greek":true,"translation":"„Și am zis către ei: Fiecare să lepede urâciunile ochilor săi și să nu vă pângăriți cu obiceiurile Egiptului; Eu sunt Domnul Dumnezeul vostru.”","note":"Septuaginta redă „idolii Egiptului” (ghilulei Mițraim) prin „obiceiurile Egiptului” (ἐπιτηδεύμασιν)."}],"refs":["Ezechiel 18:6,15,31","Isaia 31:7","2 Cronici 15:8","Levitic 18:3","Iosua 24:14","Levitic 20:7"]},{"v":"20:8","t":"Dar ei s-au răzvrătit împotriva Mea și n-au vrut să asculte de Mine. Niciunul nu a aruncat scârboșeniile ochilor lor și nu au abandonat idolii Egiptului și Mi-am spus că Îmi voi revărsa furia asupra lor, ca să Îmi sfârșesc mânia asupra lor în mijlocul țării Egiptului.","tokens":[{"t":"Dar ei "},{"t":"s-au răzvrătit","w":"s-au răzvrătit","heb":"וַיַּמְרוּ","translit":"vayamru","strong":"H4784","pos":"verb, hifil, imperfect consecutiv, persoana a III-a masculin plural","def_ro":"s-au răzvrătit, s-au împotrivit.","dict_ro":"Mara — „a fi răzvrătit, încăpățânat”, verbul care descrie în Tora generația pustiei („ați fost răzvrătiți împotriva DOMNULUI”, Deuteronom 9:7). Rashi aduce tradiția că răzvrătiții, majoritatea poporului, au murit în cele trei zile de întuneric din Egipt, iar din Egipt n-a ieșit decât unul din cincizeci (după alții, unul din cinci sute). Radak explică dublarea „să-Mi revărs furia... să-Mi sfârșesc mânia” prin imaginea vasului golit: cine varsă ce e în vas îl sfârșește."},{"t":" împotriva Mea și n-au vrut să asculte de Mine. Niciunul nu a aruncat scârboșeniile ochilor lor și nu au abandonat idolii Egiptului și Mi-am spus că Îmi voi revărsa furia asupra lor, ca să Îmi sfârșesc mânia asupra lor în mijlocul țării Egiptului."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Dar ei s-au răzvrătit împotriva Mea” — aceștia sunt nelegiuiții, majoritatea lui Israel, care au murit în cele trei zile de întuneric, precum s-a spus: „și fiii lui Israel au ieșit din Egipt «hamușim»” (Exod 13:18) — unul din cincizeci, iar unii spun: unul din cinci sute."},{"author":"Metzudat David","text":"„S-au răzvrătit împotriva Mea” — încă fiind în Egipt s-au răzvrătit împotriva DOMNULUI. „Și Mi-am spus” — din pricina aceasta M-am gândit să-Mi vărs furia asupra lor și să arunc asupra lor aprinderea mâniei Mele."},{"author":"Radak (1160–1235)","text":"Radak: „Să-Mi revărs furia... să-Mi sfârșesc mânia” — dublarea sensului în cuvinte diferite; căci atunci când omul varsă ce e într-un vas, el sfârșește ce e înăuntru."},{"author":"Metzudat Țion","text":"„Vayamru” — din răzvrătire și răscoală. „Velo avu” — și n-au vrut, ca în „nu vrea cumnatul meu” (Deuteronom 25:7). „Lehalot” — cu sensul de sfârșire."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיַּמְרוּ־בִי וְלֹא אָבוּ לִשְׁמֹעַ...","translation":"„Dar ei s-au răzvrătit împotriva Mea...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἀπέστησαν ἀπ’ ἐμοῦ καὶ οὐκ ἠθέλησαν εἰσακοῦσαί μου, τὰ βδελύγματα τῶν ὀφθαλμῶν αὐτῶν οὐκ ἀπέρριψαν καὶ τὰ ἐπιτηδεύματα Αἰγύπτου οὐκ ἐγκατέλιπον. καὶ εἶπα τοῦ ἐκχέαι τὸν θυμόν μου ἐπ’ αὐτοὺς τοῦ συντελέσαι τὴν ὀργήν μου ἐν αὐτοῖς ἐν μέσῳ γῆς Αἰγύπτου.","greek":true,"translation":"„Și s-au depărtat de Mine și n-au voit să Mă asculte; urâciunile ochilor lor nu le-au lepădat și obiceiurile Egiptului nu le-au părăsit. Și am zis să-Mi vărs mânia asupra lor, să-Mi sfârșesc urgia în ei, în mijlocul țării Egiptului.”","note":"Corespondență strânsă; „idolii Egiptului” sunt redați din nou prin „obiceiurile Egiptului”."}],"refs":["Deuteronom 9:7","Neemia 9:26","Isaia 63:10","Exod 32:4-6","Ezechiel 5:13","Ezechiel 7:8"]},{"v":"20:9","t":"Dar am acționat de dragul numelui Meu, ca să nu fie pângărit în ochii neamurilor printre care se află, în ochii cărora M-am făcut cunoscut lor ca să îi scot din țara Egiptului.","tokens":[{"t":"Dar am acționat "},{"t":"de dragul numelui Meu","w":"de dragul numelui Meu","heb":"לְמַעַן שְׁמִי","translit":"lemaan șemi","strong":"H8034","pos":"prepoziție + substantiv, masculin singular + sufix persoana I","def_ro":"pentru Numele Meu, de dragul reputației Mele.","dict_ro":"Lemaan șemi — motivul central al capitolului, repetat ca un refren (20:9, 14, 22): Dumnezeu nu i-a nimicit, nu pentru că ar fi meritat, ci ca Numele Lui să nu fie pângărit înaintea neamurilor. Rashi explică: de vreme ce M-am făcut cunoscut lor și am făgăduit să-i scot, iar egiptenii știau că sunt poporul Meu, dacă i-aș fi nimicit, dușmanii ar fi zis: „pentru că n-a fost în stare să-i scoată” — același argument pe care îl folosise Moise în rugăciunea lui (Numeri 14:13-16)."},{"t":", ca să nu fie pângărit în ochii neamurilor printre care se află, în ochii cărora M-am făcut cunoscut lor ca să îi scot din țara Egiptului."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Ca să nu fie pângărit” — ca să nu fie pângărit Numele Meu; căci M-am făcut cunoscut lor și am făgăduit să-i scot, iar egiptenii au recunoscut că sunt poporul Meu; dacă i-aș fi nimicit, dușmanii lor ar fi zis: „pentru că n-a avut puterea să-i scoată”."},{"author":"Metzudat David","text":"„Dar am acționat” — dar am lucrat de dragul Numelui Meu, ca să nu fie pângărit în ochii egiptenilor. „În ochii cărora M-am făcut cunoscut” — căci M-am făcut cunoscut lui Israel prin Aaron, care le vestea prin profeție, sub ochii egiptenilor, că îi voi răscumpăra de acolo; iar dacă ar fi pierit în Egipt, ar fi fost o pângărire a Numelui DOMNULUI, căci ar fi spus: pentru că DOMNUL n-a putut să-i scoată, i-a nimicit."},{"author":"Radak (1160–1235)","text":"Radak: „Sub ochii lor” — căci egiptenii auzeau când le vorbeau profeții și le făgăduiau să-i scoată din mijlocul lor, chiar înainte de Moise. Iar în cuvintele înțelepților noștri, și după ce a venit Moise au fost printre ei nelegiuiți care nu s-au întors de la calea lor rea, și aceia au murit în cele trei zile de întuneric, ca egiptenii să nu le vadă căderea și să se bucure de ea."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"לְכַלּוֹת אַפִּי בָּהֶם בְּתוֹךְ...","translation":"„Dar am acționat de dragul numelui...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐποίησα ὅπως τὸ ὄνομά μου τὸ παράπαν μὴ βεβηλωθῇ ἐνώπιον τῶν ἐθνῶν, ὧν αὐτοί εἰσιν ἐν μέσῳ αὐτῶν, ἐν οἷς ἐγνώσθην πρὸς αὐτοὺς ἐνώπιον αὐτῶν τοῦ ἐξαγαγεῖν αὐτοὺς ἐκ γῆς Αἰγύπτου.","greek":true,"translation":"„Și am lucrat așa încât numele Meu să nu fie deloc pângărit înaintea neamurilor în mijlocul cărora erau ei, între care M-am făcut cunoscut lor înaintea ochilor lor, ca să-i scot din țara Egiptului.”","note":"Corespondență strânsă; Septuaginta adaugă „deloc” (τὸ παράπαν) pentru a întări negația."}],"refs":["Ezechiel 36:21,22","Exod 32:12","Numeri 14:13-25","Deuteronom 9:28","Iosua 2:10"]},{"v":"20:10","t":"Și i-am scos din țara Egiptului și i-am adus în deșert,","tokens":[{"t":"Și i-am scos din țara Egiptului și i-am adus "},{"t":"în deșert","w":"în deșert","heb":"הַמִּדְבָּר","translit":"hamidbar","strong":"H4057","pos":"substantiv, masculin singular, cu articol","def_ro":"pustiul, deșertul.","dict_ro":"Midbar — pustiul, locul fără așezări, dar în tradiția biblică și locul întâlnirii cu Dumnezeu: acolo au primit Tora, Sabatul și mana. Versetul e scurt, o simplă tranziție, dar Ezechiel construiește pe el întreaga a doua etapă a istoriei: pustiul devine scena a două răzvrătiri — generația care a ieșit din Egipt (20:13-17) și copiii ei (20:18 și urm.)."},{"t":","}],"commentaries":[{"author":"Radak (1160–1235)","text":"Radak: „Și i-am scos... și i-am adus” — în amândouă cuvintele lipsește un iod [în scriere]."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וָאוֹצִיאֵם מֵאֶרֶץ מִצְרָיִם וָאֲבִאֵם...","translation":"„Și i-am scos din țara Egiptului...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἤγαγον αὐτοὺς εἰς τὴν ἔρημον","greek":true,"translation":"„Și i-am dus în pustie”","note":"Septuaginta omite prima jumătate a versetului („i-am scos din țara Egiptului”), păstrând doar „i-am dus în pustie”."}],"refs":["Exod 13:17,18","Exod 14:17-22","Exod 15:22","Exod 20:2"]},{"v":"20:11","t":"și le-am dat decretele Mele, și le-am făcut cunoscute judecățile Mele pe care omul să le înfăptuiască și să trăiască prin ele.","tokens":[{"t":"și le-am dat decretele Mele, și le-am făcut cunoscute judecățile Mele pe care omul să le înfăptuiască și "},{"t":"să trăiască prin ele","w":"să trăiască prin ele","heb":"וָחַי בָּהֶם","translit":"vahai bahem","strong":"H2425","pos":"verb, qal, perfect consecutiv, persoana a III-a masculin singular + prepoziție cu sufix","def_ro":"și va trăi prin ele.","dict_ro":"Vahai bahem — citat direct din Levitic 18:5, „pe care omul le va face și va trăi prin ele”. Radak și Metzudat David, urmând Targumul, citesc „va trăi” ca viață deplină: viața din lumea aceasta și viața lumii ce va veni. Pavel folosește același verset (Romani 10:5; Galateni 3:12) ca definiție a dreptății prin Lege."},{"t":"."}],"commentaries":[{"author":"Metzudat David","text":"„Pe care omul să le înfăptuiască” — adică decretele și judecățile acelea sunt în stare să-l facă să trăiască pe omul care le împlinește, în viața lumii acesteia și a lumii ce va veni."},{"author":"Radak (1160–1235)","text":"Radak: „Și să trăiască prin ele” — ca în traducerea lui [Ionatan]: „și va trăi prin ele viața veșnică”; și tot așa a tradus Onkelos „și va trăi prin ele” [din Levitic 18:5]."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וָאֶתֵּן לָהֶם אֶת־חֻקּוֹתַי וְאֶת־מִשְׁפָּטַי...","translation":"„și le-am dat decretele Mele, și...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἔδωκα αὐτοῖς τὰ προστάγματά μου καὶ τὰ δικαιώματά μου ἐγνώρισα αὐτοῖς, ὅσα ποιήσει αὐτὰ ἄνθρωπος καὶ ζήσεται ἐν αὐτοῖς.","greek":true,"translation":"„și le-am dat poruncile Mele și rânduielile Mele le-am făcut cunoscute lor, pe care făcându-le omul va trăi prin ele.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Deuteronom 4:8","Neemia 9:13,14","Psalmii 147:19,20","Levitic 18:5","Luca 10:28","Romani 10:5"]},{"v":"20:12","t":"Și le-am dat totodată Șabaturile Mele, ca să fie semn între Mine și ei, să știe că Eu sunt DOMNUL care îi sfințește.","tokens":[{"t":"Și le-am dat totodată Șabaturile Mele, ca să fie "},{"t":"semn","w":"semn","heb":"לְאוֹת","translit":"leot","strong":"H226","pos":"prepoziție + substantiv, masculin singular","def_ro":"semn, însemn, dovadă.","dict_ro":"Ot — semnul, marca vizibilă a unei realități nevăzute; Sabatul e numit „semn între Mine și voi” încă din Exod 31:13, de unde e preluată formularea. Rashi îl numește „un semn mare” — Dumnezeu le-a dat ziua odihnei Lui ca zi de odihnă, dovadă că i-a sfințit pentru Sine. Radak adaugă că pluralul „Sabatele Mele” cuprinde și sărbătorile și că, fiind Sabatul echivalent cu toate poruncile — învățătura lui Rebbi din Talmudul Ierușalmi, Berahot 1:5 —, profetul revine de atâtea ori la pângărirea lui."},{"t":" între Mine și ei, să știe că Eu sunt DOMNUL care îi sfințește."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Ca să fie semn” — este un semn mare pentru ei că le-am dat ziua odihnei Mele spre odihnă; iată, aceasta e o dovadă minunată că i-am sfințit pentru Mine."},{"author":"Radak (1160–1235)","text":"Radak: „Și Sabatele Mele” — a spus „și”, căci este un dar bun pe care Dumnezeu l-a dat poporului Său Israel, ca să le amintească ziua odihnei pe care le-a dat-o și că i-a scos din robie la libertate; și acesta e semnul dintre Dumnezeu și Israel, că i-a sfințit și i-a despărțit de neamuri. A spus „Sabatele” la plural, cuprinzând și odihna sărbătorilor, căci și ele sunt amintire a ieșirii din Egipt; și pentru că porunca Sabatului e mare și cântărește cât toate poruncile, a pomenit de atâtea ori în această mustrare pângărirea Sabatului."},{"author":"Talmud Ierușalmi, Berahot 1:5","text":"Rebbi a spus: aceasta este porunca Sabatului, care cântărește cât toate celelalte porunci ale Torei laolaltă, căci scrie: „Le-ai făcut cunoscut Sabatul Tău cel sfânt și le-ai poruncit porunci, legi și învățătură” (Neemia 9:14)."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְגַם אֶת־שַׁבְּתוֹתַי נָתַתִּי לָהֶם...","translation":"„Și le-am dat totodată Șabaturile Mele...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ τὰ σάββατά μου ἔδωκα αὐτοῖς τοῦ εἶναι εἰς σημεῖον ἀνὰ μέσον ἐμοῦ καὶ ἀνὰ μέσον αὐτῶν τοῦ γνῶναι αὐτοὺς διότι ἐγὼ Κύριος ὁ ἁγιάζων αὐτούς.","greek":true,"translation":"„Și Sabatele Mele le-am dat lor, ca să fie semn între Mine și ei, ca să cunoască ei că Eu sunt Domnul, Cel ce îi sfințește.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Exod 31:13-17","Exod 20:8-11","Deuteronom 5:12-15","Neemia 9:14","Marcu 2:27,28","Ezechiel 37:28"]},{"v":"20:13","t":"Dar casa lui Israel s-a răzvrătit împotriva Mea în deșert, nu au urmat decretele Mele și au respins judecățile Mele pe care să le înfăptuiască omul și să trăiască prin ele, și Șabaturile Mele le-au pângărit mult. Și Mi-am spus că Îmi voi revărsa furia asupra lor în deșert, ca să îi nimicesc.","tokens":[{"t":"Dar casa lui Israel s-a răzvrătit împotriva Mea în deșert, nu au urmat decretele Mele și "},{"t":"au respins","w":"au respins","heb":"מָאָסוּ","translit":"maasu","strong":"H3988","pos":"verb, qal, perfect, persoana a III-a plural","def_ro":"au lepădat, au disprețuit.","dict_ro":"Maas — „a respinge, a lepăda cu dispreț”, verbul folosit în blestemele din Levitic 26:15, 43 („dacă veți disprețui legile Mele”). Rashi enumeră răzvrătirile concrete din pustie: L-au ispitit cu vițelul, la Refidim au șovăit să primească Tora și au lăsat mană peste noapte; iar „Sabatele le-au pângărit” — unii din popor au ieșit să strângă mană în Sabat (Exod 16:27). Metzudat David explică „foarte”: în primul Sabat au ieșit după mană, iar în al doilea omul care strângea lemne l-a pângărit cu totul (Numeri 15:32)."},{"t":" judecățile Mele pe care să le înfăptuiască omul și să trăiască prin ele, și Șabaturile Mele le-au pângărit mult. Și Mi-am spus că Îmi voi revărsa furia asupra lor în deșert, ca să îi nimicesc."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „N-au umblat în decretele Mele” — M-au ispitit cu vițelul și la Refidim [șovăind] să primească Tora, și au lăsat din mană [până dimineața]. „Și Sabatele Mele le-au pângărit” — unii din popor au ieșit să strângă mană."},{"author":"Metzudat David","text":"„Pe care să le înfăptuiască omul” — ca și cum ar spune: deși decretele și judecățile sunt în stare să-l facă să trăiască pe omul care le împlinește, n-au ținut seama de ele. „Le-au pângărit mult” — căci în primul Sabat l-au pângărit, cum s-a spus: „în ziua a șaptea unii din popor au ieșit să strângă” (Exod 16:27), iar în al doilea Sabat l-a pângărit cel ce strângea lemne, cu dispreț."},{"author":"Radak (1160–1235)","text":"Radak: „N-au umblat în decretele Mele” — pe care li le-a poruncit la Mara, cum scrie acolo: „acolo i-a dat o lege și o rânduială” (Exod 15:25). „Le-au pângărit mult” — căci chiar primul Sabat l-au pângărit, ieșind să strângă mană; de aceea a spus „mult”."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיַּמְרוּ־בִי בֵית־יִשְׂרָאֵל בַּמִּדְבָּר בְּחֻקּוֹתַי...","translation":"„Dar casa lui Israel s-a răzvrătit...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ εἶπα πρὸς τὸν οἶκον τοῦ ᾿Ισραὴλ ἐν τῇ ἐρήμῳ· ἐν τοῖς προστάγμασί μου πορεύεσθε· καὶ οὐκ ἐπορεύθησαν καὶ τὰ δικαιώματά μου ἀπώσαντο, ἃ ποιήσει αὐτὰ ἄνθρωπος καὶ ζήσεται ἐν αὐτοῖς, καὶ τὰ σάββατά μου ἐβεβήλωσαν σφόδρα. καὶ εἶπα τοῦ ἐκχέαι τὸν θυμόν μου ἐπ’ αὐτοὺς ἐν τῇ ἐρήμῳ τοῦ ἐξαναλῶσαι αὐτούς.","greek":true,"translation":"„Și am zis casei lui Israel în pustie: Umblați în poruncile Mele; dar n-au umblat, și rânduielile Mele le-au lepădat, pe care făcându-le omul va trăi prin ele, și Sabatele Mele le-au pângărit foarte. Și am zis să-Mi vărs mânia asupra lor în pustie, ca să-i nimicesc.”","note":"Septuaginta reformulează începutul: în loc de „s-a răzvrătit împotriva Mea”, are „am zis casei lui Israel în pustie: umblați în poruncile Mele; dar n-au umblat” — o divergență reală de structură."}],"refs":["Exod 16:28","Numeri 14:22","Psalmii 78:40,41","Numeri 15:31-36","Levitic 26:15,43","Psalmii 106:23"]},{"v":"20:14","t":"Dar am acționat de dragul numelui Meu, pentru ca el să nu fie pângărit în ochii neamurilor sub ochii cărora i-am scos [din Egipt].","tokens":[{"t":"Dar am acționat de dragul numelui Meu, pentru ca el "},{"t":"să nu fie pângărit","w":"să nu fie pângărit","heb":"לְבִלְתִּי הֵחֵל","translit":"levilti hehel","strong":"H2490","pos":"prepoziție negativă + verb, nifal, infinitiv construct","def_ro":"ca să nu fie profanat.","dict_ro":"Halal, la nifal — „a fi profanat, pângărit”; pângărirea Numelui (hilul Hașem) e opusul sfințirii lui, ideea centrală a acestui capitol. Metzudat David precizează cine ar fi vorbit: egiptenii, sub ochii cărora ieșiseră, ar fi spus că DOMNUL n-a fost în stare să-i aducă în Canaan și de aceea i-a nimicit în pustie — de aceea Dumnezeu i-a cruțat și a doua oară."},{"t":" în ochii neamurilor sub ochii cărora i-am scos [din Egipt]."}],"commentaries":[{"author":"Metzudat David","text":"„Să nu fie pângărit” — ca să nu fie pângărit în ochii neamurilor sub ochii cărora i-am scos pe Israel, adică egiptenii; căci așa ar fi spus: pentru că DOMNUL n-a putut să-i aducă în țara Canaanului, i-a nimicit în pustie."},{"author":"Metzudat Țion","text":"„Hehel” — din „pângărire”."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וָאֶעֱשֶׂה לְמַעַן שְׁמִי לְבִלְתִּי...","translation":"„Dar am acționat de dragul numelui...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐποίησα ὅπως τὸ ὄνομά μου τὸ παράπαν μὴ βεβηλωθῇ ἐνώπιον τῶν ἐθνῶν, ὧν ἐξήγαγον αὐτοὺς κατ’ ὀφθαλμοὺς αὐτῶν.","greek":true,"translation":"„Și am lucrat așa încât numele Meu să nu fie deloc pângărit înaintea neamurilor din mijlocul cărora i-am scos înaintea ochilor lor.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Ezechiel 20:9,22","Ezechiel 36:22,23","Efeseni 1:6,12"]},{"v":"20:15","t":"Dar totodată, le-am jurat în deșert să nu îi aduc în țara pe care le-am dat-o lor, în care curge lapte și miere, ea fiind o splendoare pentru toate țările.","tokens":[{"t":"Dar totodată, "},{"t":"le-am jurat","w":"le-am jurat","heb":"נָשָׂאתִי יָדִי","translit":"nasati iadi","strong":"H5375","pos":"verb, qal, perfect, persoana I singular + substantiv cu sufix","def_ro":"Mi-am ridicat mâna [în jurământ], am jurat.","dict_ro":"Nasa iad — aceeași expresie a jurământului ca în 20:5, dar acum întoarsă împotriva lor: Dumnezeu, care jurase să-i aducă în Țară, jură acum că nu-i va aduce. Metzudat David și Radak identifică momentul: păcatul iscoadelor, când s-a hotărât ca generația pustiei să nu intre în Țară — „dar viu sunt Eu... niciunul dintre oamenii aceștia nu va vedea țara” (Numeri 14:21-23)."},{"t":" în deșert să nu îi aduc în țara pe care le-am dat-o lor, în care curge lapte și miere, ea fiind o splendoare pentru toate țările."}],"commentaries":[{"author":"Metzudat David","text":"„Le-am jurat” — Mi-am ridicat mâna în jurământ asupra lor. „Să nu îi aduc” — aceasta a fost din pricina păcatului iscoadelor, căci atunci s-a hotărât asupra lor să nu intre în Țară."},{"author":"Radak (1160–1235)","text":"Radak: „Și Eu Mi-am ridicat mâna împotriva lor” — la întâmplarea cu iscoadele, când a spus: „dar viu sunt Eu, și slava DOMNULUI va umple tot pământul” (Numeri 14:21)."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְגַם־אֲנִי נָשָׂאתִי יָדִי לָהֶם...","translation":"„Dar totodată, le-am jurat în deșert...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐγὼ ἐξῇρα τὴν χεῖρά μου ἐπ’ αὐτοὺς ἐν τῇ ἐρήμῳ τὸ παράπαν τοῦ μὴ εἰσαγαγεῖν αὐτοὺς εἰς τὴν γῆν, ἣν ἔδωκα αὐτοῖς, γῆν ρέουσαν γάλα καὶ μέλι, κηρίον ἐστὶ παρὰ πᾶσαν τὴν γῆν,","greek":true,"translation":"„Și Eu Mi-am ridicat mâna asupra lor în pustie, ca nicidecum să nu-i aduc în țara pe care le-am dat-o, țară în care curge lapte și miere; fagure de miere este ea peste tot pământul,”","note":"Septuaginta redă din nou „splendoare” (țevi) prin „fagure de miere” (κηρίον), ca la 20:6."}],"refs":["Numeri 14:23-30","Numeri 26:64,65","Deuteronom 1:34,35","Psalmii 95:11","Psalmii 106:26"]},{"v":"20:16","t":"Căci Mi-au respins judecățile și nu au urmat decretele Mele, Mi-au pângărit Șabaturile, căci inima lor merge după idolii lor.","tokens":[{"t":"Căci Mi-au respins judecățile și nu au urmat decretele Mele, Mi-au pângărit Șabaturile, căci inima lor merge după "},{"t":"idolii lor","w":"idolii lor","heb":"גִּלּוּלֵיהֶם","translit":"ghiluleihem","strong":"H1544","pos":"substantiv, masculin plural + sufix persoana a III-a plural","def_ro":"idolii lor.","dict_ro":"Ghilulim — idolii (cuvântul disprețuitor preferat de Ezechiel); Metzudat David precizează că e vorba de idolii pe care îi slujiseră în Egipt. Expresia „inima lor merge după idolii lor” completează imaginea din 20:7, unde păcatul pornea de la ochi: acum inima însăși a luat-o pe urma lor — cei doi „agenți ai păcatului” despre care vorbea Rabi Levi."},{"t":"."}],"commentaries":[{"author":"Metzudat David","text":"„După idolii lor” — după idolii pe care îi slujiseră în Egipt."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"יַעַן בְּמִשְׁפָּטַי מָאָסוּ וְאֶת־חֻקּוֹתַי...","translation":"„Căci Mi-au respins judecățile și nu...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ἀνθ’ ὧν τὰ δικαιώματά μου ἀπώσαντο καὶ ἐν τοῖς προστάγμασί μου οὐκ ἐπορεύθησαν ἐν αὐτοῖς καὶ τὰ σάββατά μου ἐβεβήλουν καὶ ὀπίσω τῶν ἐνθυμημάτων καρδίας αὐτῶν ἐπορεύοντο.","greek":true,"translation":"„pentru că rânduielile Mele le-au lepădat și în poruncile Mele n-au umblat și Sabatele Mele le pângăreau și mergeau după născocirile inimii lor.”","note":"Septuaginta redă „idolii lor” prin „născocirile inimii lor” (ἐνθυμημάτων καρδίας), evitând din nou numirea directă a idolilor."}],"refs":["Ezechiel 20:13,14","Exod 32:1-8","Numeri 15:39","Numeri 25:2","Amos 5:25,26","Faptele apostolilor 7:39-43"]},{"v":"20:17","t":"Dar ochiului Meu i s-a făcut milă de ei, nedistrugându-i, și nu i-am făcut să se sfârșească în deșert.","tokens":[{"t":"Dar ochiului Meu "},{"t":"i s-a făcut milă","w":"i s-a făcut milă","heb":"וַתָּחָס","translit":"vatahos","strong":"H2347","pos":"verb, qal, imperfect consecutiv, persoana a III-a feminin singular","def_ro":"a cruțat, i s-a făcut milă.","dict_ro":"Hus — „a cruța, a avea milă”, spus de obicei despre ochi („să nu-ți cruțe ochiul”, Deuteronom 7:16), de unde și formularea neobișnuită „ochiului Meu i s-a făcut milă”. Metzudat David explică: meritaseră nimicirea totală, dar ochiul Meu i-a cruțat; iar Radak arată în ce a constat mila — i-a lăsat pe copiii lor după ei, ca să-i aducă pe aceștia în Țară."},{"t":" de ei, nedistrugându-i, și nu i-am făcut să se sfârșească în deșert."}],"commentaries":[{"author":"Metzudat David","text":"„I s-a făcut milă” — adică erau vrednici chiar de nimicire, dar ochiul Meu i-a cruțat, ca să nu-i distrug, și de aceea nu i-am sfârșit în pustie."},{"author":"Radak (1160–1235)","text":"Radak: „Și nu i-am făcut să se sfârșească” — căci le-am lăsat pe copiii lor după ei, ca să-i aduc în Țară."},{"author":"Metzudat Țion","text":"„Vatahos” — din cruțare și milă."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַתָּחָס עֵינִי עֲלֵיהֶם מִשַּׁחֲתָם...","translation":"„Dar ochiului Meu i s-a făcut...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐφείσατο ὁ ὀφθαλμός μου ἐπ’ αὐτοὺς τοῦ ἐξαλεῖψαι αὐτοὺς καὶ οὐκ ἐποίησα αὐτοὺς εἰς συντέλειαν ἐν τῇ ἐρήμῳ.","greek":true,"translation":"„Și ochiul Meu i-a cruțat, ca să nu-i șterg, și nu i-am făcut să piară de tot în pustie.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Neemia 9:19","Psalmii 78:37,38","Ieremia 4:27","Ieremia 5:18"]},{"v":"20:18","t":"Ci le-am spus copiilor lor în deșert: ‘Nu urmați judecățile părinților voștri, nu păziți decretele lor și nu vă pângăriți prin idolii lor.","tokens":[{"t":"Ci le-am spus "},{"t":"copiilor lor","w":"copiilor lor","heb":"בְּנֵיהֶם","translit":"beneihem","strong":"H1121","pos":"substantiv, masculin plural + sufix persoana a III-a plural","def_ro":"fiii, copiii lor.","dict_ro":"Banim — fiii, a doua generație a pustiei, cea care urma să intre în Țară (Metzudat David). Îndemnul „nu urmați judecățile părinților voștri” răstoarnă respectul obișnuit față de tradiția părinților: când aceasta e idolatrie, fidelitatea față de părinți devine păcat — Metzudat David precizează că e vorba de „decretele pe care le-au născocit din inima lor, pe care DOMNUL nu le-a poruncit”."},{"t":" în deșert: ‘Nu urmați judecățile părinților voștri, nu păziți decretele lor și nu vă pângăriți prin idolii lor."}],"commentaries":[{"author":"Metzudat David","text":"„Copiilor lor” — fiii generației care ieșise din Egipt, ei sunt cei care au intrat în Țară. „Judecățile părinților voștri” — pe care le-au născocit din inima lor, pe care DOMNUL nu le-a poruncit."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וָאֹמַר אֶל־בְּנֵיהֶם בַּמִּדְבָּר בְּחוּקֵּי...","translation":"„Ci le-am spus copiilor lor în...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ εἶπα πρὸς τὰ τέκνα αὐτῶν ἐν τῇ ἐρήμῳ· ἐν τοῖς νομίμοις τῶν πατέρων ὑμῶν μὴ πορεύεσθε καὶ τὰ δικαιώματα αὐτῶν μὴ φυλάσσεσθε καὶ ἐν τοῖς ἐπιτηδεύμασιν αὐτῶν μὴ συναναμίσγεσθε καὶ μὴ μιαίνεσθε.","greek":true,"translation":"„Și am zis copiilor lor în pustie: În obiceiurile părinților voștri să nu umblați și rânduielile lor să nu le păziți și cu născocirile lor să nu vă amestecați și să nu vă pângăriți.”","note":"Septuaginta adaugă „să nu vă amestecați” (μὴ συναναμίσγεσθε) și redă „idolii lor” prin „născocirile lor”."}],"refs":["Numeri 14:32,33","Deuteronom 4:3-6","Psalmii 78:6-8","Zaharia 1:2-4","1 Petru 1:18"]},{"v":"20:19","t":"Eu sunt DOMNUL, Dumnezeul vostru. Urmați decretele Mele, păziți judecățile Mele și înfăptuiți-le.","tokens":[{"t":"Eu sunt DOMNUL, Dumnezeul vostru. Urmați "},{"t":"decretele Mele","w":"decretele Mele","heb":"בְּחֻקּוֹתַי","translit":"behukotai","strong":"H2708","pos":"prepoziție + substantiv, feminin plural + sufix persoana I","def_ro":"rânduielile, decretele Mele.","dict_ro":"Hukot — rânduielile, decretele (de la hakak, „a grava, a sculpta”), opuse în versetul precedent „decretelor părinților”; e același cuvânt care deschide pericopa Behukotai („dacă veți umbla în decretele Mele”, Levitic 26:3). Metzudat David leagă îndemnul de afirmația de început: „Eu sunt DOMNUL, Dumnezeul vostru” — de aceea să asculte de Mine, să umble în decretele Mele și să le păzească în inima lor."},{"t":", păziți judecățile Mele și înfăptuiți-le."}],"commentaries":[{"author":"Metzudat David","text":"„Eu sunt DOMNUL, Dumnezeul vostru” — și de aceea să Mă asculte: umblați în decretele Mele și păziți judecățile Mele în inima voastră și împliniți-le."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"אֲנִי יְהוָה אֱלֹהֵיכֶם בְּחֻקּוֹתַי...","translation":"„Eu sunt DOMNUL, Dumnezeul vostru. Urmați...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ἐγὼ Κύριος ὁ Θεὸς ὑμῶν, ἐν τοῖς προστάγμασί μου πορεύεσθε καὶ τὰ δικαιώματά μου φυλάσσεσθε, καὶ ποιεῖτε αὐτά·","greek":true,"translation":"„Eu sunt Domnul Dumnezeul vostru; în poruncile Mele umblați și rânduielile Mele păziți-le și faceți-le,”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Exod 20:2,3","Ezechiel 36:27","Deuteronom 4:1","Psalmii 19:7-11"]},{"v":"20:20","t":"Sfințiți Șabaturile Mele și ele vor fi un semn între Mine și voi, să știți că Eu sunt DOMNUL, Dumnezeul vostru.’»”","tokens":[{"t":"Sfințiți","w":"Sfințiți","heb":"קַדֵּשׁוּ","translit":"kadeșu","strong":"H6942","pos":"verb, piel, imperativ, masculin plural","def_ro":"sfințiți, țineți sfânt.","dict_ro":"Kadeș, la forma piel — „a sfinți, a trata ca sfânt”; aceeași rădăcină ca Kedoșim („sfinți”), numele pericopei, ceea ce face din acest verset încheierea firească a haftarei sefarde. Haftara se încheie cu porunca Sabatului ca „semn”, reluând 20:12 — dar acum ca îndemn adresat noii generații, care are încă posibilitatea să aleagă altfel decât părinții ei."},{"t":" Șabaturile Mele și ele vor fi un semn între Mine și voi, să știți că Eu sunt DOMNUL, Dumnezeul vostru.’»”"}],"commentaries":[{"author":"Metzudat David","text":"„Și ele vor fi un semn” — ca să fie un semn."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְאֶת־שַׁבְּתוֹתַי קַדֵּשׁוּ וְהָיוּ לְאוֹת...","translation":"„Sfințiți Șabaturile Mele și ele vor...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ τὰ σάββατά μου ἁγιάζετε, καὶ ἔστω εἰς σημεῖον ἀνὰ μέσον ἐμοῦ καὶ ὑμῶν τοῦ γινώσκειν διότι ἐγὼ Κύριος ὁ Θεὸς ὑμῶν.","greek":true,"translation":"„și Sabatele Mele sfințiți-le, și să fie semn între Mine și voi, ca să cunoașteți că Eu sunt Domnul Dumnezeul vostru.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Ezechiel 20:12","Exod 31:13-17","Isaia 58:13","Ieremia 17:22,24,27","Neemia 13:15-22"]}]},{"num":10,"title":"Emor - Spune","ref":"Ezechiel 44:15-31","intro":"Pericopa Emor începe cu legile speciale ale preoților — ferirea de necurăția morților, căsătoria, sfințenia trupului — și continuă cu calendarul sărbătorilor. Haftara din Ezechiel reia aceleași teme pentru Templul viitor: preoții din familia lui Țadok, care au rămas credincioși când poporul s-a abătut, vor sluji înaintea lui Dumnezeu în veșminte de in, fără vin, tunși cu măsură, căsătorindu-se după reguli stricte, ferindu-se de morți și învățând poporul să deosebească între sfânt și profan, între necurat și curat. Unele dintre aceste reguli diferă de cele din Tora, iar tradiția evreiască le-a înțeles fie ca rânduieli pentru vremea mesianică, fie ca pasaje pe care, după Talmud, „Eliahu le va explica în viitor”. Haftara se încheie cu darurile datorate preoților, care nu au moștenire în pământ, pentru că „Eu sunt moștenirea lor”.","verses":[{"v":"44:15","t":"Iar preoții leviți – fiii lui Țadok, care au păzit sarcina Sanctuarului Meu atunci când copiii lui Israel s-au abătut de la Mine – ei să se apropie de Mine ca să-Mi slujească și să stea în picioare în fața Mea ca să-Mi aducă grăsime și sânge – rostirea Stăpânului meu, Domnul DUMNEZEU.","tokens":[{"t":"Iar preoții leviți – "},{"t":"fiii lui Țadok","w":"fiii lui Țadok","heb":"בְּנֵי צָדוֹק","translit":"benei Țadok","strong":"H6659","pos":"substantiv, masculin plural, în construcție + nume propriu","def_ro":"urmașii lui Țadok, familia marilor preoți.","dict_ro":"Țadok — marele preot din vremea lui David și Solomon (1 Împărați 2:35), numit, după Rashi, pentru că a fost primul care a slujit ca mare preot în Templul lui Solomon; numele lui înseamnă „drept”. Ezechiel le rezervă urmașilor lui slujirea din viitorul Templu, pentru că ei „au păzit sarcina Sanctuarului” atunci când restul poporului s-a abătut; Radak explică contrastul: preoții care s-au rătăcit nu se vor mai întoarce la slujire, pe când cei care n-au rătăcit o vor primi înapoi."},{"t":", care au păzit sarcina Sanctuarului Meu atunci când copiii lui Israel s-au abătut de la Mine – ei să se apropie de Mine ca să-Mi slujească și să stea în picioare în fața Mea ca să-Mi aducă grăsime și sânge – rostirea Stăpânului meu, Domnul DUMNEZEU."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Iar preoții leviți” — [adică preoții, care sunt] din tribul lui Levi. „Fiii lui Țadok” — pentru că el a fost marele preot care a slujit primul în Sanctuarul din zilele lui Solomon, ei sunt numiți după numele lui."},{"author":"Metzudat David","text":"„Iar preoții leviți” — dar preoții din fiii lui Levi, din sămânța lui Țadok, care a slujit în zilele lui Solomon. „Care au păzit” — și nu s-au clintit de la slujirea Locului atunci când fiii lui Israel s-au rătăcit."},{"author":"Radak (1160–1235)","text":"Radak: pentru că a spus că preoții care s-au rătăcit nu se vor mai întoarce în viitor la rânduiala slujirii, a spus că cei care nu s-au rătăcit se vor întoarce la rânduiala slujirii lor."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְהַכֹּהֲנִים הַלְוִיִּם בְּנֵי צָדוֹק...","translation":"„Iar preoții leviți – fiii lui...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"οἱ ἱερεῖς οἱ Λευῖται, οἱ υἱοὶ τοῦ Σαδδούκ, οἵτινες ἐφυλάξαντο τὰς φυλακὰς τῶν ἁγίων μου ἐν τῷ πλανᾶσθαι οἶκον ᾿Ισραὴλ ἀπ’ ἐμοῦ, οὗτοι προσάξουσι πρός με τοῦ λειτουργεῖν μοι καὶ στήσονται πρὸ προσώπου μου τοῦ προσφέρειν μοι θυσίαν, στέαρ καὶ αἷμα, λέγει Κύριος ὁ Θεός.","greek":true,"translation":"„preoții leviți, fiii lui Sadduc, care au păzit rânduielile celor sfinte ale Mele când s-a rătăcit casa lui Israel de la Mine, aceștia se vor apropia de Mine ca să-Mi slujească și vor sta înaintea feței Mele ca să-Mi aducă jertfă, grăsime și sânge, zice Domnul Dumnezeu.”","note":"Corespondență strânsă; Septuaginta adaugă „jertfă” (θυσίαν) înainte de „grăsime și sânge”."}],"refs":["Ezechiel 40:46","Ezechiel 48:11","1 Samuel 2:35","1 Împărați 2:35","Deuteronom 10:8","Levitic 3:16,17"]},{"v":"44:16","t":"Ei să vină la Sanctuarul Meu și să se apropie de masa Mea, să-Mi slujească și să păzească sarcina Mea.","tokens":[{"t":"Ei să vină la Sanctuarul Meu și să se apropie de "},{"t":"masa Mea","w":"masa Mea","heb":"שֻׁלְחָנִי","translit":"șulhani","strong":"H7979","pos":"substantiv, masculin singular + sufix persoana I","def_ro":"masa Mea.","dict_ro":"Șulhan — masa; „masa Mea” e aici altarul sau masa pâinilor punerii înainte. Metzudat David și Radak (după Targum Ionatan, „la masa pâinilor feței”) o identifică cu rânduirea pâinilor punerii înainte pe masa din Sanctuar. Maleahi folosește aceeași expresie, „masa DOMNULUI”, pentru altar (Maleahi 1:7), iar ideea unei „mese” a lui Dumnezeu la care slujesc preoții a trecut și în limbajul creștin despre altar."},{"t":", să-Mi slujească și să păzească sarcina Mea."}],"commentaries":[{"author":"Metzudat David","text":"„La masa Mea, să-Mi slujească” — aceasta este rânduirea pâinilor punerii înainte, care sunt pe masă. „Și să păzească” — în orice lucru al slujirii."},{"author":"Radak (1160–1235)","text":"Radak: „La masa Mea, să-Mi slujească” — cum a tradus Ionatan: „la masa pâinilor feței”."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"הֵמָּה יָבֹאוּ אֶל־מִקְדָּשִׁי וְהֵמָּה...","translation":"„Ei să vină la Sanctuarul Meu...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"οὗτοι εἰσελεύσονται εἰς τὰ ἅγιά μου, καὶ οὗτοι προσελεύσονται πρὸς τὴν τράπεζάν μου τοῦ λειτουργεῖν μοι καὶ φυλάξουσι τὰς φυλακάς μου.","greek":true,"translation":"„Aceștia vor intra în cele sfinte ale Mele și aceștia se vor apropia de masa Mea ca să-Mi slujească și vor păzi rânduielile Mele.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Ezechiel 41:22","Maleahi 1:7,12","Numeri 18:7,8","Deuteronom 33:8-10"]},{"v":"44:17","t":"Și va fi, când intră pe porțile curții interioare, să poarte veșminte de in; niciun veșmânt de lână să nu se afle asupra lor când slujesc [dincolo de] porțile curții interioare sau înăuntrul ei.","tokens":[{"t":"Și va fi, când intră pe porțile curții interioare, să poarte "},{"t":"veșminte de in","w":"veșminte de in","heb":"בִּגְדֵי פִשְׁתִּים","translit":"bigdei fiștim","strong":"H6593","pos":"substantiv, masculin plural, în construcție + substantiv plural","def_ro":"haine de in.","dict_ro":"Pișteh — inul, fibra vegetală din care erau făcute veșmintele preoțești, în contrast cu lâna (țemer). Rashi și Metzudat David leagă versetul de slujirea marelui preot în Sfânta Sfintelor, în ziua de Iom Kipur, când purta doar „veșmintele albe” de in (Levitic 16:4), fără albastrul de lână din mantie și brâu. Radak observă însă că formularea la plural nu se potrivește cu slujba unică a marelui preot și propune că e o rânduială nouă pentru Templul viitor."},{"t":"; niciun veșmânt de lână să nu se afle asupra lor când slujesc [dincolo de] porțile curții interioare sau înăuntrul ei."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Când intră pe porțile curții interioare” — în Sfânta Sfintelor, în Ziua Ispășirii. „Și nicio lână să nu fie asupra lor” — să nu poarte albastrul de lână care era în mantie și în brâu, în Ziua Ispășirii, în timpul slujirii dinăuntru."},{"author":"Metzudat David","text":"„Și va fi” — adică în Ziua Ispășirii, când vor intra marii preoți pe porțile curții interioare, care este Sanctuarul. „Veșminte de in” — sunt veșmintele albe cu care marele preot slujește în Ziua Ispășirii, la slujba dinăuntru; căci înăuntru nu se face slujire în cele opt veșminte, în care e lână."},{"author":"Radak (1160–1235)","text":"Radak: dacă „curtea interioară” e înțeleasă la propriu, ar fi o rânduială nouă pentru viitor, căci în veșmintele preoțești folosite era lână, cum scrie în Tora lui Moise. Iar dacă spunem că e vorba de slujirea marelui preot în Ziua Ispășirii, în Sfânta Sfintelor, cum ar numi el Sanctuarul „curte”, care este o casă, și cum ar spune „când intră ei” la plural, când slujba aceea o făcea doar marele preot, singur?"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְהָיָה בְּבוֹאָם אֶל־שַׁעֲרֵי הֶחָצֵר...","translation":"„Și va fi, când intră pe...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἔσται ἐν τῷ εἰσπορεύεσθαι αὐτοὺς τὰς πύλας τῆς αὐλῆς τῆς ἐσωτέρας στολὰς λινᾶς ἐνδύσονται καὶ οὐκ ἐνδύσονται ἔρια ἐν τῷ λειτουργεῖν αὐτοὺς ἀπὸ τῆς πύλης τῆς ἐσωτέρας αὐλῆς·","greek":true,"translation":"„Și va fi, când vor intra pe porțile curții dinăuntru, vor îmbrăca veșminte de in și nu vor îmbrăca lână când slujesc de la poarta curții dinăuntru;”","note":"Septuaginta omite ultima precizare din Textul Masoretic, „sau înăuntrul ei” (uvaita)."}],"refs":["Exod 28:39,40,43","Exod 39:27-29","Levitic 16:4","Apocalipsa 19:8"]},{"v":"44:18","t":"Turbane de in să fie pe capul lor și izmene de in să fie pe coapsele lor. Și să nu se încingă în locul unde transpiră.","tokens":[{"t":"Turbane de in să fie pe capul lor și izmene de in să fie pe coapsele lor. Și să nu se încingă "},{"t":"în locul unde transpiră","w":"în locul unde transpiră","heb":"בַּיָּזַע","translit":"bayaza","strong":"H3154","pos":"prepoziție + substantiv, masculin singular, cu articol","def_ro":"în [locul de] sudoare.","dict_ro":"Yeza — sudoarea, cuvânt care apare doar aici în Biblie. Talmudul (Zevahim 18b) îl explică: „să nu se încingă în locul unde oamenii transpiră” — brâul nu se leagă nici sub șolduri, nici deasupra coatelor, ci la înălțimea coatelor; Abaye adaugă că Ezechiel doar a dat sprijin scris unei tradiții care exista de dinainte. Rashi mai aduce o explicație: Tora a interzis preoților lâna tocmai pentru că încălzește trupul și îl face să transpire."},{"t":"."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Turbane” — pălării, acoperăminte de cap. „Să nu se încingă în locul unde transpiră” — am învățat într-o baraita (Zevahim 18b-19a): nu se încing în locul unde transpiră, nici deasupra coatelor, nici sub șolduri, care sunt locuri de sudoare. O altă explicație: Tora le-a interzis preoților veșmintele de lână, pentru că lâna face trupul să transpire."},{"author":"Metzudat David","text":"„Turbane de in” — acoperăminte de in să fie pe capul lor. „Să nu se încingă în locul unde transpiră” — să nu-și lege brâiele în locul unde carnea se îndoaie și se suprapune, căci acolo e multă sudoare, și s-ar murdări veșmintele preoției."},{"author":"Talmud Bavli, Zevahim 18b","text":"Ce înseamnă „să nu se încingă cu yeza”? Abaye a spus: să nu se încingă în locul în care oamenii transpiră, precum s-a învățat într-o baraita: când se încing cu brâul, nu se încing nici sub șolduri, nici deasupra coatelor, ci în dreptul coatelor. Iar până să vină Ezechiel, de unde știam aceasta? E o tradiție primită, iar Ezechiel a venit și i-a dat sprijin printr-un verset scris."},{"author":"Metzudat Țion","text":"„Paarei” — așa se numesc acoperămintele de cap, ca în „podoabele tiarelor” (Exod 39:28), numite așa pentru frumusețea și strălucirea lor. „Bayeza” — din „sudoare”."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"פַּאֲרֵי פִשְׁתִּים יִהְיוּ עַל־רֹאשָׁם...","translation":"„Turbane de in să fie pe...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ κιδάρεις λινᾶς ἕξουσιν ἐπὶ ταῖς κεφαλαῖς αὐτῶν καὶ περισκελῆ λινᾶ ἕξουσιν ἐπὶ τὰς ὀσφύας αὐτῶν καὶ οὐ περιζώσονται βίᾳ.","greek":true,"translation":"„și tiare de in vor avea pe capetele lor și pantaloni de in vor avea pe coapsele lor, și nu se vor încinge strâns.”","note":"Septuaginta redă „să nu se încingă în locul unde transpiră” prin „să nu se încingă strâns / cu forță” (βίᾳ), pierzând legătura cu sudoarea."}],"refs":["Exod 28:40,41","Exod 39:28","Exod 28:42,43","1 Corinteni 14:40"]},{"v":"44:19","t":"Iar când ies spre curtea exterioară, către curtea exterioară și către popor, să-și scoată hainele în care slujesc și să le lase în odăile sfinte și să îmbrace alte haine și să nu sfințească poporul cu hainele lor.","tokens":[{"t":"Iar când ies spre curtea exterioară, către curtea exterioară și către popor, să-și scoată hainele în care slujesc și să le lase în "},{"t":"odăile sfinte","w":"odăile sfinte","heb":"לִשְׁכֹת הַקֹּדֶשׁ","translit":"lișhot hakodeș","strong":"H3957","pos":"substantiv, feminin plural, în construcție + substantiv cu articol","def_ro":"camerele Sanctuarului.","dict_ro":"Lișka — o încăpere laterală a Templului, folosită pentru păstrarea veșmintelor și a obiectelor sfinte (Ezechiel 42:13-14). Rashi vede aici porunca dată marelui preot în Levitic 16:23: „își va scoate veșmintele de in... și le va lăsa acolo”. Motivul — „să nu sfințească poporul cu hainele lor” — e explicat de Metzudat David și Radak: ca nu cumva, atingându-se de veșmintele sfinte, poporul să pară sfânt ca preoții."},{"t":" și să îmbrace alte haine și să nu sfințească poporul cu hainele lor."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Spre curtea exterioară, către curtea exterioară” — pentru că vorbise despre Sanctuar și Sfânta Sfintelor, numindu-le „curtea interioară”, iar față de ele curtea israeliților ar trebui numită „exterioară”, a trebuit să dubleze expresia ca să arate că vorbește de curtea bărbaților, locul în care intră tot Israelul. „Și să le lase în odăile sfinte” — cum a spus Moise, învățătorul nostru: „își va scoate veșmintele de in... și le va lăsa acolo” (Levitic 16:23)."},{"author":"Metzudat David","text":"„Alte haine” — haine obișnuite. „Să nu sfințească” — adică să nu pară că poporul e sfânt ca ei; căci, dacă ar veni acolo în veșmintele preoției, ar părea tuturor că nu e nicio grijă dacă oamenii din popor se ating de ele, ca și cum ar fi sfinți ca preoții."},{"author":"Radak (1160–1235)","text":"Radak: „Și să nu sfințească poporul cu hainele lor” — căci, dacă se vor atinge de popor cu veșmintele preoției, care sunt sfinte, va părea că poporul e sfânt ca ei; și pe această cale a tradus Ionatan: „și să nu se amestece cu poporul în veșmintele lor”."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וּבְצֵאתָם אֶל־הֶחָצֵר הַחִיצוֹנָה אֶל־הָעָם...","translation":"„Iar când ies spre curtea exterioară...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐν τῷ ἐκπορεύεσθαι αὐτοὺς εἰς τὴν αὐλὴν τὴν ἐξωτέραν πρὸς τὸν λαὸν ἐκδύσονται τὰς στολὰς αὐτῶν, ἐν αἷς αὐτοὶ λειτουργοῦσιν ἐν αὐταῖς, καὶ θήσουσιν αὐτὰς ἐν ταῖς ἐξέδραις τῶν ἁγίων καὶ ἐνδύσονται στολὰς ἑτέρας καὶ οὐ μὴ ἁγιάσωσι τὸν λαὸν ἐν ταῖς στολαῖς αὐτῶν.","greek":true,"translation":"„Și când vor ieși în curtea din afară, la popor, își vor dezbrăca veșmintele în care slujesc și le vor pune în încăperile celor sfinte și vor îmbrăca alte veșminte, și nu vor sfinți poporul cu veșmintele lor.”","note":"Septuaginta pomenește „curtea din afară” o singură dată, fără repetiția din Textul Masoretic („spre curtea exterioară, către curtea exterioară”)."}],"refs":["Ezechiel 42:13,14","Levitic 6:10,11","Ezechiel 46:20","Exod 29:37","Levitic 6:27","Matei 23:17-19"]},{"v":"44:20","t":"Să nu își radă capul și nici să nu își lase pletele să crească în voie, ci să aibă capetele tunse.","tokens":[{"t":"Să nu își radă capul și nici să nu își lase pletele să crească în voie, ci să aibă "},{"t":"capetele tunse","w":"capetele tunse","heb":"כָּסוֹם יִכְסְמוּ","translit":"kasom yihsemu","strong":"H3697","pos":"verb, qal, infinitiv absolut + imperfect, persoana a III-a plural","def_ro":"să-și tundă [părul] cu măsură.","dict_ro":"Kasam — „a tunde, a scurta”, înrudit cu kusemet, grâul spelta (Metzudat Țion). Talmudul (Sanhedrin 22b) deduce de aici că preotul obișnuit trebuie să se tundă o dată la treizeci de zile, prin analogie cu nazireul, la care „pletele” (pera) cresc cel puțin treizeci de zile. Rashi descrie tunsoarea marelui preot „ca spicele de spelta”, cu vârful unui fir lângă rădăcina celuilalt, sau, într-o altă explicație, o măsură de mijloc: nici ras cu totul, nici lăsat să crească."},{"t":"."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Și capul să nu și-l radă” — ca să îndepărteze tot părul. „Și nici să nu-și lase pletele să crească” — să nu-și lase părul să crească foarte lung. „Kasom yihsemu” — ca spelta, așezată în spic, cu vârful unuia lângă rădăcina celuilalt; așa am auzit în numele lui Rabi Menahem. Se poate explica și ca o măsură de mijloc: nici ras [tot] capul, nici părul lăsat să crească, ci o măsură potrivită."},{"author":"Metzudat David","text":"„Și capul să nu și-l radă” — părul capului să nu-l radă niciodată. „Și nici să nu-și lase pletele” — să nu lase creșterea părului să se întindă prea mult, iar înțelepții noștri au spus că se tund o dată la treizeci de zile (Sanhedrin 22)."},{"author":"Talmud Bavli, Sanhedrin 22b","text":"Preotul obișnuit se tunde o dată la treizeci de zile, căci scrie despre preoți: „capul să nu și-l radă și pletele să nu le lase să crească” (Ezechiel 44:20), și se învață „plete” de aici de la „plete” de la nazireu: „să lase să crească pletele părului capului său” (Numeri 6:5); precum acolo sunt treizeci de zile, așa și aici."},{"author":"Metzudat Țion","text":"„Pera” — așa se numește creșterea părului, ca în „să nu-și lase capul netuns” (Levitic 21:10). „Kasom yihsemu” — din „grâul și spelta” (Exod 9:32), care e un soi de sămânță."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְרֹאשָׁם לֹא יְגַלֵּחוּ וּפֶרַע...","translation":"„Să nu își radă capul și...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ τὰς κεφαλὰς αὐτῶν οὐ ξυρήσονται καὶ τὰς κόμας αὐτῶν οὐ ψιλώσουσι, καλύπτοντες καλύψουσι τὰς κεφαλὰς αὐτῶν.","greek":true,"translation":"„Și capetele nu și le vor rade și părul nu și-l vor tunde scurt; acoperind, își vor acoperi capetele.”","note":"Divergență reală: Septuaginta are „acoperind, își vor acoperi capetele” (καλύπτοντες καλύψουσι), acolo unde Textul Masoretic are „să-și tundă capetele” (kasom yihsemu)."}],"refs":["Levitic 21:5-24","Deuteronom 14:1","Numeri 6:5","1 Corinteni 11:14"]},{"v":"44:21","t":"Niciun preot să nu bea vin când intră în curtea interioară.","tokens":[{"t":"Niciun preot să nu bea "},{"t":"vin","w":"vin","heb":"וְיַיִן","translit":"veiain","strong":"H3196","pos":"conjuncție + substantiv, masculin singular","def_ro":"vin.","dict_ro":"Iain — vinul; interdicția vine din Tora, după moartea lui Nadav și Avihu: „vin și băutură tare să nu bei, tu și fiii tăi, când intrați în Cortul Întâlnirii, ca să nu muriți” (Levitic 10:9), motivul fiind — după versetul următor de acolo — ca preotul să poată deosebi între sfânt și profan. Radak observă că Ezechiel repetă aici și reguli deja scrise în Tora, alături de rânduieli noi pentru viitor."},{"t":" când intră în curtea interioară."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Când intră în curtea interioară” — în Sanctuar."},{"author":"Metzudat David","text":"„Niciun preot” — fie mare preot, fie preot obișnuit. „În curtea interioară” — este Sanctuarul, numit „curte” față de Sfânta Sfintelor."},{"author":"Radak (1160–1235)","text":"Radak: „În curtea interioară” — în curtea preoților, de la altar spre înăuntru, cum scrie în Tora; și deși aceasta e scrisă în Tora, a înșirat legile preoților pentru că a înnoit lucruri care nu sunt explicite în Tora scrisă, și poate că a înnoit lucruri care vor fi în viitor, spre o sporire a sfințeniei."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְיַיִן לֹא־יִשְׁתּוּ כָּל־כֹּהֵן בְּבוֹאָם...","translation":"„Niciun preot să nu bea vin...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ οἶνον οὐ μὴ πίωσι πᾶς ἱερεὺς ἐν τῷ εἰσπορεύεσθαι αὐτοὺς εἰς τὴν αὐλὴν τὴν ἐσωτέραν.","greek":true,"translation":"„Și vin să nu bea niciun preot când intră în curtea dinăuntru.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Levitic 10:9","Luca 1:15","1 Timotei 3:8","Tit 1:7,8"]},{"v":"44:22","t":"Văduvă sau divorțată să nu-și ia de soție, ci doar fecioare din seminția casei lui Israel, sau o văduvă care a fost soție de preot, să ia [de soție].","tokens":[{"t":"Văduvă sau divorțată să nu-și ia de soție, ci doar "},{"t":"fecioare","w":"fecioare","heb":"בְּתוּלֹת","translit":"betulot","strong":"H1330","pos":"substantiv, feminin plural","def_ro":"fecioare.","dict_ro":"Betula — fecioara. Tora interzice doar marelui preot căsătoria cu o văduvă (Levitic 21:14), iar versetul lui Ezechiel pare să extindă interdicția la toți preoții. Talmudul (Kidușin 78b) rezolvă contradicția: prima parte a versetului se referă la marele preot, iar a doua („o văduvă care a fost soție de preot, să ia”) la preotul obișnuit; Rava arată că un verset poate trata astfel două subiecte fără delimitare. Rashi și Metzudat David urmează această lectură."},{"t":" din seminția casei lui Israel, sau o văduvă care a fost soție de preot, să ia [de soție]."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Ci doar fecioare” — să ia marii preoți. Dar sunt unii preoți care pot lua o văduvă, și anume cei obișnuiți; acesta e sensul lui „dintre preoți să ia” — sunt unii preoți cărora le e îngăduit să ia o văduvă. „Care a fost [doar] văduvă” — o văduvă propriu-zisă, nu o divorțată sau una care a primit halița; aceasta, chiar dacă e necăsătorită, e oprită și preotului obișnuit."},{"author":"Metzudat David","text":"„Văduvă...” — aceasta e despre marii preoți, cărora le e oprită și văduva, și nu iau decât fecioare. „Care a fost văduvă” — adică să fie numai văduvă, nu și eliberată prin halița; atunci „dintre preoți să ia” — adică unii preoți pot s-o ia, și anume cei obișnuiți."},{"author":"Talmud Bavli, Kidușin 78b","text":"Despre acest verset din Ezechiel: prima parte se referă la marele preot, căci spune că nu va lua o văduvă, iar partea a doua se referă la preotul obișnuit, căci spune că poate lua o văduvă. Oare așa se explică un verset? Rava a spus: da, așa este explicația corectă; și există un caz asemănător: „candela lui Dumnezeu încă nu se stinsese, și Samuel era culcat în Templul DOMNULUI” (1 Samuel 3:3)."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְאַלְמָנָה וּגְרוּשָׁה לֹא־יִקְחוּ לָהֶם...","translation":"„Văduvă sau divorțată să nu-și ia...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ χήραν καὶ ἐκβεβλημένην οὐ λήψονται ἑαυτοῖς εἰς γυναῖκα, ἀλλ’ ἢ παρθένον ἐκ τοῦ σπέρματος ᾿Ισραήλ· καὶ χήρα ἐὰν γένηται ἐξ ἱερέως, λήψονται.","greek":true,"translation":"„Și văduvă și femeie izgonită nu-și vor lua de soție, ci numai fecioară din sămânța lui Israel; iar văduvă, dacă a fost [soție] de preot, vor lua.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Levitic 21:7,13,14","1 Timotei 3:2,4,5,11,12","Tit 1:6","Deuteronom 24:1-4"]},{"v":"44:23","t":"Iar pe poporul Meu să îl învețe să deosebească între sacru și profan, și să îi facă să cunoască diferența dintre necurat și curat.","tokens":[{"t":"Iar pe poporul Meu să îl învețe să deosebească "},{"t":"între sacru și profan","w":"între sacru și profan","heb":"בֵּין קֹדֶשׁ לְחֹל","translit":"bein kodeș lehol","strong":"H2455","pos":"prepoziție + substantiv + prepoziție + substantiv","def_ro":"deosebirea dintre ce e sfânt și ce e obișnuit.","dict_ro":"Hol — ceea ce e obișnuit, profan, neconsacrat, opusul lui kodeș. Rolul preoților ca învățători ai poporului e formulat încă în Levitic 10:10-11 („ca să deosebiți între sfânt și profan... și să-i învățați pe fiii lui Israel”) și în binecuvântarea lui Moise pentru Levi (Deuteronom 33:10). Ezechiel acuzase exact încălcarea acestei datorii în capitolul 22: „preoții ei... n-au făcut deosebire între sfânt și profan” (Ezechiel 22:26)."},{"t":", și să îi facă să cunoască diferența dintre necurat și curat."}],"commentaries":[{"author":"Metzudat David","text":"„Iar pe poporul Meu să îl învețe” — preoții să învețe poporul să deosebească între sfânt și profan și să le facă cunoscută și deosebirea dintre necurat și curat."},{"author":"Metzudat Țion","text":"„Yoru” — din învățătură și îndrumare."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְאֶת־עַמִּי יוֹרוּ בֵּין קֹדֶשׁ...","translation":"„Iar pe poporul Meu să îl...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ τὸν λαόν μου διδάξουσιν ἀνὰ μέσον ἁγίου καὶ βεβήλου καὶ ἀνὰ μέσον ἀκαθάρτου καὶ καθαροῦ γνωριοῦσιν αὐτοῖς.","greek":true,"translation":"„Și pe poporul Meu îl vor învăța deosebirea dintre sfânt și profan, și deosebirea dintre necurat și curat le-o vor face cunoscută.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Ezechiel 22:26","Levitic 10:10,11","Deuteronom 33:10","Osea 4:6","Hagai 2:11-13","Maleahi 2:6-9"]},{"v":"44:24","t":"Și legat de orice dispută, să stea la judecată și să o decidă după legile Mele; învățăturile Mele și decretele legate de soroacele Mele să le păzească și Șabaturile Mele să le sfințească.","tokens":[{"t":"Și legat de orice dispută, să stea la judecată și să o decidă după legile Mele; învățăturile Mele și decretele legate de "},{"t":"soroacele Mele","w":"soroacele Mele","heb":"מוֹעֲדַי","translit":"moadai","strong":"H4150","pos":"substantiv, masculin plural + sufix persoana I","def_ro":"sărbătorile, timpurile rânduite ale Mele.","dict_ro":"Moed — timpul fixat, întâlnirea rânduită; „soroacele Mele” sunt sărbătorile descrise pe larg în pericopa Emor (Levitic 23) — legătura cea mai directă dintre pericopă și această haftara. Metzudat David explică că preoții trebuie să păzească legile jertfelor pentru fiecare sărbătoare și să sfințească Sabatele prin jertfele datorate în ziua aceea; iar în pricinile de judecată să judece „după judecățile Torei, nu după părerea lor”."},{"t":" să le păzească și Șabaturile Mele să le sfințească."}],"commentaries":[{"author":"Metzudat David","text":"„Și legat de orice dispută” — pentru pricinile de bani, poporul va sta la judecată înaintea lor, iar ei îi vor judeca după judecățile Torei, nu după aprecierea lor. „Învățăturile Mele” — învățăturile și decretele obișnuite în toate zilele de sărbătoare ale DOMNULUI, privitoare la jertfe, să le păzească ei împlinindu-le; și tot așa să sfințească Sabatele, prin jertfele datorate în ziua aceea."},{"author":"Radak (1160–1235)","text":"Radak: „Lemișpat” — scris „lișpot” și citit „lemișpat”, iar sensul e același. „Și decretele Mele la toate soroacele Mele” — în privința jertfelor; și tot așa să sfințească Sabatele Mele."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְעַל־רִיב הֵמָּה יַעַמְדוּ לְשָׁפְט...","translation":"„Și legat de orice dispută, să...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐπὶ κρίσιν αἵματος οὗτοι ἐπιστήσονται τοῦ διακρίνειν· τὰ δικαιώματά μου δικαιώσουσι καὶ τὰ κρίματά μου κρινοῦσι καὶ τὰ νόμιμά μου καὶ τὰ προστάγματά μου ἐν πάσαις ταῖς ἑορταῖς μου φυλάξονται καὶ τὰ σάββατά μου ἁγιάσουσι.","greek":true,"translation":"„Și la judecată de sânge aceștia vor sta ca să hotărască; rânduielile Mele le vor împlini și judecățile Mele le vor judeca, și legiuirile Mele și poruncile Mele la toate sărbătorile Mele le vor păzi și Sabatele Mele le vor sfinți.”","note":"Septuaginta redă „dispută” (riv) prin „judecată de sânge” (κρίσιν αἵματος), restrângând competența preoților la pricinile capitale."}],"refs":["Deuteronom 17:8-13","2 Cronici 19:8-10","Levitic 23:1-44","Numeri 28:1-29","Isaia 58:13,14"]},{"v":"44:25","t":"Și să nu vină la un trup mort ca să devină necurați, ci numai pentru tată și pentru mamă, pentru fiu și pentru fiică, pentru frate și pentru soră care nu a fost niciodată cu un bărbat să devină necurați.","tokens":[{"t":"Și să nu vină la "},{"t":"un trup mort","w":"un trup mort","heb":"מֵת אָדָם","translit":"met adam","strong":"H4191","pos":"verb, qal, participiu (substantivat) + substantiv","def_ro":"un mort, un cadavru de om.","dict_ro":"Met — mortul; contactul cu un cadavru e sursa cea mai gravă de necurăție rituală (tumat met), de care preotul trebuie să se ferească, cu excepția rudelor apropiate enumerate aici și în Levitic 21:1-3 — legea care deschide chiar pericopa Emor. Radak precizează că e vorba de preotul obișnuit, marele preot neavând voie să se facă necurat nici pentru părinții lui (Levitic 21:11); Metzudat David explică „sora care n-a fost cu un bărbat”: care n-a fost căsătorită."},{"t":" ca să devină necurați, ci numai pentru tată și pentru mamă, pentru fiu și pentru fiică, pentru frate și pentru soră care nu a fost niciodată cu un bărbat să devină necurați."}],"commentaries":[{"author":"Metzudat David","text":"„Ca să devină necurați” — ca să se facă pe sine necurat. „Care nu a fost cu un bărbat” — spre culcare, adică necăsătorită."},{"author":"Radak (1160–1235)","text":"Radak: „Și să nu vină la un trup mort” — aceasta este despre preotul obișnuit."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְאֶל־מֵת אָדָם לֹא יָבוֹא...","translation":"„Și să nu vină la un...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐπὶ ψυχὴν ἀνθρώπου οὐκ εἰσελεύσονται τοῦ μιανθῆναι, ἀλλ’ ἢ ἐπὶ πατρὶ καὶ ἐπὶ μητρὶ καὶ ἐπὶ υἱῷ καὶ ἐπὶ θυγατρὶ καὶ ἐπὶ ἀδελφῷ καὶ ἐπὶ ἀδελφῇ αὐτοῦ, ἣ οὐ γέγονεν ἀνδρί, μιανθήσεται.","greek":true,"translation":"„Și la suflet de om [mort] nu vor intra ca să se pângărească, ci numai pentru tată și pentru mamă și pentru fiu și pentru fiică și pentru frate și pentru sora lui care n-a fost a unui bărbat se va pângări.”","note":"Corespondență strânsă; „mort” e redat prin „suflet de om” (ψυχὴν ἀνθρώπου), ca și în Levitic 21:1 după Septuaginta."}],"refs":["Levitic 21:1-6","Levitic 22:4","Matei 8:21,22","Luca 9:59,60"]},{"v":"44:26","t":"Iar după ce [un preot] se va curăța, să numere pentru sine șapte zile.","tokens":[{"t":"Iar după ce [un preot] se va curăța, să numere pentru sine "},{"t":"șapte zile","w":"șapte zile","heb":"שִׁבְעַת יָמִים","translit":"șivat iamim","strong":"H7651","pos":"numeral + substantiv plural","def_ro":"șapte zile.","dict_ro":"Șivat iamim — perioada de purificare după contactul cu un mort (Numeri 19:11-12). Versetul ridică o întrebare: purificarea obișnuită durează deja șapte zile, atunci ce sunt aceste „șapte zile” numărate „după curățire”? Rashi și Metzudat David, după înțelepți (Moed Katan 15b), explică „după curățire” ca „după despărțirea de mort”; Radak propune și posibilitatea unei rânduieli noi pentru viitor, o sporire a sfințeniei, cu încă șapte zile după purificare. Metzudat David adaugă că frații preoți numără pentru el, ca să nu intre din greșeală."},{"t":"."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Și după curățirea lui” — și după ce s-a despărțit de mort; așa s-a învățat în Moed Katan (15b)."},{"author":"Metzudat David","text":"„Și după curățirea lui” — adică după despărțirea lui de mort, așa au spus înțelepții. „Șapte zile” — și după aceea e curat. „Să numere” — adică frații lui, preoții, să numere pentru el, ca, dacă el uită, să nu-l lase să intre în Sanctuar până după șapte zile, când va fi curat."},{"author":"Radak (1160–1235)","text":"Radak: se poate ca aceasta să fie pentru viitor, o sporire a sfințeniei: după ce se vor curăți la sfârșitul celor șapte [zile], să mai numere pentru el încă șapte zile; dar înțelepții noștri au explicat-o fără înnoire, explicând „după curățirea lui” ca „după despărțirea lui de mort”."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְאַחֲרֵי טָהֳרָתוֹ שִׁבְעַת יָמִים...","translation":"„Iar după ce [un preot] se...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ μετὰ τὸ καθαρισθῆναι αὐτὸν ἑπτὰ ἡμέρας ἐξαριθμηθήσῃ αὐτῷ·","greek":true,"translation":"„Și după ce se va curăți, șapte zile i se vor număra lui;”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Numeri 6:10-21","Numeri 19:11-13","Evrei 9:13,14"]},{"v":"44:27","t":"Și în ziua în care va intra în Sanctuar, în curtea interioară, ca să slujească în Sanctuar, să își aducă jertfa sa de păcat – rostirea Stăpânului meu, Domnul DUMNEZEU.","tokens":[{"t":"Și în ziua în care va intra în Sanctuar, în curtea interioară, ca să slujească în Sanctuar, să își aducă "},{"t":"jertfa sa de păcat","w":"jertfa sa de păcat","heb":"חַטָּאתוֹ","translit":"hatato","strong":"H2403","pos":"substantiv, feminin singular + sufix persoana a III-a masculin","def_ro":"jertfa lui de ispășire pentru păcat.","dict_ro":"Hatat — jertfa pentru păcat, de la hata, „a greși ținta”. Rashi și Metzudat David o identifică, după înțelepți (Moed Katan 16a; Menahot 51b), cu „a zecea parte de efă” de făină pe care preotul obișnuit o aduce în ziua în care începe să slujească (Levitic 6:20). Radak nu e convins: el observă că versetul vorbește despre preotul obișnuit care s-a făcut necurat pentru o rudă și vede aici fie o jertfă nouă pentru viitor, fie regula că preotul nu-și poate aduce jertfele în zilele necurăției."},{"t":" – rostirea Stăpânului meu, Domnul DUMNEZEU."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Și în ziua în care va intra în Sanctuar” — pentru prima dată, ca să se inițieze în slujire, să-și aducă jertfa de păcat; aceasta este a zecea parte de efă. În Moed Katan (16a) se învață: preotul obișnuit trebuie să aducă a zecea parte de efă în ziua inițierii lui, precum s-a spus: „aceasta este jertfa lui Aaron și a fiilor lui” (Levitic 6:20), și cum se explică în tratatul Menahot (51b)."},{"author":"Metzudat David","text":"„Și în ziua în care va intra” — adică la începutul intrării preotului, ca să se inițieze în slujire. „Să își aducă jertfa de păcat” — aceasta e a zecea parte de efă pe care preoții o aduceau în ziua inițierii, cum s-a spus: „aceasta este jertfa lui Aaron și a fiilor lui... a zecea parte dintr-o efă de făină”."},{"author":"Radak (1160–1235)","text":"Radak: adică după ce se va curăți și va intra în Sanctuar, în care n-a intrat în timpul necurăției, acum, după curățire, va aduce o jertfă de păcat pentru necurăția lui, și aceasta ar fi o înnoire pentru viitor; înțelepții noștri au explicat-o fără înnoire. Și mă mir de cel care a spus că „jertfa lui de păcat” e a zecea parte de efă, căci versetul vorbește de preotul obișnuit, care se face necurat pentru rude, iar a zecea parte de efă o aducea marele preot în fiecare zi, iar preotul obișnuit doar la inițierea în slujire."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וּבְיוֹם בֹּאוֹ אֶל־הַקֹּדֶשׁ אֶל־הֶחָצֵר...","translation":"„Și în ziua în care va...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ᾗ ἂν ἡμέρᾳ εἰσπορεύωνται εἰς τὴν αὐλὴν τὴν ἐσωτέραν τοῦ λειτουργεῖν ἐν τῷ ἁγίῳ, προσοίσουσιν ἱλασμόν, λέγει Κύριος ὁ Θεός.","greek":true,"translation":"„și în ziua în care vor intra în curtea dinăuntru ca să slujească în cel sfânt, vor aduce ispășire, zice Domnul Dumnezeu.”","note":"Septuaginta omite prima mențiune „în Sanctuar” și redă „jertfa sa de păcat” prin „ispășire” (ἱλασμόν), la plural („vor aduce”)."}],"refs":["Levitic 4:3-35","Levitic 8:14-36","Numeri 6:9-11","Evrei 7:26-28"]},{"v":"44:28","t":"Și aceasta să fie moștenirea pentru ei: Eu sunt moștenirea lor, să nu le dai nicio posesiune în Israel, Eu sunt posesiunea lor.","tokens":[{"t":"Și aceasta să fie moștenirea pentru ei: Eu sunt "},{"t":"moștenirea lor","w":"moștenirea lor","heb":"נַחֲלָתָם","translit":"nahalatam","strong":"H5159","pos":"substantiv, feminin singular + sufix persoana a III-a plural","def_ro":"moștenirea, partea lor de moștenire.","dict_ro":"Nahala — moștenirea, lotul de pământ primit în Țară; preoții și leviții nu primesc teritoriu, pentru că „Eu sunt moștenirea lor” (Numeri 18:20; Deuteronom 18:1-2). Rashi și Radak înțeleg „aceasta” din începutul versetului ca preoția însăși, care le ține loc de pământ, iar Metzudat David explică scopul practic: să fie liberi pentru slujirea în Templu, trăind din ce rămâne din jertfe."},{"t":", să nu le dai nicio posesiune în Israel, Eu sunt posesiunea lor."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Și aceasta să fie pentru ei” — preoția, drept moștenire."},{"author":"Metzudat David","text":"„Și aceasta să fie moștenirea pentru ei” — preoția le va fi moștenire, căci nu vor moșteni o parte în Țară. „Eu sunt moștenirea lor” — adică ce rămâne din jertfele Mele va fi moștenirea lor. „Și posesiune” — posesiune de ogoare și vii să nu le dați, ca să fie liberi să se ocupe de slujirea Sanctuarului."},{"author":"Radak (1160–1235)","text":"Radak: „Și aceasta să fie moștenirea pentru ei” — preoția le va fi moștenire, ca să nu aibă posesiune în Israel, cum a spus în Tora."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְהָיְתָה לָהֶם לְנַחֲלָה אֲנִי...","translation":"„Și aceasta să fie moștenirea pentru...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἔσται αὐτοῖς εἰς κληρονομίαν· ἐγὼ κληρονομία αὐτοῖς, καὶ κατάσχεσις αὐτοῖς οὐ δοθήσεται ἐν τοῖς υἱοῖς ᾿Ισραήλ, ὅτι ἐγὼ κατάσχεσις αὐτῶν.","greek":true,"translation":"„Și le va fi spre moștenire: Eu sunt moștenirea lor; și stăpânire nu li se va da între fiii lui Israel, căci Eu sunt stăpânirea lor.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Ezechiel 45:4","Numeri 18:20","Deuteronom 10:9","Deuteronom 18:1,2","Iosua 13:14,33"]},{"v":"44:29","t":"Să mănânce prinosul, jertfa de păcat și jertfa de vină, și toate cele consacrate prin jurământ să fie pentru ei.","tokens":[{"t":"Să mănânce "},{"t":"prinosul","w":"prinosul","heb":"הַמִּנְחָה","translit":"haminha","strong":"H4503","pos":"substantiv, feminin singular, cu articol","def_ro":"darul de făină (jertfa nesângeroasă).","dict_ro":"Minha — darul, jertfa de făină; Metzudat David precizează că preoții mănâncă „ce rămâne din prinos”, după arderea părții de pe altar (Levitic 2:3). „Toate cele consacrate” (herem) desemnează, după Rashi și Metzudat Țion, bunurile închinate Sanctuarului, care revin preoților (Numeri 18:14) — un sens al cuvântului herem diferit de cel de „nimicire totală” din relatările cuceririi."},{"t":", jertfa de păcat și jertfa de vină, și toate cele consacrate prin jurământ să fie pentru ei."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Și toate cele consacrate” — „herem” este o expresie de sfințenie, și așa este orice „herem” în contextul lucrurilor sfințite."},{"author":"Metzudat David","text":"„Prinosul” — adică rămășițele prinosului. „Și toate cele consacrate” — toate lucrurile închinate."},{"author":"Metzudat Țion","text":"„Herem” — adică lucru sfințit, ca în „tot ce e închinat în Israel va fi al tău” (Numeri 18:14)."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"הַמִּנְחָה וְהַחַטָּאת וְהָאָשָׁם הֵמָּה...","translation":"„Să mănânce prinosul, jertfa de păcat...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ τὰς θυσίας καὶ τὰ ὑπὲρ ἁμαρτίας καὶ τὰ ὑπὲρ ἀγνοίας οὗτοι φάγονται, καὶ πᾶν ἀφόρισμα ἐν τῷ ᾿Ισραὴλ αὐτοῖς ἔσται·","greek":true,"translation":"„Și jertfele și cele pentru păcat și cele pentru neștiință aceștia le vor mânca, și tot ce e pus deoparte în Israel va fi al lor.”","note":"Septuaginta redă „jertfa de vină” (așam) prin „[jertfa] pentru neștiință” (ὑπὲρ ἀγνοίας), accentuând caracterul involuntar al greșelii."}],"refs":["Levitic 2:3,10","Levitic 6:14-18,26,29","Numeri 18:9-11","1 Corinteni 9:13,14","Levitic 27:21,28","Numeri 18:14"]},{"v":"44:30","t":"Și cele mai bune din primele roade de orice fel și toată donația de [recolte] de orice fel – din toate darurile donate – să meargă la preoți; prima parte din coca voastră să o dați preotului, ca să păstrați binecuvântarea asupra casei tale.","tokens":[{"t":"Și cele mai bune din primele roade de orice fel și toată donația de [recolte] de orice fel – din toate darurile donate – să meargă la preoți; "},{"t":"prima parte din coca voastră","w":"prima parte din coca voastră","heb":"רֵאשִׁית עֲרִסוֹתֵיכֶם","translit":"reșit arisoteihem","strong":"H6182","pos":"substantiv, feminin singular, în construcție + substantiv plural cu sufix","def_ro":"pârga aluatului, hala.","dict_ro":"Arisa — aluatul, coca; „pârga cocii” e porunca halei, partea de aluat dată preotului (Numeri 15:20-21), păstrată în practica evreiască până azi prin separarea și arderea unei bucăți din aluatul frământat. Metzudat David explică promisiunea „ca să păstrați binecuvântarea asupra casei tale”: să nu vă pară rău că dați toate acestea preoților, căci darul va aduce binecuvântare și bogăția nu va scădea, ci va crește — idee reluată de Maleahi 3:10."},{"t":" să o dați preotului, ca să păstrați binecuvântarea asupra casei tale."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Ca să păstrați binecuvântarea asupra casei tale” — „lehaniah” înseamnă a face să se așeze, să rămână, ca în „și s-au așezat în toate hotarele Egiptului” (Exod 10:14)."},{"author":"Metzudat David","text":"„Și cele mai bune din primele roade” — pârga din toate lucrurile care s-au copt primele, adică primele roade. „Prima parte din coca voastră” — prima parte din aluat, înainte de a mânca din el; aceasta se spune despre hala. „Ca să păstrați binecuvântarea” — ca și cum ar spune: să nu vă pară rău să dați toate acestea preoților, căci aceasta va fi pricină ca binecuvântarea să se așeze în casa ta, și bogăția nu se va împuțina, ci va spori."},{"author":"Metzudat Țion","text":"„Bikurei” — coacerea timpurie a recoltei se numește „bikur”, ca în „cele dintâi roade ale pământului tău” (Exod 23:19). „Arisoteihem” — cu sensul de aluat, cocă. „Lehaniah” — din „a așeza”."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְרֵאשִׁית כָּל־בִּכּוּרֵי כֹל וְכָל־תְּרוּמַת...","translation":"„Și cele mai bune din primele...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ἀπαρχαὶ πάντων καὶ τὰ πρωτότοκα πάντων καὶ τὰ ἀφαιρέματα πάντα ἐκ πάντων τῶν ἀπαρχῶν ὑμῶν τοῖς ἱερεῦσιν ἔσται· καὶ τὰ πρωτογεννήματα ὑμῶν δώσετε τῷ ἱερεῖ τοῦ θεῖναι εὐλογίας ὑμῶν ἐπὶ τοὺς οἴκους ὑμῶν.","greek":true,"translation":"„Pârgile tuturor și întâii-născuți ai tuturor și toate cele luate deoparte din toate pârgile voastre vor fi ale preoților; și pârga aluaturilor voastre o veți da preotului, ca să puneți binecuvântările voastre asupra caselor voastre.”","note":"Septuaginta adaugă „întâii-născuți ai tuturor” (τὰ πρωτότοκα), absent din Textul Masoretic, și trece binecuvântarea la plural („asupra caselor voastre”)."}],"refs":["Exod 23:19","Numeri 15:19-21","Numeri 18:12-18,27-30","Deuteronom 18:4","Proverbe 3:9,10","Maleahi 3:10,11"]},{"v":"44:31","t":"Orice hoit sau animal sfâșiat dintre păsări și dintre dobitoace, preoții să nu le mănânce.","tokens":[{"t":"Orice "},{"t":"hoit","w":"hoit","heb":"נְבֵלָה","translit":"nevela","strong":"H5038","pos":"substantiv, feminin singular","def_ro":"animal mort de la sine, hoit.","dict_ro":"Nevela — animalul mort fără sacrificare rituală, oprit oricărui israelit (Deuteronom 14:21), la fel ca terefa, animalul sfâșiat. De aceea Talmudul (Menahot 45a) se întreabă: doar preoților le e oprit? Rabi Iohanan răspunde: „acest pasaj e greu, iar în viitor Eliahu îl va explica”; Ravina propune că, fiindcă preoților le era îngăduită jertfa de păcat din păsări ucisă prin ciupire (care e tehnic nevela), ar fi putut crede că li se îngăduie și alte hoituri. Rashi, Metzudat David și Radak aduc aceeași explicație."},{"t":" sau animal sfâșiat dintre păsări și dintre dobitoace, preoții să nu le mănânce."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Orice hoit sau animal sfâșiat” — pentru că ciupirea gâtului păsării aduse ca jertfă de păcat era îngăduită [preoților], iar aceasta echivalează cu un hoit sau cu un animal sfâșiat, a trebuit să-i avertizeze în privința celorlalte hoituri și animale sfâșiate. Așa explică înțelepții noștri."},{"author":"Radak (1160–1235)","text":"Radak: „Orice hoit sau animal sfâșiat” — cum s-a spus în Tora: „hoit și animal sfâșiat să nu mănânce, ca să nu se pângărească prin ele” (Levitic 22:8); deși și Israelul e oprit de la ele, preoții sunt avertizați mai mult din pricina necurăției, pentru că sunt mereu în Sanctuar. Iar înțelepții noștri au spus: pentru că le-a fost îngăduită ciupirea jertfei de păcat din păsări, care e hoit și animal sfâșiat, s-ar putea crede că le sunt îngăduite și celelalte hoituri; de aceea au fost avertizați."},{"author":"Talmud Bavli, Menahot 45a","text":"„Orice hoit sau animal sfâșiat, din păsări și din dobitoace, să nu mănânce preoții” (Ezechiel 44:31) — oare doar preoții nu pot mânca, iar un israelit poate? Rabi Iohanan a spus: acest pasaj e greu, iar în viitor Eliahu îl va explica. Ravina a spus: era necesar pentru preoți, căci ți-ar fi putut trece prin minte că, de vreme ce ciupirea [jertfei din păsări] le-a fost îngăduită, [și hoiturile le-ar fi îngăduite]."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"כָּל־נְבֵלָה וּטְרֵפָה מִן־הָעוֹף וּמִן־הַבְּהֵמָה...","translation":"„Orice hoit sau animal sfâșiat dintre...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ πᾶν θνησιμαῖον καὶ θηριάλωτον ἐκ τῶν πετεινῶν καὶ ἐκ τῶν κτηνῶν οὐ φάγονται οἱ ἱερεῖς.","greek":true,"translation":"„Și orice mortăciune și ce e sfâșiat de fiare, din păsări și din dobitoace, să nu mănânce preoții.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Exod 22:31","Levitic 17:15","Levitic 22:8","Deuteronom 14:21","Romani 14:20","1 Corinteni 8:13"]}]},{"num":11,"title":"Behar - Pe munte","ref":"Ieremia 32:6-27","intro":"Pericopa Behar rânduiește anul sabatic, jubileul și dreptul rudei de a răscumpăra pământul vândut de fratele sărăcit, pentru ca moștenirea familiei să nu fie pierdută pentru totdeauna. Haftara arată această lege pusă în practică în cel mai neașteptat moment: Ierusalimul e asediat de babilonieni, iar Ieremia e închis în curtea temniței pentru profețiile lui de pedeapsă. Tocmai atunci, vărul lui, Hanamel, vine să-i ceară să-și exercite dreptul de răscumpărare și să cumpere ogorul familiei din Anatot, un pământ deja aflat sub ocupație. Profetul cumpără, semnează, cheamă martori și pune actele într-un vas de lut, „ca să se păstreze vreme lungă”, pentru că DOMNUL a spus: „Se vor mai cumpăra case, ogoare și vii pe pământul acesta.” Rugăciunea nedumerită a lui Ieremia primește un răspuns simplu: nimic nu e ascuns și nimic nu e prea greu pentru Dumnezeul tuturor făpturilor. Exilul care începe nu va fi veșnic.","verses":[{"v":"32:6","t":"Ieremia a spus: „Cuvântul DOMNULUI a venit la mine, spunând:","tokens":[{"t":"Ieremia a spus: „"},{"t":"Cuvântul DOMNULUI","w":"Cuvântul DOMNULUI","heb":"דְבַר־יְהוָה","translit":"devar-ADONAI","strong":"H1697","pos":"substantiv, masculin singular, în construcție + nume divin","def_ro":"cuvântul DOMNULUI.","dict_ro":"Devar ADONAI — profeția vine în al zecelea an al lui Țedekia, când Ieremia era închis în curtea temniței pentru că prevestise căderea Ierusalimului (32:1-5). Rashi observă că versetul reia firul întrerupt: Scriptura a explicat mai întâi de ce fusese închis profetul, apoi revine să spună care a fost cuvântul primit; Metzudat David precizează la fel că, după lunga descriere a asediului, textul se întoarce la cuvântul DOMNULUI."},{"t":" a venit la mine, spunând:"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Ieremia a spus” — nu i-a spus aceasta lui Țedekia, ci Scriptura a explicat de ce l-a închis, apoi s-a întors la cuvintele de la început, ca să explice care a fost cuvântul ce a venit la Ieremia."},{"author":"Metzudat David","text":"„Cuvântul DOMNULUI a venit” — se întoarce la cele de mai sus, ca să spună că acesta este cuvântul care a venit la Ieremia în anul al zecelea; și pentru că s-au lungit cuvintele despre asediu și despre pricina închiderii lui Ieremia, a revenit să spună din nou: cuvântul DOMNULUI a venit la mine."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיֹּאמֶר יִרְמְיָהוּ הָיָה דְבַר־יְהוָה...","translation":"„Ieremia a spus: „Cuvântul DOMNULUI a...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ λόγος Κυρίου ἐγενήθη πρὸς ῾Ιερεμίαν λέγων·","greek":true,"translation":"„Și cuvântul Domnului a fost către Ieremia, zicând:”","note":"Septuaginta formulează la persoana a treia („către Ieremia”), fără introducerea „Ieremia a spus” și fără „la mine” din Textul Masoretic."}],"refs":[]},{"v":"32:7","t":"«Iată, Hanamel, fiul unchiului tău Șalum, vine la tine să spună: ‘Cumpără pentru tine ogorul meu din Anatot, căci al tău este dreptul de răscumpărare ca să cumperi.’»","tokens":[{"t":"«Iată, Hanamel, fiul unchiului tău Șalum, vine la tine să spună: ‘Cumpără pentru tine ogorul meu din Anatot, căci al tău este "},{"t":"dreptul de răscumpărare","w":"dreptul de răscumpărare","heb":"מִשְׁפַּט הַגְּאֻלָּה","translit":"mișpat hagheula","strong":"H1353","pos":"substantiv, masculin singular, în construcție + substantiv, feminin singular, cu articol","def_ro":"dreptul (datoria) rudei de a răscumpăra.","dict_ro":"Gheula — răscumpărarea pământului de către ruda cea mai apropiată, ca proprietatea familiei să nu treacă la străini: „dacă fratele tău sărăcește și vinde din moșia lui, ruda lui cea mai apropiată să vină și să răscumpere ce a vândut fratele său” (Levitic 25:25). Este chiar legea din pericopa Behar, de aici legătura haftarei cu pericopa; Metzudat David trimite și la Rut 4:3-4, unde Boaz îi propune răscumpărătorului „ogorul lui Elimelec”."},{"t":" ca să cumperi.’»"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Vine la tine” — din porunca lui Dumnezeu."},{"author":"Metzudat David","text":"„Unchiului tău” — se referă la Șalum. „Vine la tine” — e pe cale să vină la tine. „Căci al tău este dreptul de răscumpărare” — pentru că ești ruda mea apropiată, e dreptul tău să răscumperi ogorul meu, ca să nu ajungă în mâinile altora, și să-l cumperi tu; căci așa era rânduiala lor, cum s-a spus despre Boaz: „i-a spus răscumpărătorului: partea de ogor... dacă vrei să răscumperi, răscumpără” (Rut 4:3-4)."},{"author":"Radak (1160–1235)","text":"Radak: „Dreptul de răscumpărare” — dacă aș fi vândut ogorul altcuiva, tu ai avea dreptul să-l răscumperi din mâna lui; cu atât mai mult ești vrednic să-l cumperi tu direct de la mine."},{"author":"Metzudat Țion","text":"„Mișpat” — cu sensul de obicei și rânduială, ca în „rânduiala preoților” (1 Samuel 2:13)."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"הִנֵּה חֲנַמְאֵל בֶּן־שַׁלֻּם דֹּדְךָ...","translation":"„«Iată, Hanamel, fiul unchiului tău Șalum...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ἰδοὺ ᾿Αναμεὴλ υἱὸς Σαλὼμ ἀδελφοῦ πατρός σου ἔρχεται πρὸς σὲ λέγων· κτῆσαι σεαυτῷ τὸν ἀγρόν μου τὸν ἐν ᾿Αναθώθ, ὅτι σοὶ κρίσις παραλαβεῖν εἰς κτῆσιν.","greek":true,"translation":"„Iată, Anameel, fiul lui Salom, fratele tatălui tău, vine la tine zicând: Cumpără-ți ogorul meu cel din Anatot, căci ție îți aparține dreptul de a-l lua în stăpânire.”","note":"Corespondență strânsă; Septuaginta îl numește pe Salom „fratele tatălui tău” și redă „dreptul de răscumpărare” prin „dreptul de a-l lua în stăpânire”."}],"refs":["1 Împărați 14:5","Ieremia 1:1","Levitic 25:23,34,49","Numeri 35:2","Rut 4:4-9"]},{"v":"32:8","t":"Hanamel, vărul meu, a venit la mine, după rostirea DOMNULUI, în curtea temniței, și mi-a spus: «Te rog, cumpără-ți ogorul meu din Anatot, care este în ținutul lui Beniamin, căci al tău este dreptul de moștenire și al tău este [dreptul de] răscumpărare. Cumpără-l pentru tine!» Și am cunoscut că fusese cuvântul DOMNULUI.","tokens":[{"t":"Hanamel, vărul meu, a venit la mine, după rostirea DOMNULUI, în curtea temniței, și mi-a spus: «Te rog, cumpără-ți ogorul meu din Anatot, care este în ținutul lui Beniamin, căci al tău este "},{"t":"dreptul de moștenire","w":"dreptul de moștenire","heb":"מִשְׁפַּט הַיְרֻשָּׁה","translit":"mișpat haierușa","strong":"H3425","pos":"substantiv, masculin singular, în construcție + substantiv, feminin singular, cu articol","def_ro":"dreptul de a moșteni.","dict_ro":"Ieruța — moștenirea; Hanamel invocă două drepturi deodată: Ieremia e moștenitorul firesc al ogorului și, tot ca rudă, cel care îl poate răscumpăra. Radak și Metzudat David explică încheierea „și am cunoscut că fusese cuvântul DOMNULUI”: abia când vărul a venit întocmai cum i se spusese, profetul a înțeles că cumpărarea, oricât de absurdă ar părea în mijlocul asediului, este o poruncă divină."},{"t":" și al tău este [dreptul de] răscumpărare. Cumpără-l pentru tine!» Și am cunoscut că fusese cuvântul DOMNULUI."}],"commentaries":[{"author":"Metzudat David","text":"„Dreptul de moștenire” — adică, de vreme ce n-am rudă mai apropiată decât tine și tu ești vrednic să-l moștenești, răscumpără-l ca să nu ajungă în mâna altora și cumpără-l. „Și am cunoscut” — am înțeles în mintea mea că este cuvântul DOMNULUI să-l cumpăr cu adevărat, și de aceea mi-a făcut cunoscut lucrul acesta."},{"author":"Radak (1160–1235)","text":"Radak: „După rostirea DOMNULUI” — așa cum spusese DOMNUL că va veni la mine, așa a făcut. „Că fusese cuvântul DOMNULUI” — am știut că de la Dumnezeu este să-l cumpăr; căci dacă nu era de la El, de ce mi-ar fi spus că va veni Hanamel la mine să-și vândă ogorul?"}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיָּבֹא אֵלַי חֲנַמְאֵל בֶּן־דֹּדִי...","translation":"„Hanamel, vărul meu, a venit la...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἦλθε πρός με ᾿Αναμεὴλ υἱὸς Σαλώμ, ἀδελφοῦ πατρός μου, εἰς τὴν αὐλὴν τῆς φυλακῆς καὶ εἶπε· κτῆσαι σεαυτῷ τὸν ἀγρόν μου τὸν ἐν γῇ Βενιαμὶν τὸν ἐν ᾿Αναθώθ, ὅτι σοὶ κρίμα κτήσασθαι αὐτόν, καὶ σὺ πρεσβύτερος. καὶ ἔγνων ὅτι λόγος Κυρίου ἐστί,","greek":true,"translation":"„Și a venit la mine Anameel, fiul lui Salom, fratele tatălui meu, în curtea temniței și a zis: Cumpără-ți ogorul meu cel din pământul lui Beniamin, cel din Anatot, căci ție îți aparține dreptul să-l cumperi, și tu ești cel mai în vârstă. Și am cunoscut că este cuvântul Domnului.”","note":"Divergență reală: Septuaginta omite „după rostirea DOMNULUI” și dublul drept (moștenire și răscumpărare), adăugând în schimb „și tu ești cel mai în vârstă” (πρεσβύτερος)."}],"refs":["Ieremia 32:2","Ieremia 33:1","1 Împărați 2:26","1 Samuel 10:3-7","Zaharia 11:11"]},{"v":"32:9","t":"Așa că am cumpărat ogorul care era în Anatot, de la Hanamel, vărul meu, și am cântărit pentru el argintul, șapte sicli și zece selaim de argint.","tokens":[{"t":"Așa că am cumpărat ogorul care era în Anatot, de la Hanamel, vărul meu, și am cântărit pentru el argintul, "},{"t":"șapte sicli","w":"șapte sicli","heb":"שִׁבְעָה שְׁקָלִים","translit":"șiva șekalim","strong":"H8255","pos":"numeral + substantiv, masculin plural","def_ro":"șapte sicli (unitate de greutate pentru argint).","dict_ro":"Șekel — unitatea de bază a greutății pentru metale prețioase, de la șakal, „a cântări”: prețul nu se număra în monede, ci se cântărea. Metzudat David și Radak, după Targum Ionatan, citesc „șapte” ca șapte mine și „zece” ca zece sela de argint — o sumă mult mai mare decât sugerează traducerea literală, potrivită pentru un ogor întreg."},{"t":" și zece selaim de argint."}],"commentaries":[{"author":"Metzudat David","text":"„Am cântărit” — i-am dat cu greutate argintul, prețul ogorului; și erau la număr șapte sicli, adică șapte mine, așa au spus înțelepții noștri. „Și zece de argint” — zece sela, așa traduce Ionatan."},{"author":"Radak (1160–1235)","text":"Radak: argintul pe care l-am tocmit cu el: șapte sicli și zece de argint — siclii sunt mine, iar „argintul” sunt sela, și așa a tradus Ionatan: „șapte mine și zece sela de argint”."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וָאֶקְנֶה אֶת־הַשָּׂדֶה מֵאֵת חֲנַמְאֵל בֶּן־דֹּדִי אֲשֶׁר בַּעֲנָתוֹת וָאֶשְׁקֲלָה־לּוֹ אֶת־הַכֶּסֶף שִׁבְעָה שְׁקָלִים וַעֲשָׂרָה הַכָּסֶף","translation":"Textul masoretic are „șapte șekeli și zece, argintul” (șiv'a șekalim va'asara hakasef); traducerea rabinului Rosen are „șapte sicli și zece selaim de argint”.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐκτησάμην τὸν ἀγρὸν ᾿Αναμεὴλ υἱοῦ ἀδελφοῦ πατρός μου καὶ ἔστησα αὐτῷ ἑπτὰ σίκλους καὶ δέκα ἀργυρίου·","greek":true,"translation":"„Și am cumpărat ogorul lui Anameel, fiul fratelui tatălui meu, și i-am cântărit șapte sicli și zece de argint.”","note":"Corespondență strânsă; Septuaginta omite repetarea „care era în Anatot”."}],"refs":["Geneza 23:15,16","1 Împărați 20:39","Isaia 55:2","Geneza 37:28","Osea 3:2","Zaharia 11:12,13"]},{"v":"32:10","t":"Am scris actul și l-am pecetluit, și am numit martori și am cântărit argintul în balanță.","tokens":[{"t":"Am scris actul și "},{"t":"l-am pecetluit","w":"l-am pecetluit","heb":"וָאֶחְתֹּם","translit":"vaehtom","strong":"H2856","pos":"verb, qal, imperfect consecutiv, persoana I singular","def_ro":"am pecetluit, am sigilat.","dict_ro":"Hatam — „a pecetlui”, a închide un document cu sigiliul, ca să nu poată fi modificat. Descrierea e cea a unei vânzări juridice complete din Antichitatea iudaică: act scris, pecetluire, martori, argint cântărit pe balanță. Radak explică repetarea cântăririi (deja pomenită în v. 9): de data aceasta s-a făcut înaintea martorilor, cu greutate exactă, ca să nu poată apărea mai târziu vreo ceartă asupra plății."},{"t":", și am numit martori și am cântărit argintul în balanță."}],"commentaries":[{"author":"Metzudat David","text":"„Am scris actul” — am poruncit să se scrie în act cele despre cumpărarea ogorului. „Și l-am pecetluit” — i-am poruncit stăpânului ogorului să-și semneze numele pe actul de cumpărare. „Am numit martori” — am chemat martori să vadă lucrul, și înaintea lor am cântărit argintul pe balanță."},{"author":"Radak (1160–1235)","text":"Radak: am scris cuvintele cumpărării în act și apoi am pecetluit actul cu sigiliul. „Am numit martori” — am cumpărat ogorul înaintea martorilor chemați pentru aceasta, iar ei au semnat actul de cumpărare. „Am cântărit argintul în balanță” — deși a spus mai sus „i-am cântărit”, vrea să spună că înaintea martorilor i-a cântărit argintul cu greutate dreaptă, ca să nu poată fi între ei vorbe despre greutatea lui."},{"author":"Metzudat Țion","text":"„Basefer” — așa se numește un sul scris."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וָאֶכְתֹּב בַּסֵּפֶר וָאֶחְתֹּם וָאָעֵד...","translation":"„Am scris actul și l-am pecetluit...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἔγραψα εἰς βιβλίον καὶ ἐσφραγισάμην καὶ διεμαρτυράμην μάρτυρας καὶ ἔστησα τὸ ἀργύριον ἐν ζυγῷ.","greek":true,"translation":"„Și am scris într-o carte și am pecetluit și am chemat martori și am cântărit argintul în cântar.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Ieremia 32:12,44","Isaia 44:5","Rut 4:9-11","Isaia 8:1,2"]},{"v":"32:11","t":"Și am luat actul de vânzare, cel pecetluit, [scris] conform poruncii și decretelor, și cel nepecetluit.","tokens":[{"t":"Și am luat actul de vânzare, cel pecetluit, [scris] conform poruncii și decretelor, și "},{"t":"cel nepecetluit","w":"cel nepecetluit","heb":"הַגָּלוּי","translit":"hagaluy","strong":"H1540","pos":"verb, qal, participiu pasiv, masculin singular, cu articol","def_ro":"cel deschis, nesigilat.","dict_ro":"Galuy — „descoperit, deschis”, de la gala, „a dezveli”. Talmudul (Bava Batra 160b) vede în acest verset temeiul biblic al celor două feluri de acte: cel obișnuit („actul de vânzare”) și cel legat sau pliat („cel pecetluit”), iar „cel deschis” e partea desfăcută a actului pliat; „porunca și decretele” sunt tocmai regulile care le deosebesc (numărul martorilor, locul semnăturilor). Rashi adaugă că actul deschis era confirmat de judecători, ca vânzarea să rămână publică și după moartea martorilor."},{"t":"."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Actul de vânzare” — actul vânzării. „Cel pecetluit” — cu semnăturile lui, cum a fost semnat după poruncă și decret. „Și cel deschis” — care a fost confirmat în judecată prin cuvântul martorilor, iar judecătorii au scris și au semnat o întărire; aceasta e întărirea actelor, ca lucrul să fie deschis și făcut public, ca nu cumva să moară martorii. Iar înțelepții noștri au explicat aceasta despre actul simplu și cel pliat, în Bava Batra (160b)."},{"author":"Metzudat David","text":"„Actul de vânzare” — actul cumpărării. „Cel pecetluit” — când e pecetluit de mâna stăpânului ogorului. „Porunca și decretele” — adică făcut după porunca și decretele obișnuite în zilele acelea. „Și cel deschis” — este un act în care se scrie că vânzarea s-a făcut pe față și public, și n-a fost nimeni care să conteste vânzarea."},{"author":"Talmud Bavli, Bava Batra 160b","text":"Rafram a spus: [temeiul celor două feluri de acte vine] de aici: „Am luat actul de vânzare, cel pecetluit, porunca și decretele, și cel deschis” (Ieremia 32:11). „Actul de vânzare” — acesta este actul obișnuit; „cel pecetluit” — acesta este actul legat; „și cel deschis” — este partea deschisă a actului legat. „Porunca și decretele” — acestea sunt lucrurile care deosebesc actul obișnuit de cel legat: unul are doi martori, iar celălalt trei martori."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וָאֶקַּח אֶת־סֵפֶר הַמִּקְנָה אֶת־הֶחָתוּם...","translation":"„Și am luat actul de vânzare...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἔλαβον τὸ βιβλίον τῆς κτήσεως τὸ ἐσφραγισμένον καὶ τὸ ἀνεγνωσμένον","greek":true,"translation":"„Și am luat cartea cumpărării, cea pecetluită, și cea citită”","note":"Septuaginta omite „[scris] conform poruncii și decretelor” și redă „cel nepecetluit” prin „cea citită” (ἀνεγνωσμένον)."}],"refs":["Luca 2:27","Faptele apostolilor 26:3","1 Corinteni 11:16"]},{"v":"32:12","t":"Și am dat actul de vânzare lui Baruh, fiul lui Neria, fiul lui Mahseia, sub ochii lui Hanamel, [fiul] unchiului meu, și sub ochii martorilor care semnaseră actul de vânzare, sub ochii tuturor iudeilor care stăteau în curtea temniței.","tokens":[{"t":"Și am dat actul de vânzare lui "},{"t":"Baruh","w":"Baruh","heb":"בָּרוּךְ","translit":"Baruh","strong":"H1263","pos":"substantiv propriu, masculin","def_ro":"Baruh („binecuvântat”), scribul lui Ieremia.","dict_ro":"Baruh, fiul lui Neria — scribul și ucenicul credincios al lui Ieremia, cel care îi va scrie profețiile pe sul (Ieremia 36:4) și care îl va însoți în exilul din Egipt (Ieremia 43:6); fratele lui, Seraia, era slujbaș la curtea regelui (Ieremia 51:59). Rashi se oprește asupra unei dificultăți: Hanamel e numit aici „unchiul meu”, deși mai sus era „fiul unchiului” — poate erau doi, sau poate a fost deodată și unchi și văr, deși un asemenea mod de exprimare nu apare nicăieri în Scriptură."},{"t":", fiul lui Neria, fiul lui Mahseia, sub ochii lui Hanamel, [fiul] unchiului meu, și sub ochii martorilor care semnaseră actul de vânzare, sub ochii tuturor iudeilor care stăteau în curtea temniței."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Sub ochii lui Hanamel, unchiul meu” — și până acum îl numea „fiul unchiului meu”. Poate că erau doi; altfel nu știu ce înseamnă. Unii înclină să spună că Hanamel era deopotrivă unchiul și vărul lui Ieremia; dar acesta nu e felul de a vorbi, căci nu găsim nicăieri în Biblie ca fratele mamei să fie numit „unchi”."},{"author":"Metzudat David","text":"„Hanamel, unchiul meu” — se poate ca acesta să nu fie stăpânul ogorului, căci acela era fiul unchiului său. „Cei care semnaseră” — cei care scriseseră în act cele despre vânzare. „Sub ochii tuturor iudeilor” — ca și cum ar fi „și sub ochii”, lipsind vav-ul."},{"author":"Radak (1160–1235)","text":"Radak: „Hanamel, unchiul meu” — vrea să spună fiul unchiului meu, căci era fiul unchiului său, cum a spus mai sus; tot așa „și pe Lot, fratele lui” înseamnă fiul fratelui său. Sau acest Hanamel era altul, unchiul lui, fratele tatălui său, iar vânzătorul era vărul lui; iar acest Hanamel, unchiul, era de față la cumpărare."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וָאֶתֵּן אֶת־הַסֵּפֶר הַמִּקְנָה אֶל־בָּרוּךְ...","translation":"„Și am dat actul de vânzare...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἔδωκα αὐτὸ τῷ Βαροὺχ υἱῷ Νηρίου υἱῷ Μαασαίου κατ’ ὀφθαλμοὺς ᾿Αναμεὴλ υἱοῦ ἀδελφοῦ πατρός μου καὶ κατ’ ὀφθαλμοὺς τῶν ἀνδρῶν τῶν παρεστηκότων καὶ γραφόντων ἐν τῷ βιβλίῳ τῆς κτήσεως καὶ κατ’ ὀφθαλμοὺς τῶν ᾿Ιουδαίων τῶν ἐν τῇ αὐλῇ τῆς φυλακῆς.","greek":true,"translation":"„și am dat-o lui Baruh, fiul lui Nerie, fiul lui Maasaias, înaintea ochilor lui Anameel, fiul fratelui tatălui meu, și înaintea ochilor oamenilor care stăteau și scriau în cartea cumpărării, și înaintea ochilor iudeilor din curtea temniței.”","note":"Septuaginta are „fiul fratelui tatălui meu” (văr), acolo unde Textul Masoretic are „Hanamel, unchiul meu” — dificultate discutată și de Rashi."}],"refs":["Ieremia 36:4,5,16-19,26","Ieremia 43:3-6","Ieremia 45:1-5","Ieremia 51:59","2 Corinteni 8:21"]},{"v":"32:13","t":"Și l-am instruit pe Baruh sub ochii lor, spunând:","tokens":[{"t":"Și "},{"t":"l-am instruit","w":"l-am instruit","heb":"וָאֲצַוֶּה","translit":"vaațave","strong":"H6680","pos":"verb, piel, imperfect consecutiv, persoana I singular","def_ro":"am poruncit, am dat instrucțiuni.","dict_ro":"Țiva — „a porunci, a rândui”, aceeași rădăcină ca mițva, poruncă. Instrucțiunea e dată „sub ochii lor” — ai martorilor și ai iudeilor din curtea temniței —, pentru că gestul profetic trebuia să fie public: toți cei care îl vedeau pe Ieremia păstrând actul pentru „vreme lungă” primeau astfel, fără cuvinte, mesajul că exilul va avea un sfârșit."},{"t":" pe Baruh sub ochii lor, spunând:"}],"commentaries":[],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וָאֲצַוֶּה אֶת־בָּרוּךְ לְעֵינֵיהֶם לֵאמֹר׃...","translation":"„Și l-am instruit pe Baruh sub...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ συνέταξα τῷ Βαροὺχ κατ’ ὀφθαλμοὺς αὐτῶν λέγων·","greek":true,"translation":"„Și i-am poruncit lui Baruh înaintea ochilor lor, zicând:”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":[]},{"v":"32:14","t":"«Așa a spus DOMNUL Oștirilor, Dumnezeul lui Israel: ‘Ia aceste acte, actul acesta de vânzare și pe cel pecetluit și actul acesta nepecetluit, și pune-le într-un vas de lut ca să se păstreze vreme lungă.’","tokens":[{"t":"«Așa a spus DOMNUL Oștirilor, Dumnezeul lui Israel: ‘Ia aceste acte, actul acesta de vânzare și pe cel pecetluit și actul acesta nepecetluit, și pune-le într-un "},{"t":"vas de lut","w":"vas de lut","heb":"כְלִי־חָרֶשׂ","translit":"hli-hares","strong":"H2789","pos":"substantiv, masculin singular, în construcție + substantiv","def_ro":"vas de pământ ars, de lut.","dict_ro":"Heres — lutul ars, ceramica; Metzudat David explică de ce actele se pun într-un vas de lut: acesta păstrează ce e pus înăuntru ferit de putrezire. Descoperirile de la Qumran, unde sulurile au supraviețuit aproape două milenii tocmai în vase de lut, confirmă practica. Rashi citește în porunca aceasta mesajul: să nu crezi că le ascund degeaba, fiindcă toți merg în exil — Radak adaugă că actele trebuie să dăinuie „până la întoarcerea exilaților”."},{"t":" ca să se păstreze vreme lungă.’"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Așa a spus...” — să nu spui că le ascund degeaba, de vreme ce toți merg în exil."},{"author":"Metzudat David","text":"„Și pe cel pecetluit” — cu pecetea lui. „Și pune-le” — actele acestea. „Ca să se păstreze vreme lungă” — căci vasul de lut păstrează lucrul pus în el de putrezire."},{"author":"Radak (1160–1235)","text":"Radak: „Ca să se păstreze vreme lungă” — până la întoarcerea exilului, când se va împlini profeția „se vor mai cumpăra case”; iar ca semn al întoarcerii din exil a poruncit Dumnezeu să se cumpere ogorul, ca să-i mângâie pe cei din Israel, să nu creadă că le-a pierit nădejdea dacă vor fi exilați."},{"author":"Metzudat Țion","text":"„Yaamdu” — se vor păstra."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"כֹּה־אָמַר יְהוָה צְבָאוֹת אֱלֹהֵי...","translation":"„«Așa a spus DOMNUL Oștirilor, Dumnezeul...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"οὕτως εἶπε Κύριος παντοκράτωρ· λάβε τὸ βιβλίον τῆς κτήσεως τοῦτο καὶ τὸ βιβλίον τὸ ἀνεγνωσμένον καὶ θήσεις αὐτὸ εἰς ἀγγεῖον ὀστράκινον, ἵνα διαμείνῃ ἡμέρας πλείους.","greek":true,"translation":"„Așa zice Domnul Atotțiitorul: Ia cartea aceasta a cumpărării și cartea cea citită și o vei pune într-un vas de lut, ca să rămână multe zile.”","note":"Septuaginta scurtează titulatura („Domnul Atotțiitorul” în loc de „DOMNUL Oștirilor, Dumnezeul lui Israel”) și omite mențiunea actului „pecetluit”."}],"refs":[]},{"v":"32:15","t":"Căci așa a spus DOMNUL Oștirilor, Dumnezeul lui Israel: ‘Se vor mai cumpăra case, ogoare și vii pe pământul acesta.’»","tokens":[{"t":"Căci așa a spus DOMNUL Oștirilor, Dumnezeul lui Israel: ‘"},{"t":"Se vor mai cumpăra","w":"Se vor mai cumpăra","heb":"עוֹד יִקָּנוּ","translit":"od yikanu","strong":"H7069","pos":"adverb + verb, nifal, imperfect, persoana a III-a plural","def_ro":"iarăși vor fi cumpărate.","dict_ro":"Kana — „a cumpăra, a dobândi”; la forma pasivă, „vor fi cumpărate”. Acesta e miezul haftarei: în ajunul distrugerii, când ogoarele din jurul Ierusalimului erau deja în mâinile babilonienilor, DOMNUL poruncește o cumpărare ca semn că viața economică obișnuită va reveni. Metzudat David explică: să nu crezi că actul și vasul de lut sunt deșertăciune pentru că pământul va fi al caldeenilor — el e semn că Israel se va întoarce."},{"t":" case, ogoare și vii pe pământul acesta.’»"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Căci așa a spus DOMNUL” — în cele din urmă se vor cumpăra case."},{"author":"Metzudat David","text":"„Căci așa” — ca și cum ar spune: să nu crezi că cumpărarea ogorului și punerea actelor în vasul de lut sunt deșertăciune, de vreme ce caldeenii vor moșteni țara; căci intenția este să fie un semn și o aluzie că va mai veni o vreme când fiii lui Israel vor cumpăra case, iar țara nu va rămâne definitiv în mâna caldeenilor, căci se vor întoarce aici."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"כִּי כֹה אָמַר יְהוָה...","translation":"„Căci așa a spus DOMNUL Oștirilor...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ὅτι οὕτως εἶπε Κύριος· ἔτι κτηθήσονται ἀγροὶ καὶ οἰκίαι καὶ ἀμπελῶνες ἐν τῇ γῇ ταύτῃ.","greek":true,"translation":"„Căci așa zice Domnul: Încă vor fi cumpărate ogoare și case și vii în țara aceasta.”","note":"Septuaginta omite „Oștirilor, Dumnezeul lui Israel” și schimbă ordinea („ogoare și case”)."}],"refs":["Ieremia 32:37,43,44","Ieremia 30:18","Ieremia 31:5,12,24","Ieremia 33:12,13","Amos 9:14,15","Zaharia 3:10"]},{"v":"32:16","t":"M-am rugat DOMNULUI după ce i-am dat actul de vânzare lui Baruh, fiul lui Neria, spunând:","tokens":[{"t":"M-am rugat","w":"M-am rugat","heb":"וָאֶתְפַּלֵּל","translit":"vaetpalel","strong":"H6419","pos":"verb, hitpael, imperfect consecutiv, persoana I singular","def_ro":"m-am rugat.","dict_ro":"Hitpalel — „a se ruga”, forma reflexivă a rădăcinii palal, „a judeca, a hotărî”: rugăciunea ebraică e, etimologic, o „judecare de sine” înaintea lui Dumnezeu. Rugăciunea care urmează (32:17-25) e una dintre cele mai lungi din Ieremia: profetul ascultă porunca, dar își pune înaintea lui Dumnezeu nedumerirea — cum să cumpere un ogor într-o cetate care e pe cale să cadă?"},{"t":" DOMNULUI după ce i-am dat actul de vânzare lui Baruh, fiul lui Neria, spunând:"}],"commentaries":[{"author":"Metzudat David","text":"„Actul de vânzare” — și tot așa actul deschis; pentru scurtare a pomenit doar ce e de căpetenie."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וָאֶתְפַּלֵּל אֶל־יְהוָה אַחֲרֵי תִתִּי...","translation":"„M-am rugat DOMNULUI după ce i-am...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"Καὶ προσευξάμην πρὸς Κύριον μετὰ τὸ δοῦναί με τὸ βιβλίον τῆς κτήσεως πρὸς Βαροὺχ υἱὸν Νηρίου λέγων·","greek":true,"translation":"„Și m-am rugat Domnului după ce am dat cartea cumpărării lui Baruh, fiul lui Nerie, zicând:”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Geneza 32:9-12","2 Samuel 7:18-25","Ezechiel 36:35-37"]},{"v":"32:17","t":"«Vai, Stăpâne, Doamne DUMNEZEULE, iată – Tu ai făcut cerurile și pământul cu puterea Ta cea mare și cu brațul Tău cel întins, niciun lucru nu este ascuns de Tine,","tokens":[{"t":"«Vai, Stăpâne, Doamne DUMNEZEULE, iată – Tu ai făcut cerurile și pământul cu puterea Ta cea mare și cu brațul Tău cel întins, "},{"t":"niciun lucru nu este ascuns","w":"niciun lucru nu este ascuns","heb":"לֹא־יִפָּלֵא ... כָּל־דָּבָר","translit":"lo-yipale ... kol-davar","strong":"H6381","pos":"negație + verb, nifal, imperfect","def_ro":"nimic nu e prea greu, nimic nu e ascuns.","dict_ro":"Pala — „a fi minunat, a fi prea greu, a fi ascuns”; aceeași expresie o spune îngerul Sarei: „este oare ceva prea greu pentru DOMNUL?” (Geneza 18:14). Rashi o citește ca nedumerire: nimic nu-Ți e ascuns, deci știi că suntem sortiți exilului — de ce mi-ai spus să cumpăr un ogor? Iar DOMNUL îi va răspunde cu propriile lui cuvinte în 32:27: „există oare vreun lucru ascuns de Mine?”."},{"t":" de Tine,"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Niciun lucru nu este ascuns de Tine” — nimic nu e ascuns; deci știi că suntem sortiți exilului — de ce mi-ai spus atunci să cumpăr un ogor?"},{"author":"Metzudat David","text":"„Vai” — este un strigăt de tânguire, căci era întristat și îngrijorat, fiind nedumerit să cunoască adevărata tâlcuire a cumpărării ogorului. „Nu este ascuns” — adică, de vreme ce toate sunt lucrarea mâinilor Tale, desigur nimic nu-Ți este ascuns."},{"author":"Radak (1160–1235)","text":"Radak: de vreme ce Tu ai făcut cerurile și pământul, nu se poate să-Ți fie ascuns ceva din ce se face în ele; și dacă cetatea va fi dată în mâna caldeenilor, Tu știi. Ieremia se gândea că poate s-a întors mânia Ta de la ei, din pricina marii Tale bunătăți, pentru că ai pomenit milostivirile părinților — căci altfel de ce ar fi spus să cumpere ogorul, când cetatea e aproape să fie cucerită? Și aceasta este rugăciunea lui."},{"author":"Metzudat Țion","text":"„Aha” — este un strigăt de tânguire. „Yipale” — cu sensul de acoperit și ascuns, ca în „dacă ți se va părea prea greu un lucru la judecată” (Deuteronom 17:8)."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"אֲהָהּ אֲדֹנָי יְהוִה הִנֵּה...","translation":"„«Vai, Stăpâne, Doamne DUMNEZEULE, iată –...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ᾦ Κύριε, σὺ ἐποίησας τὸν οὐρανὸν καὶ τὴν γῆν τῇ ἰσχύϊ σου τῇ μεγάλῃ καὶ τῷ βραχίονί σου τῷ ὑψηλῷ καὶ τῷ μετεώρῳ, οὐ μὴ ἀποκρυβῇ ἀπὸ σοῦ οὐθέν,","greek":true,"translation":"„O, Doamne, Tu ai făcut cerul și pământul cu tăria Ta cea mare și cu brațul Tău cel înalt și ridicat; nimic nu-Ți va fi ascuns,”","note":"Septuaginta omite interjecția „Vai” și titulatura „Stăpâne, Doamne DUMNEZEULE” (doar „Doamne”), iar „brațul întins” devine „brațul înalt și ridicat”."}],"refs":["Ieremia 10:11,12","Neemia 9:6","Ieremia 32:27","Geneza 18:14","Luca 1:37"]},{"v":"32:18","t":"Cel care arăți milă la mii [de generații] și răsplătești păcatul părinților în sânul copiilor lor, după ei, Dumnezeul cel mare și puternic, numele Său este DOMNUL Oștirilor,","tokens":[{"t":"Cel care arăți milă la mii [de generații] și răsplătești păcatul părinților în sânul copiilor lor, după ei, "},{"t":"Dumnezeul cel mare și puternic","w":"Dumnezeul cel mare și puternic","heb":"הָאֵל הַגָּדוֹל הַגִּבּוֹר","translit":"haEl hagadol hagibor","strong":"H410","pos":"substantiv cu articol + adjective","def_ro":"Dumnezeul cel mare, cel puternic.","dict_ro":"HaEl hagadol hagibor — Moise spusese „Dumnezeul cel mare, puternic și înfricoșător” (Deuteronom 10:17). Talmudul (Yoma 69b) observă că Ieremia a omis „înfricoșător”: a spus „neamurile petrec în Sanctuarul Lui — unde îi sunt lucrările înfricoșătoare?”, iar Daniel a omis „puternic”, văzând copiii lui Dumnezeu în robie; bărbații Marii Adunări au readus toate cele trei atribute, spunând că tocmai răbdarea față de cei răi este tăria Lui. De aici formula din rugăciunea zilnică Amida."},{"t":", numele Său este DOMNUL Oștirilor,"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Și răsplătești păcatul părinților în sânul” — al acestei generații, care îi urmează pe părinții ei pe calea lor rea. „Cel mare și puternic” — dar n-a spus „și înfricoșător”. El a spus: neamurile dansează în Templul Lui — unde sunt atunci lucrările Lui înfricoșătoare? În tratatul Yoma (69b)."},{"author":"Metzudat David","text":"„Arăți milă la mii” — pentru dreptatea celui drept faci milă urmașilor lui până la mii de generații. „În sânul copiilor lor” — plătești răsplata păcatului în mijlocul copiilor lor. „După ei” — adică atunci când merg după ei, ținându-se de faptele lor."},{"author":"Talmud Bavli, Yoma 69b","text":"Moise a venit și a spus: „Dumnezeul cel mare, puternic și înfricoșător” (Deuteronom 10:17). A venit Ieremia și a spus: neamurile petrec în Sanctuarul Lui — unde este caracterul Lui înfricoșător? De aceea n-a spus „înfricoșător”: „Dumnezeul cel mare, cel puternic, DOMNUL Oștirilor este numele Său” (Ieremia 32:18). A venit Daniel și a spus: neamurile îi înrobesc copiii — unde este puterea Lui? De aceea n-a spus „puternic”. Au venit bărbații Marii Adunări și au spus: dimpotrivă, aceasta este puterea puterii Lui, că Își stăpânește pornirea și are răbdare cu cei răi."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"עֹשֶׂה חֶסֶד לַאֲלָפִים וּמְשַׁלֵּם...","translation":"„Cel care arăți milă la mii...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ποιῶν ἔλεος εἰς χιλιάδας καὶ ἀποδιδοὺς ἁμαρτίας πατέρων εἰς κόλπους τέκνων αὐτῶν μετ’ αὐτούς, ὁ Θεὸς ὁ μέγας καὶ ἰσχυρός,","greek":true,"translation":"„Cel ce faci milă cu mii și răsplătești păcatele părinților în sânul copiilor lor după ei, Dumnezeul cel mare și tare,”","note":"Septuaginta omite încheierea „DOMNUL Oștirilor este numele Său” (în versiunea greacă, titulatura e mutată și dezvoltată în versetul următor)."}],"refs":["Exod 20:5,6","Exod 34:7","Deuteronom 7:9,10","Deuteronom 10:17","Neemia 1:5","Ieremia 10:16"]},{"v":"32:19","t":"mare în sfat și măreț în întreprindere, ai cărui ochi sunt deschiși față de toate căile oamenilor, pentru a da oricărui om după calea sa și după rodul întreprinderilor sale,","tokens":[{"t":"mare în sfat","w":"mare în sfat","heb":"גְּדֹל הָעֵצָה","translit":"ghedol haeța","strong":"H6098","pos":"adjectiv, în construcție + substantiv, feminin singular, cu articol","def_ro":"mare în planuri, mare în înțelepciune.","dict_ro":"Eța — sfatul, planul; „mare în sfat și măreț în întreprindere” pune alături planul divin și împlinirea lui. Metzudat David explică încheierea: Dumnezeu judecă omul nu doar după faptele lui, ci și după „rodul” lor — urmările pe care omul nu le-a urmărit, dar pentru care răspunde totuși. Radak adaugă că „ochii deschiși spre căile oamenilor” răspund celor care spuneau „DOMNUL nu ne vede” (Ezechiel 8:12)."},{"t":" și măreț în întreprindere, ai cărui ochi sunt deschiși față de toate căile oamenilor, pentru a da oricărui om după calea sa și după rodul întreprinderilor sale,"}],"commentaries":[{"author":"Metzudat David","text":"„Mare în sfat” — sfatul Lui e mare și însemnat. „Măreț în întreprindere” — faptele Lui sunt multe, căci tot ce voiește face. „Asupra tuturor căilor” — ca să vegheze asupra tuturor căilor oamenilor, ca să dea fiecăruia după căile lui. „Și după rodul faptelor lui” — adică lucrul care urmează din faptele lui, fără să fi fost intenția lui, căci și pentru aceasta va fi adus la judecată."},{"author":"Radak (1160–1235)","text":"Radak: „Mare în sfat” — sfaturile Lui sunt mari și faptele Lui prea multe ca să fie cuprinse. „Asupra tuturor căilor oamenilor” — nu cum spuneau ei: „DOMNUL nu ne vede”."},{"author":"Metzudat Țion","text":"„Haalilia” — cu sensul de faptă, ca în „și prin faptele lui” (Proverbe 20:11). „Pekuhot” — deschise, ca în „deschide, DOAMNE, ochii Tăi” (Isaia 37:17)."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"גְּדֹל הָעֵצָה וְרַב הָעֲלִילִיָּה...","translation":"„mare în sfat și măreț în...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"Κύριος μεγάλης βουλῆς καὶ δυνατὸς τοῖς ἔργοις, ὁ Θεὸς ὁ μέγας, ὁ παντοκράτωρ καὶ μεγαλώνυμος Κύριος· οἱ ὀφθαλμοί σου εἰς τὰς ὁδοὺς τῶν υἱῶν τῶν ἀνθρώπων δοῦναι ἑκάστῳ κατὰ τὴν ὁδὸν αὐτοῦ·","greek":true,"translation":"„Domn mare în sfat și puternic în lucrări, Dumnezeul cel mare, Atotțiitorul și mult-numitul Domn; ochii Tăi sunt spre căile fiilor oamenilor, ca să dai fiecăruia după calea lui.”","note":"Septuaginta adaugă aici titulatura („Dumnezeul cel mare, Atotțiitorul și mult-numitul Domn”) și omite „după rodul faptelor lui”."}],"refs":["Isaia 9:6","Isaia 28:29","Romani 11:33,34","2 Cronici 16:9","Proverbe 5:21","Ieremia 17:10"]},{"v":"32:20","t":"cel care ai pus semne și minuni în țara Egiptului, [care sunt cunoscute] până în ziua de astăzi, și în Israel și în [ochii] omului, și care Ți-ai făcut un renume până în ziua aceasta","tokens":[{"t":"cel care ai pus "},{"t":"semne și minuni","w":"semne și minuni","heb":"אוֹתוֹת וּמֹפְתִים","translit":"otot umoftim","strong":"H4159","pos":"substantiv, masculin plural + conjuncție + substantiv, masculin plural","def_ro":"semne și minuni.","dict_ro":"Otot umoftim — perechea clasică pentru minunile din Egipt (Deuteronom 6:22). Rashi și Radak aduc un midraș despre „în Israel și printre oameni”: aceeași minune a lucrat deodată spre bine pentru Israel și spre rău pentru egipteni — „norul era întuneric [pentru unii] și lumina noaptea [pentru ceilalți]” (Exod 14:20). Metzudat David citește la fel: într-o singură lucrare, lumină pentru unii și întuneric pentru alții."},{"t":" în țara Egiptului, [care sunt cunoscute] până în ziua de astăzi, și în Israel și în [ochii] omului, și care Ți-ai făcut un renume până în ziua aceasta"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Și printre oameni” — și printre ceilalți oameni. O altă explicație: semne care au fost deodată pentru Israel și pentru egipteni. Cum așa? „Și era norul și întunericul, și lumina noaptea” (Exod 14:20): același înger care a slujit ca întuneric pentru egipteni a slujit ca lumină pentru israeliți. Iar Ionatan traduce: „și pentru Israel ai făcut minuni între oameni”."},{"author":"Metzudat David","text":"„Până în ziua de astăzi” — adică pomenite până în ziua de astăzi. „În Israel și printre oameni” — ai pus semne în Israel și în ceilalți oameni, egiptenii, adică într-o singură dată ai făcut o minune bună pentru unii și rea pentru alții, cum s-a spus: „și era norul și întunericul, și lumina noaptea”, întuneric pentru egipteni și lumină pentru Israel. „Și Ți-ai făcut un renume” — faimă de laudă."},{"author":"Radak (1160–1235)","text":"Radak: „Până în ziua de astăzi” — până în ziua aceasta sunt cunoscute între oameni. „Și Ți-ai făcut un renume” — ești cunoscut prin semne și minuni, și prin ele Te-au cunoscut oamenii, chiar fără voia lor."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"אֲשֶׁר־שַׂמְתָּ אוֹתוֹת וּמֹפְתִים בְּאֶרֶץ...","translation":"„cel care ai pus semne și...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ὃς ἐποίησας σημεῖα καὶ τέρατα ἐν γῇ Αἰγύπτῳ ἕως τῆς ἡμέρας ταύτης καὶ ἐν ᾿Ισραὴλ καὶ ἐν τοῖς γηγενέσι· καὶ ἐποίησας σεαυτῷ ὄνομα, ὡς ἡμέρα αὕτη","greek":true,"translation":"„care ai făcut semne și minuni în țara Egiptului până în ziua aceasta, și în Israel și între cei născuți din pământ, și Ți-ai făcut nume ca ziua aceasta,”","note":"Corespondență strânsă; „oameni” (adam) e redat prin „cei născuți din pământ” (γηγενέσι)."}],"refs":["Exod 7:3","Deuteronom 4:34","Neemia 9:10","Psalmii 78:43-51","Faptele apostolilor 7:36","Isaia 63:12"]},{"v":"32:21","t":"și ai scos pe poporul Tău, pe Israel, din țara Egiptului, cu semne și cu minuni, și cu mână puternică, și cu braț întins, și cu mare înfricoșare,","tokens":[{"t":"și ai scos pe poporul Tău, pe Israel, din țara Egiptului, cu semne și cu minuni, și cu mână puternică, și cu braț întins, și "},{"t":"cu mare înfricoșare","w":"cu mare înfricoșare","heb":"וּבְמוֹרָא גָּדוֹל","translit":"uvmora gadol","strong":"H4172","pos":"conjuncție + prepoziție + substantiv + adjectiv","def_ro":"cu mare groază, cu fapte înfricoșătoare.","dict_ro":"Mora — frica, groaza, dar și faptele care o stârnesc. Versetul reproduce aproape cuvânt cu cuvânt formula din Deuteronom 26:8, recitată de cel ce aducea pârga la Templu și păstrată în Hagada de Pesah („cu mână tare, cu braț întins, cu mare înfricoșare, cu semne și minuni”); Hagada o interpretează drept „descoperirea Prezenței divine”. Metzudat David explică „înfricoșarea” ca spaima pe care Dumnezeu a pus-o asupra Egiptului."},{"t":","}],"commentaries":[{"author":"Metzudat David","text":"„Și cu brațul întins” — a luat pilda unui viteaz care își întinde mâna asupra celui care se luptă cu el. „Cu mare înfricoșare” — pentru că îi înspăimântai pe egipteni."},{"author":"Radak (1160–1235)","text":"Radak: „Uvezroa” — cu alef adăugat, din literele de prefix."},{"author":"Metzudat Țion","text":"„Uvezroa” — alef-ul este adăugat."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַתֹּצֵא אֶת־עַמְּךָ אֶת־יִשְׂרָאֵל מֵאֶרֶץ...","translation":"„și ai scos pe poporul Tău...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐξήγαγες τὸν λαόν σου ᾿Ισραὴλ ἐκ γῆς Αἰγύπτου ἐν σημείοις καὶ ἐν τέρασιν, ἐν χειρὶ κραταιᾷ καὶ ἐν βραχίονι ὑψηλῷ","greek":true,"translation":"„și ai scos pe poporul Tău Israel din țara Egiptului cu semne și minuni, cu mână tare și cu braț înalt”","note":"Septuaginta citește ultimul cuvânt ca mar'eh („vedenie”), nu mora („înfricoșare”), și îl mută la începutul versetului următor: „și cu vedenii mari”."}],"refs":["Exod 6:6","Exod 13:14","Psalmii 105:37,43","Exod 6:1","Deuteronom 26:8","Psalmii 136:11,12"]},{"v":"32:22","t":"și le-ai dat această țară pe care ai jurat-o strămoșilor lor să le-o dai, o țară în care curge lapte și miere.","tokens":[{"t":"și le-ai dat această țară pe care ai jurat-o strămoșilor lor să le-o dai, o țară "},{"t":"în care curge lapte și miere","w":"în care curge lapte și miere","heb":"זָבַת חָלָב וּדְבָשׁ","translit":"zavat halav udvaș","strong":"H2100","pos":"verb, qal, participiu, feminin singular, în construcție + substantive","def_ro":"din care curge lapte și miere.","dict_ro":"Zava — „a curge, a picura”; „țara în care curge lapte și miere” e formula făgăduinței din Exod 3:8. Metzudat David o explică la propriu: laptele picură din ugerele vitelor, care pasc pășune grasă, iar din curmali picură „mierea”, adică siropul de curmale. Aici, la mijlocul rugăciunii, formula are o amărăciune aparte: țara făgăduinței e tocmai cea pe care cetatea asediată e pe cale s-o piardă."},{"t":"."}],"commentaries":[{"author":"Metzudat David","text":"„Țară în care curge” — este țara în care laptele picură din ugerele vitelor, căci pasc pășune grasă și au lapte mult, iar curmalele picură mierea."},{"author":"Metzudat Țion","text":"„Zavat” — din curgere și picurare."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַתִּתֵּן לָהֶם אֶת־הָאָרֶץ הַזֹּאת...","translation":"„și le-ai dat această țară pe...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἐν ὁράμασι μεγάλοις· καὶ ἔδωκας αὐτοῖς τὴν γῆν ταύτην, ἣν ὤμοσας τοῖς πατράσιν αὐτῶν, γῆν ῥέουσαν γάλα καὶ μέλι.","greek":true,"translation":"„și cu vedenii mari; și le-ai dat țara aceasta, pe care ai jurat-o părinților lor, țară în care curge lapte și miere.”","note":"Septuaginta începe versetul cu „și cu vedenii mari” (vezi nota de la 32:21); în rest, corespondență strânsă."}],"refs":["Geneza 15:18-21","Deuteronom 6:10,18,23","Iosua 21:43","Ieremia 11:5","Exod 3:8,17","Ezechiel 20:6,15"]},{"v":"32:23","t":"Ei au venit și au luat în stăpânire [țara Canaanului], dar nu au ascultat de glasul Tău, după învățătura Ta nu au mers, tot ce le-ai poruncit să facă nu au făcut și [de aceea] Tu ai făcut să li se întâmple tot acest rău.","tokens":[{"t":"Ei au venit și au luat în stăpânire [țara Canaanului], dar nu au ascultat de glasul Tău, după învățătura Ta nu au mers, tot ce le-ai poruncit să facă nu au făcut și [de aceea] "},{"t":"Tu ai făcut să li se întâmple","w":"Tu ai făcut să li se întâmple","heb":"וַתַּקְרֵא","translit":"vatakre","strong":"H7122","pos":"verb, hifil, imperfect consecutiv, persoana a II-a masculin singular","def_ro":"ai făcut să vină asupra lor.","dict_ro":"Kara (cu alef în loc de he) — „a întâmpina, a se întâmpla”, de unde mikre, „întâmplare”. Radak observă că forma e scrisă cu alef și vede aici o intenție: răul venit asupra lor nu e o întâmplare oarbă, venită de la sine, ci Dumnezeu Însuși l-a făcut să vină. Metzudat David leagă cauza de efect: pentru că n-au ascultat, le-ai adus nenorocirea descrisă în versetul următor."},{"t":" tot acest rău."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Ai făcut să vină asupra lor” — ai făcut să li se întâmple; este o expresie a „întâmplării” (mikre)."},{"author":"Metzudat David","text":"„Și după învățătura Ta” — după cuvintele învățăturii Tale n-au umblat. „Ai făcut să li se întâmple” — și de aceea ai adus asupra lor întâmplarea acestui rău, explicată în versetul următor."},{"author":"Radak (1160–1235)","text":"Radak: „Vatakre” — de la „căci DOMNUL, Dumnezeul tău, a făcut să mi se întâmple”; e scris cu alef în loc de he, ca să arate că întâmplarea rea venită asupra lor nu este o întâmplare deplină, venită de la sine, ci El, binecuvântat fie, a făcut-o să vină."},{"author":"Metzudat Țion","text":"„Vatakre” — din „întâmplare”, iar alef-ul vine în locul lui he."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיָּבֹאוּ וַיִּירְשׁוּ אֹתָהּ וְלֹא־שָׁמְעוּ...","translation":"„Ei au venit și au luat...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ εἰσήλθοσαν καὶ ἐλάβοσαν αὐτὴν καὶ οὐκ ἤκουσαν τῆς φωνῆς σου καὶ ἐν τοῖς προστάγμασί σου οὐκ ἐπορεύθησαν· ἅπαντα, ἃ ἐνετείλω αὐτοῖς οὐκ ἐποίησαν· καὶ ἐποίησας συμβῆναι αὐτοῖς πάντα τὰ κακὰ ταῦτα.","greek":true,"translation":"„Și au intrat și au luat-o și n-au ascultat de glasul Tău și în poruncile Tale n-au umblat; toate câte le-ai poruncit n-au făcut; și ai făcut să se întâmple asupra lor toate relele acestea.”","note":"Corespondență strânsă; „învățătura Ta” (torah) e redată prin „poruncile Tale” (προστάγμασι)."}],"refs":["Neemia 9:15,22-25","Psalmii 44:2,3","Ieremia 7:23,24","Judecători 2:11-13","Daniel 9:11,12","Levitic 26:14-46"]},{"v":"32:24","t":"Iată, pe rampe înălțate de pământ au venit la oraș să-l cucerească și orașul a fost predat în mâna caldeenilor care îl atacau, din pricina sabiei, a foametei și a molimei, iar ceea ce ai spus Tu [așa] a fost și Tu vezi asta!","tokens":[{"t":"Iată, "},{"t":"pe rampe înălțate de pământ","w":"pe rampe înălțate de pământ","heb":"הַסֹּלְלוֹת","translit":"hasolelot","strong":"H5550","pos":"substantiv, feminin plural, cu articol","def_ro":"valurile de pământ ale asediului, rampele.","dict_ro":"Solela — movila sau rampa de pământ înălțată lângă zidul unei cetăți asediate, ca atacatorii să poată urca pe ea; Metzudat Țion o descrie ca „tell de țărână vărsat în fața cetății, ca să se urce pe ea”. Radak aduce și o altă lectură: mașinile care aruncau pietre în ziduri. Prin „și Tu vezi asta!”, profetul Îl ia pe Dumnezeu martor: cuvântul de pedeapsă s-a împlinit sub ochii tuturor."},{"t":" au venit la oraș să-l cucerească și orașul a fost predat în mâna caldeenilor care îl atacau, din pricina sabiei, a foametei și a molimei, iar ceea ce ai spus Tu [așa] a fost și Tu vezi asta!"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Și ceea ce ai spus” — răul [rostit] asupra ei s-a împlinit."},{"author":"Metzudat David","text":"„Iată, rampele” — căci iată, oamenii de război care stau pe rampe ca să lupte de pe ele au venit deja asupra cetății s-o cucerească, și este ca și cum ar fi fost deja dată în mâna lor, căci locuitorii cetății n-au putere să-i împiedice, fiind sfârșiți de sabie, de foamete și de molimă. „Și ceea ce ai spus” — de mult, că cetatea va fi cucerită, iată, așa a fost, și Tu vezi că așa este."},{"author":"Radak (1160–1235)","text":"Radak: „Iată, rampele” — sunt lemnele [mașinile] cu care aruncă pietre în zidurile cetății ca să le lovească; iar Ionatan traduce „iată, valurile au urcat asupra cetății ca s-o cucerească” — un tell de țărână care se strânge în jurul zidului ca să se urce de acolo pe zid."},{"author":"Metzudat Țion","text":"„Hasolelot” — tellul de țărână care se varsă în fața cetății ca să se urce pe el și să se lupte cu cetatea se numește solela, ca în „și va ridica val” (Daniel 11:15). „Vehineha” — iată-te."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"הִנֵּה הַסֹּלְלוֹת בָּאוּ הָעִיר...","translation":"„Iată, pe rampe înălțate de pământ...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ἰδοὺ ὄχλος ἥκει εἰς τὴν πόλιν ταύτην συλλαβεῖν αὐτήν, καὶ ἡ πόλις ἐδόθη εἰς χεῖρας Χαλδαίων τῶν πολεμούντων αὐτὴν ἀπὸ προσώπου μαχαίρας καὶ τοῦ λιμοῦ· ὡς ἐλάλησας, οὕτως ἐγένετο.","greek":true,"translation":"„Iată, mulțime a venit în cetatea aceasta ca s-o cucerească, și cetatea a fost dată în mâinile caldeenilor care se luptă împotriva ei, din pricina sabiei și a foametei; cum ai grăit, așa s-a întâmplat.”","note":"Septuaginta redă „rampele” prin „mulțime” (ὄχλος), omite „molima” și încheierea „și Tu vezi asta”."}],"refs":["Ieremia 33:4","Ezechiel 21:22","Ieremia 21:4-7","Ieremia 37:6-10","Plângerile lui Ieremia 4:3-10","Iosua 23:15,16"]},{"v":"32:25","t":"Și totuși, Tu mi-ai spus, Stăpâne, Doamne DUMNEZEULE: «Cumpără pentru tine cu argint un ogor și numește martori – dar orașul a fost predat caldeenilor!»”","tokens":[{"t":"Și totuși, Tu mi-ai spus, Stăpâne, Doamne DUMNEZEULE: «Cumpără pentru tine cu argint un ogor și "},{"t":"numește martori","w":"numește martori","heb":"וְהָעֵד עֵדִים","translit":"vehaed edim","strong":"H5707","pos":"verb, hifil, imperativ + substantiv, masculin plural","def_ro":"cheamă martori.","dict_ro":"Ed — martorul; profetul își încheie rugăciunea punând alături porunca și realitatea: „cumpără și cheamă martori — dar cetatea a fost dată caldeenilor!”. Rashi o rezumă: ce folos îmi mai e ogorul? Metzudat David precizează o nuanță importantă: deși Ieremia însuși îi spusese lui Baruh că e un semn al întoarcerii (32:15), acum vorbește din gândurile inimii lui, căci profeția încă nu-i fusese descoperită pe deplin — răspunsul vine în versetele următoare."},{"t":" – dar orașul a fost predat caldeenilor!»”"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Și totuși orașul a fost predat” — ce folos îmi mai este ogorul?"},{"author":"Metzudat David","text":"„Și totuși, Tu mi-ai spus” — adică ce este aceasta, că mi-ai făcut cunoscută venirea lui Hanamel, ca și cum mi-ai fi spus prin aceasta să cumpăr ogorul de la el și să chem martori, după obiceiul cumpărătorilor? „Și orașul” — oare nu a fost dat orașul în mâna caldeenilor? Ce folos este atunci cumpărarea ogorului, de vreme ce caldeenii îl vor lua? Și deși el însuși îi spusese lui Baruh, fiul lui Neria, că lucrul vine ca aluzie și semn, aceasta a spus-o din gândurile inimii lui, și nu-i venise încă profeția despre aceasta."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְאַתָּה אָמַרְתָּ אֵלַי אֲדֹנָי...","translation":"„Și totuși, Tu mi-ai spus, Stăpâne...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ σὺ λέγεις πρός με· κτῆσαι σεαυτῷ τὸν ἀγρὸν ἀργυρίου· καὶ ἔγραψα βιβλίον καὶ ἐσφραγισάμην καὶ ἐπεμαρτυράμην μάρτυρας· καὶ ἡ πόλις ἐδόθη εἰς χεῖρας Χαλδαίων.","greek":true,"translation":"„Și Tu îmi zici: Cumpără-ți ogorul cu argint; și am scris o carte și am pecetluit și am chemat martori; și cetatea a fost dată în mâinile caldeenilor.”","note":"Septuaginta omite adresarea „Stăpâne, Doamne DUMNEZEULE” și adaugă „și am scris o carte și am pecetluit” — relatarea îndeplinirii poruncii, nu doar porunca."}],"refs":["Ieremia 32:24"]},{"v":"32:26","t":"Și apoi a venit cuvântul DOMNULUI la Ieremia, spunând:","tokens":[{"t":"Și apoi a venit "},{"t":"cuvântul DOMNULUI","w":"cuvântul DOMNULUI","heb":"דְבַר־יְהוָה","translit":"devar-ADONAI","strong":"H1697","pos":"substantiv, masculin singular, în construcție + nume divin","def_ro":"cuvântul DOMNULUI.","dict_ro":"Devar ADONAI — răspunsul divin vine imediat după rugăciune. Din punct de vedere liturgic, haftara se oprește aici, cu primul verset al răspunsului (32:27), iar comunitățile Chabad se opresc chiar mai devreme, după 32:22; continuarea capitolului (32:28-44) dezvoltă promisiunea: pedeapsa va veni, dar DOMNUL îi va aduna din nou și se vor cumpăra ogoare „în ținutul lui Beniamin și în împrejurimile Ierusalimului” (32:44)."},{"t":" la Ieremia, spunând:"}],"commentaries":[],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וַיְהִי דְבַר־יְהוָה אֶל־יִרְמְיָהוּ לֵאמֹר׃...","translation":"„Și apoi a venit cuvântul DOMNULUI...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"Καὶ ἐγένετο λόγος Κυρίου πρός με λέγων·","greek":true,"translation":"„Și a fost cuvântul Domnului către mine, zicând:”","note":"Septuaginta are „către mine” (persoana întâi), acolo unde Textul Masoretic are „către Ieremia”."}],"refs":[]},{"v":"32:27","t":"„Iată, Eu sunt DOMNUL, Dumnezeul tuturor făpturilor. Există oare vreun lucru ascuns de Mine?”","tokens":[{"t":"„Iată, Eu sunt DOMNUL, "},{"t":"Dumnezeul tuturor făpturilor","w":"Dumnezeul tuturor făpturilor","heb":"אֱלֹהֵי כָּל־בָּשָׂר","translit":"Elohei kol-basar","strong":"H1320","pos":"substantiv, în construcție + substantiv","def_ro":"Dumnezeul oricărei făpturi (a oricărei cărni).","dict_ro":"Kol basar — „toată carnea”, adică orice făptură vie; titlul apare în Tora în rugăciunea lui Moise, „Dumnezeul duhurilor oricărei făpturi” (Numeri 16:22; 27:16). Răspunsul lui Dumnezeu reia chiar cuvintele profetului din 32:17 („niciun lucru nu este ascuns de Tine”): da, știu că cetatea va cădea, spune Radak, și totuși ți-am poruncit să cumperi ogorul, ca să le fie mângâiere că se vor întoarce din exil și vor cumpăra iarăși ogoare și case."},{"t":". Există oare vreun lucru ascuns de Mine?”"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Există oare vreun lucru ascuns de Mine?” — sunt ascunse de Mine cele ce vor fi?"},{"author":"Metzudat David","text":"„Tuturor făpturilor” — tuturor creaturilor. „De Mine” — adică, dacă Eu sunt Dumnezeul lumii, oare poate exista vreun lucru care să-Mi fie acoperit, ca să nu-l pot face? Ca și cum ar spune: chiar dacă țara a fost dată în mâna caldeenilor, totuși e în mâna Mea s-o întorc lui Israel; și de aceea ți-am poruncit să cumperi ogorul, să fie semn și aluzie că așa voi face."},{"author":"Radak (1160–1235)","text":"Radak: „Există oare vreun lucru ascuns de Mine?” — cu adevărat nu Mi-e ascuns; știam că cetatea va fi dată în mâna caldeenilor, căci nu s-a întors mânia Mea de la ei, fiindcă păcatele lor s-au înmulțit ca să Mă mânie; și totuși ți-am spus să cumperi ogorul, ca să le fie mângâiere că se vor întoarce din exil și vor cumpăra ogoare și case în țara aceasta."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"הִנֵּה אֲנִי יְהוָה אֱלֹהֵי...","translation":"„„Iată, Eu sunt DOMNUL, Dumnezeul tuturor...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ἐγὼ Κύριος ὁ Θεὸς πάσης σαρκός, μὴ ἀπ’ ἐμοῦ κρυβήσεταί τι;","greek":true,"translation":"„Eu sunt Domnul, Dumnezeul a toată carnea; oare se va ascunde ceva de Mine?”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Numeri 16:22","Numeri 27:16","Psalmii 65:2","Luca 3:6","Ieremia 32:17","Matei 19:26"]}]},{"num":12,"title":"Behukotai - În decretele Mele","ref":"Ieremia 16:19-17:14","intro":"Pericopa Behukotai încheie cartea Leviticului cu binecuvântările făgăduite celor care umblă în decretele lui Dumnezeu și cu avertismentele pentru cei care le părăsesc, printre care exilul, în care „țara își va plăti Sabatele” neținute. Haftara din Ieremia reia aceeași alternativă. Păcatul lui Iuda e „scris cu o daltă de fier” pe inima poporului, iar pedeapsa va fi tocmai pierderea moștenirii, ca plată pentru anii sabatici nerespectați. Urmează un diptic memorabil: blestemat este omul care se încrede în om, ca un arbust uscat în pustie; binecuvântat este cel care se încrede în DOMNUL, ca un pom sădit lângă ape, care rodește și în anul de secetă. Haftara se încheie cu rugăciunea profetului, intrată în rugăciunea zilnică evreiască: „Vindecă-mă, DOAMNE, și voi fi vindecat, salvează-mă și voi fi salvat, căci Tu ești lauda mea.”","verses":[{"v":"16:19","t":"DOAMNE – Tăria mea, Cetățuia mea și Refugiul meu în ziua nenorocirii – la Tine vor veni neamuri de la marginile pământului și vor spune: „Strămoșii noștri au moștenit doar minciună, deșertăciune care nu are niciun rost.","tokens":[{"t":"DOAMNE – Tăria mea, Cetățuia mea și "},{"t":"Refugiul meu","w":"Refugiul meu","heb":"וּמְנוּסִי","translit":"umnusi","strong":"H4498","pos":"conjuncție + substantiv, masculin singular + sufix persoana I","def_ro":"locul meu de scăpare, refugiul meu.","dict_ro":"Manos — locul în care fugi ca să scapi, de la nus, „a fugi”; Metzudat Țion îl explică „din fugă și scăpare”. Triada „Tăria mea, Cetățuia mea și Refugiul meu” e o mărturisire personală a profetului persecutat, iar Metzudat David explică: când vine necazul, fug la Tine ca să scap. Rashi aduce și lectura lui Menahem, care leagă cuvântul de nes, „steag, minune”, ca în „ai dat celor ce se tem de Tine un steag” (Psalmii 60:4)."},{"t":" în ziua nenorocirii – la Tine vor veni neamuri de la marginile pământului și vor spune: „Strămoșii noștri au moștenit doar minciună, deșertăciune care nu are niciun rost."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Și Refugiul meu” — lauda mea; iar Menahem l-a clasificat ca expresie de „minune”, ca în „ai dat celor ce se tem de Tine un steag ca să se înalțe” (Psalmii 60:4). „La Tine vor veni neamuri” — în cele din urmă păgânii vor veni la Tine și Te vor sluji într-un cuget și vor spune: „Cum și-au făcut dumnezei, și ei nu sunt dumnezei?” „Au moștenit” — o expresie de moștenire. „Rost” — o expresie de folos."},{"author":"Metzudat David","text":"„DOAMNE – Tăria mea și Cetățuia mea” — a spus profetul: Tu, DOAMNE, ești puterea mea, iar dublarea cuvântului întărește lucrul. „În ziua nenorocirii” — când vine necazul, fug la Tine ca să scap; e o figură de stil care vrea să spună: atunci mă încred în Tine. „La Tine” — iată, știu că la sfârșit neamurile de la marginile pământului vor veni la Tine ca să creadă în Tine și vor spune: idolii pe care i-au moștenit părinții noștri ca să le fie dumnezei sunt doar minciună și deșertăciune, fără niciun folos."},{"author":"Radak (1160–1235)","text":"Radak: profetul spune ca într-o chemare: Tu, DOAMNE, care ești tăria mea împotriva celor ce se luptă cu mine, și la Tine fug în ziua necazului — aceștia, pe care îi mustru pentru idolatrie, nu vor să se întoarcă de la calea lor rea; dar știu că va veni o vreme când chiar neamurile îndepărtate se vor întoarce și vor veni la Tine, în locul acesta, și vor spune: „părinții noștri au moștenit doar minciună” — și aceasta va fi în zilele lui Mesia. Iar „au moștenit” — pentru că au slujit idolilor generație după generație, moștenire de la părinți la fii."},{"author":"Metzudat Țion","text":"„Uzzi umaUzzi” — cu sensul de tărie. „Umnusi” — din fugă și scăpare. „Meafsei” — de la margini, căci la marginile pământului e ca și cum totul s-ar sfârși. „Moil” — din „folos”."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"יְהוָה עֻזִּי וּמָעֻזִּי וּמְנוּסִי...","translation":"„DOAMNE – Tăria mea, Cetățuia mea...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"Κύριε, σὺ ἰσχύς μου καὶ βοήθειά μου καὶ καταφυγή μου ἐν ἡμέρᾳ κακῶν· πρὸς σὲ ἔθνη ἥξουσιν ἀπ’ ἐσχάτου τῆς γῆς καὶ ἐροῦσιν· ὡς ψευδῆ ἐκτήσαντο οἱ πατέρες ἡμῶν εἴδωλα, καὶ οὐκ ἔστιν ἐν αὐτοῖς ὠφέλημα.","greek":true,"translation":"„Doamne, Tu ești tăria mea și ajutorul meu și scăparea mea în ziua relelor; la Tine vor veni neamuri de la marginea pământului și vor zice: Ce idoli mincinoși au dobândit părinții noștri, și nu este în ei niciun folos.”","note":"Septuaginta explicitează „minciuna” moștenită drept „idoli” (εἴδωλα); în rest, corespondență strânsă."}],"refs":["Psalmii 18:1,2","Psalmii 46:1,7,11","Naum 1:7","Isaia 2:2,3","Zaharia 8:20-23","Ieremia 10:14,15"]},{"v":"16:20","t":"Poate oare omul să-și facă un dumnezeu? [Ce face omul] nu sunt dumnezei!”","tokens":[{"t":"Poate oare omul să-și facă "},{"t":"un dumnezeu","w":"un dumnezeu","heb":"אֱלֹהִים","translit":"elohim","strong":"H430","pos":"substantiv, masculin plural","def_ro":"dumnezei (aici: idoli făcuți de om).","dict_ro":"Elohim — același cuvânt desemnează pe Dumnezeu și pe „dumnezeii” neamurilor; versetul se joacă tocmai cu această dublă folosire: „să-și facă omul elohim — și ei nu sunt elohim!”. Metzudat David dezvoltă logica: dacă oamenii înșiși nu sunt dumnezei, cum ar putea lucrarea mâinilor lor să fie mai presus decât ei? Radak pune întrebarea în gura neamurilor care se vor întoarce, uimite cum a putut exista vreodată o asemenea credință."},{"t":"? [Ce face omul] nu sunt dumnezei!”"}],"commentaries":[{"author":"Metzudat David","text":"„Poate oare omul” — se cuvine oare ca omul să-și facă un dumnezeu prin lucrarea mâinilor lui? Oare oamenii înșiși nu sunt dumnezei; cum ar putea atunci lucrarea mâinilor lor să fie mai bună decât ei?"},{"author":"Radak (1160–1235)","text":"Radak: „Poate oare omul să-și facă dumnezei?” — nu vor face lucrarea unui dumnezeu, să le răspundă când strigă la ei și să-i ajute în necazul lor; aceasta o vor spune neamurile când vor veni la Tine și își vor mărturisi nelegiuirea, uimindu-se cum a putut să le treacă prin minte o asemenea credință."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"הֲיַעֲשֶׂה־לּוֹ אָדָם אֱלֹהִים וְהֵמָּה...","translation":"„Poate oare omul să-și facă un...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"εἰ ποιήσει ἑαυτῷ ἄνθρωπος θεούς; καὶ οὗτοι οὐκ εἰσὶ θεοί.","greek":true,"translation":"„Oare își va face omul dumnezei? Și aceștia nu sunt dumnezei.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Psalmii 115:4-8","Isaia 37:19","Osea 8:4-6","Faptele apostolilor 19:26","Galateni 4:8"]},{"v":"16:21","t":"De aceea, iată, le vestesc de această dată, îi voi face să știe despre mâna Mea și puterea Mea; și vor cunoaște că numele meu este DOMNUL.","tokens":[{"t":"De aceea, iată, le vestesc de această dată, îi voi face să știe despre mâna Mea și puterea Mea; și vor cunoaște că "},{"t":"numele meu este DOMNUL","w":"numele meu este DOMNUL","heb":"שְׁמִי יְהוָה","translit":"șemi ADONAI","strong":"H8034","pos":"substantiv + sufix persoana I + nume divin","def_ro":"numele Meu este DOMNUL.","dict_ro":"Șem — numele, în gândirea biblică expresia însăși a ființei și a puterii celui ce îl poartă. Rashi citește „vor cunoaște că numele Meu este DOMNUL” la propriu: stăpânitor și suveran, care Își împlinește hotărârea. Metzudat David precizează că Numele indică puterea absolută, iar oamenii nu vor mai fi nedumeriți ca în trecut; Radak pune versetul în legătură cu cei care refuză să se întoarcă: de data aceasta le va face cunoscută mâna Sa prin pedeapsă."},{"t":"."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Că numele Meu este DOMNUL” — după sensul simplu: stăpânitor și suveran, care Își împlinește hotărârea."},{"author":"Metzudat David","text":"„De aceea” — a spus, în locul DOMNULUI: le voi face cunoscută puterea mâinii Mele și tăria Mea, și atunci vor ști că numele Meu este DOMNUL, care arată puterea absolută, și nu vor mai fi nedumeriți în privința aceasta, cum erau în trecut."},{"author":"Radak (1160–1235)","text":"Radak: „De aceea” — i-a spus Dumnezeu: de aceea le voi face cunoscut acelora care nu vor să se întoarcă, că de data aceasta le voi face cunoscută mâna Mea. „Și vor cunoaște că numele Meu este DOMNUL” — ca în „că Eu sunt DOMNUL”, căci El este numele Său, și numele Său este El."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"לָכֵן הִנְנִי מוֹדִיעָם בַּפַּעַם...","translation":"„De aceea, iată, le vestesc de...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"διὰ τοῦτο ἰδοὺ ἐγὼ δηλώσω αὐτοῖς ἐν τῷ καιρῷ τούτῳ τὴν χεῖρά μου καὶ γνωριῶ αὐτοῖς τὴν δύναμίν μου, καὶ γνώσονται ὅτι ὄνομά μοι Κύριος.","greek":true,"translation":"„De aceea, iată, le voi arăta în vremea aceasta mâna Mea și le voi face cunoscută puterea Mea, și vor cunoaște că numele Meu este Domnul.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Exod 9:14-18","Exod 14:4","Psalmii 9:16","Ezechiel 6:7","Exod 15:3","Psalmii 83:18"]},{"v":"17:1","t":"Păcatul lui Iuda este scris cu o daltă de fier, cu o unghie [ca] de diamant, gravat pe tăblița inimii lor și pe coarnele altarelor lor.","tokens":[{"t":"Păcatul lui Iuda este scris cu "},{"t":"o daltă de fier","w":"o daltă de fier","heb":"בְּעֵט בַּרְזֶל","translit":"beet barzel","strong":"H5842","pos":"prepoziție + substantiv, masculin singular, în construcție + substantiv","def_ro":"o daltă (condei) de fier.","dict_ro":"Et — condeiul, dalta de scris; imaginea e a unei inscripții săpate în piatră, care nu mai poate fi ștearsă (compară Iov 19:24). Rashi o numește o pildă: păcatul e gravat adânc, de neșters; Metzudat David adaugă că e scris atât pe „tăblița inimii” — în gând —, cât și pe coarnele altarelor — în faptă. Rashi aduce și un midraș: „dalta de fier” e Ieremia, numit „zid de fier” (1:18), iar „vârful de diamant” e Ezechiel, căruia i s-a spus „ți-am făcut fruntea ca diamantul” (Ezechiel 3:9)."},{"t":", cu o unghie [ca] de diamant, gravat pe tăblița inimii lor și pe coarnele altarelor lor."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Cu o daltă de fier” — aceasta este o pildă, adică este gravat adânc și nu poate fi șters. Iar Midrașul Agada explică: „cu o daltă de fier, cu un vârf de diamant” — păstrat de Ieremia, numit „zid de fier”, și de Ezechiel, căruia i s-a spus: „ca diamantul, mai tare decât cremenea, ți-am făcut fruntea” (Ezechiel 3:9). „Gravat” — săpat ca unul care ară adânc. „Pe tăblița inimii lor” — ca să nu-și uite idolatria."},{"author":"Metzudat David","text":"„Păcatul lui Iuda” — se leagă de cele de mai sus: iată, la sfârșit chiar și neamurile își vor părăsi idolii și vor crede în DOMNUL, dar Iuda își păstrează încă păcatul în inimă, ca și cum ar fi scris acolo cu condei de fier și cu vârf de diamant, care sapă puternic și foarte adânc. „Pe tăblița inimii lor” — sunt pereții inimii, căci ea e făcută ca din pereți și goluri. „Și pe coarnele” — și pe coarnele altarelor voastre e săpat păcatul vostru, căci pe coarnele acelea stropesc mereu sânge pentru idoli; ca și cum ar spune: fie în gândul inimii, fie în faptă, lucrul e păstrat la voi."},{"author":"Radak (1160–1235)","text":"Radak: păcatul lor e ca și cum ar fi scris și săpat pe tăblița inimii lor, ca să nu poată fi șters din inimă, ca și cum ar fi scris și săpat cu dalta de fier; căci ce scrie și sapă omul în piatră rămâne pe veci, cum s-a spus: „cu o daltă de fier și cu plumb, să fie săpate în stâncă pe vecie” (Iov 19:24)."},{"author":"Metzudat Țion","text":"„Beet” — cu condeiul. „Bețiporen” — [unghia] de deasupra degetelor; și pentru că omul obișnuiește să taie cu unghiile, a numit condeiul „unghie”. „Șamir” — așa se numește fierul tare, ca în „ca diamantul (șamir), mai tare decât cremenea” (Ezechiel 3:9). „Luah” — tăbliță, scândură. „Ulkarnot” — sunt proeminențele din cele patru colțuri ale altarului."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"חַטַּאת יְהוּדָה כְּתוּבָה בְּעֵט...","translation":"„Păcatul lui Iuda este scris cu...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"","greek":true,"translation":"","note":"Versetele 17:1-4 lipsesc din Septuaginta: textul grec trece direct de la 16:21 la „Blestemat este omul care își pune nădejdea în om” (17:5)."}],"refs":["Iov 19:23,24","Proverbe 3:3","Proverbe 7:3","2 Corinteni 3:3","Levitic 4:17,18,25","Osea 12:11"]},{"v":"17:2","t":"Cum își amintesc de copiii lor, așa [își amintesc și] de altarele lor și de copacii lor sacri de lângă pomii înfrunziți de pe dealurile înalte.","tokens":[{"t":"Cum își amintesc de copiii lor, așa [își amintesc și] de altarele lor și de "},{"t":"copacii lor sacri","w":"copacii lor sacri","heb":"וַאֲשֵׁרֵיהֶם","translit":"vaașereihem","strong":"H842","pos":"conjuncție + substantiv, masculin plural + sufix","def_ro":"așerele lor, stâlpii/pomii închinați zeiței Așera.","dict_ro":"Așera — zeița canaanită a fertilității și, prin extensie, stâlpul de lemn sau pomul sacru închinat ei, pus lângă altar; Metzudat Țion îl definește simplu: „un copac căruia i se slujește”. Tora poruncise: „să nu-ți sădești așeră de niciun fel de copac lângă altarul DOMNULUI” (Deuteronom 16:21). Rashi explică comparația: își aminteau de altare cum își amintește omul de fiul pe care îl dorește — o legătură afectivă, nu doar un obicei."},{"t":" de lângă pomii înfrunziți de pe dealurile înalte."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Cum își amintesc de copiii lor, așa [își amintesc și] de altarele lor” — ca amintirea copiilor lor, așa era pentru ei amintirea altarelor lor, ca un om care tânjește după fiul lui. „Și de copacii lor sacri de lângă pomii înfrunziți” — „al” are sensul de „lângă”; și așa traduce Ionatan: „sub orice pom înfrunzit”."},{"author":"Metzudat David","text":"„Cum își amintesc” — precum își amintesc mereu de copiii lor, așa își amintesc de altarele și de așerele lor. „Lângă pomii înfrunziți” — aproape de pomul înfrunzit; se leagă de altare, pe care le așezau lângă pomul înfrunzit și pe dealurile înalte."},{"author":"Radak (1160–1235)","text":"Radak: amintirea altarelor și a așerelor lor și povestirea despre ele le sunt plăcute ca amintirea copiilor lor, care le sunt dragi și pe care și-i amintesc mereu din iubire; iar unii explică „cum își amintesc” ca pe o ardere de tămâie, adică își treceau copiii prin foc — dar prima explicație e cea bună."},{"author":"Metzudat Țion","text":"„Vaașereihem” — este copacul căruia i se slujește. „Raanan” — cu sensul de umezeală și prospețime."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"כִּזְכֹּר בְּנֵיהֶם מִזְבְּחוֹתָם וַאֲשֵׁרֵיהֶם...","translation":"„Cum își amintesc de copiii lor...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"","greek":true,"translation":"","note":"Versetele 17:1-4 lipsesc din Septuaginta: textul grec trece direct de la 16:21 la „Blestemat este omul care își pune nădejdea în om” (17:5)."}],"refs":["Ieremia 7:18","Osea 4:13,14","Ieremia 2:20","Judecători 3:7","2 Cronici 33:3,19","Isaia 17:8"]},{"v":"17:3","t":"Cei care slujiți [idoli] pe munți, pe câmpuri: bogăția ta, toate comorile tale, le voi da drept pradă, din pricina înălțimilor tale [făcute] în păcat pretutindeni între hotarele tale.","tokens":[{"t":"Cei care slujiți [idoli] pe munți, pe câmpuri: bogăția ta, toate comorile tale, le voi da "},{"t":"drept pradă","w":"drept pradă","heb":"לָבַז","translit":"lavaz","strong":"H957","pos":"prepoziție + substantiv, masculin singular","def_ro":"spre jaf, ca pradă.","dict_ro":"Baz — prada, jaful de război. Rashi citește „cei de pe munte, în câmpie” ca pe Ierusalimul așezat pe munte, înconjurat de câmpie; Radak îi vede pe cei ce slujeau idolilor pe munți. Metzudat David explică scena: jefuitorii vor scoate averea în câmpul unde vor fi tăbărât împotriva cetății și o vor împărți acolo. Profeția s-a împlinit la litera ei: 2 Împărați 25:13-17 enumeră comorile Templului duse la Babilon."},{"t":", din pricina înălțimilor tale [făcute] în păcat pretutindeni între hotarele tale."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Cei de pe munte, în câmpie” — Ierusalimul, care e așezat pe muntele din câmpie; de jur împrejurul cetății e o câmpie cu ogoare. „Bogăția ta” — averea ta. „Înălțimile tale [făcute] în păcat” — înălțimile tale sunt făcute în păcat, pentru idolatrie, în toate hotarele tale."},{"author":"Metzudat David","text":"„Cei de pe munți” — adică voi, cei din Iuda, care slujiți idolilor care stau pe munți: iată, averea ta o vor scoate jefuitorii și o vor împărți între ei pe câmp, în locul unde vor tăbărî împotriva ta; toate comorile ascunse le voi da pradă. „Înălțimile tale” — adică din pricina înălțimilor tale făcute în păcat pentru idoli, care stau în toate hotarele tale, fără să lipsească vreun loc."},{"author":"Radak (1160–1235)","text":"Radak: pentru că slujeau idolilor pe munți, i-a numit pe cei din Israel „cei de pe munte”; ca și cum ar spune: de ce va fi toată averea ta și toate comorile tale pradă? Din pricina păcatului înălțimilor tale, care sunt în toate hotarele tale."},{"author":"Metzudat Țion","text":"„Harari” — din „munte”. „Heleha” — bogăția ta. „Lavaz” — spre pradă și jaf. „Bamoteha” — din „înălțime [de cult]”."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"הֲרָרִי בַּשָּׂדֶה חֵילְךָ כָּל־אוֹצְרוֹתֶיךָ...","translation":"„Cei care slujiți [idoli] pe munți...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"","greek":true,"translation":"","note":"Versetele 17:1-4 lipsesc din Septuaginta: textul grec trece direct de la 16:21 la „Blestemat este omul care își pune nădejdea în om” (17:5)."}],"refs":["Ieremia 26:18","Mica 3:12","Ieremia 15:13","2 Împărați 24:13","Isaia 39:4-6","Levitic 26:30"]},{"v":"17:4","t":"Vei fi deposedat de moștenirea pe care ți-am dat-o și te voi pune să muncești pentru dușmanii tăi într-o țară pe care nu o cunoști, căci ai aprins foc în nările Mele, care va arde veșnic.”","tokens":[{"t":"Vei fi deposedat","w":"Vei fi deposedat","heb":"וְשָׁמַטְתָּה","translit":"veșamatta","strong":"H8058","pos":"verb, qal, perfect consecutiv, persoana a II-a masculin singular","def_ro":"vei lăsa (pământul) nelucrat, vei renunța la el.","dict_ro":"Șamat — „a lăsa, a elibera”, rădăcina lui șemita, anul sabatic în care pământul rămâne nelucrat (Exod 23:11; Deuteronom 15:2). Aici se află legătura directă cu pericopa Behukotai: Tora avertiza că, dacă poporul nu va ține anii sabatici, „țara își va plăti Sabatele ei” în vremea exilului (Levitic 26:34-35). Rashi explică exact așa: vei elibera țara fără voia ta, pentru vremea în care nu s-a odihnit în Sabatele voastre; Metzudat David: fiindcă n-ați lăsat-o în al șaptelea an, veți fi lăsați voi înșivă departe de moștenirea voastră."},{"t":" de moștenirea pe care ți-am dat-o și te voi pune să muncești pentru dușmanii tăi într-o țară pe care nu o cunoști, căci ai aprins foc în nările Mele, care va arde veșnic.”"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Și vei elibera” — fără voia ta vei elibera țara pentru vremea în care nu s-a odihnit în Sabatele voastre, despre care v-am spus: „și țara să țină un Sabat pentru DOMNUL” (Levitic 25:2). „Și prin tine” — Mă voi răzbuna pe tine din pricina moștenirii pe care ți-am dat-o, pentru că n-ai făcut voia Mea s-o eliberezi. „Căci ai aprins foc în nările Mele” — „kedahtem”."},{"author":"Metzudat David","text":"„Și vei elibera” — vei lăsa pământul nelucrat, fără arat și semănat. „Și prin tine” — adică nu de bunăvoie vei părăsi lucrarea lui, ci părăsirea va fi prin tine, căci vei fi părăsit de moștenirea ta și nu vei fi acolo s-o lucrezi; și aceasta ca răsplată pentru că n-au lăsat-o în anul al șaptelea. „Te voi pune să muncești” — adică vei lucra pământul dușmanului într-o țară pe care n-ai cunoscut-o. „Căci ai aprins foc” — ați aprins mânia Mea și va arde pe vecie, adică Mă voi mânia pe voi vreme îndelungată."},{"author":"Radak (1160–1235)","text":"Radak: „Și vei elibera, și prin tine” — adică eliberarea va fi în tine: vei fi eliberat de moștenirea ta, pentru că n-ai eliberat-o [în anul sabatic] când erai în ea; iar Ionatan traduce: „voi aduce dușmanul asupra țării voastre și va fi pustie, lăsată în pace de voi”."},{"author":"Metzudat Țion","text":"„Veșamatta” — din „eliberare, lăsare”, ca în „orice creditor să-și lase împrumutul” (Deuteronom 15:2). „Kedahtem” — cu sensul de aprindere și ardere, ca în „un foc s-a aprins în mânia Mea” (Ieremia 15:14)."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְשָׁמַטְתָּה וּבְךָ מִנַּחֲלָתְךָ אֲשֶׁר...","translation":"„Vei fi deposedat de moștenirea pe...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"","greek":true,"translation":"","note":"Versetele 17:1-4 lipsesc din Septuaginta: textul grec trece direct de la 16:21 la „Blestemat este omul care își pune nădejdea în om” (17:5)."}],"refs":["Ieremia 16:13","Levitic 26:31-34","Deuteronom 28:47,48","Deuteronom 32:22-25","Plângerile lui Ieremia 1:12","Naum 1:5,6"]},{"v":"17:5","t":"Așa a spus DOMNUL: „Blestemat este bărbatul care se încrede în om și care face din muritor tăria sa și care își abate inima de la DOMNUL.","tokens":[{"t":"Așa a spus DOMNUL: „"},{"t":"Blestemat","w":"Blestemat","heb":"אָרוּר","translit":"arur","strong":"H779","pos":"verb, qal, participiu pasiv, masculin singular","def_ro":"blestemat.","dict_ro":"Arur — „blestemat”, forma formulelor solemne de blestem din Deuteronom 27. Rashi leagă din nou versetul de pericopă: blestemat este cel care se încrede în omul care ară și seceră, zicând „voi semăna și în al șaptelea an și voi mânca”, și a cărui inimă se abate de la DOMNUL, care promisese „voi porunci binecuvântarea Mea” asupra anului al șaselea (Levitic 25:21). Radak dă sensul istoric: Israel se încredea în Egipt și în Asiria."},{"t":" este bărbatul care se încrede în om și care face din muritor tăria sa și care își abate inima de la DOMNUL."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Care se încrede în om” — în aratul și seceratul lui, zicând: „voi semăna în anul al șaptelea și voi mânca”. „Brațul” — ca „ajutorul lui”, și așa a tradus Ionatan: „încrederea lui”. „Și care își abate inima de la DOMNUL” — care i-a făgăduit: „și voi porunci binecuvântarea Mea asupra voastră” (Levitic 25:21). Așa am auzit."},{"author":"Metzudat David","text":"„Care se încrede în om” — adică nu vor găsi ajutor de la carne și sânge, căci blestemat este omul... „Și care face” — își pune tăria și încrederea în carne și sânge și își abate inima de la a se încrede în DOMNUL."},{"author":"Radak (1160–1235)","text":"Radak: pentru că Israel se încredea în Egipt și în Asiria, a spus aceasta. „Și care își abate inima de la DOMNUL” — căci dacă inima nu i se abate de la DOMNUL, nu e rău dacă se încrede în om că-l va ajuta, iar intenția lui este că, prin ajutorul lui Dumnezeu, omul poate ajuta, nu fără El."},{"author":"Metzudat Țion","text":"„Arur” — cu sensul de blestem. „Hagever” — omul. „Basar” — adică omul, care e carne. „Zeroo” — tăria lui."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"כֹּה אָמַר יְהוָה אָרוּר...","translation":"„Așa a spus DOMNUL: „Blestemat este...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ΕΠΙΚΑΤΑΡΑΤΟΣ ὁ ἄνθρωπος, ὃς τὴν ἐλπίδα ἔχει ἐπ’ ἄνθρωπον καὶ στηρίζει σάρκα βραχίονος αὐτοῦ ἐπ’ αὐτόν, καὶ ἀπὸ Κυρίου ἀποστῇ ἡ καρδία αὐτοῦ·","greek":true,"translation":"„Blestemat este omul care își pune nădejdea în om și sprijină pe el carnea brațului său, iar inima lui se depărtează de la Domnul.”","note":"În Septuaginta acest verset deschide capitolul 17 (fără 17:1-4) și nu are formula introductivă „Așa a spus DOMNUL”."}],"refs":["Psalmii 62:9","Psalmii 118:8,9","Psalmii 146:3,4","Isaia 31:1-9","2 Cronici 32:8","Evrei 3:12"]},{"v":"17:6","t":"El este ca un copac singuratic în pustietate și nu va vedea când vine binele; el va locui într-un deșert arid, într-un ținut de pucioasă, nelocuit.","tokens":[{"t":"El este ca un "},{"t":"copac singuratic","w":"copac singuratic","heb":"כְּעַרְעָר","translit":"keararar","strong":"H6199","pos":"prepoziție + substantiv, masculin singular","def_ro":"ca un arbust de pustiu, ca un copac părăsit.","dict_ro":"Arar — un arbust din deșert (Metzudat Țion îl numește „un copac al pustiei”), înrudit cu ariri, „fără copii, singur” (Geneza 15:2); Rashi aduce ambele lecturi, iar Radak, după Rav Hai Gaon, îl identifică cu un arbust spinos pe dinafară, cu fruct comestibil înăuntru. Imaginea e contrapunctul exact al versetului 17:8: acolo, copacul sădit lângă ape; aici, arbustul care „nu vede când vine binele” — ploaia — și trăiește într-un pământ sărat, nelocuit."},{"t":" în pustietate și nu va vedea când vine binele; el va locui într-un deșert arid, într-un ținut de pucioasă, nelocuit."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Ca un copac singuratic” — o expresie ca „fără copii” (ariri, Geneza 15:2); unii spun: pustiit; iar Menahem a explicat: numele unui copac din copacii pădurii, numit arar, și aceasta e explicația lui „ca un aroer în pustie” (Ieremia 48:6). „În pustietate” — o expresie de câmpie. „Deșert arid” — uscăciune, ca în „oasele mele au ars (hara) de arșiță” (Iov 30:30). „Ținut de pucioasă” — pământ sărat, care nu va fi locuit."},{"author":"Metzudat David","text":"„El este” — cel ce se încrede în om va fi ca ararul care crește în pustie. „Și nu va vedea” — nu vede când vine binele în lume, adică ploile; vrea să spună că nu asupra lui vor fi ploile. „Va locui într-un deșert arid” — locuiește acolo, în locuri uscate de prea multă căldură a pustiei. „Ținut de pucioasă” — e un pământ al cărui țărână e sărată și nu e locuit; e o dublare a sensului în alte cuvinte."},{"author":"Radak (1160–1235)","text":"Radak: Ionatan traduce „ca spinul din câmpie”, iar Rav Hai a explicat că ararul este spinos pe dinafară, iar înăuntru are un fruct care se mănâncă. Și a asemănat omul care își ia încrederea de la Dumnezeu cu acest copac, care nu se umezește niciodată, ci stă mereu în uscăciune; și deși nu moare, tot așa omul rău va fi în rău toate zilele lui și își va alege moartea mai degrabă decât viața."},{"author":"Metzudat Țion","text":"„Kearar” — numele unui copac de pustie, ca în „ca un arar în pustie” (Ieremia 48:6). „Baarava” — sensul lui e ca „în pustie”. „Harerim” — sensul lui e uscăciune. „Melehah” — din „sare”."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְהָיָה כְּעַרְעָר בָּעֲרָבָה וְלֹא...","translation":"„El este ca un copac singuratic...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἔσται ὡς ἡ ἀγριομυρίκη ἡ ἐν τῇ ἐρήμῳ, οὐκ ὄψεται ὅταν ἔλθῃ τὰ ἀγαθά, καὶ κατασκηνώσει ἐν ἁλίμοις καὶ ἐν ἐρήμῳ, ἐν γῇ ἁλμυρᾷ, ἥτις οὐ κατοικεῖται.","greek":true,"translation":"„Și va fi ca tamariscul sălbatic din pustie; nu va vedea când vor veni bunătățile și va locui în locuri sărate și în pustie, în pământ sărat, care nu e locuit.”","note":"Septuaginta identifică arbustul cu „tamariscul sălbatic” (ἀγριομυρίκη)."}],"refs":["Ieremia 48:6","Isaia 1:30","2 Împărați 7:2,19,20","Deuteronom 29:23"]},{"v":"17:7","t":"Binecuvântat este bărbatul care se încrede în DOMNUL – atunci DOMNUL îi va fi încrederea.","tokens":[{"t":"Binecuvântat","w":"Binecuvântat","heb":"בָּרוּךְ","translit":"baruh","strong":"H1288","pos":"verb, qal, participiu pasiv, masculin singular","def_ro":"binecuvântat.","dict_ro":"Baruh — „binecuvântat”, perechea directă a lui arur din 17:5: cele două versete formează un diptic, iar imaginea pomului sădit lângă ape reia aproape cuvânt cu cuvânt Psalmii 1:3. Metzudat David explică încheierea „atunci DOMNUL îi va fi încrederea”: în măsura în care se încrede în El, în aceeași măsură Dumnezeu îi va fi sprijin și ajutor; Radak adaugă: dacă se încrede în El, nu se va teme de niciun rău."},{"t":" este bărbatul care se încrede în DOMNUL – atunci DOMNUL îi va fi încrederea."}],"commentaries":[{"author":"Metzudat David","text":"„Atunci DOMNUL îi va fi încrederea” — adică, precum se încrede în El, așa îi va fi El spre încredere și ajutor."},{"author":"Radak (1160–1235)","text":"Radak: „Binecuvântat este bărbatul... atunci DOMNUL îi va fi încrederea” — dacă se încrede în El, El îi va fi încrederea, și nu se va teme de niciun rău."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"בָּרוּךְ הַגֶּבֶר אֲשֶׁר יִבְטַח...","translation":"„Binecuvântat este bărbatul care se încrede...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ εὐλογημένος ὁ ἄνθρωπος, ὃς πέποιθεν ἐπὶ τῷ Κυρίῳ καὶ ἔσται Κύριος ἐλπὶς αὐτοῦ·","greek":true,"translation":"„Și binecuvântat este omul care s-a încrezut în Domnul, și Domnul va fi nădejdea lui.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Psalmii 2:12","Psalmii 34:8","Psalmii 84:12","Psalmii 125:1","Proverbe 16:20","Isaia 26:3,4"]},{"v":"17:8","t":"El este ca un copac plantat lângă apă, care își întinde rădăcinile lângă pâraie și nu va vedea când vine arșița, al cărui frunziș este de-a pururea verde și nu se teme în ani de secetă și nu va înceta niciodată să aibă rod.","tokens":[{"t":"El este ca "},{"t":"un copac plantat","w":"un copac plantat","heb":"כְּעֵץ שָׁתוּל","translit":"keeț șatul","strong":"H8362","pos":"prepoziție + substantiv + verb, qal, participiu pasiv","def_ro":"un pom sădit (răsădit).","dict_ro":"Șatal — „a sădi, a răsădi”, spus mai ales despre pomii mutați intenționat lângă apă; aceeași imagine deschide Psalmii: „este ca un pom sădit lângă pâraie de apă, care își dă rodul la vremea lui” (Psalmii 1:3). Metzudat David și Radak dezvoltă pilda: chiar în anul de secetă, când ceilalți copaci se usucă, acesta rămâne verde și rodește — așa omul care se încrede în DOMNUL nu duce lipsă, chiar când lumea e în necaz."},{"t":" lângă apă, care își întinde rădăcinile lângă pâraie și nu va vedea când vine arșița, al cărui frunziș este de-a pururea verde și nu se teme în ani de secetă și nu va înceta niciodată să aibă rod."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Și nu va vedea” — copacul nu va vedea când vine arșița. „Secetă” — o expresie de foamete; o altă explicație: „bațoret” e o expresie de întăritură, și așa a clasificat-o Menahem. „Nu se teme” — nu se va îngrijora."},{"author":"Metzudat David","text":"„Ca un copac plantat” — va fi plin de bine ca pomul sădit lângă apă, ale cărui rădăcini se întind lângă pâraie. „Și nu va vedea” — nu va simți când vine căldura și arșița, pentru că e sădit lângă apele care îl udă. „Și în anul secetei” — în anul în care se opresc ploile nu se îngrijorează, adică nu-i va strica. „Și nu va înceta” — nu se va opri din a crește rod; și tot așa va fi cel ce se încrede în DOMNUL: nu-i va lipsi nimic și nu se va îngrijora de necazurile care se abat asupra lumii."},{"author":"Radak (1160–1235)","text":"Radak: „Sădit lângă ape” — ca să nu însetoșeze niciodată; chiar dacă e arșiță în lume, nu o va simți, căci e sădit lângă ape, iar frunzele lui nu vor cădea ca ale celorlalți pomi; chiar în anul de secetă, când se opresc ploile, nu se va îngrijora și își va da rodul la vremea lui. Tot așa omul bun, care se încrede în DOMNUL: binele lui nu se va îndepărta niciodată, și chiar când ceilalți oameni sunt în necaz, el va fi în bine."},{"author":"Metzudat Țion","text":"„Șatul” — sădit, ca în „sădiți în casa DOMNULUI” (Psalmii 92:13). „Yuval” — pâraie de apă. „Batzoret” — cu sensul de oprire a ploilor. „Yamiș” — cu sensul de îndepărtare, ca în „stâlpul de nor nu se depărta” (Exod 13:22)."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"וְהָיָה כְּעֵץ שָׁתוּל עַל־מַיִם...","translation":"„El este ca un copac plantat...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"καὶ ἔσται ὡς ξύλον εὐθηνοῦν παρ’ ὕδατα, καὶ ἐπὶ ἰκμάδα βαλεῖ ῥίζαν αὐτοῦ καὶ οὐ φοβηθήσεται ὅταν ἔλθῃ καῦμα, καὶ ἔσται ἐπ’ αὐτῷ στελέχη ἀλσώδη, ἐν ἐνιαυτῷ ἀβροχίας οὐ φοβηθήσεται καὶ οὐ διαλείψει ποιῶν καρπόν.","greek":true,"translation":"„Și va fi ca un pom înfloritor lângă ape, și spre umezeală își va trimite rădăcina, și nu se va teme când va veni arșița, și vor fi pe el ramuri umbroase; în anul secetei nu se va teme și nu va înceta să facă rod.”","note":"Corespondență strânsă; „frunzișul verde” e redat prin „ramuri umbroase” (στελέχη ἀλσώδη)."}],"refs":["Psalmii 1:3","Iov 8:16","Psalmii 92:10-15","Isaia 58:11","Ezechiel 47:12","Ieremia 14:1"]},{"v":"17:9","t":"Inima este cea mai înșelătoare din toate și perversă, cine o cunoaște?","tokens":[{"t":"Inima este "},{"t":"cea mai înșelătoare","w":"cea mai înșelătoare","heb":"עָקֹב","translit":"akov","strong":"H6121","pos":"adjectiv, masculin singular","def_ro":"înșelător, strâmb, viclean.","dict_ro":"Akov — „strâmb, înșelător”, din aceeași rădăcină ca Iaakov (Iacov), „cel ce ține călcâiul, cel ce înșală” (Geneza 27:36). Radak explică legătura cu versetele precedente: încrederea — în om sau în Dumnezeu — ține de intenția inimii, iar omul poate arăta bine în cuvinte și fapte, cu inima rea înăuntru; de aceea „cine o cunoaște?” își primește răspunsul imediat: „Eu, DOMNUL, cercetez inima”."},{"t":" din toate și perversă, cine o cunoaște?"}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Inima este înșelătoare” — plină de pretexte și de viclenie a tot răul. „Și bolnavă” — o expresie de boală, și aceasta e boala ei. „Cine o cunoaște?” — ea gândește: „cine o cunoaște?” — Eu, DOMNUL, o cercetez."},{"author":"Metzudat David","text":"„Inima este înșelătoare” — deși inima omului e mai strâmbă și mai sucită decât toate mădularele lui și are o durere puternică, adică o judecată stricată, gândind: cine cunoaște tainele inimii mele, dacă se încrede cu adevărat sau nu?"},{"author":"Radak (1160–1235)","text":"Radak: pentru că a vorbit despre încrederea care e rea când omul și-o pune în om, și aceasta ține de intenția inimii, a vorbit despre intenția inimii și a spus că inima e mai înșelătoare decât orice lucru, căci omul poate arăta binele cu gura și cu faptele, iar inima lui să fie rea; și cine știe aceasta, decât Dumnezeu? De aceea a spus: „Eu, DOMNUL, cercetez inima”."},{"author":"Metzudat Țion","text":"„Akov” — cu sensul de strâmb și sucit, ca în „fiecare frate înșală (akov yaakov)” (Ieremia 9:4). „Veanuș” — cu sensul de durere puternică, ca în „rana mea e fără leac” (Iov 34:6)."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"עָקֹב הַלֵּב מִכֹּל וְאָנֻשׁ...","translation":"„Inima este cea mai înșelătoare din...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"βαθεῖα ἡ καρδία παρά πάντα, καὶ ἄνθρωπός ἐστι· καὶ τίς γνώσεται αὐτόν;","greek":true,"translation":"„Adâncă este inima mai mult decât toate, și om este — și cine îl va cunoaște?”","note":"Divergență reală: Septuaginta citește amok („adâncă”) în loc de akov („înșelătoare”) și enoș („om”) în loc de anuș („bolnavă, fără leac”)."}],"refs":["Ieremia 16:12","Geneza 6:5","Proverbe 28:26","Matei 15:19"]},{"v":"17:10","t":"Eu, DOMNUL, cercetez inima și încerc mintea, ca să îi dau omului după căile lui, după roadele faptelor lui.","tokens":[{"t":"Eu, DOMNUL, cercetez inima și "},{"t":"încerc mintea","w":"încerc mintea","heb":"בֹּחֵן כְּלָיוֹת","translit":"bohen kelaiot","strong":"H3629","pos":"verb, qal, participiu + substantiv, feminin plural","def_ro":"încerc rărunchii (lăuntrul, gândurile ascunse).","dict_ro":"Kelayot — literal „rărunchii”, considerați în gândirea biblică sediul gândurilor și al emoțiilor celor mai ascunse; Radak explică perechea „inima și rărunchii”: rărunchii sfătuiesc, iar inima hotărăște. Formula revine la Ieremia (11:20; 20:12) și e preluată în Apocalipsa 2:23: „Eu sunt Cel ce cercetez rărunchii și inimile”."},{"t":", ca să îi dau omului după căile lui, după roadele faptelor lui."}],"commentaries":[{"author":"Metzudat David","text":"„Eu, DOMNUL” — adică: dar Eu, DOMNUL, cercetez inima omului și încerc gândul rărunchilor, ca să știu ce este, ca să dau fiecăruia după căile inimii lui și după rodul faptelor lui — acestea sunt gândurile, care sunt lucrarea inimii și căile ei; și e o dublare a lucrului în alte cuvinte."},{"author":"Radak (1160–1235)","text":"Radak: „Eu, DOMNUL, cercetez inima și încerc rărunchii” — a pomenit rărunchii, pentru că rărunchii sfătuiesc, iar inima hotărăște. „Și să dau” — a spus: Eu, DOMNUL, cercetez inima, și tot în mâna Mea este să dau omului după căile lui."},{"author":"Metzudat Țion","text":"„Hoker” — cu sensul de căutare și cercetare. „Bohen” — din „încercare, probă”. „Maalalav” — faptele lui."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"אֲנִי יְהוָה חֹקֵר לֵב בֹּחֵן כְּלָיוֹת וְלָתֵת לְאִישׁ כִּדְרָכָו כִּפְרִי מַעֲלָלָיו","translation":"Textul masoretic are „încerc rărunchii” (bohen kelaiot); traducerea rabinului Rosen are „încerc mintea”.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ἐγὼ Κύριος ἐτάζων καρδίας καὶ δοκιμάζων νεφροὺς τοῦ δοῦναι ἑκάστῳ κατὰ τὰς ὁδοὺς αὐτοῦ καὶ κατὰ τοὺς καρποὺς τῶν ἐπιτηδευμάτων αὐτοῦ.","greek":true,"translation":"„Eu, Domnul, cercetez inimile și încerc rărunchii, ca să dau fiecăruia după căile lui și după roadele faptelor lui.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Ieremia 11:20","Ieremia 20:12","1 Samuel 16:7","Psalmii 139:1,2,23,24","Romani 8:27","Apocalipsa 2:23"]},{"v":"17:11","t":"Ca un cuc, clocind ouă pe care nu le-a ouat, este cel ce strânge bogăție pe nedrept; la jumătatea zilelor lui, [bogăția] îl va părăsi, și când îi va veni sfârșitul va fi un biet nebun.","tokens":[{"t":"Ca un cuc","w":"Ca un cuc","heb":"קֹרֵא","translit":"kore","strong":"H7124","pos":"substantiv, masculin singular","def_ro":"o pasăre (potârniche/cuc) care clocește ouă străine.","dict_ro":"Kore — o pasăre, identificată de obicei cu potârnichea (literal „cea care strigă”), numită și în 1 Samuel 26:20; Rashi o traduce în franceza veche prin „cuc”. Pilda, explicată de Rashi, Radak și Metzudat David: pasărea atrage cu glasul ei puii din ouă pe care nu le-a ouat, dar când cresc aceștia o părăsesc, pentru că nu sunt de felul ei; tot așa averea strânsă pe nedrept îl părăsește pe cel ce a strâns-o, la jumătatea zilelor lui."},{"t":", clocind ouă pe care nu le-a ouat, este cel ce strânge bogăție pe nedrept; la jumătatea zilelor lui, [bogăția] îl va părăsi, și când îi va veni sfârșitul va fi un biet nebun."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Ca un cuc” — [coucou, în franceza veche]. „Clocind ouă pe care nu le-a ouat” — cucul acesta trage după el pui pe care nu i-a ouat; dagar este ciripitul pe care pasărea îl scoate cu glasul ca să tragă puii după ea, dar cei chemați de cuc nu-l vor urma când vor crește, căci nu sunt de felul lui. Tot așa este cel care strânge bogăție, dar nu pe drept. „Un biet nebun” — va fi numit nelegiuit."},{"author":"Metzudat David","text":"„Ca un cuc” — ca pasărea care cheamă și trage după ea pui cu ciripitul glasului, deși nu ea i-a născut, lucru care nu dăinuie, căci când cresc înțeleg că nu ea i-a născut și o părăsesc; tot așa cel ce strânge bogăție nu cu dreptate, ci prin viclenia inimii: bogăția aceasta nu va dăinui în mâna lui, la jumătatea zilelor lui o va părăsi, iar la sfârșit viclenia inimii lui va fi descoperită oamenilor și va fi socotit un nebun."},{"author":"Radak (1160–1235)","text":"Radak: pentru că a spus „să dau fiecăruia după căile lui”, a spus: să nu te miri de cel rău care prosperă în avere — cum de nu-i dă Dumnezeu după căile lui? — căci să știi că cel rău, a cărui bogăție nu e cu dreptate, nu se va ține de ea, ci îi va ieși din mână la jumătatea zilelor lui. Și l-a asemănat cu kore, o pasăre care clocește ouăle altei păsări și le încălzește, iar puii ieșiți nu vor fi ca fiii ei, să meargă după ea, ci o vor părăsi."},{"author":"Metzudat Țion","text":"„Kore” — numele unei păsări, ca în „cum se vânează o potârniche (kore) în munți” (1 Samuel 26:20). „Dagar” — cu sensul de ciripit al păsării, ca să tragă puii după ea. „Ose” — cu sensul de adunare. „Naval” — de nimic și disprețuit."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"קֹרֵא דָגַר וְלֹא יָלָד עֹשֶׂה עֹשֶׁר וְלֹא בְמִשְׁפָּט בַּחֲצִי יָמָו יַעַזְבֶנּוּ וּבְאַחֲרִיתוֹ יִהְיֶה נָבָל","translation":"Textul masoretic are „kore”, pasăre identificată de obicei cu potârnichea („cea care strigă”); traducerea rabinului Rosen are „cuc”.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ἐφώνησε πέρδιξ, συνήγαγεν ἃ οὐκ ἔτεκε· ποιῶν πλοῦτον αὐτοῦ οὐ μετὰ κρίσεως, ἐν ἡμίσει ἡμερῶν αὐτοῦ ἐγκαταλείψουσιν αὐτόν, καὶ ἐπ’ ἐσχάτων αὐτοῦ ἔσται ἄφρων.","greek":true,"translation":"„A strigat potârnichea, a adunat ce n-a născut; cel ce își face bogăția fără dreptate, la jumătatea zilelor lui îl vor părăsi, și la sfârșitul lui va fi nebun.”","note":"Septuaginta identifică pasărea cu „potârnichea” (πέρδιξ) și redă „a clocit” (dagar) prin „a adunat”."}],"refs":["Proverbe 13:11","Proverbe 21:6","Habacuc 2:6-12","Psalmii 55:23","Proverbe 23:5","Luca 12:20"]},{"v":"17:12","t":"Precum Tronul Gloriei, înălțat de la început, este locul Sanctuarului nostru.","tokens":[{"t":"Precum "},{"t":"Tronul Gloriei","w":"Tronul Gloriei","heb":"כִּסֵּא כָבוֹד","translit":"kise havod","strong":"H3678","pos":"substantiv, masculin singular, în construcție + substantiv","def_ro":"tronul slavei.","dict_ro":"Kise havod — „Tronul slavei”, locul de unde domnește Dumnezeu. Talmudul (Pesahim 54a) învață din acest verset că Tronul slavei și Templul se numără printre cele șapte lucruri create înainte de facerea lumii, iar Radak adaugă tradiția că Templul de jos e așezat exact în dreptul Tronului de sus. Metzudat David explică: precum Prezența divină e în ceruri, așa e și în Templu — de aceea, cum spune Rashi, versetul începe cu lauda Celui Omniprezent înainte de a vorbi despre cei ce Îl părăsesc."},{"t":", înălțat de la început, este locul Sanctuarului nostru."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Precum Tronul Gloriei” — pentru că vrea să spună „toți cei ce Te părăsesc vor fi făcuți de rușine”, începe cu lauda Celui Omniprezent și spune înaintea Lui: Tu, al cărui Tron al Gloriei e înălțat de la începutul creării lumii și e îndreptat spre Sanctuarul nostru."},{"author":"Metzudat David","text":"„Tronul Gloriei” — ca Tronul Gloriei, adică cerurile înalte, cum s-a spus: „cerurile sunt tronul Meu” (Isaia 66:1). „De la început” — pregătit Ție de demult, cum s-a spus: „tronul Tău e întemeiat de atunci” (Psalmii 93:2). „Locul Sanctuarului nostru” — adică așa este locul Sanctuarului nostru; căci precum Prezența divină este în ceruri, așa este și în Templu."},{"author":"Talmud Bavli, Pesahim 54a","text":"S-a învățat într-o baraita: șapte lucruri au fost create înainte ca lumea să fie creată, și acestea sunt: Tora, pocăința, Grădina Edenului, Gheena, Tronul slavei, Templul și numele lui Mesia. Tronul slavei și Templul au fost create înainte de lume, precum este scris: „Tronul slavei, înălțat de la început, este locul Sanctuarului nostru” (Ieremia 17:12)."},{"author":"Metzudat Țion","text":"„Kise” — ca „precum tronul”, lipsind kaf-ul de comparație. „Marom” — cerurile înalte. „Merișon” — de atunci, de demult."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"כִּסֵּא כָבוֹד מָרוֹם מֵרִאשׁוֹן...","translation":"„Precum Tronul Gloriei, înălțat de la...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"θρόνος δόξης ὑψωμένος, ἁγίασμα ἡμῶν,","greek":true,"translation":"„Tron de slavă înălțat, sfințenia noastră,”","note":"Septuaginta omite „de la început” și leagă versetul direct de următorul."}],"refs":["Ieremia 3:17","Ieremia 14:21","Psalmii 103:19","Isaia 6:1","Isaia 66:1","Evrei 4:16"]},{"v":"17:13","t":"Nădejdea lui Israel este DOMNUL, toți cei care Te părăsesc vor fi făcuți de rușine, vor fi înscriși către temeliile pământului, căci ei L-au părăsit pe DOMNUL, Izvorul apelor vii.","tokens":[{"t":"Nădejdea lui Israel este DOMNUL, toți cei care Te părăsesc vor fi făcuți de rușine, vor fi înscriși către temeliile pământului, căci ei L-au părăsit pe DOMNUL, "},{"t":"Izvorul apelor vii","w":"Izvorul apelor vii","heb":"מְקוֹר מַיִם־חַיִּים","translit":"mekor maim-haim","strong":"H4726","pos":"substantiv, masculin singular, în construcție + substantiv + adjectiv","def_ro":"izvorul de ape vii (curgătoare).","dict_ro":"Mekor maim haim — „izvorul apelor vii”, imaginea pe care Ieremia o folosise deja: „M-au părăsit pe Mine, izvorul apelor vii, ca să-și sape puțuri crăpate” (Ieremia 2:13). „Mikve Israel” de la începutul versetului înseamnă „nădejdea lui Israel”, dar mikve înseamnă și „bazin de apă”; Radak menționează lectura care vede aici „mikve-ul de purificare” al lui Israel — interpretare pe care Rabi Akiva o face celebră în Mișna (Yoma 8:9): „precum mikve-ul îi curăță pe cei necurați, așa Sfântul, binecuvântat fie El, îl curăță pe Israel”."},{"t":"."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „DOMNUL” — care este izvorul nădejdilor lui Israel, stă pe el [pe Tron]; de aceea, toți cei ce Te părăsesc vor fi făcuți de rușine. „Și cei ce se abat de la Mine vor fi înscriși în pământ” — cei ce se abat de la cuvintele mele, care nu ascultă solia mea, vor fi însemnați în mormintele de jos ale pământului."},{"author":"Metzudat David","text":"„Nădejdea lui Israel este DOMNUL” — de aceea se cuvine ca nădejdea lui Israel să fie la DOMNUL, de vreme ce Ți-ai sădit Prezența în mijlocul lor. „Toți cei care Te părăsesc” — toți cei care Te părăsesc și se încred în om se cuvine să fie făcuți de rușine. „Vor fi înscriși către temeliile pământului” — vor fi scriși în carte să coboare în adâncurile pământului, în adâncimile Șeolului, pentru că au părăsit izvorul din care țâșnesc ape vii; și explică apoi: pe DOMNUL, care revarsă binele în orice vreme, ca un izvor care țâșnește."},{"author":"Radak (1160–1235)","text":"Radak: „Mikve Israel” — sensul e de chemare: Tu, care ești nădejdea lui Israel și încrederea tuturor celor ce se încred în Tine; toți cei ce Te părăsesc și nu se încred în Tine vor fi rușinați de încrederea lor în carne și sânge. „Căci au părăsit izvorul apelor vii” — măsură pentru măsură: ei Te-au părăsit pe Tine, izvorul apelor vii care nu încetează; iar unii explică mikve ca „bazin de apă”, adică Tu ești mikve-ul de curățire al lui Israel — dar prima explicație e cea bună."},{"author":"Mișna, Yoma 8:9","text":"Rabi Akiva a spus: ferice de voi, Israel! Înaintea cui vă curățiți și cine vă curăță? Tatăl vostru din ceruri, precum s-a spus: „vă voi stropi cu apă curată și veți fi curățiți” (Ezechiel 36:25); și s-a spus: „mikve-ul lui Israel este DOMNUL” (Ieremia 17:13) — precum mikve-ul îi curăță pe cei necurați, așa Sfântul, binecuvântat fie El, îl curăță pe Israel."},{"author":"Metzudat Țion","text":"„Mikve” — din „nădejde”. „Vesurai” — din „abatere”. „Mekor” — izvor."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"מִקְוֵה יִשְׂרָאֵל יְהוָה כָּל־עֹזְבֶיךָ...","translation":"„Nădejdea lui Israel este DOMNUL, toți...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ὑπομονὴ ᾿Ισραήλ, Κύριε, πάντες οἱ καταλιπόντες σε καταισχυνθήτωσαν, ἀφεστηκότες ἐπὶ τῆς γῆς γραφήτωσαν, ὅτι ἐγκατέλιπον πηγὴν ζωῆς, τὸν Κύριον.","greek":true,"translation":"„nădejdea lui Israel, Doamne; toți cei ce Te-au părăsit să fie rușinați; cei ce s-au depărtat să fie scriși pe pământ, căci au părăsit izvorul vieții, pe Domnul.”","note":"Septuaginta redă „izvorul apelor vii” prin „izvorul vieții” (πηγὴν ζωῆς), iar verbele devin dorințe („să fie rușinați”, „să fie scriși”)."}],"refs":["Ieremia 17:17","Ieremia 14:8","Psalmii 97:7","Isaia 1:28","Ieremia 2:13,17","Ioan 4:10,14"]},{"v":"17:14","t":"Vindecă-mă, DOAMNE, și voi fi vindecat, salvează-mă și voi fi salvat, căci Tu ești lauda mea.","tokens":[{"t":"Vindecă-mă","w":"Vindecă-mă","heb":"רְפָאֵנִי","translit":"refaeni","strong":"H7495","pos":"verb, qal, imperativ, masculin singular + sufix persoana I","def_ro":"vindecă-mă.","dict_ro":"Rafa — „a vindeca”; versetul a intrat, la plural, în rugăciunea zilnică Amida, ca binecuvântarea pentru vindecare: „Vindecă-ne, DOAMNE, și vom fi vindecați; mântuiește-ne și vom fi mântuiți, căci Tu ești lauda noastră”. Metzudat David explică dublarea: nimeni altcineva nu mă poate mântui decât Tu; Radak precizează că „boala” de care cere vindecare profetul sunt disprețul și blestemul îndurate din partea poporului pe care îl mustra."},{"t":", DOAMNE, și voi fi vindecat, salvează-mă și voi fi salvat, căci Tu ești lauda mea."}],"commentaries":[{"author":"Rashi (1040–1105)","text":"Rashi: „Căci Tu ești lauda mea” — mă laud și mă fălesc cu Tine, spunând că Tu ești Mântuitorul meu."},{"author":"Metzudat David","text":"„Vindecă-mă” — a spus profetul: când Tu mă vei vindeca, voi fi vindecat; și ca lămurire a adăugat: mântuiește-mă de cei ce se ridică împotriva mea, și atunci voi fi mântuit — adică nimeni nu mă poate mântui în afară de Tine. „Căci Tu ești lauda mea” — mă laud cu Tine, spunând că Tu ești Dumnezeul mântuirii mele."},{"author":"Radak (1160–1235)","text":"Radak: „Vindecă-mă, DOAMNE” — cere vindecare de rană și de durere, cum a spus: „de ce este durerea mea necurmată și rana mea fără leac?” (Ieremia 15:18); iar durerea și rana, cum am explicat, sunt disprețul și blestemul. „Căci Tu ești lauda mea” — mă laud cu Tine, că mă vei izbăvi din mâna lor."}],"textCompare":[{"source":"Textul Masoretic (ebraică)","original":"רְפָאֵנִי יְהוָה וְאֵרָפֵא הוֹשִׁיעֵנִי...","translation":"„Vindecă-mă, DOAMNE, și voi fi vindecat...” — traducerea rabinului Rosen.","note":""},{"source":"Septuaginta (greacă, sec. III-II î.Hr.)","original":"ἴασαί με, Κύριε, καὶ ἰαθήσομαι· σῶσόν με, καὶ σωθήσομαι· ὅτι καύχημά μου σὺ εἶ.","greek":true,"translation":"„Vindecă-mă, Doamne, și voi fi vindecat; mântuiește-mă și voi fi mântuit, căci lauda mea ești Tu.”","note":"Corespondență strânsă cu Textul Masoretic."}],"refs":["Ieremia 31:18","Deuteronom 32:39","Psalmii 6:2,4","Isaia 57:18,19","Luca 4:18","Deuteronom 10:21"]}]}]};
